INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (2, '1591883.0', 'Metzeler CruiseTec Tires', 'metzeler-cruisetec-tires-1591883.0', 'Metzeler', 2, 'STREET BIKE', 'Customcruisertouring Bi / Customcruisertouring Ra / Cruiser Tire / Harley Tire', 'Harley-Davidson', 'Harley Sportster / Harley Fxfxr / Harley Street / Harley Touring / Harley V Rod / Harley Softail / Harley Dyna / Harley Dyna Fat Bo / Harley Dyna Street / Harley Dyna Super / Harley Dyna Switch / Harley Softail Del / Harley Softail Deu / Harley Softail Fat / Harley Softail Her / Harley Softail Nig / Harley Sportster 1 / Harley Sportster 8 / Harley Sportster I / Harley Touring Ele / Harley Touring Roa / Harley Touring Str', '1990 - 2025', 'P673121', 153.51, '469.57', '469.57', 'Save up to Save $113.61 24%', 4.7, 415, 'nan', 'nan', 'Rear; Front', 36, '140/75R15 65H TL; 130/90B16 73H TL; MT90B16 72H TL; MT90B16 74H TL; MU85B16 77H TL; 150/80-16 71H TL; 150/80B16 77H TL; 180/60R16 80H TL; 180/60R16 80H TL I-spec; 180/65B16 81H TL; 180/70R16 77V TL; 180/70B16 77H TL; 200/55R16 77H TL; 240/50R16 84V TL; 100/80-17 52H TL; 130/80B17 65H TL; 150/80R17 72V TL; 160/70B17 79V TL; 160/70R17 73V TL; 200/55R17 78V TL; 130/70B18 63H TL; 130/70R18 63H TL; 150/70B18 76H TL; 160/60R18 70V TL; 180/55B18 80H TL; 180/55ZR18 74W TL; 240/40VR18 79V TL; 260/40VR18 84V TL; 100/90-19 57H TL; 110/90-19 62H TL; 120/70ZR19 60W TL; 130/60B19 61H TL; 130/60B19 66H; MH90-21 54H TL; 120/70B21 68H TL; 130/60B21 63H TL', 37, 'Metzeler Cruisetec Tires The Cruisetec is the latest addition to Metzeler''s line of cruiser tires. With a new aggressive tread pattern set in dual-compound rubber, the Cruisetec offer supreme handling in both dry and wet conditions. Featuring an all-new carcass specification, the Cruisetec provides excellent, predictable handling and cornering stability throughout corner entry and exit. This performance tire will not only help make use of all the extra power of performance cruisers but also improve the handling characteristics of cruisers of all shapes and pedigrees.', 'Dual compound rubber provides long lasting grip New compound has excellent grip, wet and dry Hi-performance carcass construction for smooth and predictable handling Tubeless "I" spec tire is the OE tire for Indian Challenger. Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/metzeler_cruisetec_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/metzeler_cruisetec_tires.webp", "https://americaapi.kaafifoods.com/storage/products/metzeler_cruisetec65_h.webp"]', '{"Wheel Location": "Rear; Front", "Type": "STREET BIKE", "Product Type": "Customcruisertouring Bi / Customcruisertouring Ra / Cruiser Tire / Harley Tire", "Make": "Harley-Davidson", "Model": "Harley Sportster / Harley Fxfxr / Harley Street / Harley Touring / Harley V Rod / Harley Softail / Harley Dyna / Harley Dyna Fat Bo / Harley Dyna Street / Harley Dyna Super / Harley Dyna Switch / Harley Softail Del / Harley Softail Deu / Harley Softail Fat / Harley Softail Her / Harley Softail Nig / Harley Sportster 1 / Harley Sportster 8 / Harley Sportster I / Harley Touring Ele / Harley Touring Roa / Harley Touring Str", "Tire Size": "140/75R15 65H TL; 130/90B16 73H TL; MT90B16 72H TL; MT90B16 74H TL; MU85B16 77H TL; 150/80-16 71H TL; 150/80B16 77H TL; 180/60R16 80H TL; 180/60R16 80H TL I-spec; 180/65B16 81H TL; 180/70R16 77V TL; 180/70B16 77H TL; 200/55R16 77H TL; 240/50R16 84V TL; 100/80-17 52H TL; 130/80B17 65H TL; 150/80R17 72V TL; 160/70B17 79V TL; 160/70R17 73V TL; 200/55R17 78V TL; 130/70B18 63H TL; 130/70R18 63H TL; 150/70B18 76H TL; 160/60R18 70V TL; 180/55B18 80H TL; 180/55ZR18 74W TL; 240/40VR18 79V TL; 260/40VR18 84V TL; 100/90-19 57H TL; 110/90-19 62H TL; 120/70ZR19 60W TL; 130/60B19 61H TL; 130/60B19 66H; MH90-21 54H TL; 120/70B21 68H TL; 130/60B21 63H TL"}', 50, 1, 1, NOW(), NOW());
