INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (3, '1776952.0', 'Dunlop Trailmax Mission Tires', 'dunlop-trailmax-mission-tires-1776952.0', 'Dunlop', 1, 'STREET BIKE', 'Dual Road Bias Dot / 60 On Road 40 Off Road / 50 On Road 50 Off Road / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P824886', 163.99, '377.95', '377.95', 'Save up to Save $65.96 17%', 4.7, 280, 'nan', 'nan', 'Front; Rear', 10, '120/90-17 64T TL; 130/80B17 65T TL; 150/70B17 69T TL; 170/60B17 72T TL; 140/80B18 70T TL; 150/70B18 70T TL; 100/90-19 57T TL; 110/80-19 59T TL; 120/70B19 60T TL; 90/90-21 54T TL', 10, 'Dunlop Trailmax Mission Tires The Dunlop Trailmax Mission Tire is a "50/50" adventure tire that is ready for even the biggest ADV rigs. Dunlop''s "Staggered Step" tread pattern delivers sure-footed wet weather road carving and predictable grip on the trails via the large, deep tread pattern. Tread blocks that wrap up and around the sidewall increase puncture resistance and traction while adding to the tire''s technical appearance. Revised rubber compounds help extend tire life.', '50% on-road and 50% off-road performance Tread blocks feature Dunlop''s "Staggered Step" design Wraparound lugs reduce punctures and add grip Deep grooves improve wet weather grip and offer a more aggressive biting edge off-road Improved tread compounds balance off-road performance with class leading mileage Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_trailmax_mission_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_trailmax_mission_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dual Road Bias Dot / 60 On Road 40 Off Road / 50 On Road 50 Off Road / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/90-17 64T TL; 130/80B17 65T TL; 150/70B17 69T TL; 170/60B17 72T TL; 140/80B18 70T TL; 150/70B18 70T TL; 100/90-19 57T TL; 110/80-19 59T TL; 120/70B19 60T TL; 90/90-21 54T TL"}', 50, 1, 1, NOW(), NOW());
