INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (4, '10202407.0', 'Pirelli Diablo Rosso IV Corsa Tires', 'pirelli-diablo-rosso-iv-corsa-tires-10202407.0', 'Pirelli', 4, 'STREET BIKE', 'Hypersport Dot / Dot Tire / Sportbike Tire / Multi Compound Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P986108', 162.16, '447.46', '447.46', 'Save up to Save $113.60 25%', 4.9, 51, 'nan', 'nan', 'Front; Rear', 9, '110/70ZR17 54W; 120/70ZR17 58W; 150/60ZR17 66W; 180/55ZR17 73W; 180/60ZR17 75W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W; 200/60ZR17 80W', 9, 'Pirelli Diablo Rosso IV Corsa Tires The fiercer version of the Diablo Rosso IV, the Diablo Rosso IV Corsa is intended for thrill seekers and bike-tuning enthusiasts looking for more than a supersport tire. Experience higher grip in dry conditions, enhanced hard handling and consistent performance even after multiple hard riding sessions.', 'Designed for supersport, naked and crossover motorcycles for aggressive road use Outstanding cornering support at extreme lean angles Increased tire solidity and lateral thrust while cornering Reduced number of lateral grooves, more rubber to the road at mid-lean Dual compound layout with soft shoulders for both front and rear tires Blackwall Tubeless (TL) W-rated for speeds of 168+ MPH Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/pirelli_diablo_rosso_iv_corsa_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/pirelli_diablo_rosso_iv_corsa_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Hypersport Dot / Dot Tire / Sportbike Tire / Multi Compound Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "110/70ZR17 54W; 120/70ZR17 58W; 150/60ZR17 66W; 180/55ZR17 73W; 180/60ZR17 75W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W; 200/60ZR17 80W"}', 50, 1, 1, NOW(), NOW());
