INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (5, '880485.0', 'Pirelli Angel GT Tires', 'pirelli-angel-gt-tires-880485.0', 'Pirelli', 2, 'STREET BIKE', 'Sport Touring Radial Do / Sportbike Tire / Touring Tire / Dot Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P237529', 162.48, '350.31', '350.31', 'Save up to Save $93.67 27%', 4.7, 118, 'nan', 'nan', 'Front; Rear', 15, '120/70ZR17 58W; 120/70ZR17 58W A Spec; 150/70R17 69V; 160/60ZR17 69W; 180/55ZR17 73W; 180/55ZR17 73W A Spec; 190/50ZR17 73W; 190/50ZR17 73W A Spec; 190/55ZR17 75W; 190/55ZR17 75W A Spec; 190/55ZR17 75W D Spec; 110/80ZR18 58W; 120/70ZR18 59W; 160/60ZR18 70W; 110/80R19 59V', 15, 'Pirelli Angel GT Tires The Pirelli Angel GT Tires have been setting a higher standard for sport touring and commuter bikes. Featuring high mileage along with legendary Pirelli performance, the Angel GT Tires are the perfect addition to modern sport and sport touring bikes. The dual compound gives you the performance and handling you need in the corners, while the center of the tire provides longer tire life and superior traction.', '(W)-rated for speeds of 168+ mph (V)-rated for speeds up to 149 mph Ideal for sport riders looking for increased mileage without sacrificing grip and traction Extended Mileage Sport (EMS) tires provide best-in-class for mileage and grip Rear tires feature new Bi-compound formula improves cornering traction Available in "Reinforced" for heavyweight touring bikes, two-up riding, or when required by OEM specifications "A Spec" tires feature a reinforced, 2-ply carcass Improved wet grip Tubeless Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/pirelli_angel_gt_front_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/pirelli_angel_gt_front_tires.webp", "https://americaapi.kaafifoods.com/storage/products/pirelli_angel_gt_tires.webp", "https://americaapi.kaafifoods.com/storage/products/pirelli_angel_gt_rear_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sport Touring Radial Do / Sportbike Tire / Touring Tire / Dot Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "120/70ZR17 58W; 120/70ZR17 58W A Spec; 150/70R17 69V; 160/60ZR17 69W; 180/55ZR17 73W; 180/55ZR17 73W A Spec; 190/50ZR17 73W; 190/50ZR17 73W A Spec; 190/55ZR17 75W; 190/55ZR17 75W A Spec; 190/55ZR17 75W D Spec; 110/80ZR18 58W; 120/70ZR18 59W; 160/60ZR18 70W; 110/80R19 59V"}', 50, 1, 1, NOW(), NOW());
