INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (9, '1790970.0', 'Michelin Commander III Cruiser Tires', 'michelin-commander-iii-cruiser-tires-1790970.0', 'Michelin Tires', 2, 'STREET BIKE', 'Customcruisertouring Ra / Cruiser Tire / Harley Tire / Touring Tire', 'Harley-Davidson', 'Harley Sportster / Harley Fxfxr / Harley Street / Harley Touring / Harley V Rod / Harley Softail / Harley Dyna / Harley Dyna Fat Bo / Harley Dyna Street / Harley Dyna Super / Harley Dyna Switch / Harley Softail Del / Harley Softail Deu / Harley Softail Fat / Harley Softail Her / Harley Softail Nig / Harley Sportster 1 / Harley Sportster 8 / Harley Sportster I / Harley Touring Ele / Harley Touring Roa / Harley Touring Str', '1990 - 2025', 'P836176', 170.99, '436.95', '436.95', 'Save up to Save $103.96 24%', 4.7, 226, 'nan', 'nan', 'Front; Rear', 14, '140/90B15 76H Reinforced TL/TT; 150/90B15 74H TL/TT; 170/80B15 77H TL/TT; 180/70B15 76H TL/TT; 130/90B16 73H Reinforced TL/TT; 140/90B16 77H Reinforced TL/TT; 150/80B16 77H Reinforced TL/TT; 140/75R17 67V TL; 160/70B17 73V TL/TT; 200/55R17 78V TL; 100/90B19 57H TL/TT; 110/90B19 62H TL/TT; 80/90B21 54H Reinforced TL/TT; 90/90B21 54H TL/TT', 15, 'Michelin Commander 3 Cruiser Tires Engineered for V-twin and custom cruisers seeking head turning style and trusted performance Silica Rain Technology for outstanding wet grip and even wear patterns Amplified Density Technology for sharp handling and solid road feedback Aramid fiber crown ply for durability, high speed stability and reduced weight Improved wet performance and legendary mileage, even better than the Commander II Optimized tread grooves effectively channel water for excellent wet road confidence Premium ''''velvet'''' sidewall detailing enhances your bike''s custom look Square bead wires for improved rigidity, handling and straightforward installation Available in "Reinforced" for heavyweight touring bikes, two-up riding, or when required by OEM specifications Please Note: The Commander III "Touring" and Commander III "Cruiser" are unique tires. Each model features a specific set of sizes, distinct sidewall designs and slightly different tread patterns. Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount The Michelin Commander III Cruiser Tire carries forward the legacy of its legendary predecessor, the Commander II, setting a new standard for V-twin and custom cruiser tires. True to Michelin''s ''Total Performance'' promise, the Commander III Cruiser delivers an unbeatable combination of dry road authority, enhanced wet weather grip and exceptional longevity. Building on the Commander II''s renowned durability (proven capable of up to 25,000 miles), this new generation tire gives cruiser riders the confidence to roll on, backed by performance that doesn''t quit and looks that turn heads. It’s the new legend for your cruiser. Exceptional Longevity Building on legendary mileage, the Commander III Cruiser offers even greater tread life. Silica Rain Tech ensures even wear, while the aramid ply adds durability for countless miles of style. Solid Handling & Stability Amplified Density Technology provides a rigid casing for excellent feedback and responsive handling. The high density carcass and aramid plies ensure V-twin stability and nimble control on any road. Confident Wet Grip Ride confidently in the rain. Silica Rain Technology delivers outstanding wet grip, while deep tread grooves efficiently evacuate water. Stay planted and in control, whatever the weather. Cruiser Style & Performance Get the complete package with impressive grip, long tread life and stable handling. The unique tread pattern and premium ''velvet'' sidewalls ensure your V-twin looks as great as it performs.', 'nan', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_commander_iii_cruiser_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_commander_iii_cruiser_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Customcruisertouring Ra / Cruiser Tire / Harley Tire / Touring Tire", "Make": "Harley-Davidson", "Model": "Harley Sportster / Harley Fxfxr / Harley Street / Harley Touring / Harley V Rod / Harley Softail / Harley Dyna / Harley Dyna Fat Bo / Harley Dyna Street / Harley Dyna Super / Harley Dyna Switch / Harley Softail Del / Harley Softail Deu / Harley Softail Fat / Harley Softail Her / Harley Softail Nig / Harley Sportster 1 / Harley Sportster 8 / Harley Sportster I / Harley Touring Ele / Harley Touring Roa / Harley Touring Str", "Tire Size": "140/90B15 76H Reinforced TL/TT; 150/90B15 74H TL/TT; 170/80B15 77H TL/TT; 180/70B15 76H TL/TT; 130/90B16 73H Reinforced TL/TT; 140/90B16 77H Reinforced TL/TT; 150/80B16 77H Reinforced TL/TT; 140/75R17 67V TL; 160/70B17 73V TL/TT; 200/55R17 78V TL; 100/90B19 57H TL/TT; 110/90B19 62H TL/TT; 80/90B21 54H Reinforced TL/TT; 90/90B21 54H TL/TT"}', 50, 1, 1, NOW(), NOW());
