INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (10, '10324912.0', 'Pirelli Diablo Supercorsa SP V4 Tires', 'pirelli-diablo-supercorsa-sp-v4-tires-10324912.0', 'Pirelli', 4, 'STREET BIKE', 'Hypersport Dot / Road Race Dot And Non D / Multi Compound Tire / Dot Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P1057226', 199.66, '513.79', '513.79', 'Save up to Save $130.44 25%', 5.0, 37, 'nan', 'nan', 'Front; Rear', 10, '110/70ZR17 54W; 120/70ZR17 58W; 140/70ZR17 66W; 150/60ZR17 66W; 180/55ZR17 73W; 180/60ZR17 75W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W; 200/60ZR17 80W', 10, 'Pirelli Diablo Supercorsa SP V4 Tires Now on to its fourth generation, completely revised from the ground up, the Pirelli Diablo Supercorsa SPV4 Tires are as close as you can get to a race tire that is still street legal. Using compounds and structure directly pulled from the tires used in the FIM Superbike World Championship. Pirelli''s motto is in full display here "we sell what we race, we race what we sell" and when you lean into that race spec compound on the shoulder of the tires you''ll feel it. Perfectly at home carving your way through a mountain pass or knee down at the track, the Supercorsa SP V4 tires will make you the only thing holding your bike back. Pirelli first started this series of tires to parallel the spirit of the World Superbike Championships, where you can buy the same motorcycles you see at the track for yourself. Then used the lessons learned and experience gained through years of its races to apply back into the design of the tire. Truly a race tire you can enjoy on the street.', 'FLASH grooves for homogeneous thrust at any lean angle and performance consistency turn after turn Compounds and profiles directly from the FIM World Superbike Championship for ultimate grip and lap time record setting Tire structure directly derived from World SBK Racing profiles directly derived from World SBK Outstanding riding ease, line holding and high speed stability Racing compound on the shoulders and slick road compound in the central band Homogeneous thrust at any lean angle and performance consistency turn after turn Optimized contact patch providing greater traction and precision when cornering Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/pirelli_diablo_supercorsa_spv4_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/pirelli_diablo_supercorsa_spv4_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Hypersport Dot / Road Race Dot And Non D / Multi Compound Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "110/70ZR17 54W; 120/70ZR17 58W; 140/70ZR17 66W; 150/60ZR17 66W; 180/55ZR17 73W; 180/60ZR17 75W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W; 200/60ZR17 80W"}', 50, 1, 1, NOW(), NOW());
