INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (12, '10482241.0', 'Dunlop Sportmax Q5A Tires', 'dunlop-sportmax-q5a-tires-10482241.0', 'Dunlop', 2, 'STREET BIKE', 'Hypersport Dot / Dot Tire / Touring Tire / Sportbike Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P1132893', 146.99, '300.95', '300.95', 'Save up to Save $60.96 20%', 4.8, 6, 'nan', 'nan', 'Front; Rear', 11, '140/70R17 66H TL; 130/70ZR16 61W TL; 110/70R17 54H TL; 120/60ZR17 55W TL; 120/70ZR17 58W TL; 150/60R17 66H TL; 160/60ZR17 69W TL; 180/55ZR17 73W TL; 190/50ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL', 11, 'Dunlop Sportmax Q5A Tires The Sportmax Q5A tire provides unmatched riding performance by advancing the proven designs of Dunlop''s iconic Roadsport and Q Series lines. With Multi-Tread technology, this tire achieves a balance between durability and dexterity, featuring a long-lasting compound at the center and high-adhesion materials on the sides for superior handling and grip. The utilization of Jointless Belt technology in both the front and rear tires enhances comfort, curtails expansion at high velocities, and delivers remarkable stability and feedback. Additionally, an innovative compound that incorporates Carbon R and Hi Silica X has been introduced to enhance grip under both dry and wet conditions.', 'Enhanced wet and dry grip Outstanding mileage without sacrificing handling or grip Multi-Tread technology - long-wearing compound in the center of the rear tread flanked by lateral-grip compounds Jointless Belt (JBL) technology - improves compliance and comfort, reduces dynamic growth at high speeds and provides exceptional feel and stability New compound implements Carbon R and Hi Silica X to increase both dry and wet grip performance Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop11070_r17_mc54_h_dun_sportmax_q5_abltl_1800x1800.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop11070_r17_mc54_h_dun_sportmax_q5_abltl_1800x1800.webp", "https://americaapi.kaafifoods.com/storage/products/dunlop11070_r17_mc54_h_dun_sportmax_q5_abltl.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Hypersport Dot / Dot Tire / Touring Tire / Sportbike Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "140/70R17 66H TL; 130/70ZR16 61W TL; 110/70R17 54H TL; 120/60ZR17 55W TL; 120/70ZR17 58W TL; 150/60R17 66H TL; 160/60ZR17 69W TL; 180/55ZR17 73W TL; 190/50ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL"}', 50, 1, 1, NOW(), NOW());
