INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (13, '10144070.0', 'Michelin Road 6 Tires', 'michelin-road-6-tires-10144070.0', 'Michelin Tires', 2, 'STREET BIKE', 'Sport Touring Radial Do / Touring Tire / Sportbike Tire / Multi Compound Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P955302', 208.99, '437.95', '437.95', 'Save up to Save $115.96 26%', 4.7, 294, 'nan', 'nan', 'Front; Rear', 14, '110/70ZR17 54W; 120/60ZR17 55W; 120/70ZR17 58W; 140/70ZR17 66W; 150/60ZR17 66W; 150/70ZR17 69W; 160/60ZR17 69W; 170/60ZR17 72W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 120/70ZR18 59W; 110/80ZR19 59W; 120/70ZR19 60W', 14, 'Michelin Road 6 Tires Patented Water Evergrip Tech tread pattern for exceptional water evacuation Patented Silica Technology tread compound for consistent grip Michelin''s 2CT+ Tech (front and rear) for better rigidity and stability through corners for confident handling Delivers 15% more wet grip than Road 5 Delivers 10% longer tread life than the Road 5 Superb grip in both wet and dry conditions Designed for consistent performance throughout the tire''s life Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount The Michelin Road 6 continues the legendary Road series, offering exceptional cornering and mileage, rain or shine. Featuring 2CT+ Tech in front and rear for enhanced lean rigidity and cornering stability, the Road 6 embodies two decades of innovation for the ultimate all around street tire. Exceptional Wet Grip Ride confidently in the wet. The Road 6 combines Silica Technology and Water Evergrip Tech for 15% more wet grip than the Road 5. Experience secure handling and improved braking, keeping you connected in any weather. Confident Cornering Conquer turns with the Road 6. Now with 2CT+ Technology in both front and rear tires, experience enhanced lean rigidity and stability. Enjoy precise feedback and confident control through every corner. Proven Reliability Go the distance with the Road 6. Enjoy 10% longer tread life than the Road 5, thanks to two decades of Michelin innovation. This tire offers lasting performance and reliability for countless miles of riding. Legendary Performance The Road 6 continues its iconic lineage, elevating the renowned Road series performance. It delivers an unmatched blend of grip, longevity, and stability, making it the ultimate all around tire for diverse street riding.', 'nan', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_road6_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_road6_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sport Touring Radial Do / Touring Tire / Sportbike Tire / Multi Compound Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "110/70ZR17 54W; 120/60ZR17 55W; 120/70ZR17 58W; 140/70ZR17 66W; 150/60ZR17 66W; 150/70ZR17 69W; 160/60ZR17 69W; 170/60ZR17 72W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 120/70ZR18 59W; 110/80ZR19 59W; 120/70ZR19 60W"}', 50, 1, 1, NOW(), NOW());
