INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (14, '10375972.0', 'Michelin Power 6 Tires', 'michelin-power-6-tires-10375972.0', 'Michelin Tires', 1, 'STREET BIKE', 'Dot Tire / Sportbike Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P1083803', 186.99, '435.95', '435.95', 'Save up to Save $109.96 25%', 4.9, 43, 'nan', 'nan', 'Front; Rear', 10, '110/70ZR17 54W; 120/70ZR17 58W; 140/70ZR17 66W; 150/60ZR17 66W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W; 240/45ZR17 82W', 10, 'Michelin Power 6 Tires Michelin''s premium sport bike tire designed for exhilarating road performance Optimized grip for both wet and dry conditions, ensuring confidence in every ride Delivers precise handling and improved road feedback for a superior riding experience Utilizes development tools and insights derived from MotoGP technology 100% road focused performance, building on the success of the acclaimed Power 5 Suitable for a wide range of sport bikes with engines exceeding 300cc Please Note: The Michelin Power 5 and Michelin Pilot Power 2CT lines will continue to be available for the foreseeable future. Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount Unleash the full potential of your sport bike with the Michelin Power 6, the latest evolution in street riding tire technology. Building on the acclaimed performance of the Power 5, the Power 6 is meticulously engineered for riders who demand optimal road performance, whether carving through dry corners or navigating challenging wet conditions. With an emphasis on razor sharp handling and enhanced road feedback, this tire leverages MotoGP derived development insights to deliver an unparalleled riding experience. Designed for bikes over 300cc, the Power 6 is the new benchmark for sporty road riding. Superb Grip And Sharp Handling Experience exceptional wet and dry grip with the Power 6''s advanced compounds. Enjoy precise, agile handling and enhanced road feedback for a connected, confidence inspiring ride in all conditions. Race Inspired Road Dominance Leveraging MotoGP development insights, the Power 6 sets a new benchmark. Succeeding the Power 5, it offers peak performance in handling, grip and feedback. Upgrade to Power 6 for the ultimate street riding experience.', 'nan', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_power6_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_power6_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Sportbike Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "110/70ZR17 54W; 120/70ZR17 58W; 140/70ZR17 66W; 150/60ZR17 66W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W; 240/45ZR17 82W"}', 50, 1, 1, NOW(), NOW());
