INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (17, '10267934.0', 'Dunlop Q5S Sportmax Tires', 'dunlop-q5s-sportmax-tires-10267934.0', 'Dunlop', 1, 'STREET BIKE', 'Hypersport Dot / Multi Compound Tire / Dot Tire / Sportbike Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P1025678', 205.99, '425.95', '425.95', 'Save up to Save $99.96 23%', 4.9, 29, 'nan', 'nan', 'Rear; Front', 9, '110/70ZR17 54W; 120/70ZR17 58W; 140/70ZR17 66W; 150/60ZR17 66W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W', 9, 'Dunlop Q5S Sportmax Tires The Dunlop Sportmax Q5S, in its fifth iteration, arrives as a DOT-compliant tire designed to meet the rigorous demands of both track-day enthusiasts and street riders. This tire is an evolution, drawing upon the favorable elements from the well-received Sportmax Q3+ and Dunlop''s advanced MotoAmerica-spec road race tires. It incorporates Dunlop''s prime technologies, resulting in a track and street tire that excels without compromise. The Q5S offers enhanced construction, profile, compounds, and tread pattern to deliver lighter, more agile handling and superior grip in both dry and wet conditions, all while providing exceptional feel regardless of the riding environment.', 'Even more user-friendly, as dry and wet grip, tire compliance, and warm-up times have all been improved New race tire derived compounds provide incredible grip Updated profiles increase footprints at more extreme lean angles to give you more tire on the road for more grip and less slip Made in USA Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_q5_s_sportmax_tires_1800x1800.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_q5_s_sportmax_tires_1800x1800.webp", "https://americaapi.kaafifoods.com/storage/products/dunlop_q5_s_sportmax_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "STREET BIKE", "Product Type": "Hypersport Dot / Multi Compound Tire / Dot Tire / Sportbike Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "110/70ZR17 54W; 120/70ZR17 58W; 140/70ZR17 66W; 150/60ZR17 66W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W"}', 50, 1, 1, NOW(), NOW());
