INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (18, '270447.0', 'Michelin Pilot Power 2CT Tires', 'michelin-pilot-power-2ct-tires-270447.0', 'Michelin Tires', 4, 'STREET BIKE', 'Hypersport Dot / Race Tire / Sportbike Tire / Dot Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P246272', 144.99, '305.95', '305.95', 'Save up to Save $68.96 23%', 4.8, 279, 'nan', 'nan', 'Front; Rear', 10, '110/70ZR17 54W; 120/60ZR17 55W; 120/65ZR17; 120/70ZR17 58W; 150/60ZR17 66W; 160/60ZR17 69W; 170/60ZR17; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W', 10, 'Michelin Pilot Power 2CT Tires The Michelin Pilot Power 2CT tires feature dual-compound technology to the already renowned Pilot Power range. The 2CT tires are intended for the most demanding sportbike riders, who use their bikes both on the road and for track days. Its tread is separated into three areas, incorporating different compounds. This provides numerous benefits in terms of grip, handling and acceleration and braking on wet surfaces.', 'Real Moto GP technology from the tire company that has won 15 consecutive GPWorld Championships 20% softer rubber mix on the edges of the tread yields phenomenal cornering grip Unprecedented lean angles: 51.2 degrees in the dry on Michelin''s test track Precise handling and feedback Track Day tire that is equally at home on the road Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_tires_tire_pilot_pwr2_ct.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_tires_tire_pilot_pwr2_ct.webp", "https://americaapi.kaafifoods.com/storage/products/michelin_pilot_power2_ct_front_tires.webp", "https://americaapi.kaafifoods.com/storage/products/michelin_pilot_power2_ct_tires.webp", "https://americaapi.kaafifoods.com/storage/products/michelin_pilot_power2_ct_rear_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Hypersport Dot / Race Tire / Sportbike Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "110/70ZR17 54W; 120/60ZR17 55W; 120/65ZR17; 120/70ZR17 58W; 150/60ZR17 66W; 160/60ZR17 69W; 170/60ZR17; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W"}', 50, 1, 1, NOW(), NOW());
