INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (19, '10144084.0', 'Michelin Road 6 GT Tires', 'michelin-road-6-gt-tires-10144084.0', 'Michelin Tires', 2, 'STREET BIKE', 'Dot Tire / Sportbike Tire / Touring Tire / Multi Compound Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P955305', 245.99, '458.95', '458.95', 'Save up to Save $120.96 26%', 4.8, 132, 'nan', 'nan', 'Front; Rear', 4, '120/70ZR17 58W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W', 4, 'Michelin Road 6 GT Tires Specifically designed for the demands of heavier touring and sport touring motorcycles Patented Water Evergrip Tech tread pattern for superior water evacuation on loaded journeys Patented Silica Technology tread compound for consistent grip under heavier loads Michelin''s 2CT+ Tech (front and rear) for enhanced rigidity & stability, crucial for touring machines Delivers 15% increased wet grip over the Road 5 GT Offers 10% longer tread life than the Road 5 GT Optimized for superb all weather grip on heavier motorcycles Engineered for lasting performance throughout the tire''s lifespan on touring bikes Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount The Michelin Road 6 GT Tire takes the celebrated performance of its predecessor, the Road 5 GT and elevates it for the specific demands of heavier touring and sport touring motorcycles. Engineered to confidently manage high mileage journeys in all weather conditions, the Road 6 GT features Michelin''s 2CT+ Technology in both front and rear tires. This enhances rigidity when leaned over, delivering crucial stability through corners for loaded machines. By integrating advanced Silica Technology compounds with the innovative Water Evergrip Tech tread pattern, Michelin achieves an impressive 15% increase in wet grip and a 10% boost in tread longevity compared to the Road 5 GT. The Road 6 GT embodies two decades of Michelin''s relentless innovation, offering the ultimate tire solution for riders who demand the best for their grand touring adventures. Increased Tread Life Ride further with the Road 6 GT, offering 10% longer tread life than the Road 5 GT. Engineered for durability and backed by two decades of expertise, expect reliable, consistent performance for extended tours. Superior Heavy Load Stability Michelin''s 2CT+ Technology in front and rear Road 6 GT tires increases lean rigidity. This delivers improved stability and feedback, crucial for managing the dynamics of heavier, loaded motorcycles for precise cornering control. Advanced Wet Grip The Road 6 GT delivers 15% more wet grip than the Road 5 GT, thanks to Silica Technology and Water Evergrip Tech. Experience secure handling and braking on wet roads, even with fully loaded touring bikes. Ultimate Touring Tire Engineered for heavier sport-touring and grand touring bikes, the Road 6 GT combines exceptional wet grip, extended mileage and load stability. It sets a new benchmark for ultimate long-distance performance and reliability.', 'nan', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_road6_gt_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_road6_gt_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Sportbike Tire / Touring Tire / Multi Compound Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "120/70ZR17 58W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W"}', 50, 1, 1, NOW(), NOW());
