INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (21, '10340860.0', 'Dunlop Trailmax Raid Tires', 'dunlop-trailmax-raid-tires-10340860.0', 'Dunlop', 1, 'STREET BIKE', 'Dual Road Radial Dot / Dual Road Bias Dot / 50 On Road 50 Off Road / 40 On Road 60 Off Road', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1065584', 172.99, '377.95', '377.95', 'Save up to Save $65.96 17%', 4.3, 43, 'nan', 'nan', 'Front; Rear', 9, '130/80-17 65S TL; 140/80-17 69S TL; 150/70R17 69T TL; 170/60R17 72T TL; 140/80-18 70S TL; 150/70R18 70T TL; 110/80R19 59T TL; 120/70R19 60T TL; 90/90-21 54T TL', 9, 'Dunlop Trailmax Raid Tires The Dunlop Trailmax Raid Tires provide excellent off-road traction and cornering grip, outstanding wet grip, good chipping resistance, balanced handling and road-tire stability and performance.', '40% on-road / 60% off-road adventure tire (per Dunlop) Tire design and rider experience favors approximately 50% on-road / 50% off-road bias Dynamic Front Formula (DFF) is a tire design method utilizing an intricately balanced combination of section profile, carcass material properties and assembly process to provide exceptional handling Hi Silica is a highly dispersible high surface area silica used to increase the silica filler ratio to promote compound flexibility at low temperatures and provide tremendous wet grip and good durability Carcass Tension Control System (CTCS) utilizes variable tension across the whole carcass width to optimize the contact patch for the ideal footprint and remarkable handling Jointless Belt construction (JLB) in radial sizes eliminates the belt overlap, resulting in smoother handling, minimizes the tread center’s dynamic growth at high speed, and reduces distortion and excessive heat build-up Aggressive tread pattern derived from our popular D908RR has been optimized to reduce rolling noise and provide improved road performance without sacrificing off-road performance Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_trailmax_raid_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_trailmax_raid_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dual Road Radial Dot / Dual Road Bias Dot / 50 On Road 50 Off Road / 40 On Road 60 Off Road", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "130/80-17 65S TL; 140/80-17 69S TL; 150/70R17 69T TL; 170/60R17 72T TL; 140/80-18 70S TL; 150/70R18 70T TL; 110/80R19 59T TL; 120/70R19 60T TL; 90/90-21 54T TL"}', 50, 1, 1, NOW(), NOW());
