INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (22, '10482460.0', 'Bridgestone Battlax T33 Sport Touring Tires', 'bridgestone-battlax-t33-sport-touring-tires-10482460.0', 'Bridgestone', 2, 'STREET BIKE', '100 On Road 0 Off Road / Dot Tire / Multi Compound Tire / Touring Tire', 'Honda', 'Touring', '1995 - 2025', 'P1133039', 204.75, '385.85', '385.85', 'Save up to Save $96.50 25%', 4.9, 20, 'nan', 'nan', 'Front; Rear', 15, '120/60ZR17 55W; 120/70ZR17 58W; 150/70ZR17 69W; 160/60ZR17 69W; 160/70ZR17 73W; 170/60ZR17 72W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 110/80ZR18 58W; 120/70ZR18 59W; 160/60ZR18 70W; 110/80R19 59V; 120/70R19 60V; 120/70ZR19 60W', 15, 'Bridgestone Battlax T33 Sport Touring Tires', 'Improved mileage of up to 47% compared to T32 Continuation of T32 shape for optimized grip, stability and handling Tread pattern features optimized land-sea ratio and pattern stiffness Excellent wet and dry condition performance Fits on light and heavy bikes Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount Technology: RC Polymer - Improves tread flexibility, rolling resistance and fuel economy ULTIMATEYE - Allows for good traction and improves wear life NanoPro-Tech Front Tire: Cross Belt - Flexible construction for lightweight stability Silica Rich Compound - Enhanced gripping capability in wet conditions and low temperatures & consistent, long-lasting grip Rear Tire: MS Belt & HTSPC - Provide lightweight stability and high shock absorption 3LC Dual Compound - Grip performance for all riding modes Silica Rich EX Compound - Enhanced gripping capability in wet conditions by increasing the amount of silica compared to conventional SILICA RICH Center of tire features a unique wear-resistant polymer Miles of Smiles The T33 Sport Touring tire preserves the excellent wet performance of its predecessor, the T32, while enhancing cornering, stability, and overall performance in dry conditions. Get a Grip The Battlax T33 Sport Touring tires deliver up to 47% improved mileage over their predecessor, the T32, thanks to a refined compound, pattern, and construction that optimize grip.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_t33_sport_touring_tires_front_1800x1800.webp', '["https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_t33_sport_touring_tires_front_1800x1800.webp", "https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_t33_sport_touring_tires_front.webp", "https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_t33_sport_touring_tires_rear.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "100 On Road 0 Off Road / Dot Tire / Multi Compound Tire / Touring Tire", "Make": "Honda", "Model": "Touring", "Tire Size": "120/60ZR17 55W; 120/70ZR17 58W; 150/70ZR17 69W; 160/60ZR17 69W; 160/70ZR17 73W; 170/60ZR17 72W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 110/80ZR18 58W; 120/70ZR18 59W; 160/60ZR18 70W; 110/80R19 59V; 120/70R19 60V; 120/70ZR19 60W"}', 50, 1, 1, NOW(), NOW());
