INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (25, '594633.0', 'Shinko 705 Dual Sport Tires', 'shinko-705-dual-sport-tires-594633.0', 'Shinko Tires', 2, 'STREET BIKE', '80 On Road 20 Off Road / Dual Sport Tire / Touring Tire / Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P148939', 92.61, '255.95', '255.95', 'Save up to Save $38.39 15%', 4.5, 438, 'nan', 'nan', 'Front; Front/Rear; Rear', 14, '120/70R17 58H TL; 120/90-17 64H TT; 130/80-17 65H TL; 130/90-17 68H TT; 140/80-17 69H TT; 150/70R17 69H TL; 170/60R17 72H TL; 120/80-18 62H TT; 150/70R18 70V TL; 4.10x18 59P TT; 110/80-19 59Q TL; 110/80R19 59H TL; 120/70R19 60H TL; 90/90-21 54H TL', 14, 'Shinko 705 Dual Sport Tires Designed for 80% street and 20% trail riding, the Shinko 705 has a versatile tread pattern for everything from the trail to the highway.', 'Rubber compound resists tearing during off road use 4-ply construction Front/Rear indicates that tire can go on either the front or rear on the bike Tires are bias ply except where indicated 150/70R18 TL 70V is a radial tire Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/shinko705_dual_sport_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/shinko705_dual_sport_tires.webp"]', '{"Wheel Location": "Front; Front/Rear; Rear", "Type": "STREET BIKE", "Product Type": "80 On Road 20 Off Road / Dual Sport Tire / Touring Tire / Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/70R17 58H TL; 120/90-17 64H TT; 130/80-17 65H TL; 130/90-17 68H TT; 140/80-17 69H TT; 150/70R17 69H TL; 170/60R17 72H TL; 120/80-18 62H TT; 150/70R18 70V TL; 4.10x18 59P TT; 110/80-19 59Q TL; 110/80R19 59H TL; 120/70R19 60H TL; 90/90-21 54H TL"}', 50, 1, 1, NOW(), NOW());
