INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (26, '1841637.0', 'Bridgestone Battlax BT46 Sport Touring Tires', 'bridgestone-battlax-bt46-sport-touring-tires-1841637.0', 'Bridgestone', 2, 'STREET BIKE', 'Sport Touring Bias Dot / Cruiser Tire / Harley Tire / Vintage Tire', 'Harley-Davidson', 'Touring', '1990 - 2025', 'P865273', 157.82, '329.99', '329.99', 'Save up to Save $98.63 30%', 4.7, 47, 'nan', 'nan', 'Front; Rear', 40, '120/80B17 61H; 100/90B16 54H; 110/90B16 59V; 120/80B16 60V; 130/90B16 67H; 130/90B16 67V; 150/80B16 71V; 100/80B17 52H; 110/70B17 54H; 110/80B17 57H; 110/80B17 57V; 120/70B17 58H; 120/90B17 64V; 130/70B17 62H; 130/80B17 65H; 130/90B17 68V; 140/70B17 66H; 140/80B17 69V; 150/70B17 69H; 150/70B17 69V; 90/90B18 51H; 100/80B18 53H; 100/90B18 56H; 100/90B18 56V; 110/80B18 58H; 110/80B18 58V; 110/90B18 61H; 110/90B18 61V; 120/80B18 62H; 120/90B18 65V; 130/70B18 63H; 130/80B18 66V; 140/70B18 67H; 140/70B18 67V; 150/70B18 70H; 4.00-18 64H; 100/90B19 57H; 100/90B19 57V; 3.25-19 54H; 90/90B21 54H', 41, 'Bridgestone Battlax BT-46 Sport Touring Tires Upgrading an icon is never easy. The Bridgestone BT46 Sport Touring Tire replaces and improves the long-standing BT45 Tire with the latest tire technology. Using "Silica Rich EX" technology, performance in wet conditions is improved by increasing the amount of silica. This grippy compound is then processed further using Bridgestone''s RC Polymer construction method to optimize the distribution of silica within the rubber compound. This improves tread flexibility allowing greater contact with the road surface in both hot and cold conditions. The reduction in molecular friction also improves rolling resistance and boosts fuel economy. Capturing a new set of riders, the BT46 is also available in popular vintage sportbike tire sizes. These sizes achieve a higher "V" speed rating.', 'Bias-ply construction designed for touring bikes and vintage sport motorcycles Common vintage sportbike sizes rated to "V" speed rating Silica Rich EX single compound composition RC Polymer construction technology NanoPro-Tech controlled micro structure Long-lasting compound on rear applications Increased wet performance All sizes tubeless (TL) Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_bt46_sport_touring_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_bt46_sport_touring_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sport Touring Bias Dot / Cruiser Tire / Harley Tire / Vintage Tire", "Make": "Harley-Davidson", "Model": "Touring", "Tire Size": "120/80B17 61H; 100/90B16 54H; 110/90B16 59V; 120/80B16 60V; 130/90B16 67H; 130/90B16 67V; 150/80B16 71V; 100/80B17 52H; 110/70B17 54H; 110/80B17 57H; 110/80B17 57V; 120/70B17 58H; 120/90B17 64V; 130/70B17 62H; 130/80B17 65H; 130/90B17 68V; 140/70B17 66H; 140/80B17 69V; 150/70B17 69H; 150/70B17 69V; 90/90B18 51H; 100/80B18 53H; 100/90B18 56H; 100/90B18 56V; 110/80B18 58H; 110/80B18 58V; 110/90B18 61H; 110/90B18 61V; 120/80B18 62H; 120/90B18 65V; 130/70B18 63H; 130/80B18 66V; 140/70B18 67H; 140/70B18 67V; 150/70B18 70H; 4.00-18 64H; 100/90B19 57H; 100/90B19 57V; 3.25-19 54H; 90/90B21 54H"}', 50, 1, 1, NOW(), NOW());
