INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (27, '10482253.0', 'Dunlop AE2 Tires', 'dunlop-ae2-tires-10482253.0', 'Dunlop', 2, 'STREET BIKE', 'Customcruisertouring Bi / Customcruisertouring Ra / Dot Tire / Multi Compound Tire', 'Harley-Davidson', 'Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard', '1990 - 2025', 'P1132895', 180.99, '453.95', '453.95', 'Save up to Save $79.96 18%', 4.6, 53, 'nan', 'nan', 'Front; Rear', 25, '130/90B16 73H TL; MT90B16 72H TL; MT90B16 72H WWW TL; MT90B16 74H TL; MT90B16 74H WWW TL; MU85B16 77H TL; MU85B16 77H WWW TL; 150/80B16 77H TL; 180/65B16 81H TL; 180/70B16 77H TL; 130/80B17 65H TL; 140/75R17 67V TL; 160/70B17 73V TL; 200/55R17 78V TL; 130/70B18 63H TL; 160/60R18 70V TL; 180/55B18 80H TL; 240/40R18 79V TL; 100/90-19 57H TL; 110/90B19 62H TL; 130/60B19 67H TL; MH90-21 54H TL; 90/90-21 54H TL; 120/70B21 68H TL; 130/60B21 69H TL', 25, 'Dunlop American Elite 2 Tires The AE2 tires mark an evolution from the iconic American Elite series, delivering a refreshed aesthetic with an optimized tread pattern and an updated compound formulation. This tire is crafted to extend mileage while improving performance in wet conditions. Utilizing Multi-Tread™ technology, the AE2 features a durable compound at the center of the rear tire, bordered by compounds designed for superior lateral grip. This not only ensures impressive longevity but also does not compromise on handling or traction. An enhancement in tread pattern design contributes to better wear distribution and increased mileage. Both the front and rear tires have been formulated with advanced compounds that bolster resistance to wear and performance during wet weather. The tires'' construction employs a cut-breaker design, providing a sturdy casing that effortlessly supports the weights and torques of a wide array of motorcycles, from the latest to older models, across cruiser, v-twin, and touring categories.', 'Optimized tread pattern Updated compound formula for improved wear resistance and wet-weather performance Multi-Tread technology - long-wearing compound in the center of the rear tread flanked by lateral-grip compounds Cut-breaker construction provides robust casing to handle weights and torques of most v-twin, cruiser and touring motorcycles Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_ae2_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_ae2_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Customcruisertouring Bi / Customcruisertouring Ra / Dot Tire / Multi Compound Tire", "Make": "Harley-Davidson", "Model": "Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard", "Tire Size": "130/90B16 73H TL; MT90B16 72H TL; MT90B16 72H WWW TL; MT90B16 74H TL; MT90B16 74H WWW TL; MU85B16 77H TL; MU85B16 77H WWW TL; 150/80B16 77H TL; 180/65B16 81H TL; 180/70B16 77H TL; 130/80B17 65H TL; 140/75R17 67V TL; 160/70B17 73V TL; 200/55R17 78V TL; 130/70B18 63H TL; 160/60R18 70V TL; 180/55B18 80H TL; 240/40R18 79V TL; 100/90-19 57H TL; 110/90B19 62H TL; 130/60B19 67H TL; MH90-21 54H TL; 90/90-21 54H TL; 120/70B21 68H TL; 130/60B21 69H TL"}', 50, 1, 1, NOW(), NOW());
