INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (28, '817463.0', 'Michelin Commander II Tires', 'michelin-commander-ii-tires-817463.0', 'Michelin Tires', 2, 'STREET BIKE', 'Customcruisertouring Bi / Customcruisertouring Ra / Cruiser Tire / Harley Tire', 'Harley-Davidson', 'Harley Sportster / Harley Fxfxr / Harley Street / Harley Touring / Harley V Rod / Harley Softail / Harley Dyna / Harley Dyna Fat Bo / Harley Dyna Street / Harley Dyna Super / Harley Dyna Switch / Harley Softail Del / Harley Softail Deu / Harley Softail Fat / Harley Softail Her / Harley Softail Nig / Harley Sportster 1 / Harley Sportster 8 / Harley Sportster I / Harley Touring Ele / Harley Touring Roa / Harley Touring Str', '1990 - 2025', 'P210011', 143.99, '398.95', '398.95', 'Save up to Save $74.96 19%', 4.9, 1939, 'nan', 'nan', 'Front; Rear', 17, '170/80B15 77H TL/TT; 130/90B16 73H TL/TT; 130/90B16 73H TL/TT Reinforced; 140/90B16 77H TL/TT; 150/80B16 77H TL/TT; 180/65B16 81H TL/TT; 120/90B17 64S TL/TT; 130/80B17 65H TL/TT; 140/80B17 69H TL/TT; 160/70B17 73V TL/TT; 110/90B18 61H TL/TT; 150/70B18 76H TL/TT; 240/40R18 79V TL; 100/90B19 57H TL/TT; 120/70ZR19 60W TL/TT; 80/90-21 54H TL/TT Reinforced; 90/90-21 54H TL/TT', 17, 'Michelin Commander II Tires Unrivaled tire life; Capable of covering up to 40,000 kilometers (Almost 25,000 miles) as proven in Michelin tests Superior wet weather grip and stability without compromising on durability, thanks to Silica Rain Technology Exclusive architecture with a rigid, high density carcass and aramid fiber crown ply allowing for exceptional maneuverability and stability, even at high speeds Amplified Density Technology helps deliver excellent feedback and handling Unique tread pattern and premium sidewall treatment for that classic eye catching cruiser style Available in "Reinforced" versions for heavyweight touring bikes or specific OEM requirements Please Note: Check your manufacturer''s specifications for required load ratings when replacing OE Tires. Notes : 140/75R17 size is a radial tire. It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount Set a new standard for your cruiser with the Michelin Commander II tire, engineered for longevity and impeccable performance. Designed to go the distance, the Commander II offers nearly double the mileage of its main competitors without sacrificing wet grip, maneuverability or stability. Whether you''re on a long tour or a daily ride, experience the confidence that comes with advanced Michelin technology, ensuring a smooth, stable and stylish journey. Record Mileage & All Weather Grip The Michelin Commander II offers class leading longevity, lasting nearly twice as long as competitors, up to 25,000 miles. Silica Rain Technology and deep tread grooves ensure outstanding wet grip and even wear for confident riding in all conditions. Stable Handling & Cruiser Style Experience superb stability and responsive handling with the Commander II. Its rigid carcass (Amplified Density Technology) and aramid crown ply provide excellent feedback and high speed stability. The unique tread and premium sidewall complete your cruiser''s look.', 'nan', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_commander_iii_touring_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_commander_iii_touring_tires.webp", "https://americaapi.kaafifoods.com/storage/products/michelin_commander_ii_front_tires.webp", "https://americaapi.kaafifoods.com/storage/products/michelin_commander_2-9b550.webp", "https://americaapi.kaafifoods.com/storage/products/michelin_commander_ii_rear_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Customcruisertouring Bi / Customcruisertouring Ra / Cruiser Tire / Harley Tire", "Make": "Harley-Davidson", "Model": "Harley Sportster / Harley Fxfxr / Harley Street / Harley Touring / Harley V Rod / Harley Softail / Harley Dyna / Harley Dyna Fat Bo / Harley Dyna Street / Harley Dyna Super / Harley Dyna Switch / Harley Softail Del / Harley Softail Deu / Harley Softail Fat / Harley Softail Her / Harley Softail Nig / Harley Sportster 1 / Harley Sportster 8 / Harley Sportster I / Harley Touring Ele / Harley Touring Roa / Harley Touring Str", "Tire Size": "170/80B15 77H TL/TT; 130/90B16 73H TL/TT; 130/90B16 73H TL/TT Reinforced; 140/90B16 77H TL/TT; 150/80B16 77H TL/TT; 180/65B16 81H TL/TT; 120/90B17 64S TL/TT; 130/80B17 65H TL/TT; 140/80B17 69H TL/TT; 160/70B17 73V TL/TT; 110/90B18 61H TL/TT; 150/70B18 76H TL/TT; 240/40R18 79V TL; 100/90B19 57H TL/TT; 120/70ZR19 60W TL/TT; 80/90-21 54H TL/TT Reinforced; 90/90-21 54H TL/TT"}', 50, 1, 1, NOW(), NOW());
