INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (29, '10468107.0', 'Michelin Road W GT Honda Gold Wing Tires', 'michelin-road-w-gt-honda-gold-wing-tires-10468107.0', 'Michelin Tires', 2, 'STREET BIKE', '100 On Road 0 Off Road / Dot Tire / Touring Tire', 'Honda', 'Honda Gold Wing', '1995 - 2025', 'P1125272', 221.99, '410.95', '410.95', 'Save up to Save $111.96 27%', 4.5, 47, 'nan', 'nan', 'Front; Rear', 3, '130/70R18 63H TL; 180/60R16 74H TL; 200/55R16 77H TL', 3, 'Michelin Road W GT Honda Gold Wing Tires Michelin presents the Road W GT tires, specially crafted for Honda Gold Wing motorcycles to deliver peak performance. Designed with endurance in mind, these tires feature wear resistance that extends travel distances, ensuring riders can confidently embark on longer journeys. Engineered for reliability, especially on wet roads, the Road W GT incorporates Michelin''s proven techniques from the Touring and Sport Touring niches. Sipes included in the front tire tread and the inclusion of silica in both front and rear tires enhance grip in challenging conditions. The tires also offer dependable handling and facilitate smooth cornering due to their sturdy 3-ply radial carcass construction, making them a suitable choice for Gold Wing enthusiasts seeking tires that match the quality of their ride.', 'Reliable wear resistance to go even further Proven wet grip thanks to Michelin''s road-tested and advanced technologies Sipes in the front tire tread Silica in both front and rear tires Trustworthy handling and cornering thanks to 3-ply radial carcass', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_road_wgt_honda_gold_wing_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_road_wgt_honda_gold_wing_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "100 On Road 0 Off Road / Dot Tire / Touring Tire", "Make": "Honda", "Model": "Honda Gold Wing", "Tire Size": "130/70R18 63H TL; 180/60R16 74H TL; 200/55R16 77H TL"}', 50, 1, 1, NOW(), NOW());
