an', 'nan', 'https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_hypersport_s23_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_hypersport_s23_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sportbike Tire / Hypersport Dot / Dot Tire / Multi Compound Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "140/70R17 66H TL; 110/70R17 54H TL; 120/70ZR17 58W TL; 150/60R17 66H TL; 160/60ZR17 69W TL; 180/55ZR17 73W TL; 190/50ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL"}', 50, 1, 1, NOW(), NOW());
