INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (31, '1819828.0', 'Michelin City Grip 2 Scooter Tire', 'michelin-city-grip-2-scooter-tire-1819828.0', 'Michelin Tires', 1, 'STREET BIKE', 'Scooter Tire / Dot Tire', 'Honda', 'Honda PCX150 / Ruckus, Yamaha Zuma / XMAX, Vespa Primavera / GTS 300, Suzuki Burgman 400', '2005 - 2025', 'P853988', 77.99, '211.95', '211.95', 'Save up to Save $52.96 25%', 4.6, 75, 'nan', 'nan', 'Front; Front/Rear; Rear', 34, '100/80-10 53L TL; 120/70-10 54L TL; 110/70-11 45L TL; 120/70-11 56L TL; 110/70-12 47S; 110/90-12 64S; 120/70-12 58S Reinforced; 130/70-12 62S Reinforced; 140/70-12 65S TL; 110/70-13 48S; 110/90-13 56S; 120/70-13 53S TL; 130/70-13 63S Reinforced; 140/60-13 63S TL; 150/70-13 64S; 90/90-14 52S Reinforced; 100/90-14 57S; 110/80-14 59S; 120/80-12 65S; 130/60-13 60S; 120/70-14 61S Reinforced; 120/80-14 58S TL; 140/60-14 64S Reinforced; 140/70-14 68S Reinforced; 150/70-14 66S; 120/70-15 56S; 130/80-15 63S TL; 90/80-16 51S; 100/80-16 50P; 100/80-16 50S; 110/70-16 52S; 120/80-16 60P; 120/80-16 60S; 140/70-16 65S', 34, 'Michelin City Grip 2 Scooter Tire The Michelin City Grip 2 Tires are back and ready for more. The City Grip 2 features an increased number of sipes that come in contact with the road as you lean into corners. This means increased excellent traction on wet pavement for your bike and piece of mind for you.', 'Excellent mileage Progressive Sipe Technology gradually increases sipe contact during corner for better grip on wet surfaces Some sizes available in reinforced sizing for heavier bikes or 2-up touring Reliable and reassuring handling and comfort Available in "Reinforced" for heavyweight touring bikes, two-up riding, or when required by OEM specifications Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Sold individually. "Front/Rear" option designates that this tire can fit both front or rear for certain applications.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_city_grip2_scooter_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_city_grip2_scooter_tires.webp"]', '{"Wheel Location": "Front; Front/Rear; Rear", "Type": "STREET BIKE", "Product Type": "Scooter Tire / Dot Tire", "Make": "Honda", "Model": "Honda PCX150 / Ruckus, Yamaha Zuma / XMAX, Vespa Primavera / GTS 300, Suzuki Burgman 400", "Tire Size": "100/80-10 53L TL; 120/70-10 54L TL; 110/70-11 45L TL; 120/70-11 56L TL; 110/70-12 47S; 110/90-12 64S; 120/70-12 58S Reinforced; 130/70-12 62S Reinforced; 140/70-12 65S TL; 110/70-13 48S; 110/90-13 56S; 120/70-13 53S TL; 130/70-13 63S Reinforced; 140/60-13 63S TL; 150/70-13 64S; 90/90-14 52S Reinforced; 100/90-14 57S; 110/80-14 59S; 120/80-12 65S; 130/60-13 60S; 120/70-14 61S Reinforced; 120/80-14 58S TL; 140/60-14 64S Reinforced; 140/70-14 68S Reinforced; 150/70-14 66S; 120/70-15 56S; 130/80-15 63S TL; 90/80-16 51S; 100/80-16 50P; 100/80-16 50S; 110/70-16 52S; 120/80-16 60P; 120/80-16 60S; 140/70-16 65S"}', 50, 1, 1, NOW(), NOW());
