INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (32, '1588626.0', 'Michelin Anakee Adventure Tires', 'michelin-anakee-adventure-tires-1588626.0', 'Michelin Tires', 2, 'STREET BIKE', '80 On Road 20 Off Road / Dual Sport Tire / Touring Tire / Multi Compound Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P647865', 161.99, '375.95', '375.95', 'Save up to Save $88.96 24%', 4.5, 171, 'nan', 'nan', 'Front; Rear', 13, '120/70 R17 58V; 130/80R17 65H TL/TT; 140/80R17 69H; 150/70R17 69V TL/TT; 160/60 R17 69H TL/TT; 170/60R17 72V; 180/55 R17 73V TL/TT; 110/80 R18 58V TL/TT; 150/70R18 70V TL/TT; 100/90-19 57V; 110/80R19 59V TL/TT; 120/70R19 60V TL/TT; 90/90-21 54V', 13, 'Michelin Anakee Adventure Tires Situated comfortably between the off-road biased 50/50 Anakee Wild tires and road biased 90/10 Anakee 3 tires, the 80/20 Anakee Adventure stands poised to handle hard-packed trail and any paved roads from there in between. Michelin''s proven 2CT and 2CT+ compounds offer excellent grip on wet and dry tarmac. Front applications feature 2CT technology with two different silica blends - one down the center of the tread and the second on the shoulders. This gives excellent traction at a range of lean angles, especially in wet conditions. On the back tire, 2CT+ technology is applied by layering different durometers of rubber around the main contact patch - enhancing the tire’s rigidity, stability at high speeds and ability to handle off-road terrain under load.The tread pattern gradually gets deeper along the sides for better traction on wet terrain.', '80% on-road / 20% off-road 2CT and 2CT+ compounds Fitment for popular ADV bikes including the BMW R1200GS Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_anakee_adventure_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_anakee_adventure_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "80 On Road 20 Off Road / Dual Sport Tire / Touring Tire / Multi Compound Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/70 R17 58V; 130/80R17 65H TL/TT; 140/80R17 69H; 150/70R17 69V TL/TT; 160/60 R17 69H TL/TT; 170/60R17 72V; 180/55 R17 73V TL/TT; 110/80 R18 58V TL/TT; 150/70R18 70V TL/TT; 100/90-19 57V; 110/80R19 59V TL/TT; 120/70R19 60V TL/TT; 90/90-21 54V"}', 50, 1, 1, NOW(), NOW());
