INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (33, '10005454.0', 'Dunlop Roadsmart 4 Tires', 'dunlop-roadsmart-4-tires-10005454.0', 'Dunlop', 2, 'STREET BIKE', 'Sport Touring Radial Do / Dual Road Radial Dot / Touring Tire / Multi Compound Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P875049', 230.83, '411.95', '411.95', 'Save up to Save $91.12 22%', 4.8, 59, 'nan', 'nan', 'Front; Rear', 8, '120/70ZR17; 160/60ZR17; 170/60ZR17; 180/55ZR17; 190/50ZR17; 190/55ZR17; 120/70ZR18; 120/70ZR19 60W', 8, 'Dunlop Roadsmart 4 Tires Dunlop''s Roadsmart 4 tires eliminate compromise for riders. They''ve improved mileage by 23% for the front and 26% for the rear with new technology, enhancing grip, comfort, and confidence in twisty roads. The new compound features Hi Silica X and Fine Carbon for wet grip and stopping power, while sidewall improvements enhance dry and wet handling comfort. The rear tires utilize Multi Tread Technology for longer-lasting center compounds and exceptional grip on the shoulders. Plus, revamped profiles offer 15% lighter steering for a more effortless and fatigue-free ride. Say goodbye to compromise and hit the road!', 'Hi Silica X and Fine Carbon technology to increase grip and decrease stopping distance in the wet Multi Tread Compound design helps top level performance throughout the life of the tire All new bead profile improves traction and slide control by minimizing buckling at full lean 15% lighter steering Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_roadsmart4.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_roadsmart4.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sport Touring Radial Do / Dual Road Radial Dot / Touring Tire / Multi Compound Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "120/70ZR17; 160/60ZR17; 170/60ZR17; 180/55ZR17; 190/50ZR17; 190/55ZR17; 120/70ZR18; 120/70ZR19 60W"}', 50, 1, 1, NOW(), NOW());
