INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (34, '10321534.0', 'Motoz Tractionator RallZ Tires', 'motoz-tractionator-rallz-tires-10321534.0', 'Motoz', 3, 'DIRT BIKE', '20 On Road 80 Off Road / Dot Dirt Tires / Dual Sport Tire / Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1055273', 138.99, '313.99', '313.99', 'nan', 4.6, 18, 'nan', 'nan', 'Rear; Front', 10, '130/80-17 65R TT; 150/70B17 69Q TL; 170/60B17 72Q TL; 120/90-18 65R TT; 140/80-18 70R TT; 150/70B18 70Q TL; 110/80B19 59Q TL; 120/70B19 60Q TL; 90/90B21 54Q TL; 90/90-21 54R TT', 10, 'Motoz Tractionator RallZ Tires The RallZ is the most aggressive ADV option in the Motoz lineup, offering supreme traction for those daring enough to leave the tarmac behind and set off on a real off-road adventure. Note: The Tube-Type Tractionator RallZ options are specifically designed for lighter single seat enduro bikes and are not designed for larger displacement adventure bikes.', 'Designed for 20% on-road / 80% off-road use Hybrid natural / synthetic rubber compound with silica Self-sharpening tread blocks Directional tread pattern Tubeless (TL) and Tube-Type (TT) options available Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_tractionator_rall_z_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_tractionator_rall_z_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "DIRT BIKE", "Product Type": "20 On Road 80 Off Road / Dot Dirt Tires / Dual Sport Tire / Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "130/80-17 65R TT; 150/70B17 69Q TL; 170/60B17 72Q TL; 120/90-18 65R TT; 140/80-18 70R TT; 150/70B18 70Q TL; 110/80B19 59Q TL; 120/70B19 60Q TL; 90/90B21 54Q TL; 90/90-21 54R TT"}', 50, 1, 1, NOW(), NOW());
