INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (35, '1814150.0', 'Metzeler Sportec M9 RR Tires', 'metzeler-sportec-m9-rr-tires-1814150.0', 'Metzeler', 1, 'STREET BIKE', 'Hypersport Dot / Multi Compound Tire / Sportbike Tire / Dot Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P850470', 159.55, '384.75', '384.75', 'Save up to Save $93.07 24%', 4.8, 61, 'nan', 'nan', 'Front; Rear', 16, '110/70R17 54H; 110/70ZR17 54W; 120/70ZR17 58W; 140/70R17 66H; 150/60R17 66H; 150/60ZR17 66W; 160/60ZR17 69W; 170/60R17 72V; 170/60R17 72W; 180/55ZR17 73W; 180/60ZR17 75W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W; 120/70R19 60V; 120/70R19 60W', 16, 'Metzeler Sportec M9 RR Tires "Ride the Unexpected." Metzeler''s simple tagline for the M9 RR hints at this tire''s wide range of talents. The M9 RR Tires answer the needs of sportbike riders who''ll take their miles however they can get them - from city streets to back roads to long interstates highways. And time on the track. Born in the era of yaw sensors, IMUs and traction assist, Metzeler engineers had electronic rider aids in mind from the onset of the M9 RR''s development. The dual compound construction balances the heavier carcass construction with the softer, grippier outer tread to reduce disruption between rider and bike when electronic rider aids intervene. The M9 RR is Metzeler''s first 100% silica compound tire in the supersport category. The full silica blend reaches operating temperatures quickly, resists overheating and effectively handles heat cycling over the life of the tire. Metzeler engineers saw an increase in mileage by more than 10% when compared to the Sportec M7 RR predecessor. What''s more significant is the M9 RR''s ability to maintain wet and dry performance further into its effective lifespan. Versus the competition, the detrimental effects of age and mileage have been greatly mitigated. When it does come time to spoon some fresh rubber onto your rims, the M9 RR Tires will still be delivering admirable levels of that "fresh" tire feel and performance.', 'Versatile hypersport tire Road, track and rain ready Engineered with electronic rider aids in mind Dual compound front and rear construction in all sizes Reduced time to temperature Metzeler''s first 100% silica high-performance tire Compound and advanced tread pattern inspire confidence in wet conditions Expected 10% mileage gains over M7 RR models W-rated for speeds up to 168 mph Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/metzeler_sportec_m9_rr_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/metzeler_sportec_m9_rr_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Hypersport Dot / Multi Compound Tire / Sportbike Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "110/70R17 54H; 110/70ZR17 54W; 120/70ZR17 58W; 140/70R17 66H; 150/60R17 66H; 150/60ZR17 66W; 160/60ZR17 69W; 170/60R17 72V; 170/60R17 72W; 180/55ZR17 73W; 180/60ZR17 75W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W; 120/70R19 60V; 120/70R19 60W"}', 50, 1, 1, NOW(), NOW());
