INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (36, '10571184.0', 'Michelin Anakee Adventure 2 Tires', 'michelin-anakee-adventure-2-tires-10571184.0', 'Michelin Tires', 2, 'STREET BIKE', '80 On Road 20 Off Road / Dot Tire / Touring Tire / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1177512', 170.99, '394.95', '394.95', 'Save up to Save $91.96 23%', 4.0, 4, 'nan', 'nan', 'Front; Rear', 9, '110/80R19 59V TL/TT; 120/70R17 58V TL/TT; 120/70R19 60V TL/TT; 150/70R17 69V TL/TT; 170/60R17 72V TL/TT; 180/55R17 73V TL/TT; 90/90-21 54V TL/TT; 110/80R18 58V TL/TT; 150/70R18 70V TL/TT', 9, 'Michelin Anakee Adventure 2 Tires Specifications: A capable street tire engineered for confidence on gravel and dirt Noise Reduction: Michelin testing shows a 30% drop in highway drone and -2 dB reduction in trackside noise Increased Longevity: A claimed +7% front and +21% rear increase in tire life (vs. original Anakee Adventure) 80% on-road / 20% off-road ADV tire Accels in ADV touring, mixed surfaces, and heavy payloads Advanced Technology: Michelin 2CT silica-based technology Enhances grip on wet surfaces Reinforced Radial-X Evo technology Maintains grip over the entire life of tire Tread & Compound: Engineered for long miles, wet performance, and full payloads Michelin silica technology Optimized tread design Michelin Premium Touch Design TT/TL design (all sizes) Sold each Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount Engineered as a highly-capable street tire that''s more than ready for gravel and dirt excursions, the Anakee Adventure 2 borrows from Michelin''s 130 years of tire building experience, giving a strong option to ADV riders who demand performance on all surfaces. A Quieter Journey The Anakee 2''s updated design answer the call of the original Anakee Adventure devotees: A quieter highway ride. And Michelin delivered. With a claimed 30% reduction in perceived highway drone, Michelin minimized harmonic frequency generation and reports a -2 dB cut in trackside-perceived flyby noise. Extended Longevity Proprietary 2CT Dual-Compound Technology with a longer-wearing center tread portion increases expected front tire life by 7% and rear tire life by 21%. Where the rubber meets the "road", riders can conquer the longest journey with confidence. All-Weather Traction The Anakee Adventure 2 Tire utilizes advanced silica-based compounds to ensure remarkable grip on wet surfaces, giving you the traction you need when conditions turn slick. Heavy-Load Stability Reinforced Radial-X Evo and Aramid Shield Technologies form a rigid, high-density casing that remain stable under heavy loads and resist punctures, making the Anakee Adventure 2 perfect for fully packed adventure touring setups.', 'nan', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_anakee_adventure2_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_anakee_adventure2_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "80 On Road 20 Off Road / Dot Tire / Touring Tire / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/80R19 59V TL/TT; 120/70R17 58V TL/TT; 120/70R19 60V TL/TT; 150/70R17 69V TL/TT; 170/60R17 72V TL/TT; 180/55R17 73V TL/TT; 90/90-21 54V TL/TT; 110/80R18 58V TL/TT; 150/70R18 70V TL/TT"}', 50, 1, 1, NOW(), NOW());
