INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (38, '10043020.0', 'Michelin Road Classic Tires', 'michelin-road-classic-tires-10043020.0', 'Michelin Tires', 2, 'STREET BIKE', 'Cruiser Tire / Harley Tire / Vintage Tire / Dot Tire', 'Harley-Davidson', 'Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard', '1990 - 2025', 'P895784', 183.99, '324.95', '324.95', 'Save up to Save $76.96 24%', 4.7, 44, 'nan', 'nan', 'Front; Rear', 20, '100/80B17 52H TL; 110/70B17 54H TL; 110/80B17 57V TL; 130/70B17 62H TL; 130/80B17 65H TL; 130/90B17 68V TL; 140/80B17 69V TL; 150/70B17 69V TL; 150/70R17 69H TL; 90/90B18 51H TL; 100/90-18 56H TL; 100/90-18 56V TL; 110/80B18 58V TL; 110/90B18 61V TL; 120/90B18 65V TL; 130/70B18 63H TL; 130/80B18 66V TL; 4.00B18 64H TL; 100/90B19 57V TL; 3.25B19 54H TL', 20, 'Michelin Road Classic Tires Optimize performance for your ageless classic. Michelin''s Road Classic Tires provide the rider with more cornering stability, straight line stability, and 50% more wet grip than its predecessor. With technical approval from Triumph and their most iconic street cruiser models, the Michelin Road Classic Tires offer rider confidence with a classic look.', 'Michelin Silica Rain Technology and a 26% void ratio provide 50% more wet grip than the previous generation Provides 50% more stability in cornering 40% more straight-line stability Bias ply technology and bias casing supported by two crown plies Technical approval from Triumph for its most iconic models (Bonneville, Street Twin, etc.) Tubeless Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_road_classic_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_road_classic_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Cruiser Tire / Harley Tire / Vintage Tire / Dot Tire", "Make": "Harley-Davidson", "Model": "Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard", "Tire Size": "100/80B17 52H TL; 110/70B17 54H TL; 110/80B17 57V TL; 130/70B17 62H TL; 130/80B17 65H TL; 130/90B17 68V TL; 140/80B17 69V TL; 150/70B17 69V TL; 150/70R17 69H TL; 90/90B18 51H TL; 100/90-18 56H TL; 100/90-18 56V TL; 110/80B18 58V TL; 110/90B18 61V TL; 120/90B18 65V TL; 130/70B18 63H TL; 130/80B18 66V TL; 4.00B18 64H TL; 100/90B19 57V TL; 3.25B19 54H TL"}', 50, 1, 1, NOW(), NOW());
