INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (39, '1278933.0', 'Michelin Road 5 Tires', 'michelin-road-5-tires-1278933.0', 'Michelin Tires', 2, 'STREET BIKE', 'Sport Touring Radial Do / Sportbike Tire / Touring Tire / Multi Compound Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P394394', 201.99, '347.95', '347.95', 'Save up to Save $52.96 15%', 4.8, 445, 'nan', 'nan', 'Front; Rear', 7, '120/60ZR17 55W; 120/70ZR17 58W; 150/70ZR17 69W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W', 7, 'Michelin Road 5 Tires The Road 5 is a premium all-purpose tire that actually maintains traction in wet conditions as the tire wears. This wet weather confidence has advanced inverted-pyramid Michelin XST Evo siping to thank. In a normal continuous-profile extruded cut sipe, the water carrying ability of a tire decreases as it wears down since the volume of the sipe decreases. With Michelin XST Evo siping, the tread cuts actually flare outward towards the center of the tire, giving a well-worn tire the same water carrying capacity of a brand new tire. Wet weather confidence is certainly the main act of the Road 5 but this IS a dual compound sport / sport touring tire from Michelin. Keen eyes will notice the uninterrupted expanses of rubber on the edges of the tire. These are the softer 2CT and 2CT+ zones of the front and rear tires respectively. As you lean the bike over, your grip effectively increases as you enter into these zones. From the increased braking and cornering performance of the Road 5 in wet conditions to the full-lean confidence of the tire in dry conditions, the Michelin Road 5 is a superb sport tire for those who ride rain or shine.', 'Patented Michelin XST Evo siping design Patented ACT+ casing technology 2CT dual compound front tire composition 2CT+ dual compound rear tire composition Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_pilot_road5_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_pilot_road5_tires.webp", "https://americaapi.kaafifoods.com/storage/products/michelin_road5_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sport Touring Radial Do / Sportbike Tire / Touring Tire / Multi Compound Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "120/60ZR17 55W; 120/70ZR17 58W; 150/70ZR17 69W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W"}', 50, 1, 1, NOW(), NOW());
