INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (41, '10375985.0', 'Michelin Power GP2 Tires', 'michelin-power-gp2-tires-10375985.0', 'Michelin Tires', 1, 'STREET BIKE', 'Dot Tire / Sportbike Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P1083805', 218.99, '448.95', '448.95', 'Save up to Save $124.96 28%', 4.9, 13, 'nan', 'nan', 'Front; Rear', 6, '120/70ZR17; 160/60ZR17 69W; 180/55ZR17; 190/50ZR17; 190/55ZR17; 200/55ZR17', 6, 'Michelin Power GP2 tires Building on the success of the Power GP predecessor, The Power GP2 Tire is a 50/50 track day tire made with super sport bikes in mind. The Power GP2 has even better grip in both wet and dry situations. Using the same development tools as those used for MotoGP™ tires, the new Michelin Power GP2 benefits from the experience gained by Michelin as it earned 500 victories in the FIM World Championship. Elevating the track experience so you can push your limits!', '50/50 road/track performance Improved grip over the Power GP on both wet and dry tracks (W)-rated for speeds of 168+ mph Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_power_gp2_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_power_gp2_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Sportbike Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/70ZR17; 160/60ZR17 69W; 180/55ZR17; 190/50ZR17; 190/55ZR17; 200/55ZR17"}', 50, 1, 1, NOW(), NOW());
