INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (42, '817357.0', 'Pirelli Diablo Rosso II Tires', 'pirelli-diablo-rosso-ii-tires-817357.0', 'Pirelli', 1, 'STREET BIKE', 'Hypersport Dot / Sportbike Tire / Dot Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P209956', 138.9, '329.95', '329.95', 'Save up to Save $92.07 28%', 4.8, 307, 'nan', 'nan', 'Front; Rear', 8, '120/70ZR17 58W; 120/70ZR17 58W D Spec; 160/60ZR17 69W; 170/60ZR17 72W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/50ZR17 75W', 8, 'Pirelli Diablo Rosso II Tires Bringing the technology developed for World Superbike to the road, the Pirelli Diablo Rosso II Tires gives your bike an amazing combination of grip and long tread-life for sport riders looking for an upgrade. The Tri-zone dual compound composition and improved tread design offers improved drainage, better wear and handling.', 'The Diablo Rosso II is the sportiest and most versatile road-oriented tire of the Rosso generation Diablo Rosso II is Pirelli''s newest super sport radial for all riding conditions, including the wet Grip is enhanced even further by EPT (Enhanced Patch Technology) developed in WSBK, which optimizes the contact patch for improved grip A maximum contact patch area is due in part to an ICS (Integrated Contour Shaping) technology, complimenting handling and power of today''s modern motorcycles Slick shoulder area maximizes grip at full lean which boosts confidence and performance while cornering Functional Groove Design (FGD) to optimize wet behavior D Spec tire is OE for 2013 Ducati''s fitted with Rosso II tires Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/pirelli_diablo_rosso_ii_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/pirelli_diablo_rosso_ii_tires.webp", "https://americaapi.kaafifoods.com/storage/products/0000-Pirelli-Diablo-Rosso-II-Front-Tire---.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Hypersport Dot / Sportbike Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/70ZR17 58W; 120/70ZR17 58W D Spec; 160/60ZR17 69W; 170/60ZR17 72W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/50ZR17 75W"}', 50, 1, 1, NOW(), NOW());
