INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (45, '1287437.0', 'Pirelli Scorpion Rally STR Tires', 'pirelli-scorpion-rally-str-tires-1287437.0', 'Pirelli', 1, 'STREET BIKE', 'Dual Road Radial Dot / Dual Road Bias Dot / Dual Onoff Dot / 70 On Road 30 Off Road', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P404080', 168.58, '388.72', '388.72', 'Save up to Save $98.68 25%', 4.6, 63, 'nan', 'nan', 'Front; Rear', 15, '110/70R17 54H; 120/70R17 58V TL; 130/80R17 65V TL; 140/80R17 69V TL; 150/60R17 66H; 150/70R17 69V TL; 170/60R17 72V TL; 180/55R17 73V TL; 120/70R18 59V TL; 150/70R18 70V TL; 100/90-19 57V TL; 110/80R19 59H TL; 110/80R19 59V TL; 120/70R19 60V TL; 90/90-21 54V TL', 15, 'Pirelli Scorpion Rally STR Tires The Pirelli Scorpion Rally STR Tires will quickly become your go-to choice if you demand a high level of performance both on and off road. The Rally STR tires feature an off road inspired knobby design, with an increased land to sea ratio, and an innovative knob height-width ratio that combine to offer riders the best of both worlds when it comes to tire performance.', 'Compound with high silicontent delivers excellent traction on road, in dry or wet, and at low temperatures Street derived profiles and structures provide a large, consistent and confidence inspiring contact patch Consistent contact patch delivers high performance on tarmac and works well with sophisticated electronics packages Off road inspired knob pattern with increased land area for on road stability Unique knob height-width ratio provides the right combination of on road/off road chops while not being too loud on the highway DOT Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/pirelli_scorpion_rally_str_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/pirelli_scorpion_rally_str_tires.webp", "https://americaapi.kaafifoods.com/storage/products/pirelli_tire_scorp_rally_str.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dual Road Radial Dot / Dual Road Bias Dot / Dual Onoff Dot / 70 On Road 30 Off Road", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/70R17 54H; 120/70R17 58V TL; 130/80R17 65V TL; 140/80R17 69V TL; 150/60R17 66H; 150/70R17 69V TL; 170/60R17 72V TL; 180/55R17 73V TL; 120/70R18 59V TL; 150/70R18 70V TL; 100/90-19 57V TL; 110/80R19 59H TL; 110/80R19 59V TL; 120/70R19 60V TL; 90/90-21 54V TL"}', 50, 1, 1, NOW(), NOW());
