INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (49, '454102.0', 'Pirelli Night Dragon Tires', 'pirelli-night-dragon-tires-454102.0', 'Pirelli', 2, 'STREET BIKE', 'Customcruisertouring Bi / Customcruisertouring Ra / Cruiser Tire / Harley Tire', 'Harley-Davidson', 'Harley Sportster / Harley Fxfxr / Harley Street / Harley Touring / Harley V Rod / Harley Softail / Harley Dyna / Harley Dyna Fat Bo / Harley Dyna Street / Harley Dyna Super / Harley Dyna Switch / Harley Softail Del / Harley Softail Deu / Harley Softail Fat / Harley Softail Her / Harley Softail Nig / Harley Sportster 1 / Harley Sportster 8 / Harley Sportster I / Harley Touring Ele / Harley Touring Roa / Harley Touring Str', '1990 - 2025', 'P211459', 138.27, '398.56', '398.56', 'Save up to Save $102.29 26%', 4.5, 31, 'nan', 'nan', 'Front; Rear', 15, '180/70B15 76H TL; 130/90-16 67H TL; 130/90B16 73H TL Reinforced; 150/80B16 71H TL; 180/70R16 77H TL; 130/80B17 65H TL; 140/75R17 67V TL; 180/60B17 81H TL Reinforced; 130/70R18 63V TL; 240/40R18 79V TL; 100/90-19 57H TL; 110/90-19 62H TL; 130/60B19 61H TL; 90/90-21 54H TL; 120/70B21 68H TL Reinforced', 15, 'Pirelli Night Dragon Tires Better adhesion, road holding and looks than standard tires for custom and cruiser motorcycles Designed for motorcyclists that need tires with excellent grip but also last in high mileage scenarios Excellent performance and great fun to ride with a good balance between reliability and life of the tire Optimized for V-Twin engines with more power and higher torque Special research of the contact patch in order to ensure great stability at high speeds and quick acceleration Contact Patch / Compound: New shape and new dimension Allows use of more durable compounds with increased levels of grip 10% larger contact patch Structural Solutions: New front and rear profile Supports the bike at every lean angle Optimized pressure distribution on the contact patch Unbeatable dampening properties High level of riding comfort', 'Pirelli''s Night Dragon allows a rider and his bike to reach their full potential without sacrificing mileage The Night Dragon increases not only wet and dry grip but gives you noticeably better handling on backroads and the interstate Modern tread pattern combines high-performance attributes and a great new style Outstanding grip at all lean angles Special compounds offer incredible straight-line acceleration and traction New structural designs provide great stability and comfort Tube/tubeless (TL); blackwall H-rated for speeds up to 130 mph; V-rated for speeds up to 149 mph; (V)-rated for speeds of 149+ mph; W-rated for speeds up to 168 mph or (W)-rated for speeds of 168+ mph Available in "Reinforced" for heavyweight touring bikes, two-up riding, or when required by OEM specifications GT "reinforced" spec for heavier touring bikes Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/0000_Pirelli_Night_Dragon_Front_Tire_--.webp', '["https://americaapi.kaafifoods.com/storage/products/0000_Pirelli_Night_Dragon_Front_Tire_--.webp", "https://americaapi.kaafifoods.com/storage/products/pirelli_night_dragon_tires.webp", "https://americaapi.kaafifoods.com/storage/products/pirelli_night_dragon_rear_tires.webp", "https://americaapi.kaafifoods.com/storage/products/0000_Pirelli_Night_Dragon_Rear_Tire_--.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Customcruisertouring Bi / Customcruisertouring Ra / Cruiser Tire / Harley Tire", "Make": "Harley-Davidson", "Model": "Harley Sportster / Harley Fxfxr / Harley Street / Harley Touring / Harley V Rod / Harley Softail / Harley Dyna / Harley Dyna Fat Bo / Harley Dyna Street / Harley Dyna Super / Harley Dyna Switch / Harley Softail Del / Harley Softail Deu / Harley Softail Fat / Harley Softail Her / Harley Softail Nig / Harley Sportster 1 / Harley Sportster 8 / Harley Sportster I / Harley Touring Ele / Harley Touring Roa / Harley Touring Str", "Tire Size": "180/70B15 76H TL; 130/90-16 67H TL; 130/90B16 73H TL Reinforced; 150/80B16 71H TL; 180/70R16 77H TL; 130/80B17 65H TL; 140/75R17 67V TL; 180/60B17 81H TL Reinforced; 130/70R18 63V TL; 240/40R18 79V TL; 100/90-19 57H TL; 110/90-19 62H TL; 130/60B19 61H TL; 90/90-21 54H TL; 120/70B21 68H TL Reinforced"}', 50, 1, 1, NOW(), NOW());
