INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (50, '10267864.0', 'Dunlop Q5 Sportmax Tires', 'dunlop-q5-sportmax-tires-10267864.0', 'Dunlop', 4, 'STREET BIKE', 'Road Race Dot And Non D / Multi Compound Tire / Race Tire / Sportbike Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P1025651', 234.99, '472.95', '472.95', 'Save up to Save $81.96 17%', 4.6, 17, 'nan', 'nan', 'Front; Rear', 11, '110/70ZR17 54W; 120/70ZR17 58W; 140/70ZR17 66W; 150/60ZR17 66W; 160/60ZR17 69W; 180/55ZR17 73W; 180/60ZR17 75W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W; 200/60ZR17 80W', 11, 'Dunlop Q5 Sportmax Tires The fifth generation Dunlop Sportmax Q5 is a purpose-built, DOT compliant track-day tire that has been in the making for over 4 years. Evolving from a blend of the highly popular Sportmax Q4 and Dunlop’s cutting-edge MotoAmerica spec road race tires, the Q5 utilizes the very best technologies Dunlop has to offer for a track tire that is still street legal. Having enhanced constructions, profiles, compounds and tread patterns, the Q5 is the benchmark for track-day tires. The Q5 is even more user-friendly, as dry and wet grip, tire compliance and warm-up times have all been improved. Dunlop changed the polymer, reduced the shore hardness, increased the carbon black content by utilizing Carbon R technology, added a traction resin and fine-tuned the curatives, all to greatly improve upon the already successful Q4. They also optimized the tread pattern design and position to aid in quicker warm-up times and improved wet-weather performance.', 'Even more user-friendly, as dry and wet grip, tire compliance, and warm-up times have all been improved New race tire derived compounds provide incredible grip Updated profiles increase footprints at more extreme lean angles to give you more tire on the road for more grip and less slip Do not require tire warmers for track use Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_q5_sportmax_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_q5_sportmax_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Road Race Dot And Non D / Multi Compound Tire / Race Tire / Sportbike Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "110/70ZR17 54W; 120/70ZR17 58W; 140/70ZR17 66W; 150/60ZR17 66W; 160/60ZR17 69W; 180/55ZR17 73W; 180/60ZR17 75W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W; 200/60ZR17 80W"}', 50, 1, 1, NOW(), NOW());
