INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (51, '10148950.0', 'Continental Road Attack 4 Tires', 'continental-road-attack-4-tires-10148950.0', 'Continental Tire', 2, 'STREET BIKE', 'Sport Touring Radial Do / Touring Tire / Multi Compound Tire / Dot Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P958672', 203.0, '460.95', '460.95', 'Save up to Save $162.86 35%', 4.8, 32, 'nan', 'nan', 'Front; Rear', 9, '120/70R17 58W TL; 150/70R17 69V TL; 160/60R17 69W TL; 170/60ZR17 72W TL; 180/55R17 73W TL; 190/50R17 73W TL; 190/55R17 75W TL; 110/80R19 59V TL; 120/70ZR19 60W TL', 9, 'Continental Road Attack 4 Tires For excellent grip in a variety of conditions and longevity you can count on, look no further than the Continental Road Attack 4. Thanks to its performance-oriented tread pattern and improved compound, you can just as confidently knock down those miles in wet weather as you do in dry conditions. This is the perfect tire for someone who wants a long lasting tire that performs year round.', 'Performance oriented tread pattern for excellent grip in both wet and dry conditions Faster warm-up in cold and wet conditions Compound for improved wet grip in cold and slippery conditions Easy intuitive handling characteristics and optimal cornering grip TractionSkin technology ensures tires are ready to use straight away and a short break-in period Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/continental_road_attack4_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/continental_road_attack4_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sport Touring Radial Do / Touring Tire / Multi Compound Tire / Dot Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "120/70R17 58W TL; 150/70R17 69V TL; 160/60R17 69W TL; 170/60ZR17 72W TL; 180/55R17 73W TL; 190/50R17 73W TL; 190/55R17 75W TL; 110/80R19 59V TL; 120/70ZR19 60W TL"}', 50, 1, 1, NOW(), NOW());
