INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (54, '10375977.0', 'Michelin Anakee Road Tires', 'michelin-anakee-road-tires-10375977.0', 'Michelin Tires', 2, 'STREET BIKE', '90 On Road 10 Off Road / Dot Tire / Multi Compound Tire / Touring Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1083804', 183.99, '386.95', '386.95', 'Save up to Save $100.96 26%', 4.6, 27, 'nan', 'nan', 'Front; Rear', 8, '150/70R17 69V; 170/60R17 72V; 170/60ZR17 72W; 150/70R18 70V; 110/80R19 59V; 120/70R19 60V; 120/70ZR19 60W; 90/90-21 54V', 8, 'Michelin Anakee Road tire Get the Adventure handling with the Michelin Road Performance you expect. Offering enhanced grip and longevity, the Michelin Anakee Road tire is the latest 90/10 Adventure Touring tire for a smooth quiet ride. Just as amazing for long touring rides as well as every day travel. A vast range of use, just like the adventure bikes they go on. If you''re a rider that prefers the pavement path, the Anakee Road tire is designed with high level grip, regardless if you''re in dry or wet conditions. Built to handle significant weight of some adventure bikes, they are still a perfect fit for the modern lighter generation adventure bikes.', '90% on-road / 10% off-road Optimized wet grip for confident riding Longer lasting center tread compound for more miles Reliable on-road stability Additional sizing for W speed rated tires Note: Michelin will continue to offer the Michelin Road 6 (100% on-road) tire, the Michelin Anakee Adventure (80/20) tire, and the Michelin Anakee Wild (50/50) tire for the Adventure Touring segment. The Michelin Anakee III tire, Michelin’s current 90/10 tire, will be available until further notice. Michelin’s current offer of tubes will work with the new tire range. Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_anakee_road_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_anakee_road_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "90 On Road 10 Off Road / Dot Tire / Multi Compound Tire / Touring Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "150/70R17 69V; 170/60R17 72V; 170/60ZR17 72W; 150/70R18 70V; 110/80R19 59V; 120/70R19 60V; 120/70ZR19 60W; 90/90-21 54V"}', 50, 1, 1, NOW(), NOW());
