INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (58, '1088274.0', 'Michelin Anakee Wild Tires', 'michelin-anakee-wild-tires-1088274.0', 'Michelin Tires', 1, 'STREET BIKE', 'Dual Road Radial Dot / Dual Road Bias Dot / 50 On Road 50 Off Road / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P326409', 160.99, '369.99', '369.99', 'Save up to Save $89.00 24%', 4.0, 81, 'nan', 'nan', 'Front; Rear', 13, '130/80B17 65R TL; 140/80-17; 150/70R17 69R TL; 170/60R17 72R TL; 110/80-18 58S TT; 120/80-18 62S TT; 130/80-18 66S TT; 140/80B18 70R TL; 150/70R18 70R TL; 110/80R19 59R TL; 120/70R19 60R TL; 80/90-21 48S TT; 90/90B21 54R TL', 13, 'Michelin Anakee Wild Tires The Michelin Anakee Wild Tires make all the different for those that venture off the beaten path. Off road designed compounds, combined with an aggressive tread pattern inspired by Michelin''s Dakar winning Desert Race tire, offer extraordinary performance for long adventures. These tires provide true off-road performance, especially in challenging conditions and, in addition to proven off-road performance, the front/rear casing design ensures superior on-road stability. With sizes specifically made for ADV bikes, the Anakee 3 Wild Tires will help you put your bike''s horsepower to the ground in a meaningful way.', 'An off-road version of the popular Anakee III Ideal for riders who like to take their bikes on the trails 50% on-road / 50% off-road Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_anakee_wild_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_anakee_wild_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dual Road Radial Dot / Dual Road Bias Dot / 50 On Road 50 Off Road / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "130/80B17 65R TL; 140/80-17; 150/70R17 69R TL; 170/60R17 72R TL; 110/80-18 58S TT; 120/80-18 62S TT; 130/80-18 66S TT; 140/80B18 70R TL; 150/70R18 70R TL; 110/80R19 59R TL; 120/70R19 60R TL; 80/90-21 48S TT; 90/90B21 54R TL"}', 50, 1, 1, NOW(), NOW());
