INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (59, '10042266.0', 'Dunlop Mutant Tires', 'dunlop-mutant-tires-10042266.0', 'Dunlop', 2, 'STREET BIKE', 'Sport Touring Radial Do / Dual Road Radial Dot / 90 On Road 10 Off Road / Sportbike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P895450', 210.99, '346.95', '346.95', 'Save up to Save $57.96 17%', 4.6, 71, 'nan', 'nan', 'Front; Rear', 11, '110/70ZR17 54W; 120/70ZR17 58W; 150/60ZR17 66W; 150/70ZR17 69W; 160/60ZR17 69W; 170/60ZR17 72W; 180/55ZR17 73W; 190/55ZR17 75W; 110/80ZR18 58W; 110/80R19 59V; 120/70ZR19 60W', 11, 'Dunlop Mutant Tires The all in one Dunlop Mutant Tire takes elements from sports bikes, super motos, powerful cruisers and ADV bikes for full versatility with today''s market of crossover bikes. This set of tires provides the rider with the handling and stability of a hyper sport tire, but the durability sought out after in touring tires. Made from state of the art compounds and resins for longevity and a bonus claimed best wet grip this side of a rain slick, the Mutant gives the rider supreme versatility and confidence in all kinds of conditions, year round.', 'Excellent wet grip Supreme versatility giving the rider confidence year-round Sport tire handling and stability courtesy of tire contours developed using DFF (Dynamic Front Formula) State of the art compounds and resins combine performance and durability Tubeless Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_mutant_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_mutant_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sport Touring Radial Do / Dual Road Radial Dot / 90 On Road 10 Off Road / Sportbike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/70ZR17 54W; 120/70ZR17 58W; 150/60ZR17 66W; 150/70ZR17 69W; 160/60ZR17 69W; 170/60ZR17 72W; 180/55ZR17 73W; 190/55ZR17 75W; 110/80ZR18 58W; 110/80R19 59V; 120/70ZR19 60W"}', 50, 1, 1, NOW(), NOW());
