INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (61, '10575901.0', 'Bridgestone Battlax RS12 Tires', 'bridgestone-battlax-rs12-tires-10575901.0', 'Bridgestone', 1, 'STREET BIKE', 'Dot Tire / Multi Compound Tire / Sportbike Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P1179999', 244.0, '472.42', '472.42', 'Save up to Save $118.42 25%', 4.5, 2, 'nan', 'nan', 'Front; Rear', 4, '120/70ZR17 58W TL; 180/55ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL', 4, 'Bridgestone Battlax RS12 Tires The Bridgestone Battlax Racing Street RS12 stands as the pinnacle of hypersport tires within Bridgestone''s range, crafted for those who demand peak performance on both roads and racetracks. It offers superb performance for track days, negating the necessity of complete slick tires. With a focus on superior dry traction and assured steering, it comes with striking sidewall and tread patterns. Fast and steady laps are its forte, ensuring riders derive maximum pleasure during their circuit runs and street rides.', 'Bridgestone’s most aggressive, street legal, hypersport tire Engineered to bridge the gap between a dedicated track tire and a high-performance street tire Maximum Dry Grip : Bridgestone race tire compound technology helps deliver amazing grip and durability for both track and street riding\\ For riders requiring some level of rain performance, better options exist The new steel HE-MSB construction in the front tires is engineered for stabilizing and equalizing pressure under extreme braking loads, while the wide shoulder of advanced race compound on the rear helps drive out of corners Consistent Lap Time : Race tire compounds developed in endurance racing help deliver fast times, lap after lap Racing-Inspired Appearance: A slick, redesigned shoulder provides a true racing aesthetic and a contact patch increase of 9% on the front tire and a 4% on the rear tire compared to the preceding RS11 tire Compared to the RS11 predecessor: Softer race compound at the shoulders is slick - no tread pattern for max grip Drastically improved dry grip at far lean angles Groove pattern redesign not only adds a racing aesthetic but it increases the overall contact patch High-Elongation Mono Spiral Belt design : delivers harder trail breaking into corners In initial private testing, the RS12 demonstrates significantly faster lap times with less degradation against the RS11 and 3rd party competitors Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_rs12_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_rs12_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Multi Compound Tire / Sportbike Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/70ZR17 58W TL; 180/55ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL"}', 50, 1, 1, NOW(), NOW());
