INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (62, '1088791.0', 'Pirelli Night Dragon GT Rear Tires', 'pirelli-night-dragon-gt-rear-tires-1088791.0', 'Pirelli', 2, 'STREET BIKE', 'Customcruisertouring Bi / Customcruisertouring Ra / Cruiser Tire / Harley Tire', 'Harley-Davidson', 'Harley Sportster / Harley Fxfxr / Harley Street / Harley Touring / Harley V Rod / Harley Softail / Harley Dyna / Harley Dyna Fat Bo / Harley Dyna Street / Harley Dyna Super / Harley Dyna Switch / Harley Softail Del / Harley Softail Deu / Harley Softail Fat / Harley Softail Her / Harley Softail Nig / Harley Sportster 1 / Harley Sportster 8 / Harley Sportster I / Harley Touring Ele / Harley Touring Roa / Harley Touring Str', '1990 - 2025', 'P722106', 194.37, '403.52', '403.52', 'Save up to Save $102.43 25%', 4.7, 121, 'nan', 'nan', 'Rear', 8, '170/80B15 77H TL; 130/90B16 73H; MU85B16 77H TL; 150/80B16 77H TL Reinforced; 180/65B16 81H TL Reinforced; 160/70B17 TL 79V; 200/55R17 78V TL; 180/55B18 80H TL', 8, 'Pirelli Night Dragon GT Rear Tires The Pirelli Night Dragon GT Rear Tires are 20% longer lasting than standard Night Dragon rear tires. Designed for larger and heavier motorcycles that need tires with excellent grip but also last in high mileage scenarios. Excellent performance and great fun to ride with a good balance between reliability and life of the tire. Special research of the contact patch in order to ensure great stability at high speeds and quick acceleration. Optimized for V-Twin engines with more power and higher torque.', 'Up to 20% Longer lasting Advanced Full Carbon Black compound Stiffer carcass thanks to structure stiffening and high belt tension Same legendary performance and 100% mixable with all Night Dragon front tires Available in "Reinforced" for heavyweight touring bikes, two-up riding, or when required by OEM specifications Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/pirelli_tire_night_dragon_gt_mt90_b1674_h.webp', '["https://americaapi.kaafifoods.com/storage/products/pirelli_tire_night_dragon_gt_mt90_b1674_h.webp", "https://americaapi.kaafifoods.com/storage/products/pirelli_tire_nght_dragon_gt_rear13090_b1673_h_belted_bias.webp", "https://americaapi.kaafifoods.com/storage/products/pirelli_night_dragon_rear_tires.webp"]', '{"Wheel Location": "Rear", "Type": "STREET BIKE", "Product Type": "Customcruisertouring Bi / Customcruisertouring Ra / Cruiser Tire / Harley Tire", "Make": "Harley-Davidson", "Model": "Harley Sportster / Harley Fxfxr / Harley Street / Harley Touring / Harley V Rod / Harley Softail / Harley Dyna / Harley Dyna Fat Bo / Harley Dyna Street / Harley Dyna Super / Harley Dyna Switch / Harley Softail Del / Harley Softail Deu / Harley Softail Fat / Harley Softail Her / Harley Softail Nig / Harley Sportster 1 / Harley Sportster 8 / Harley Sportster I / Harley Touring Ele / Harley Touring Roa / Harley Touring Str", "Tire Size": "170/80B15 77H TL; 130/90B16 73H; MU85B16 77H TL; 150/80B16 77H TL Reinforced; 180/65B16 81H TL Reinforced; 160/70B17 TL 79V; 200/55R17 78V TL; 180/55B18 80H TL"}', 50, 1, 1, NOW(), NOW());
