INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (64, '1790964.0', 'Michelin Power 5 Tires', 'michelin-power-5-tires-1790964.0', 'Michelin Tires', 1, 'STREET BIKE', 'Sportbike Tire / Dot Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P836175', 181.99, '391.95', '391.95', 'Save up to Save $128.96 33%', 4.8, 79, 'nan', 'nan', 'Front; Rear', 6, '120/70ZR17 58W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W', 6, 'Michelin Power 5 Tires The Power 5 is as superb as a daily ridden tire can be. Building on the Michelin Power RS, the Power 5 Tire exceeds both the former RS''s dry performance and adds even better wet-weather grip. Using Michelin’s "Adaptive Casing Technology", the Power 5 uses a unique single ply carcass at an angle close to 90° to increase grip at the crown of the tire, yet folds that single ply over on itself on each sidewall to stiffen it - resulting in less sidewall flex and better tracking through corners. A void ratio of 11% is matched between front and rear tire sizes. Rubber compounds use a mix of Michelin''s proprietary 2CT and 2CT+ silica blends to balance longevity with dry and wet performance.', 'Incorporates ACT (Adaptive Casing Technology) developed from Michelin race tires for improved grip and unique feel Front tire profile optimized to promote quick turn in and accurate feedback 2CT compound used on the front tire to enhance corner grip without compromising longevity 2CT+ compound on rear tire reduces sidewall flex at lean and increases corner exit stability Outstanding grip in wet or dry conditions Tubeless (TL) (W)-rated for speeds of 168+ mph Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_power5_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_power5_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sportbike Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/70ZR17 58W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W"}', 50, 1, 1, NOW(), NOW());
