INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (65, '1193734.0', 'Dunlop Roadsmart 3 Tires', 'dunlop-roadsmart-3-tires-1193734.0', 'Dunlop', 2, 'STREET BIKE', 'Sport Touring Radial Do / Touring Tire / Multi Compound Tire / Dot Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P365725', 155.99, '310.95', '310.95', 'Save up to Save $54.96 18%', 4.7, 245, 'nan', 'nan', 'Rear; Front', 13, '120/60ZR17 55W; 120/70ZR17 58W; 150/70R17 69V; 160/60ZR17 69W; 160/70ZR17 73W; 170/60ZR17 72W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 110/80R18 58V; 120/70ZR18 59W; 110/80R19 59V; 120/70ZR19 60W', 13, 'Dunlop Roadsmart 3 Tires The Dunlop Roadsmart 3 Tires feature Interconnecting Groove Tread technology and an entirely revised rayon ply carcass that, together, provide excellent wet weather grip and handling. Thanks to a redesigned front profile, the Roadsmart 3 tires require significantly less steering input then previous versions. Dunlop''s MultiTread technology uses a long-wearing compound at the center and soft lateral-grip compound at the sides to provide superior grip without compromising longevity.', 'Entirely revised rayon ply carcass and front profile requires less steering input and provides precise handling without sacrificing Roadsmart''s trademark confidence inspiring feel and feedback Interconnecting Groove Tread (iGT) provides excellent water evacuation while promoting even tire wear MultiTread compound with tri-polymer blend and high dispersion silica mix provides increased mileage and wet weather grip MT compound and iGT design work together to ensure top level performance for the life of the tire Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_roadsmart3_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_roadsmart3_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "STREET BIKE", "Product Type": "Sport Touring Radial Do / Touring Tire / Multi Compound Tire / Dot Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "120/60ZR17 55W; 120/70ZR17 58W; 150/70R17 69V; 160/60ZR17 69W; 160/70ZR17 73W; 170/60ZR17 72W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 110/80R18 58V; 120/70ZR18 59W; 110/80R19 59V; 120/70ZR19 60W"}', 50, 1, 1, NOW(), NOW());
