INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (66, '10578494.0', 'Continental TKC80 Generation 2 Dual Sport Tires', 'continental-tkc80-generation-2-dual-sport-tires-10578494.0', 'Continental Tire', 3, 'DIRT BIKE', '50 On Road 50 Off Road / Dot Tire / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1181073', 141.3, '411.95', '411.95', 'Save up to Save $146.63 36%', 5.0, 1, 'nan', 'nan', 'Front; Rear', 10, '130/80-17 65R TL; 150/70B17 69R TL; 170/60B17 72R TL; 120/90-18 65R TL; 140/80-18 70R TL; 150/70B18 70R TL; 100/90-19 57R TL; 110/80B19 59R TL; 120/70-19 60R TL; 90/90-21 54R TL', 10, 'Continental TKC80 Generation 2 Dual Sport Tires Continental TKC80 Generation 2 Dual Sport Tires represent a significant enhancement for any motorcycle, delivering a balanced 50/50 performance that effortlessly transitions from pavement to rugged trails. Riders can enjoy a seamless riding experience on the road, while the advanced off-road technology ensures a strong grip and superior handling when the terrain gets challenging.', 'Optimized damping based on a carcass construction tailored for 50/50 on- and off-road use, ensuring stable and comfortable handling even at high speeds on paved roads and beyond Strong off-road traction and mileage thanks to a new tread design that delivers more mechanical grip through added biting edges, staggered shoulder blocks and optimized block geometry Enhanced wet grip for greater confidence and safety in rainy conditions, enabled by a new compound and RainGrip technology Noticeably improved stability and control on both road and trail due to a new block design with a larger contact patch Bigger footprint area in critical wear zone with a net area increase of +17%', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/continental_tkc80_generation2_dual_sport_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/continental_tkc80_generation2_dual_sport_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "50 On Road 50 Off Road / Dot Tire / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "130/80-17 65R TL; 150/70B17 69R TL; 170/60B17 72R TL; 120/90-18 65R TL; 140/80-18 70R TL; 150/70B18 70R TL; 100/90-19 57R TL; 110/80B19 59R TL; 120/70-19 60R TL; 90/90-21 54R TL"}', 50, 1, 1, NOW(), NOW());
