INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (70, '10042549.0', 'Michelin Pilot Street 2 Tires', 'michelin-pilot-street-2-tires-10042549.0', 'Michelin Tires', 1, 'STREET BIKE', 'Scooter Tire / Sportbike Tire / Dot Tire', 'Honda', 'Honda PCX150 / Ruckus, Yamaha Zuma / XMAX, Vespa Primavera / GTS 300, Suzuki Burgman 400', '2005 - 2025', 'P895611', 47.99, '143.95', '143.95', 'Save up to Save $20.96 15%', 4.5, 28, 'nan', 'nan', 'Front; Front/Rear; Rear', 19, '90/90-10 50P; 100/90-10 61P; 3.50-10 59J; 130/70-12 62S; 70/90-14 40S; 80/90-14 46S; 90/90-14 52S; 100/90-14 57S; 110/80-14 59S; 120/70-14 61P; 80/90-16 48S; 60/90-17 36S; 70/90-17 43S; 80/90-17 50S; 90/80-17 46S; 100/80-17 52S; 110/70-17 54S; 130/70-17 62S; 140/70-17 66S', 19, 'Michelin Pilot Street 2 Tires The Michelin Pilot Street 2 Tires provides an optimal rain or shine tire to scooters and small bikes. The all new tread pattern is designed to minimize uneven wear and maximize mileage, while maintaining great handling and braking in wet conditions. The shape of the tire allows more feel resulting in more maneuverability and confidence in any conditions.', 'Optimized groove tread pattern Tread pattern designed to minimize uneven wear and maximize mileage while enhancing wet weather performance Small central grooves and progressive side grooves designed for enhanced water evacuation Precision handling with high level of rider feedback Superior longevity compared to a primary bias-ply competitor Tubeless Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here!', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_pilot_street2_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_pilot_street2_tires.webp"]', '{"Wheel Location": "Front; Front/Rear; Rear", "Type": "STREET BIKE", "Product Type": "Scooter Tire / Sportbike Tire / Dot Tire", "Make": "Honda", "Model": "Honda PCX150 / Ruckus, Yamaha Zuma / XMAX, Vespa Primavera / GTS 300, Suzuki Burgman 400", "Tire Size": "90/90-10 50P; 100/90-10 61P; 3.50-10 59J; 130/70-12 62S; 70/90-14 40S; 80/90-14 46S; 90/90-14 52S; 100/90-14 57S; 110/80-14 59S; 120/70-14 61P; 80/90-16 48S; 60/90-17 36S; 70/90-17 43S; 80/90-17 50S; 90/80-17 46S; 100/80-17 52S; 110/70-17 54S; 130/70-17 62S; 140/70-17 66S"}', 50, 1, 1, NOW(), NOW());
