INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (73, '10321424.0', 'Motoz Tractionator GPS Tires', 'motoz-tractionator-gps-tires-10321424.0', 'Motoz', 1, 'STREET BIKE', '40 On Road 60 Off Road / 30 On Road 70 Off Road / 50 On Road 50 Off Road / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1055163', 74.99, '305.99', '305.99', 'nan', 4.3, 44, 'nan', 'nan', 'Rear; Front', 13, '120/70-12 51L TL; 130/70-12 56L TL; 120/70B17 58Q TL; 130/80B17 65T TL; 150/70B17 69T TL; 160/70B17 73T TL; 170/60B17 72Q TL; 110/80B18 58Q TL; 140/80B18 70T TL; 150/70B18 70T TL; 110/80B19 59T TL; 120/70B19 60Q TL; 90/90B21 54T TL', 13, 'Motoz Tractionator GPS Tires You have the right bike, picked up the right GPS and now you need the right tires - the Tractionator GPS tires are made for riders who need dependability in all conditions, no matter what mother nature throws your way. Motoz designed these tires to get you anywhere on the globe and back home again. Long mileage, serious traction and smooth transition from pavement to gravel to dirt, the Tractionator GPS does it all well. The Motoz Tractionator GPS rear tire is reversible to suit the rider’s needs - either 50/50 or Mostly Off Road. In the 50/50 direction the GPS is a well behaved street-able tire with smooth cornering transition from center to cranked all the way over. In Mostly Off Road direction the aggressive straight line hook up and cornering drive is engaged.', 'Designed for 50% on-road / 50% off-road* *Reversible rear tread - flip the tire for more aggressive off-road grip Hybrid compound with Silica Tubeless type Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_tractionator_gps_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_tractionator_gps_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "STREET BIKE", "Product Type": "40 On Road 60 Off Road / 30 On Road 70 Off Road / 50 On Road 50 Off Road / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/70-12 51L TL; 130/70-12 56L TL; 120/70B17 58Q TL; 130/80B17 65T TL; 150/70B17 69T TL; 160/70B17 73T TL; 170/60B17 72Q TL; 110/80B18 58Q TL; 140/80B18 70T TL; 150/70B18 70T TL; 110/80B19 59T TL; 120/70B19 60Q TL; 90/90B21 54T TL"}', 50, 1, 1, NOW(), NOW());
