INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (74, '10313424.0', 'Dunlop Geomax MX34 Tires', 'dunlop-geomax-mx34-tires-10313424.0', 'Dunlop', 3, 'DIRT BIKE', 'Off Highway Non Dot Inc / Dirt Bike Tire / Non Dot Tire / Intermediate Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1051915', 47.99, '197.95', '197.95', 'Save up to Save $44.61 23%', 4.9, 18, 'nan', 'nan', 'Front; Rear', 19, '70/100-14 37M; 90/100-12 46M; 60/100-10 33J; 70/100-10 41J; 60/100-12 36J; 80/100-12 41M; 60/100-14 29M; 90/100-14 49M; 90/100-16 51M; 70/100-17 40M; 100/100-18 59M; 110/100-18 64M; 120/90-18 65M; 70/100-19 42M; 100/90-19 57M; 110/90-19 62M; 120/80-19 63M; 120/90-19 66M; 80/100-21 51M', 19, 'Dunlop Geomax MX34 Tires Dunlop has proven their dominance at every level of competition, and they''re back for more with the improved MX34 tire. Taking pointers from the highly successful MX33 and MX3s lines. the MX34 offers improved traction over a wider range of terrain for the best all-around performance available. Before being made available to the public, the MX34 prototype racked up 22 Supercross wins and 3 Outdoor Motocross wins wile in the testing phase. The final product delivers unparalleled traction, durability and stability out on the track or trails.', 'Advanced carcass improves performance longevity by 30% Improved rubber compound increases traction while maintaining durability Progressive Cornering Block Technology for improved grip while turning Rear center tread is 11% taller and 44% wider than previous models Offered in a complete range of sizes for minis to big bikes Optimized tread pattern to evacuate mud and dirt Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_geomax_mx34_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_geomax_mx34_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Off Highway Non Dot Inc / Dirt Bike Tire / Non Dot Tire / Intermediate Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "70/100-14 37M; 90/100-12 46M; 60/100-10 33J; 70/100-10 41J; 60/100-12 36J; 80/100-12 41M; 60/100-14 29M; 90/100-14 49M; 90/100-16 51M; 70/100-17 40M; 100/100-18 59M; 110/100-18 64M; 120/90-18 65M; 70/100-19 42M; 100/90-19 57M; 110/90-19 62M; 120/80-19 63M; 120/90-19 66M; 80/100-21 51M"}', 50, 1, 1, NOW(), NOW());
