INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (76, '454651.0', 'Metzeler Tourance Tires', 'metzeler-tourance-tires-454651.0', 'Metzeler', 1, 'STREET BIKE', 'Dual Road Radial Dot / Dual Road Bias Dot / 80 On Road 20 Off Road / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P126403', 133.65, '340.62', '340.62', 'Save up to Save $82.43 24%', 4.6, 55, 'nan', 'nan', 'Rear; Front', 9, '120/90-17 64S TL; 130/80R17 65H TL; 130/80R17 65S; 140/80R17 69H TL; 150/70R17 69H; 150/70R17 69V TL; 100/90-19 57H TL; 110/80R19 59V TL; 90/90-21 54H TL', 9, 'Metzeler Tourance Tires The Metzeler Tourance dual sport tires were developed and tuned for today''s big, modern, street-oriented Enduro bikes.', 'Lets you take your touring-configured enduro bike for longer rides Radial tires feature twin layer, 4-ply diagonal tire carcass construction 85% on-road / 15% off-road bias Radial front and rear tires feature Metzeler''s 0° Steel Radial belt technology Maximum mileage on the street and great traction also on light off-road surfaces thanks to the specific compound Tire compound provides long mileage, stable handling and touring comfort on road; tread design also handles light off-road riding Optimized tread design reduces rolling noise MAW (Metzeler Advanced Winding) Technology Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/Metzeler_Tourance_Rear_Tire.webp', '["https://americaapi.kaafifoods.com/storage/products/Metzeler_Tourance_Rear_Tire.webp", "https://americaapi.kaafifoods.com/storage/products/Metzeler_Tourance_Front_Tire.webp", "https://americaapi.kaafifoods.com/storage/products/metzeler_tourance_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "STREET BIKE", "Product Type": "Dual Road Radial Dot / Dual Road Bias Dot / 80 On Road 20 Off Road / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/90-17 64S TL; 130/80R17 65H TL; 130/80R17 65S; 140/80R17 69H TL; 150/70R17 69H; 150/70R17 69V TL; 100/90-19 57H TL; 110/80R19 59V TL; 90/90-21 54H TL"}', 50, 1, 1, NOW(), NOW());
