INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (77, '1040244.0', 'Pirelli Scorpion Trail II Dual Sport Tires', 'pirelli-scorpion-trail-ii-dual-sport-tires-1040244.0', 'Pirelli', 1, 'STREET BIKE', 'Dual Road Radial Dot / Dual Road Bias Dot / 90 On Road 10 Off Road / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P305803', 131.19, '407.0', '407.0', 'Save up to Save $103.27 25%', 4.7, 49, 'nan', 'nan', 'Rear; Front', 18, '120/70ZR17 58W TL; 130/80R17 65V TL; 140/80R17 69V TL; 150/70R17 69V TL; 160/60ZR17 69W TL; 170/60R17 72V TL; 170/60ZR17 72W TL D; 170/60ZR17 72W TL K; 180/55ZR17 73W TL; 190/55ZR17 75W TL; 100/90-18 56V TL; 150/70R18 70V TL; 100/90-19 57V TL; 110/80R19 59V TL; 120/70R19 60V TL; 120/70ZR19 60V TL; 120/70ZR19 60W TL D; 90/90-21 54V TL', 18, 'Pirelli Scorpion Trail 2 Dual Sport Tires The Pirelli Scorpion Trail II Tires were specifically designed to meet the versatility of the modern adventure touring motorcycle. They feature an aggressive tread pattern supported by strong technological innovations, giving good stability even at high speed, excellent traction on dirt as well as superior handling, comfort and grip in all riding conditions. The tread pattern of Pirelli Scorpion Trail II Tires have an aggressive look typical of an off-road tire, but that combines the greatest features of an enduro tire with those of a sport touring tire. The side grooves have been designed to ensure optimal drainage of water, while the layout and shape of the central grooves not only contribute to the drainage of water but also ensure better traction, greater stability and normal wear. The structure that lies beneath the Pirelli Scorpion Trail 2 Tires ensures high performance, even at full load or with heavier motorcycles, making it comfortable for long trips and winding roads.', 'Increased mileage, improved wet grip with an incredible performance consistency throughout its entire life cycle Innovative tread pattern combines the typical off-road style of the Pirelli Scorpion™ range with the experience directly derived from the Angel GT (Pirelli''s top sport touring product) Peak performance of enduro and sport touring blended into one product Larger center compound stripe to guarantee enhanced cornering performance Central compound developed for higher mileage and improved behavior in wet conditions Side compound for optimized balance between dry and wet performance High performance for heavy, fully-loaded bikes Incredible versatility ensures peak performance on long, straight journeys or twisty roads with the most adverse weather conditions V-rated for speeds up to 149 mph, (V)-rated for speeds to 149+ mph, W-rated for speeds up to 168 mph, (W)-rated for speeds to 168+ mph K-spec denotes OE tire for the KTM Super Adventure 1290 and Adventure 1190 D-spec denotes OE tire for the Ducati Multistrada 1200 Enduro Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/pirelli_tire_scorpion_trail_ii60_v_radial.webp', '["https://americaapi.kaafifoods.com/storage/products/pirelli_tire_scorpion_trail_ii60_v_radial.webp", "https://americaapi.kaafifoods.com/storage/products/pirelli_scorpion_trail_ii_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "STREET BIKE", "Product Type": "Dual Road Radial Dot / Dual Road Bias Dot / 90 On Road 10 Off Road / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/70ZR17 58W TL; 130/80R17 65V TL; 140/80R17 69V TL; 150/70R17 69V TL; 160/60ZR17 69W TL; 170/60R17 72V TL; 170/60ZR17 72W TL D; 170/60ZR17 72W TL K; 180/55ZR17 73W TL; 190/55ZR17 75W TL; 100/90-18 56V TL; 150/70R18 70V TL; 100/90-19 57V TL; 110/80R19 59V TL; 120/70R19 60V TL; 120/70ZR19 60V TL; 120/70ZR19 60W TL D; 90/90-21 54V TL"}', 50, 1, 1, NOW(), NOW());
