INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (80, '876141.0', 'Michelin Anakee 3 Tires', 'michelin-anakee-3-tires-876141.0', 'Michelin Tires', 2, 'STREET BIKE', 'Dual Road Radial Dot / Dual Road Bias Dot / 80 On Road 20 Off Road / Touring Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P234679', 158.99, '287.95', '287.95', 'Save up to Save $42.96 15%', 4.5, 48, 'nan', 'nan', 'Front; Rear', 5, '150/70R17 69V; 170/60R17 72V; 110/80R19 59V; 120/70R19 60V; 90/90-21 54V', 5, 'Michelin Anakee 3 Tires Michelin went back to the drawing board with the Anakee tire and didn''t stop until they were sure previous Anakee users would be satisfied. The Anakee has evolved in both performance and wear with a balance of long tread life and aggressive riding.', 'Performance that lasts mile after mile with a new silica tread compound yields even more mileage compared to MICHELIN® Anakee® 2 tires Innovative tread pattern inhibits irregular wear patterns, while evacuating water, dirt and mud Transverse grooves efficiently evacuate water for dependable wet-weather grip Beveled lateral grooves help shed mud and gravel when riding off-road Enhanced ride qualities and tire architecture engineered for easy maneuverability and precise handling Amazing stability and rider feedback, thanks to a new high-rigidity casing Indented tread grooves help to provide consistent lateral grip even as the tire wears Excellent wet traction and an innovative silica tread compounds offer the best balance between grip and durability Distinctive tread pattern pulls water away from the contact patch Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_anakee3_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_anakee3_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dual Road Radial Dot / Dual Road Bias Dot / 80 On Road 20 Off Road / Touring Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "150/70R17 69V; 170/60R17 72V; 110/80R19 59V; 120/70R19 60V; 90/90-21 54V"}', 50, 1, 1, NOW(), NOW());
