INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (81, '1821673.0', 'Michelin Power Cup 2 Tires', 'michelin-power-cup-2-tires-1821673.0', 'Michelin Tires', 4, 'STREET BIKE', 'Race Tire / Sportbike Tire / Multi Compound Tire / Dot Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P855241', 234.99, '462.95', '462.95', 'Save up to Save $124.96 27%', 4.7, 19, 'nan', 'nan', 'Front; Rear', 4, '120/70ZR17 58W TL; 180/55ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL', 4, 'Michelin Power Cup 2 Tires The Power Cup 2 from Michelin is a tire designed for 95% track use with DOT approval for the street. Dual compound construction puts a denser, more robust tread compound to the ground to cope with aggressive brake and throttle application while a softer compound increases grip at the tire''s shoulder. The tire''s groove ratio is less than 5%. Michelin tuned the Power Cup 2 for safe, predictable use with or without tire warmers. Warm-up periods are short. Add tire warmers to reach the Power Cup 2 Tire''s upper limits of grip even sooner. Handling is communicative with little to no specific setup adaptations required. Adaptive Casing Technology (ACT) matches these high levels of dry grip with predictable response from the carcass and sidewall at all angles of lean. Put simply, the Michelin''s Power Cup 2 is a treaded version of Michelin''s Power Slick 2 non-DOT racing slick.', 'Designed for high output liter- and open-class track machines 95% track / 5% street use Less than 5% groove ratio Engineered for use with or without tire warmers 2CT dual compound technology ACT+ adaptive casing technology SCT synthetic component technology DOT approved Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_power_cup2_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_power_cup2_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Race Tire / Sportbike Tire / Multi Compound Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/70ZR17 58W TL; 180/55ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL"}', 50, 1, 1, NOW(), NOW());
