INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (83, '1814156.0', 'Metzeler Roadtec 01 SE Tires', 'metzeler-roadtec-01-se-tires-1814156.0', 'Metzeler', 2, 'STREET BIKE', 'Sport Touring Radial Do / Sportbike Tire / Touring Tire / Dot Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P850771', 183.25, '353.53', '353.53', 'Save up to Save $85.56 24%', 4.7, 121, 'nan', 'nan', 'Front; Rear', 9, '120/70ZR17 58W SE; 150/70ZR17 69V SE; 160/60ZR17 69W SE; 170/60ZR17 72W SE; 180/55ZR17 73W SE; 190/50ZR17 73W SE; 190/55ZR17 75W SE; 110/80R19 59V SE; 120/70ZR19 60W SE', 9, 'Metzeler Roadtec 01 SE Tires The "SE", or "Supersport" version, of the Metzeler Road Tec 01 Tire takes the sport-touring prowess of the standard Road Tec 01 and increases the grip offered in the dry. The SE tread pattern and composition maintains the tire''s supersport-touring capabilities and wet weather performance. The SE version features a higher land/sea ratio along the shoulder block for enhanced traction at extreme lean angles. Sidewall construction is standard-duty across all options to communicate better with the road and offer more compliance under light- and medium-weight motorcycles.', 'Increased grip on wet roads, with a focus on low friction surfaces (such as city streets and worn tarmac, low temperature), thanks to radial position of grooves Rebalanced tire stiffness to allow a better adherence of the rubber with the tarmac micro-asperities, increasing mechanical grip even on lower friction surfaces Belt and carcass tension parameters upgraded to increase stability on rear tires during strong braking Increased mileage vs. Roadtec Z8 Interact (up to 10%), thanks to a different footprint shape (larger and shorter) which also enhances motorcycle handling Higher wear resistance, obtained through a revised land/sea ration on the rear tire in conjunction with the new tread design, ensures product performance consistency allowing users to enjoy the tire for its entire service life Blackwall Tubeless (TL) W rated for speeds of 168+ MPH Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/metzeler_roadtec01_se_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/metzeler_roadtec01_se_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sport Touring Radial Do / Sportbike Tire / Touring Tire / Dot Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "120/70ZR17 58W SE; 150/70ZR17 69V SE; 160/60ZR17 69W SE; 170/60ZR17 72W SE; 180/55ZR17 73W SE; 190/50ZR17 73W SE; 190/55ZR17 75W SE; 110/80R19 59V SE; 120/70ZR19 60W SE"}', 50, 1, 1, NOW(), NOW());
