INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (84, '10480810.0', 'Pirelli Diablo Powercruiser Tires', 'pirelli-diablo-powercruiser-tires-10480810.0', 'Pirelli', 2, 'STREET BIKE', 'Dot Tire / Harley Tire / Cruiser Tire', 'Harley-Davidson', 'Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard', '1990 - 2025', 'P1131995', 203.91, '521.43', '521.43', 'Save up to Save $132.32 25%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 15, '130/90B16 73H; 150/80B16 71H; 150/80B16 77H; 180/70B16 77H; 180/70R16 77V; 160/70B17 79V; 160/70R17 73V; 160/60R18 70V; 180/55B18 80H; 240/40R18 79V; 260/40R18 84V; 100/90-19 57H; 110/90-19 62H; 130/60B19 61H; 130/60B21 63H', 15, 'Pirelli Diablo Powercruiser Tires The Pirelli Diablo Powercruiser Tires represent the forefront of Pirelli''s high-performance series, designed especially for sport cruisers and high-powered tourers that frequently reach the bounds of their capabilities. These tires seamlessly blend into the Diablo family, known for their sport-centric attributes. With a design that prioritizes slickness at the shoulders, they excel in dry conditions, providing an aggressive edge during hard leans. The central portion of the tire sports the distinctive ''Flash'' pattern by Pirelli, facilitating enhanced grip and steadfast stability. Catering to contemporary V-twin motorcycles renowned for robust torque and agile handling, the Diablo Powercruiser merges appealing aesthetics with exceptional performance capabilities.', 'Iconic Diablo flash tread design Slick shoulder to enhance performance in dry conditions Dynamic handling with high level of precision Racing inspired structures for sport cruisers Excellent traction and stability at high speed High visibility sidewall design Sold individually Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/pirelli_diablo_powercruiser_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/pirelli_diablo_powercruiser_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Harley Tire / Cruiser Tire", "Make": "Harley-Davidson", "Model": "Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard", "Tire Size": "130/90B16 73H; 150/80B16 71H; 150/80B16 77H; 180/70B16 77H; 180/70R16 77V; 160/70B17 79V; 160/70R17 73V; 160/60R18 70V; 180/55B18 80H; 240/40R18 79V; 260/40R18 84V; 100/90-19 57H; 110/90-19 62H; 130/60B19 61H; 130/60B21 63H"}', 50, 1, 1, NOW(), NOW());
