INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (85, '10386861.0', 'Mitas Enduro Trail Plus Tires', 'mitas-enduro-trail-plus-tires-10386861.0', 'Mitas', 3, 'DIRT BIKE', '60 On Road 40 Off Road / Dot Tire / Hard Terrain / Intermediate Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1087803', 118.35, '230.99', '230.99', 'Save up to Save $28.24 12%', 4.1, 24, 'nan', 'nan', 'Front; Rear', 17, '120/90-17 64H; 130/80B17 65H; 140/80B17 69H; 150/70B17 69H; 170/60B17 72H; 120/80B18 62H; 140/80B18 70H; 150/70B18 70H; 150/70B18 70T; 4.00-18 64H; 100/90-19 57H; 100/90B19 57H; 110/80B19 59H; 120/70B19 60H; 90/90-21 54H; 90/90-21 54T; 90/90B21 54H', 17, 'Mitas Enduro Trail Plus Tires The Mitas Enduro Trail Tires feature a reinforced carcass and sidewall, coupled with a long-wearing rubber compound for extended durability.', 'Designed for 60% on-road / 40% off-road bias use on Adventure and Dual Sport motorcycles TL (Tubeless) and TT (Tube Type) applications E-07+ Sidewall marking confirms the highly popular original design Can be used in combination with other E-07/E-07+ or ENDURO TRAIL 60/40 and 50/50 tires (Dakar & Standard) for customized performance Features large chevron style block pattern and independent shoulder knobs for ideal handling and wear on tarmac combined with stable, predictable off-highway performance Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_plus_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_plus_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "60 On Road 40 Off Road / Dot Tire / Hard Terrain / Intermediate Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/90-17 64H; 130/80B17 65H; 140/80B17 69H; 150/70B17 69H; 170/60B17 72H; 120/80B18 62H; 140/80B18 70H; 150/70B18 70H; 150/70B18 70T; 4.00-18 64H; 100/90-19 57H; 100/90B19 57H; 110/80B19 59H; 120/70B19 60H; 90/90-21 54H; 90/90-21 54T; 90/90B21 54H"}', 50, 1, 1, NOW(), NOW());
