INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (88, '10454146.0', 'Metzeler RoadTec 02 Tires', 'metzeler-roadtec-02-tires-10454146.0', 'Metzeler', 2, 'STREET BIKE', '100 On Road 0 Off Road / Dot Tire / Multi Compound Tire / Touring Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1117735', 203.59, '378.28', '378.28', 'Save up to Save $91.50 24%', 4.5, 6, 'nan', 'nan', 'Front; Rear', 10, '120/70ZR17 58W; 150/70R17 69V; 160/60ZR17 69W; 170/60ZR17 72V; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 190/55ZR17 75W O Spec; 110/80R19 59V; 120/70ZR19 60V', 10, 'Metzeler Road Tec 02 Tires The Metzeler RoadTec 02 Tire is a hybrid marvel for those who crave the excitement of supersport performance with the comfort of sport-touring. Designed with a unique dual-mode tread pattern, the RoadTec caters to various riding styles. The simplified groove arrangement offers quick warm-up times, reliable water dispersal, and a smooth ride during relaxed cruising. In contrast, aggressive riding causes the groove''s center section to compact, enlarging the contact patch for enhanced grip and more precise steering. Regardless of pace, the RoadTec 02 Tires promise a serene riding experience with reduced vibration and noise, alongside effortless transitions into corners. Full silica compound gives higher chemical grip levels in wet conditions. All front tire sizes feature a single compound, Rear tires boast a dual-compound design - with 80% of the tread surface using the softer, grippier formulation.', 'Metzeler "super-sport-touring" technology Radial construction Adaptive Tread Design Single compound front applications Dual compound rear applications Rear tires feature soft compounds over 80% of tread surface High-performance and safety on a wide range of temperatures and asphalt conditions Flowing groove tread pattern During easy riding: Quick warm-up Compliant ride quality Excellent water evacuation During hard riding: Treads squeeze together Siping becomes more compact More rubber contacts road Increased grip Improve road feel Long tire life Increased stability Blackwall Tubeless (TL) in all sizes V and W speed ratings Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/metzeler_road_tec02_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/metzeler_road_tec02_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "100 On Road 0 Off Road / Dot Tire / Multi Compound Tire / Touring Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/70ZR17 58W; 150/70R17 69V; 160/60ZR17 69W; 170/60ZR17 72V; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 190/55ZR17 75W O Spec; 110/80R19 59V; 120/70ZR19 60V"}', 50, 1, 1, NOW(), NOW());
