INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (90, '1088477.0', 'Metzeler Roadtec 01 Tires', 'metzeler-roadtec-01-tires-1088477.0', 'Metzeler', 2, 'STREET BIKE', 'Sport Touring Radial Do / Sportbike Tire / Touring Tire / Dot Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P326537', 126.13, '351.12', '351.12', 'Save up to Save $84.97 24%', 4.7, 121, 'nan', 'nan', 'Front; Rear', 32, '3.25-19 54H TL; 100/90-16 54H TL; 110/90-16 59V TL; 130/90-16 67H TL; 150/80-16 71H TL; 100/80-17 52H TL; 110/70-17 54H TL; 110/80-17 57H TL; 120/60ZR17 55W TL; 120/70R17 58W TL; 120/70ZR17 58W TL; 120/70ZR17 58W TL HWM; 130/70-17 62H TL; 130/80-17 65H TL; 140/80-17 69V TL; 150/70-17 69V TL; 170/60R17 72W TL; 180/55ZR17 73W TL HWM; 190/50ZR17 73W HW; 190/50ZR17 73W TL; 190/55ZR17 75W TL; 190/55ZR17 75W TL HWM; 80/100-18 47P TL; 90/90-18 51P TL; 100/90-18 56V TL; 110/90-18 61V TL; 120/80-18 62H TL; 4.00-18 64V TL; 90/90-19 52H TL; 100/90-19 57V TL; 110/80R19 59V TL; 3.25-19 54V TL', 32, 'Metzeler Roadtec 01 Tires', 'Increased grip on wet roads, with a focus on low friction surfaces (such as city streets and worn tarmac, low temperature), thanks to radial position of grooves Rebalanced tire stiffness to allow a better adherence of the rubber with the tarmac micro-asperities, increasing mechanical grip even on lower friction surfaces Belt and carcass tension parameters upgraded to increase stability on rear tires during strong braking Increased mileage vs. Roadtec Z8 Interact (up to 10%), thanks to a different footprint shape (larger and shorter) which also enhances motorcycle handling Higher wear resistance, obtained through a revised land/sea ration on the rear tire in conjunction with the new tread design, ensures product performance consistency allowing users to enjoy the tire for its entire service life Metzeler multi-compound rear on selected sizes, with increased harmonization between the different compounds HWM (Heavy Weight Motorcycles) special version brings the ROADTEC 01 performances to a wider selection of motorcycles Increased stability by reducing both intensity and duration of oscillations due to road irregularities or steering maneuvers Distinguishable by a “Weight” icon next to the product name on the tire sidewall Increased stability is reached by employing stiffer carcass material and sidewall construction plus a slightly different compound recipe Blackwall Tubeless (TL) W rated for speeds of 168+ MPH SE = "Supersport" version with slicker shoulder tread for enhanced dry grip Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/metzeler_road_tec02_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/metzeler_road_tec02_tires.webp", "https://americaapi.kaafifoods.com/storage/products/metzeler_roadtec01_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sport Touring Radial Do / Sportbike Tire / Touring Tire / Dot Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "3.25-19 54H TL; 100/90-16 54H TL; 110/90-16 59V TL; 130/90-16 67H TL; 150/80-16 71H TL; 100/80-17 52H TL; 110/70-17 54H TL; 110/80-17 57H TL; 120/60ZR17 55W TL; 120/70R17 58W TL; 120/70ZR17 58W TL; 120/70ZR17 58W TL HWM; 130/70-17 62H TL; 130/80-17 65H TL; 140/80-17 69V TL; 150/70-17 69V TL; 170/60R17 72W TL; 180/55ZR17 73W TL HWM; 190/50ZR17 73W HW; 190/50ZR17 73W TL; 190/55ZR17 75W TL; 190/55ZR17 75W TL HWM; 80/100-18 47P TL; 90/90-18 51P TL; 100/90-18 56V TL; 110/90-18 61V TL; 120/80-18 62H TL; 4.00-18 64V TL; 90/90-19 52H TL; 100/90-19 57V TL; 110/80R19 59V TL; 3.25-19 54V TL"}', 50, 1, 1, NOW(), NOW());
