INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (91, '1275479.0', 'Bridgestone Battlax Adventure A41 Tires', 'bridgestone-battlax-adventure-a41-tires-1275479.0', 'Bridgestone', 1, 'STREET BIKE', 'Dual Road Radial Dot / Dual Road Bias Dot / Dual Onoff Dot / 90 On Road 10 Off Road', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P398559', 158.64, '385.37', '385.37', 'Save up to Save $108.73 28%', 4.6, 33, 'nan', 'nan', 'Front; Rear', 20, '120/70R15 56V M TL; 120/70ZR17 58W TL; 130/80R17 65H TL; 140/80R17 69V TL; 150/70R17 69V TL; 160/60ZR17 69W TL; 170/60R17 72V TL; 170/60R17 72W TL; 180/55ZR17 73W TL; 190/55R17 M TL; 190/55ZR17 75W TL; 110/80R18 58H TL; 150/70R18 G TT; 150/70ZR18 70W TL; 100/90V19 57V TL; 110/80R19 59V TL; 120/70R19 60V TL; 120/70ZR19 60W TL; 90/90-21 G TT; 90/90V21 54V TL', 20, 'Bridgestone Battlax Adventure A41 Tires The Bridgestone Battlax A41 Tires are designed for the modern day, high-powered adventure bikes. They put an emphasis on wet weather handling and a reassuring feel on any type of tarmac.', 'Improved grip in ALL conditions, when compared to the A40, with no reduction in tire life Greatly improved wet weather performance Mono-spiral belt constuction (MSB) together with a revised case construction provides improved contact feel and high speed stability Increased sea to land ratio at the shoulders provides better water evacuation at lean Rear tire groove angles optimized for water evacuation 3LC (dual compound) front tire 3LC Cap and Base rear tire construction (cap tread uses a soft silica compound with a medium silica compound base resulting in improved shock absorption and more grip without sacrificing rigidity) Rear tire features larger block tread at the center to improve tire life and high speed stability, especially on fully loaded ADV bikes 90/90-21 G OE Tube Type fitment for Honda Africa Twin CRF1000L 120/70R15 M OE fitment for Yamaha Niken 150/70R18 G OE Tube Type fitment for Honda Africa Twin CRF1000L 190/55R17 M OE fitment for Yamaha Niken Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/bridgestone_a41.webp', '["https://americaapi.kaafifoods.com/storage/products/bridgestone_a41.webp", "https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_adventure_a41_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dual Road Radial Dot / Dual Road Bias Dot / Dual Onoff Dot / 90 On Road 10 Off Road", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/70R15 56V M TL; 120/70ZR17 58W TL; 130/80R17 65H TL; 140/80R17 69V TL; 150/70R17 69V TL; 160/60ZR17 69W TL; 170/60R17 72V TL; 170/60R17 72W TL; 180/55ZR17 73W TL; 190/55R17 M TL; 190/55ZR17 75W TL; 110/80R18 58H TL; 150/70R18 G TT; 150/70ZR18 70W TL; 100/90V19 57V TL; 110/80R19 59V TL; 120/70R19 60V TL; 120/70ZR19 60W TL; 90/90-21 G TT; 90/90V21 54V TL"}', 50, 1, 1, NOW(), NOW());
