INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (94, '10321242.0', 'Motoz Tractionator Desert H/T Tires', 'motoz-tractionator-desert-h-t-tires-10321242.0', 'Motoz', 3, 'DIRT BIKE', '20 On Road 80 Off Road / 10 On Road 90 Off Road / Dot Dirt Tires / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1055051', 144.99, '285.99', '285.99', 'nan', 4.6, 10, 'nan', 'nan', 'Front; Rear', 10, '130/80-17 (M/C) 65M TT; 150/70B17 (M/C) 69Q TL; 110/100-18 (M/C) 64M TT; 130/90-18 (M/C) 69M TT; 140/80-18 (M/C) 70M TT; 150/70B18 (M/C) 70Q TL; 110/90-19 (M/C) 62M TT; 110/80B19 (M/C) 59Q TL; 90/90-21 (M/C) 54Q TL; 90/100-21 (M/C) 57M TT', 10, 'Motoz Tractionator Desert H/T Tires The Desert HT tires are designed to outperform the competition in desert rally-like conditions, offering great wear life and DOT compliance. If your current tires aren''t up to par in dry, high speed scenarios, the Desert H/T Tires may be your solution. Note: The Adventure Tubeless sizes (white/yellow stripes, see images) have a slightly different tread pattern than the Tube-Type enduro sizes (red stripes). For Adventure Bikes, these tires will provide a decent wear life when used for adventure/long distance riding. If used with excessive wheel spin, they will wear out quickly. Don’t expect to fit them to large capacity bikes, ride like an enduro pro and expect the tire to last very long or win a beauty contest. Large capacity adventure bikes punish tires to their limits and this is one of the only tires of its kind with deep tread for extreme soft terrain performance for big adventure bikes.', 'Heavy duty carcass on front sizes works great on heavy bikes Offered in Tube-Type (TT) and Tubeless (TL) sizes Intended for intermediate/hard terrain and rally use 15% on-road / 85% off-road 95% dry / 5% wet weather 90%hard / 10% soft terrain DOT approved Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_tractionator_desert_ht_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_tractionator_desert_ht_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "20 On Road 80 Off Road / 10 On Road 90 Off Road / Dot Dirt Tires / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "130/80-17 (M/C) 65M TT; 150/70B17 (M/C) 69Q TL; 110/100-18 (M/C) 64M TT; 130/90-18 (M/C) 69M TT; 140/80-18 (M/C) 70M TT; 150/70B18 (M/C) 70Q TL; 110/90-19 (M/C) 62M TT; 110/80B19 (M/C) 59Q TL; 90/90-21 (M/C) 54Q TL; 90/100-21 (M/C) 57M TT"}', 50, 1, 1, NOW(), NOW());
