INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (95, '10578487.0', 'Continental Sport Attack 5 Tires', 'continental-sport-attack-5-tires-10578487.0', 'Continental Tire', 4, 'STREET BIKE', 'Dot Tire / Multi Compound Tire / Sportbike Tire / Race Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P1181071', 186.67, '433.45', '433.45', 'Save up to Save $154.74 36%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 5, '120/70ZR17 58W TL; 160/60ZR17 69W TL; 180/55ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL', 5, 'Continental Sport Attack 5 Tires The Continental Sport Attack 5 Tires harness the latest technology to enhance your track days and weekend rides. Engineered for high performance, these tires offer exceptional grip and precision handling, enabling riders to push the limits with confidence. Whether chasing the racing line or carving through twisty roads, the Sport Attack 5 Tires deliver a thrilling and reliable riding experience.', 'Confident cornering through an innovative steel belt configuration using MultiZoneBelt technology: implementing a tighter spooling of the steel belt in the tire center ensures straight-line stability, while a broader spooling at the tire shoulder increases agility, contact patch and trust in high lean angles Outstanding grip thanks to the BlackChili Compound with a new mixture for enhanced road interlocking and optimized wear pattern during track riding Precise steering response due to a newly engineered carcass in which the stiffness zones of the tire vary in a targeted manner Outer profile "mini cuts" allow for flexibility and movement of the tire, leading to better warm-up and heat preservation Flatter angles of tread cuts for more aggressive supersport performance during acceleration out of lean angles Rapid warm-up thanks to specially optimized tread zones tailored to respective riding conditions TractionSkin surface for extremely safe and quick break-in time High void volume for better wet grip in areas where it is needed Larger dynamic footprint for better grip in extreme lean angles The tire’s solid backbone provides good mileage and stability', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/continental_tire_tire_csa5_mc58_wtl.webp', '["https://americaapi.kaafifoods.com/storage/products/continental_tire_tire_csa5_mc58_wtl.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Multi Compound Tire / Sportbike Tire / Race Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/70ZR17 58W TL; 160/60ZR17 69W TL; 180/55ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL"}', 50, 1, 1, NOW(), NOW());
