INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (96, '874652.0', 'Metzeler Roadtec Z8 Interact Tires', 'metzeler-roadtec-z8-interact-tires-874652.0', 'Metzeler', 2, 'STREET BIKE', 'Sport Touring Radial Do / Touring Tire / Multi Compound Tire / Dot Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P199437', 141.51, '324.48', '324.48', 'Save up to Save $66.49 20%', 4.5, 106, 'nan', 'nan', 'Front; Rear', 17, '110/70ZR17 M Spec; 120/70ZR17 58W E; 120/70ZR17 58W M Spec; 150/70ZR17 TL M Spec; 160/60ZR17 69W TL M Spec; 170/60ZR17 72W TL; 180/55ZR17 73W TL K Spec; 180/55ZR17 73W TL M Spec; 180/55ZR17 73W TL O Spec; 190/50ZR17 73W TL M Spec; 190/50ZR17 73W TL O Spec; 190/55ZR17 75W TL M Spec; 190/55ZR17 75W TL O Spec; 110/80ZR18 M Spec; 120/70ZR18 M Spec; 140/70ZR18 67W TL M Spec; 160/60ZR18 70W TL M Spec', 17, 'Metzeler Roadtec Z8 Interact Tires The new Metzeler Roadtec Z8 Interact allows the rider to keep everything under control. The Road Tec Z8 follows the rider''s instincts with a sublime blend of precise and effortless handing.', 'Multi Zone Tension technology, new updated tread profiles and functional tread pattern place the Z8 Roadtec Interact at the top of the sport touring tire class 8% wider final footprint area than its predecessor due to the variation of steel belt tensions and a strategically placed tread pattern which optimizes pressures in the footprint area 0° Steel Radial technology MAW (Metzeler Advanced Winding) technology The profile shape, inspired by the Greek letter "Pi", maximizes the flexibility of the profile, thus ensuring an optimum tire footprint under in all conditions The 3-zone-tension Interact ™ Technology gives outstanding mileage and sporty cornering grip FCM (Fine Carbon Mix) High Silica compound with Nano particles ensures performance and safety in all weather conditions Innovative tread pattern, a widened and more elliptical footprint and a host of wear-resistant technologies not normally seen in motorcycle tires give the Roadtec Z8 Interact its best-in-segment mileage and optimal wet performance throughout the tires life New patented tread pattern with strategically placed longitudinal central grooves provide ideal drainage for more than 3/4 of all lean angles in the wet. The remaining tread grooves work to add tread flexibility, extending the footprint for stability in the dry Updated design improves wear regularity which gives riders the benefit of a consistent riding performance across the tires entire life O-Spec features a bi-compound design and a 2-ply carcass for heavy sport-touring bikes E-Spec tire is OE on Honda NC700X K-Spec tire is OE on BMW K1300GT M-Spec tires feature a bi-compound design (W)-rated for speeds of 168+ mph Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/MetzelerRoadtec_Z8_Interact_Sport_Touring_Front_Tire.webp', '["https://americaapi.kaafifoods.com/storage/products/MetzelerRoadtec_Z8_Interact_Sport_Touring_Front_Tire.webp", "https://americaapi.kaafifoods.com/storage/products/metzeler_roadtec_z8_interact_tires.webp", "https://americaapi.kaafifoods.com/storage/products/metzeler_roadtec_z8_interact_o_rear_tire.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sport Touring Radial Do / Touring Tire / Multi Compound Tire / Dot Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "110/70ZR17 M Spec; 120/70ZR17 58W E; 120/70ZR17 58W M Spec; 150/70ZR17 TL M Spec; 160/60ZR17 69W TL M Spec; 170/60ZR17 72W TL; 180/55ZR17 73W TL K Spec; 180/55ZR17 73W TL M Spec; 180/55ZR17 73W TL O Spec; 190/50ZR17 73W TL M Spec; 190/50ZR17 73W TL O Spec; 190/55ZR17 75W TL M Spec; 190/55ZR17 75W TL O Spec; 110/80ZR18 M Spec; 120/70ZR18 M Spec; 140/70ZR18 67W TL M Spec; 160/60ZR18 70W TL M Spec"}', 50, 1, 1, NOW(), NOW());
