INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (97, '719814.0', 'Dunlop American Elite Tires', 'dunlop-american-elite-tires-719814.0', 'Dunlop', 2, 'STREET BIKE', 'Customcruisertouring Bi / Customcruisertouring Ra / Cruiser Tire / Harley Tire', 'Harley-Davidson', 'Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard', '1990 - 2025', 'P181641', 163.99, '411.95', '411.95', 'Save up to Save $71.96 17%', 4.9, 1960, 'nan', 'nan', 'Front; Rear', 29, '130/90B16 73H TL; MT90B16 72H TL; MT90B16 74H TL; 130/90B16 67H TL WWW; MT90B16 72H TL NWS; MT90B16 72H TL WWW; MT90B16 74H TL NWS; MT90B16 74H TL WWW; MU85B16 77H TL; MU85B16 77H TL NWS; MU85B16 77H TL WWW; 140/90B16 77H TL WWW; 150/80B16 77H TL; 180/65B16 81H TL; 180/65B16 81H TL NWS; 180/65B16 81H TL WWW; 130/80B17 65H TL; 130/80B17 65H TL NWS; 140/75R17 67V TL; 160/70B17 73V TL; 200/55R17 78V TL; 130/70B18 63H TL; 180/55B18 80H TL; 240/40R18 79V TL; 100/90-19 57H TL; 130/60B19 61H TL; MH90B21 54H TL; 130/60B21 63H TL; 130/60B21 69H TL', 29, 'Dunlop American Elite Tires The Dunlop American Elite tires are the only replacement motorcycle tires for Harley-Davidson bikes that are designed in America, made in America and tested in America. The Multi-Tread (MT) rear tire is built with a high-mileage compound in middle of the tread and lateral-grip compound in each side to increase turning performance.', 'Available in Blackwall, Narrow White Stripe (NWS) and Wide Whitewall (WWW) H-rated for speeds up to 130 mph V-rated for speeds up to 149 mph Made in the USA Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_american_elite2nd_generation_harley_davidson_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_american_elite2nd_generation_harley_davidson_tires.webp", "https://americaapi.kaafifoods.com/storage/products/Drag_site_icon_to_your_taskbar_to_pin_site_.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Customcruisertouring Bi / Customcruisertouring Ra / Cruiser Tire / Harley Tire", "Make": "Harley-Davidson", "Model": "Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard", "Tire Size": "130/90B16 73H TL; MT90B16 72H TL; MT90B16 74H TL; 130/90B16 67H TL WWW; MT90B16 72H TL NWS; MT90B16 72H TL WWW; MT90B16 74H TL NWS; MT90B16 74H TL WWW; MU85B16 77H TL; MU85B16 77H TL NWS; MU85B16 77H TL WWW; 140/90B16 77H TL WWW; 150/80B16 77H TL; 180/65B16 81H TL; 180/65B16 81H TL NWS; 180/65B16 81H TL WWW; 130/80B17 65H TL; 130/80B17 65H TL NWS; 140/75R17 67V TL; 160/70B17 73V TL; 200/55R17 78V TL; 130/70B18 63H TL; 180/55B18 80H TL; 240/40R18 79V TL; 100/90-19 57H TL; 130/60B19 61H TL; MH90B21 54H TL; 130/60B21 63H TL; 130/60B21 69H TL"}', 50, 1, 1, NOW(), NOW());
