n', 'https://americaapi.kaafifoods.com/storage/products/continental_sport_attack2_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/continental_sport_attack2_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Hypersport Dot / Sportbike Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/70ZR17 58W TL; 160/60ZR17 69W TL; 180/55ZR17; 180/55ZR17 73W TL; 190/50ZR17 73W TL; 190/55ZR17 75W TL"}', 50, 1, 1, NOW(), NOW());
