INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (102, '10438650.0', 'Avon 3D Supersport Tires', 'avon-3d-supersport-tires-10438650.0', 'Avon Tire', 1, 'STREET BIKE', 'Dot Tire / Sportbike Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P1109282', 132.26, '260.16', '260.16', 'Save up to Save $47.30 18%', 5.0, 3, 'nan', 'nan', 'Front; Rear', 10, '120/60ZR17 55W TL 1DK; 120/70ZR17 58W TL; 160/60ZR17 69W; 180/55ZR17 73W TL; 180/60ZR17 75W TL; 180/60ZR17 75W TL 1 DK; 190/50ZR17 73W TL 1DK; 190/55ZR17 75W TL; 190/55ZR17 75W TL 1DK; 200/55ZR17 78W TL', 10, 'Avon 3D Supersport Tires The Avon 3D Supersport Tires deliver a performance that echoes the thrill of the racetrack, tailored for road use. This product stands out with its track-developed construction, which significantly improves handling, stability, and rider feedback. Although the tires are primarily road-focused, extensive on-track testing confirms their reliability and exciting performance during track days. Innovative Silica Dual Compound technology is central to this design, optimizing grip while promoting tire longevity. The rear tire incorporates a tougher central compound for longer mileage, complemented by softer edges that provide superior cornering traction.', 'Enhanced road contact generates extensive grip Optimized handling, stability and feedback for the rider State of the are Silica Dual Compound Technology', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/avon3_d_supersport_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/avon3_d_supersport_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Sportbike Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/60ZR17 55W TL 1DK; 120/70ZR17 58W TL; 160/60ZR17 69W; 180/55ZR17 73W TL; 180/60ZR17 75W TL; 180/60ZR17 75W TL 1 DK; 190/50ZR17 73W TL 1DK; 190/55ZR17 75W TL; 190/55ZR17 75W TL 1DK; 200/55ZR17 78W TL"}', 50, 1, 1, NOW(), NOW());
