INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (103, '981146.0', 'Continental TKC 70 Tires', 'continental-tkc-70-tires-981146.0', 'Continental Tire', 2, 'STREET BIKE', '80 On Road 20 Off Road / Touring Tire / Dual Sport Tire / Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P283043', 255.47, '464.95', '464.95', 'Save up to Save $96.89 21%', 4.2, 122, 'nan', 'nan', 'Front; Rear', 10, '120/70ZR17 58W TL; 140/80R17 69H TL; 150/70R17 69V TL; 160/60ZR17 69W TL; 170/60R17 72V TL; 180/55ZR17 73W TL; 110/80R18 58H TL; 150/70R18 70H TL; 110/80R19 59V TL; 120/70R19 60V TL', 10, 'Continental TKC70 Dual Sport Tires Bridging the gap between the more off-road oriented TKC 80 Twinduro Tires and the Trail Attack 2 Tires, the Continental TKC70 Tires make an excellent balance between on-road and light off-road adventures. Featuring innovations you''ve come to expect from Continental like 0° steel belt construction for superior stability and comfort even at high cruising speeds and Continuous Compound-Technology, the TKC70 tires adapt to changing conditions with ease. Specifically designed to help alleviate the complaints of short wear-life of the TKC80 Tires, the usability of a slightly more street-oriented design has been improved and is apparent with the TKC 70.', '80% on-road / 20% off-road balance is equally at home on light trail work as they are on slab Provides a high level of grip in all wet and dry conditions Excellent mileage for long trips on asphalt Quiet high-speed stability due to the central band on the rear tire Aggressive siping and self-cleaning grooves add to the all-weather prowess Ideal ADV Tire choice for larger displacement bikes Eligible for Continental''s free 3 year roadside warranty Pair the Dual Sport front tire with TKC 70 Rocks rear tire for more aggressive off-road bias Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/continental_tkc70_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/continental_tkc70_tires.webp", "https://americaapi.kaafifoods.com/storage/products/continental_tkc70_tires_rear.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "80 On Road 20 Off Road / Touring Tire / Dual Sport Tire / Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/70ZR17 58W TL; 140/80R17 69H TL; 150/70R17 69V TL; 160/60ZR17 69W TL; 170/60R17 72V TL; 180/55ZR17 73W TL; 110/80R18 58H TL; 150/70R18 70H TL; 110/80R19 59V TL; 120/70R19 60V TL"}', 50, 1, 1, NOW(), NOW());
