INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (104, '1806538.0', 'Continental TKC 70 Rocks Tires', 'continental-tkc-70-rocks-tires-1806538.0', 'Continental Tire', 2, 'STREET BIKE', '60 On Road 40 Off Road / Touring Tire / Dual Sport Tire / Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P846225', 233.94, '450.95', '450.95', 'Save up to Save $158.11 35%', 4.7, 41, 'nan', 'nan', 'Rear', 5, '130/80R17 65S; 140/80R17 69S; 150/70R17 69S; 170/60R17 72S; 150/70R18 70S', 5, 'Continental TKC 70 Rocks Tires Bridging the gap between the more off-road oriented TKC 80 Twinduro Tires and the Trail Attack 2 Tires, the Continental TKC70 Rocks Tires make an excellent 60% on-road and 40% off-road option. More rugged offroad traction and the same balanced street performance as the original Continental TKC70 tire. Featuring innovations you''ve come to expect from Continental like 0° steel belt construction for superior stability and comfort even at high cruising speeds and Continuous Compound-Technology, the TKC70 Rocks tires adapt to changing conditions with ease. Specifically designed to help alleviate the complaints of short wear-life of the TKC80 Tires, the usability of a slightly more street-oriented design has been improved and is apparent with the TKC 70.', '60% on-road / 40% off-road Provides a high level of grip in all wet and dry conditions Equally at home on light trail work as they are on slab Excellent mileage for long trips on asphalt Quiet high-speed stability due to the central band on the rear tire Aggressive siping and self-cleaning grooves add to the all-weather prowess Ideal ADV Tire choice for larger displacement bikes Eligible for Continental''s free 3 year roadside warranty Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/continental_tkc70_rocks_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/continental_tkc70_rocks_tires.webp"]', '{"Wheel Location": "Rear", "Type": "STREET BIKE", "Product Type": "60 On Road 40 Off Road / Touring Tire / Dual Sport Tire / Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "130/80R17 65S; 140/80R17 69S; 150/70R17 69S; 170/60R17 72S; 150/70R18 70S"}', 50, 1, 1, NOW(), NOW());
