INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (105, '941748.0', 'Michelin Pilot Road 4 GT Tires', 'michelin-pilot-road-4-gt-tires-941748.0', 'Michelin Tires', 2, 'STREET BIKE', 'Sport Touring Radial Do / Touring Tire / Dot Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P261884', 181.0, '363.95', '363.95', 'Save up to Save $74.96 21%', 4.8, 86, 'nan', 'nan', 'Front; Rear', 5, '120/70ZR17 58W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 120/70ZR18 59W', 5, 'Michelin Pilot Road 4 GT Tires Next generation sport touring tire delivering maximum safety, especially on wet roads and during braking GT version specifically designed for heavier touring bikes with a stiffer casing and patented technology for superior stability and comfort, whether riding solo, two up or with luggage Stops shorter in the wet compared to leading competitors Exceptional longevity: Up to 20% longer tread life than Michelin Pilot Road 3 tires Features 2 Compound Technology with new silica charged rubber compounds for excellent grip in a wide temperature range (23°F to 113°F). New XST+ siping and enhanced tread patterns ensure optimum grip at all lean angles, even in challenging conditions. OEM choice for the BMW R1200RT, affirming its performance for GT class motorcycles. Please Note: Check your manufacturer''s specifications for required load ratings when replacing OE Tires. Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount Meet the Michelin Pilot Road 4 GT, the next evolution in sport touring tires, engineered to provide unparalleled safety and performance, especially for heavier GT class motorcycles. Built on Michelin’s Total Performance strategy, these tires deliver enhanced safety in diverse conditions, particularly on wet surfaces and during critical braking maneuvers. The GT version boasts a specialized stiffer casing, ensuring the stability and comfort demanding riders expect, whether touring solo, with a passenger or fully loaded. Experience the confidence of extended tire life and superior grip across a wide range of temperatures and road surfaces. Exceptional Wet & Cold Grip The Pilot Road 4 GT excels in challenging conditions. Its XST+ siping and silica compounds ensure outstanding wet grip for shorter stops and greater confidence. It performs reliably from 23°F to 113°F, delivering dependable traction and maximum safety on varied road surfaces, especially slippery ones. Durability, Stability & Comfort Tailored for Grand Touring bikes, the Pilot Road 4 GT boasts up to 20% longer tread life than the Pilot Road 3. Its stiffer casing with Michelin Radial 2AT Technology delivers crucial stability and superb handling for heavier loads, two up riding, or solo journeys, plus comfort for long distances. OEM choice for the BMW R1200RT.', 'nan', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_pilot_road4_gt_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_pilot_road4_gt_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sport Touring Radial Do / Touring Tire / Dot Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "120/70ZR17 58W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 120/70ZR18 59W"}', 50, 1, 1, NOW(), NOW());
