unt Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "50 On Road 50 Off Road / Hard Terrain / Dot Tire / Intermediate Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/90B17 64H; 130/80B17 65H; 140/80B17 69H; 150/70B17 69H; 130/80B18 72H; 140/80B18 70H; 150/70B18 70H; 110/80-19 59H; 90/90-21 54H"}', 50, 1, 1, NOW(), NOW());
