INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (110, '10590390.0', 'Dunlop Geomax MX54 Tires', 'dunlop-geomax-mx54-tires-10590390.0', 'Dunlop', 3, 'DIRT BIKE', 'Intermediate Terrain / Non Dot Tire / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1187335', 47.99, '197.95', '197.95', 'Save up to Save $44.96 23%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 17, '60/100-10; 70/100-10; 60/100-12; 80/100-12; 60/100-14; 90/100-14; 90/100-16; 70/100-17; 100/100-18; 110/100-18; 120/90-18; 70/100-19; 100/90-19; 110/90-19; 120/80-19; 120/90-19; 80/100-21', 17, 'Dunlop Geomax MX54 Tires The MX54 surpasses its predecessor, the MX53, by delivering exceptional performance right off the line. Dunlop has optimized the compound and tread design to excel on hard pack surfaces while maintaining traction on intermediate terrain. Whether facing tacky conditions or transitioning to a harder groove, the MX54 provides reliable sliding and aggressive grip, helping riders maintain control and achieve faster lap times.', 'Progressive Cornering Block Technology (PCBT Advanced) for elite slide control Multiple Block Distribution (MBD) increases feel and ground contact Continuous center groove on front tire for stable braking and turn-in Revised tread pattern for a wider performance window on hard terrain High-durability carcass designed to maintain predictability from start to finish Not DOT approved', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_geomax_mx54_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_geomax_mx54_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Intermediate Terrain / Non Dot Tire / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "60/100-10; 70/100-10; 60/100-12; 80/100-12; 60/100-14; 90/100-14; 90/100-16; 70/100-17; 100/100-18; 110/100-18; 120/90-18; 70/100-19; 100/90-19; 110/90-19; 120/80-19; 120/90-19; 80/100-21"}', 50, 1, 1, NOW(), NOW());
