INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (115, '1084192.0', 'Metzeler Racetec RR K3 Tires', 'metzeler-racetec-rr-k3-tires-1084192.0', 'Metzeler', 4, 'STREET BIKE', 'Road Race Dot And Non D / Race Tire / Sportbike Tire / Dot Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P324360', 168.86, '434.59', '434.59', 'Save up to Save $117.87 27%', 4.6, 16, 'nan', 'nan', 'Front; Rear', 6, '120/70ZR17 58W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W', 6, 'Metzeler Racetec RR K3 Tires Road Races are one of the most difficult and challenging racing activities due to the combination of circuit length, speed, altitude, temperature variation and variety of tarmac. The Metzeler Racetec RR has been engineered to cope with all these different situation in just one race, providing unmatched durability and versatility.', 'High flexibility polymers Combined stiffness structure Adapt to tarmac micro-texture Dual compound rear tire Resistance to abrasion Precision & stability W-rated for speeds up to 168 mph Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/metzeler_racetec_rrk3_frt.webp', '["https://americaapi.kaafifoods.com/storage/products/metzeler_racetec_rrk3_frt.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Road Race Dot And Non D / Race Tire / Sportbike Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/70ZR17 58W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W"}', 50, 1, 1, NOW(), NOW());
