INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (117, '1841617.0', 'Bridgestone Battlax RS11 Tires', 'bridgestone-battlax-rs11-tires-1841617.0', 'Bridgestone', 1, 'STREET BIKE', 'Hypersport Dot / Sportbike Tire / Multi Compound Tire / Dot Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P865272', 243.0, '473.26', '473.26', 'Save up to Save $118.26 25%', 4.7, 14, 'nan', 'nan', 'Front; Rear', 3, '120/70ZR17 58W; 190/55ZR17 75W; 200/55ZR17 78W', 3, 'Bridgestone Battlax RS11 Tires The Battlax RS11 Tires are Bridgestone''s flagship hypersport street tire. It is a street-tuned adaptation of Bridgestone''s R11 Race track compound. Dry grip, cornering stability, handling, and contact feel are taken to their absolute apex. It is the first road oriented tire that has adopted the new V-MS Belt construction in the rear - which is currently used only in Bridgestone’s non-DOT race tires. A revised molecular approach for compound formulation uses a novel, reduced particle size when adding carbon to the tire''s blend. The result is improved bite to the road surface and enhanced communication to the rider. The RS11 is the successor to the RS10, which was standard equipment on numerous top spec sport motorcycles. From winding roads to the track and back, the evolution of Bridgestone racing heritage is undeniable.', 'Bridgestone''s most aggressive street tire Designed for street riders seeking track-level performance Tread pattern and rubber compounds maximized for dry riding conditions V-MS Belt rear tire construction for enhanced temperature capacity and reduced weight Revised molecular approach using reduced carbon particle sizes 3LC multi-compound construction create greater grip, increased cornering stability and improved rider feedback Enhanced shoulder grooves result in larger contact patch for better grip at extreme lean angles Enhanced water dispersion due to new groove design 1.9 seconds faster per lap versus the outgoing Bridgestone RS10* DOT approved *Bridgestone internal testing on a 2 minute lap average. Your results may vary. Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_rs11_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_rs11_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Hypersport Dot / Sportbike Tire / Multi Compound Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/70ZR17 58W; 190/55ZR17 75W; 200/55ZR17 78W"}', 50, 1, 1, NOW(), NOW());
