INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (118, '10316797.0', 'Continental Road Attack 4 GT Tires', 'continental-road-attack-4-gt-tires-10316797.0', 'Continental Tire', 2, 'STREET BIKE', 'Dot Tire / Multi Compound Tire / Touring Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P1071985', 218.33, '473.45', '473.45', 'Save up to Save $177.26 37%', 4.8, 32, 'nan', 'nan', 'Front; Rear', 4, '120/70ZR17 58W TL; 180/55ZR17 73W TL; 190/50ZR17 73W TL; 190/55ZR17 75W TL', 4, 'Continental Road Attack 4 GT Tires Experience enhanced riding with the Continental Road Attack 4 GT Tires. These tires redefine wet weather performance through an innovative compound and updated tread pattern, delivering exceptional wet surface grip. Tailored for heavier bikes and extended trips with passengers and cargo these tires excel in touring attributes such as comfort, stability, and mileage. The introduction of a ''slick'' region on the upper tread shoulder enhances grip in diverse conditions, particularly dry ones. With improved cold and wet weather warm-up these tires instill immediate trust and safety. Their intuitive handling characteristics make them a prime choice for heavyweight touring motorcycles ensuring a seamless and confident ride on every occasion.', 'Performance oriented tread pattern for excellent grip in both wet and dry conditions Outstanding touring characteristics for heavier touring bikes Faster warm-up in cold and wet conditions Compound for improved wet grip in cold and slippery conditions Easy intuitive handling characteristics and optimal cornering grip TractionSkin technology ensures tires are ready to use straight away and a short break-in period Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/continental_road_attack4_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/continental_road_attack4_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Multi Compound Tire / Touring Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "120/70ZR17 58W TL; 180/55ZR17 73W TL; 190/50ZR17 73W TL; 190/55ZR17 75W TL"}', 50, 1, 1, NOW(), NOW());
