INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (121, '157516.0', 'Kenda K-760 Trakmaster II Tires', 'kenda-k-760-trakmaster-ii-tires-157516.0', 'nan', 3, 'DIRT BIKE', '10 On Road 90 Off Road / Dot Dirt Tires / Soft Terrain / Intermediate Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P42705', 25.64, '106.99', '106.99', 'Save up to Save $17.10 16%', 4.7, 59, 'nan', 'nan', 'Rear; Front; Front/Rear', 17, '2.50x10; 80/100-12; 60/100-14; 90/100-14; 90/100-16; 70/100-17; 130/90-17; 100/100-18; 110/100-18; 120/100-18; 140/80-18; 70/100-19; 100/90-19; 110/90-19; 120/90-19; 80/100-21; 90/90-21', 17, 'Kenda K-760 Trakmaster II Tires The legendary Trakmaster continues to be known for great value. Hit the trail and don''t be afraid to take it to the road between trails. Features Legal for highway use 10% on-road / 90% off-road Aggressive knobs are designed for dirt performance For maximum traction on soft and intermediate surfaces Stiffer bead and sidewall construction provide stability and better cornering control Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/kenda_k760_trakmaster_ii_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/kenda_k760_trakmaster_ii_tires.webp", "https://americaapi.kaafifoods.com/storage/products/Kenda_Trakmaster_II_K-760.webp"]', '{"Wheel Location": "Rear; Front; Front/Rear", "Type": "DIRT BIKE", "Product Type": "10 On Road 90 Off Road / Dot Dirt Tires / Soft Terrain / Intermediate Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "2.50x10; 80/100-12; 60/100-14; 90/100-14; 90/100-16; 70/100-17; 130/90-17; 100/100-18; 110/100-18; 120/100-18; 140/80-18; 70/100-19; 100/90-19; 110/90-19; 120/90-19; 80/100-21; 90/90-21"}', 50, 1, 1, NOW(), NOW());
