INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (122, '10321419.0', 'Motoz Tractionator Enduro I/T Tires', 'motoz-tractionator-enduro-i-t-tires-10321419.0', 'Motoz', 3, 'DIRT BIKE', '10 On Road 90 Off Road / 20 On Road 80 Off Road / Dot Dirt Tires / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1055161', 125.99, '153.99', '153.99', 'nan', 4.6, 7, 'nan', 'nan', 'Rear; Front', 5, '110/100-18 (M/C) 64R TT; 120/90-18 (M/C) 65R TT; 130/90-18 (M/C) 69R TT; 110/90-19 (M/C) 62R TT; 90/90-21 (M/C) 54R TT', 5, 'Motoz Tractionator Enduro I/T Tires The Tractionator Enduro IT can do it all - built to be the all-terrain option for all riding conditions, the Enduro IT offers the grip you''d expect from a motocross tire, while also providing exceptional durability and a DOT homologation. It is an excellent choice for a wide variety of terrain and weather conditions. The I/T excels on steep hill climbs and tight twisting single trails. The natural rubber compound and unique tread work with the terrain, creating drive and lift over obstacles as a result.', 'Intended for use in intermediate terrain Proven reliability for long distance events Natural / synthetic hybrid rubber construction 15% on-road / 85% off-road 50% dry / 50% wet weather 50% hard / 50% soft terrain DOT approved Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_tractionator_enduro_it_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_tractionator_enduro_it_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "DIRT BIKE", "Product Type": "10 On Road 90 Off Road / 20 On Road 80 Off Road / Dot Dirt Tires / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/100-18 (M/C) 64R TT; 120/90-18 (M/C) 65R TT; 130/90-18 (M/C) 69R TT; 110/90-19 (M/C) 62R TT; 90/90-21 (M/C) 54R TT"}', 50, 1, 1, NOW(), NOW());
