INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (124, '974479.0', 'Metzeler Sportec M7 RR Tires', 'metzeler-sportec-m7-rr-tires-974479.0', 'Metzeler', 2, 'STREET BIKE', 'Hypersport Dot / Sportbike Tire / Touring Tire / Dot Tire', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P279845', 144.67, '294.58', '294.58', 'Save up to Save $67.01 23%', 4.8, 127, 'nan', 'nan', 'Front; Rear', 10, '130/70ZR16 61W; 110/70ZR17 54W; 120/60ZR17 55W; 120/70ZR17 58W; 150/60ZR17 66W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W', 10, 'Metzeler Sportec M7RR Tires The Metzeler Sportec M7 RR is engineered to empower riders with a sporty riding style who use their motorcycles in all conditions, weather and temperatures. The M7RR is derived from Metzeler''s experience in Road Racing, including the Isle of Man TT and the Metzeler Ulster Grand Prix and features completely new profiles, structure materials, compounds and tread pattern.', 'The combination of profiles derived from the Road Racing activities with high stiffness structures delivers an extremely agile handling for a sporty riding style on all roads The longitudinal grooves are interrupted by compound bridges to increase the thrust in acceleration, enhance stability of tread compound and improve wear regularity 100% Silica compounds combined with a special tread pattern gives the SPORTEC M7 RR the unique capability to keep the sporty riding style in cold weather, wet roads and greasy and grimy tarmac surfaces The rear tire is Dual-Compound with a 40%-20%-40% layout Unique profile provides an immediate dive into a lean from the upright position and agile handling for quick direction change 20% more mileage compared to the SPORTEC M5 Interact and dual compound construction on rear sizes allows the use of a specific material on the central slick portion of the tread pattern to increase abrasion resistance and extend the mileage capability Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/metzeler_sportec_m7_rr_front_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/metzeler_sportec_m7_rr_front_tires.webp", "https://americaapi.kaafifoods.com/storage/products/metzeler_sportec_m7_rr_rear_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Hypersport Dot / Sportbike Tire / Touring Tire / Dot Tire", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "130/70ZR16 61W; 110/70ZR17 54W; 120/60ZR17 55W; 120/70ZR17 58W; 150/60ZR17 66W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W"}', 50, 1, 1, NOW(), NOW());
