INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (126, '1813170.0', 'Dunlop D908RR Rally Raid Tires', 'dunlop-d908rr-rally-raid-tires-1813170.0', 'Dunlop', 1, 'STREET BIKE', 'Dual Onoff Dot / 20 On Road 80 Off Road / 10 On Road 90 Off Road / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P43201', 219.99, NULL, NULL, 'Save $87.96 29%', 4.6, 16, 'nan', 'nan', 'Rear', 1, '150/70-18', 1, 'Dunlop D908 RR Dual Sport Tires The dual-sport D908RR is designed specifically to cope with the speed, horsepower and weight of large-displacement rally-type dual-sport machines.', 'Developed in Europe for rally racing, such as the famous Paris-Dakar Rally Street-legal with an emphasis on aggressive desert-enduro offroad riding Reinforced tread blocks yield exceptional traction and stability The generous open space around the shoulder area provides ultimate traction in sand and mud Heavy-duty casing provides excellent bump absorption and allows lower air pressures for a larger footprint and increased traction The D908RR is DOT-approved for road-legal use Tube type tires Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/Dunlop_D908_Rally_Raid_Enduro.webp', '["https://americaapi.kaafifoods.com/storage/products/Dunlop_D908_Rally_Raid_Enduro.webp"]', '{"Wheel Location": "Rear", "Type": "STREET BIKE", "Product Type": "Dual Onoff Dot / 20 On Road 80 Off Road / 10 On Road 90 Off Road / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "150/70-18"}', 50, 1, 1, NOW(), NOW());
