INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (127, '10207037.0', 'Dunlop Geomax MX14 Tires', 'dunlop-geomax-mx14-tires-10207037.0', 'Dunlop', 3, 'DIRT BIKE', 'Off Highway Non Dot Inc / Dirt Bike Tire / Mud Tire / Sand Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P989336', 50.99, '180.95', '180.95', 'Save up to Save $31.96 18%', 4.5, 15, 'nan', 'nan', 'Rear', 8, '70/100-10; 80/100-12; 90/100-14; 90/100-16; 110/100-18; 100/90-19; 110/90-19; 120/80-19', 8, 'Dunlop Geomax MX14 Tires When the sand gets deep or the mud starts flowing, the Dunlop MX14 is your answer. Designed specifically for the gnarliest motocross conditions, the MX14 takes cues from the successful MX12 tire but in a more refined and technical package. The MX14 offers increased drive-grip and traction on starts, straights and when exiting corners, improved braking performance for more rear tire stopping power in harsh conditions, perfect slide control when braking and cornering in sand and mud, and enhanced damping performance to keep the tire on the ground and digging in.', 'Designed for deep sand and mud conditions Increased knob height (18% over MX12) increases drive-grip and traction Updated rubber compound improves durability and increases traction through less knob flex Enhanced block angles and flexible support fins on the braking side of knob offer improved braking and slide control Construction has an additional ply to improve the linearity of the sidewall stiffness and enhance damping and absorption performance Offered in a complete range of rear sizes from minis to big bikes Pairs well with a MX12, MX33 or MX3S front Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_geomax_mx14_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_geomax_mx14_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "Off Highway Non Dot Inc / Dirt Bike Tire / Mud Tire / Sand Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "70/100-10; 80/100-12; 90/100-14; 90/100-16; 110/100-18; 100/90-19; 110/90-19; 120/80-19"}', 50, 1, 1, NOW(), NOW());
