INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (128, '10101834.0', 'Michelin Harley-Davidson Scorcher Adventure Tires', 'michelin-harley-davidson-scorcher-adventure-tires-10101834.0', 'Michelin Tires', 2, 'STREET BIKE', '80 On Road 20 Off Road / Dot Tire / Dual Sport Tire / Harley Tire', 'Harley-Davidson', 'Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard', '1990 - 2025', 'P926366', 194.99, '351.95', '351.95', 'Save up to Save $103.96 30%', 4.5, 13, 'nan', 'nan', 'Front; Rear', 2, '170/60R17 72V TL; 120/70R19 60V TL', 2, 'Michelin Harley-Davidson Scorcher Adventure Tires Michelin''s Scorcher Adventure Tires are ready to crumble any terrain that you dare trek. Proudly picked as the stock tire for the Harley Davidson Pan America, the Scorcher Adventure Tires feature compounds that allow for superior on-road stability in dry or wet conditions. The tread pattern and optimized profile provide precise handling and performance that keeps you riding mile after mile, from hot pavement to dusty trails. Michelin''s Scorcher Adventure Tires are ready to chomp out the miles and any terrain that comes your way.', 'OEM Harley Davidson Pan America tires Bridge Block and 2CT+ Technology provide maximum stability Dual compound, tread pattern and optimized profile provide precise handling and long lasting performance Silica tread compound provides phenomenal wet grip Fully grooved tread pattern delivers confidence inspiring traction off-road 80% on-road / 20% off-road Tubeless Harley branding on sidewall Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_harley_davidson_scorcher_adventure_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_harley_davidson_scorcher_adventure_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "80 On Road 20 Off Road / Dot Tire / Dual Sport Tire / Harley Tire", "Make": "Harley-Davidson", "Model": "Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard", "Tire Size": "170/60R17 72V TL; 120/70R19 60V TL"}', 50, 1, 1, NOW(), NOW());
