INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (130, '10453742.0', 'Continental ContiAttack SM2 Supermoto Tires', 'continental-contiattack-sm2-supermoto-tires-10453742.0', 'Continental Tire', 1, 'STREET BIKE', 'Dot Tire / Supermoto Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P1117626', 172.3, '362.95', '362.95', 'Save up to Save $127.98 35%', 5.0, 3, 'nan', 'nan', 'Front; Rear', 5, '140/70R17 66H TL; 110/70R17 54H TL; 120/70R17 58H TL; 150/60R17 66H TL; 160/60R17 69H TL', 5, 'Continental Conti Attack SM2 Supermoto Tires The Continental ContiAttack SM2 Supermoto Tires deliver performance virtually mirroring Continental''s most extreme DOT supermoto tire (the ContiAttack SM Supermoto EVO) but with enhanced comfort, wet grip, and longevity. The ContiAttack SM2 features a tread design and composition that draw from Continental''s experience in track-only racing tires. Continental Grip Limit Feedback technology boasts large areas of slick, uninterrupted tread block to provide road feel and predictable grip. Rear tires feature a reinforced, longer-wearing center section to handle the hard acceleration and braking demands of Supermoto - while also contributing to increased tire life for non-track riding. Infused with Continental''s BlackChili compound, the ContiAttack SM2 Tires cater to both competitive on-track supermoto styles and everyday street riding requirements.', 'Track-proven and street legal high-performance tire for the ultimate supermoto experience Signature Continental Black Chili compound MultiGrip technology for a homogeneous gradation of grip levels with a single compound TractionSkin and micro-rough tread offers grip from the first mile ZeroDegree 0° steel belt construction guarantees excellent stability at high speeds and low kickback tendency Optimum stability and damping during extreme braking and acceleration for the supermoto riding style Similar performance to the ContiAttack SM Supermoto EVO Tires with better longevity, comfort and wet performance Solid backbone for extreme braking and acceleration (or great mileage when ridden gently) Maximum traction and increased predictability at high lean angles Continental Grip Limit Feedback technology enhanced by large areas of slick, uninterrupted tread Significantly higher mileage potential thanks to increased tread depth Optimum damping and handling Radial construction Carcass inspired by Continental racing slicks Tubeless (TL) design DOT approved', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/continental_conti_attack_sm2_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/continental_conti_attack_sm2_tires.webp", "https://americaapi.kaafifoods.com/storage/products/continental_conti_attack_sm2_supermoto_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Supermoto Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "140/70R17 66H TL; 110/70R17 54H TL; 120/70R17 58H TL; 150/60R17 66H TL; 160/60R17 69H TL"}', 50, 1, 1, NOW(), NOW());
