INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (133, '1821667.0', 'Michelin Power Cup Evo Tires', 'michelin-power-cup-evo-tires-1821667.0', 'Michelin Tires', 4, 'STREET BIKE', 'Scooter Radial / Road Race Dot And Non D / Multi Compound Tire / Race Tire', 'Honda', 'Honda PCX150 / Ruckus, Yamaha Zuma / XMAX, Vespa Primavera / GTS 300, Suzuki Burgman 400', '2005 - 2025', 'P855239', 199.99, '335.95', '335.95', 'Save up to Save $89.96 27%', 4.8, 8, 'nan', 'nan', 'Front; Rear', 5, '110/70ZR17 54W TL; 120/70ZR17 58W TL; 140/70ZR17 66W TL; 150/60ZR17 66W TL; 160/60ZR17 69W TL', 5, 'Michelin Power Cup Evo Tires The Power Cup Evo is a race-ready track tire with DOT approval for street use. Engineered for small to medium displacement race-prepped motorcycles, compounds and construction methods deliver an exceptionally fast warm-up - with consideration taken for lighter weight motorcycle applications. The Power Cup Evos are equally suited for use with tire warmers. Dual compound construction puts a denser, more robust tread compound to the ground to cope with aggressive brake and throttle application while a softer compound increases grip at the tire''s shoulder. Adaptive Casing Technology (ACT) matches these high levels of dry grip with communicative response from the carcass and sidewall at all angles of lean. The tire''s groove ratio is less than 5%. Handling is predictable with little to no specific setup adaptations required. Put simply, the Michelin''s Power Cup Evo is a treaded version of Michelin''s Power Slick Evo track-only slick.', 'Designed for track-ridden small to medium displacement motorcycles 95% track / 5% street use Less than 5% groove ratio 2CT dual compound technology ACT+ adaptive casing technology SCT synthetic component technology DOT approved Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_power_cup_evo_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_power_cup_evo_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Scooter Radial / Road Race Dot And Non D / Multi Compound Tire / Race Tire", "Make": "Honda", "Model": "Honda PCX150 / Ruckus, Yamaha Zuma / XMAX, Vespa Primavera / GTS 300, Suzuki Burgman 400", "Tire Size": "110/70ZR17 54W TL; 120/70ZR17 58W TL; 140/70ZR17 66W TL; 150/60ZR17 66W TL; 160/60ZR17 69W TL"}', 50, 1, 1, NOW(), NOW());
