INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (135, '10046722.0', 'IRC VE-33S Gekkota Tires', 'irc-ve-33s-gekkota-tires-10046722.0', 'IRC Tires', 3, 'DIRT BIKE', 'Hard Terrain / Intermediate Terrain / Dirt Bike Tire / Non Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P897373', 130.36, '221.95', '221.95', 'Save up to Save $65.99 30%', 4.7, 10, 'nan', 'nan', 'Rear', 3, '110/100-18; 120/100-18; 140/80-18', 3, 'IRC VE-33S Gekkota Tires The VE-33S Gekkota tires from IRC were developed in the most extreme enduro conditions possible with the goal of making them the best tire option for single track riders and top pro enduro riders alike. Its 2-ply / breaker carcass structure resists punctures and helps provide stability over a wide range of speeds. The gummy Gekkota compound grips where other tires slip and act as a suspension component within the tire, providing extra bump absorption performance. The tire''s tall blocks were designed to provide a larger contact patch as well as flexibility for maximum traction in all conditions. IRC developed the gummy GEKKOTA compound with top pro enduro riders to enhance high speed cornering performance and durability. Take control of your next ride and put your tires to work!', 'The "Workhorse" Tire for riders looking for an extreme enduro tire IRC''s Trials compound technology and Motocross tread pattern combined into a Hybrid tire that provides best traction in the worst conditions Gummy Gekkota compound provides optimal grip and extra bump absorption in all conditions Designed to perform in EXTREME conditions from sloppy dirt or sand to logs, roots, rocks, swamps, and sliding gravel surfaces. Recommended air pressure is around 7-10 psi (with Heavy Duty Tubes) Tube type 64M speed rating, rated speeds up to 81 mph Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/ircve33_s_gekkota_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/ircve33_s_gekkota_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "Hard Terrain / Intermediate Terrain / Dirt Bike Tire / Non Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/100-18; 120/100-18; 140/80-18"}', 50, 1, 1, NOW(), NOW());
