INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (136, '10386833.0', 'Mitas Enduro Trail XT Plus Tires', 'mitas-enduro-trail-xt-plus-tires-10386833.0', 'Mitas', 3, 'DIRT BIKE', '20 On Road 80 Off Road / Dot Dirt Tires / Dot Tire / Soft Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1087799', 96.6, '230.99', '230.99', 'Save up to Save $47.87 21%', 4.0, 6, 'nan', 'nan', 'Front; Rear', 12, '130/80B17 57H; 170/60B17 72T; 110/80-18 58T; 120/90B18 65T; 140/80B18 70T; 150/70B18 70T; 100/90-19 57T; 110/80-19 59T; 120/70B19 60T; 80/90-21 48H; 90/90-21 54T; 90/100-21 57H', 12, 'Mitas Enduro Trail XT Plus Tires The Mitas Enduro Trail XT Tires answer to riders demanding the most aggressive performance off-road with the ability to ride the tarmac home. The XT+ product line was designed from testing and development of the E-12/E-13 Rally Star & E-09 Rear tires. The XT+ Rear features a profile and tread pattern/spacing that excels in aggressive offroad riding conditions while maintaining predictable road manners, consistent wear over its lifetime and comparatively low road noise.', 'The XT+ is designed for 20% on-road / 80% off-road use on Adventure and Dual Sport motorcycles All XT+ tires approved for TL (Tubeless) and TT (Tube Type) applications Fitment options from full sized ADV bikes down to single cylinder Dual Sport machines. Standard version front is an excellent hard terrain dual sport fitment ADV specific tire Profile with deep and wide knob pattern balancing maximum off-highway traction and predictable on road handling DOT approved Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_xt_plus_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_xt_plus_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "20 On Road 80 Off Road / Dot Dirt Tires / Dot Tire / Soft Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "130/80B17 57H; 170/60B17 72T; 110/80-18 58T; 120/90B18 65T; 140/80B18 70T; 150/70B18 70T; 100/90-19 57T; 110/80-19 59T; 120/70B19 60T; 80/90-21 48H; 90/90-21 54T; 90/100-21 57H"}', 50, 1, 1, NOW(), NOW());
