INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (138, '10501670.0', 'Kenda Trakmaster DTR Tires', 'kenda-trakmaster-dtr-tires-10501670.0', 'nan', 1, 'STREET BIKE', '70 On Road 30 Off Road / Dot Tire / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1144402', 78.17, '167.99', '167.99', 'Save up to Save $38.73 23%', 5.0, 5, 'nan', 'nan', 'Front; Rear', 11, '150/80-16 71H; 120/90-17 64T; 130/80-17 65T; 150/70-18 70T; 140/80-17 69H; 150/70R17 69V; 140/80-18 70T; 100/90-19 57T; 110/80-19 59T; 120/70-19 60T; 90/90-21 54T', 11, 'Kenda Trakmaster DTR Tires The Kenda Trackmaster DTR Tire offer riders the option to go unpaved. The 70/30 street-to-off road tread design packs an innovative, stepped tread blocks that are engineered to maintain a sharp leading edge even as the tire wears down. Tires feature a bias-ply construction with tubeless bead and meet DOT requirements. Ride on.', '70% on-road / 30% off-road bias Innovative stepped tread introduces fresh biting edges as the tire wears Proprietary compound and optimized tread design Excellent grip in wet conditions Lateral grooved shoulders designed for maximum water and mud dispersion Performance in any terrain without compromise Fitments for most dual sport and adventure motorcycles DOT-approved Tubeless design (TL) Bias construction Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/kenda_trakmaster_dtr_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/kenda_trakmaster_dtr_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "70 On Road 30 Off Road / Dot Tire / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "150/80-16 71H; 120/90-17 64T; 130/80-17 65T; 150/70-18 70T; 140/80-17 69H; 150/70R17 69V; 140/80-18 70T; 100/90-19 57T; 110/80-19 59T; 120/70-19 60T; 90/90-21 54T"}', 50, 1, 1, NOW(), NOW());
