INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (139, '10203258.0', 'Metzeler Karoo 4 Tires', 'metzeler-karoo-4-tires-10203258.0', 'Metzeler', 1, 'STREET BIKE', 'Dual Road Bias Dot / 50 On Road 50 Off Road / Intermediate Terrain / Hard Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P986713', 135.09, '373.29', '373.29', 'Save up to Save $90.34 24%', 4.9, 7, 'nan', 'nan', 'Rear; Front', 16, '130/80R17 65Q; 140/80R17 69Q; 150/70R17 69Q; 150/70R17 69T; 170/60R17 72Q; 170/60R17 72T; 140/80-18 70Q; 150/70R18 70Q; 150/70R18 70T; 100/90-19 57Q; 110/80R19 59Q; 110/80R19 59T; 120/70R19 60Q; 120/70R19 60T; 90/90-21 54Q; 90/90-21 54T', 16, 'Metzeler Karoo 4 Tires When you don''t know where the trail will lead you, but want to be ready for anything, the Metzler Karoo 4 Tires have the features you need.', 'Made for adventure and dual sport riders who want good off-road performance and longevity 50% on-road / 50% off-road Patented multi-pitch knob layout reduces tire noise and delivers rolling smoothness Transversal knob layout enhances off road traction, directionality and stability Footprint optimized to work in concert with electronic rider aids Tread pattern picks up and clears material for better traction Dymatec "Dynamic Mold Angle Technology", provides variable groove wall angles at different lean angles for optimized tread resistance and wear uniformity Radial construction with Interact technology, features multi-zone steel belt tension, relieves structural and thermal stresses for maximizing steering neutrality and wet performance Updated front single compound with a wide operating range Dual compound rear, with 100% Carbon Black rubber for great abrasion and tearing resistance Tubeless design (TL) Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/metzeler_karoo4_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/metzeler_karoo4_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "STREET BIKE", "Product Type": "Dual Road Bias Dot / 50 On Road 50 Off Road / Intermediate Terrain / Hard Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "130/80R17 65Q; 140/80R17 69Q; 150/70R17 69Q; 150/70R17 69T; 170/60R17 72Q; 170/60R17 72T; 140/80-18 70Q; 150/70R18 70Q; 150/70R18 70T; 100/90-19 57Q; 110/80R19 59Q; 110/80R19 59T; 120/70R19 60Q; 120/70R19 60T; 90/90-21 54Q; 90/90-21 54T"}', 50, 1, 1, NOW(), NOW());
