INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (140, '1306389.0', 'Dunlop D423 Honda Goldwing Tires', 'dunlop-d423-honda-goldwing-tires-1306389.0', 'Dunlop', 2, 'STREET BIKE', 'Customcruisertouring Ra / Touring Tire / Dot Tire', 'Honda', 'Goldwing', '1990 - 2025', 'P413344', 282.74, '475.95', '475.95', 'Save up to Save $107.64 23%', 2.9, 8, 'nan', 'nan', 'Rear; Front', 2, '200/55R16 77H; 130/70R18 63H', 2, 'Dunlop D423 Honda Goldwing Tires Designed specifically for the Honda Goldwing, the D423 hoops from Dunlop are built for trans-continental touring in comfort and style.', 'O.E. fitment for the 2018 Honda Goldwing Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_d42313070_r18_front.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_d42313070_r18_front.webp"]', '{"Wheel Location": "Rear; Front", "Type": "STREET BIKE", "Product Type": "Customcruisertouring Ra / Touring Tire / Dot Tire", "Make": "Honda", "Model": "Goldwing", "Tire Size": "200/55R16 77H; 130/70R18 63H"}', 50, 1, 1, NOW(), NOW());
