INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (146, '10153377.0', 'Bridgestone Battlecross X31 Tire', 'bridgestone-battlecross-x31-tire-10153377.0', 'Bridgestone', 3, 'DIRT BIKE', 'Off Highway Non Dot Inc / Dirt Bike Tire / Non Dot Tire / Intermediate Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P961520', 107.48, '185.37', '185.37', 'Save up to Save $50.75 27%', 4.5, 4, 'nan', 'nan', 'Front; Rear', 6, '110/100-18; 100/90-19; 110/90-19; 120/80-19; 80/100-21; 90/100-21', 6, 'Bridgestone Battlecross X31 Tire The Battlecross X31 is designed for a broad range of intermediate terrain for the ultimate traction on the track or trails. Starting where the X30 left off, the X31 is enhanced with Bunker Groove technology which works by improving casing flex for enhanced traction in harder terrain and adds biting edges for traction in softer conditions. Rear tire Cooling Fins promote consistent traction and feel under during a long moto by dispersing heat and minimizing inflation pressure gain. The symmetric front tire design enhanced with Castle Block Technology promotes braking stability while increasing biting edges and contact pressure on soft and slippery surfaces, while the asymmetric rear tire tread design enhances cornering traction by increasing lateral biting edges.', 'Intermediate terrain tire with a wide range of use Rear Cooling Fins to disperse heat and maintain tire pressure Bunker Groove Technology for tread casing flex, a stable sidewall and increased soft terrain traction Symmetrical front tread design and an asymmetrical rear tread design For offroad use only Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/bridgestone_battlecross_x31_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/bridgestone_battlecross_x31_tire.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Off Highway Non Dot Inc / Dirt Bike Tire / Non Dot Tire / Intermediate Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/100-18; 100/90-19; 110/90-19; 120/80-19; 80/100-21; 90/100-21"}', 50, 1, 1, NOW(), NOW());
