INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (148, '1063256.0', 'Pirelli MT60RS Tires', 'pirelli-mt60rs-tires-1063256.0', 'Pirelli', 1, 'STREET BIKE', 'Dual Road Radial Dot / Dual Road Bias Dot / 80 On Road 20 Off Road / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P314563', 178.88, '359.39', '359.39', 'Save up to Save $91.17 25%', 4.1, 29, 'nan', 'nan', 'Front; Rear', 10, '130/90B16 67H; 150/80B16 77H; 110/70R17 54H; 120/70ZR17 58W; 150/60R17 66H; 160/60R17 69H; 180/55R17 73H; 180/55ZR17 73W; 110/80R18 58H; 120/70ZR18 59W', 10, 'Pirelli MT60RS Tires Developed using the same winning technology used for Pirelli''s super sport tires, the Pirelli MT60RS Tires are the go-to for smaller bikes that want to get dirty. The tread design offers excellent street performance and just enough grip off-road to handle fire roads or loose terrain without getting into trouble.', 'Maximum grip tread 110/80R18 58H and 160/60R17 69H are OE fitment on certain Ducati Scrambler models 180/55ZR17 73W D-Spec is the OE rear fitment on Scrambler 1100 models Superb cornering and straight-line stability; exceptional wet-weather performance Excellent traction, on- and off-road; provides light, responsive handling H-rated for speeds up to 130 mph or W-rated for speeds up to 168 mph Tubeless (TL) Blackwall Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/pirelli_mt60_rs_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/pirelli_mt60_rs_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dual Road Radial Dot / Dual Road Bias Dot / 80 On Road 20 Off Road / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "130/90B16 67H; 150/80B16 77H; 110/70R17 54H; 120/70ZR17 58W; 150/60R17 66H; 160/60R17 69H; 180/55R17 73H; 180/55ZR17 73W; 110/80R18 58H; 120/70ZR18 59W"}', 50, 1, 1, NOW(), NOW());
