INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (152, '157450.0', 'Kenda K270 Tires', 'kenda-k270-tires-157450.0', 'nan', 3, 'DIRT BIKE', '50 On Road 50 Off Road / Dot Dirt Tires / Hard Terrain / Intermediate Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P42695', 47.59, '118.95', '118.95', 'Save up to Save $16.01 13%', 4.4, 57, 'nan', 'nan', 'Rear; Front', 17, '180/80-14 78P; 3.25x17; 4.60x17; 5.10x17; 100/90-18 56P; 120/80-18 62P; 130/80-18 66P; 2.75x18; 3.50x18; 4.00x18; 4.10x18; 4.50x18; 4.60x18; 5.10x18; 2.75x21; 3.00x21; 3.25x21', 17, 'Kenda K270 Tires The K270 Dual Sport tire is a great option for replacing your OE trail tire. It provides the perfect balance between a smooth ride on the road and great traction on the trails.', 'Designed for todays high performance dual purpose motorcycles Built with a special rubber compound Extra grip off the road without compromising wear on the street 50% on-road / 50% off-road Tube Type P-rated options are for speeds up to 93 mph DOT approved Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/Kenda_K270_Tires.webp', '["https://americaapi.kaafifoods.com/storage/products/Kenda_K270_Tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "DIRT BIKE", "Product Type": "50 On Road 50 Off Road / Dot Dirt Tires / Hard Terrain / Intermediate Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "180/80-14 78P; 3.25x17; 4.60x17; 5.10x17; 100/90-18 56P; 120/80-18 62P; 130/80-18 66P; 2.75x18; 3.50x18; 4.00x18; 4.10x18; 4.50x18; 4.60x18; 5.10x18; 2.75x21; 3.00x21; 3.25x21"}', 50, 1, 1, NOW(), NOW());
