INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (155, '10144179.0', 'Michelin City Extra Scooter Tires', 'michelin-city-extra-scooter-tires-10144179.0', 'Michelin Tires', 1, 'STREET BIKE', 'Dot Tire / Multi Compound Tire / Scooter Tire', 'Honda', 'Honda PCX150 / Ruckus, Yamaha Zuma / XMAX, Vespa Primavera / GTS 300, Suzuki Burgman 400', '2005 - 2025', 'P957944', 50.99, '92.95', '92.95', 'Save up to Save $18.96 20%', 4.2, 11, 'nan', 'nan', 'nan', 8, '3.00-10 50J TL; 3.50-10 59J TL; 80/90-17 50S TL; 2.50-17 43P TT; 2.75-17 47P TT; 90/90-18 57S TL; 2.75-18 48S TL Reinforced; 2.25-17 38P TT', 8, 'Michelin City Extra Scooter Tires The Michelin City Extra tires go the extra mile in durability and reliability, rain or shine. With an optimized version of the City Pro''s puncture resistant construction, the City Extra guarantees a reliable and worry free ride, even on some of the meanest of streets. The City Extra''s tread pattern is designed to keep churning out the extra miles, and the Water Sipe Technology™ ensures the best grip in wet conditions.', 'Excellent mileage Reliable and reassuring handling and comfort Michelin Adaptive Design™ for optimum traction and lean angle predictability Water Sipe Technology™ gradually increases sipe contact during cornering for better grip on wet surfaces High Density Technology™ provides a thick layer backed by three reinforcing plies to enhance the tire''s puncture resistance Available in "Reinforced" for heavyweight touring bikes, two-up riding, or when required by OEM specifications Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here!', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_city_extra_scooter_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_city_extra_scooter_tires.webp"]', '{"Wheel Location": "nan", "Type": "STREET BIKE", "Product Type": "Dot Tire / Multi Compound Tire / Scooter Tire", "Make": "Honda", "Model": "Honda PCX150 / Ruckus, Yamaha Zuma / XMAX, Vespa Primavera / GTS 300, Suzuki Burgman 400", "Tire Size": "3.00-10 50J TL; 3.50-10 59J TL; 80/90-17 50S TL; 2.50-17 43P TT; 2.75-17 47P TT; 90/90-18 57S TL; 2.75-18 48S TL Reinforced; 2.25-17 38P TT"}', 50, 1, 1, NOW(), NOW());
