INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (156, '1125422.0', 'Duro HF308 Tires', 'duro-hf308-tires-1125422.0', 'nan', 2, 'STREET BIKE', 'Cruiser Tire / Harley Tire / Vintage Tire / Dot Tire', 'Harley-Davidson', 'Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard', '1990 - 2025', 'P338220', 75.04, '140.95', '140.95', 'Save up to Save $43.95 31%', 4.8, 16, 'nan', 'nan', 'nan', 0, 'nan', 2, 'Duro HF308 Classic Tires Designed for use with classically styled or genuinely vintage motorcycles, the HF308 Classic Tire from Duro is capable, road-friendly rubber for your retro ride. Durable construction features 4 to 6 tread plies (depending on tire size). great replacement for Ural stock tires featuring 4-ply and 6-ply options for optimal load capacity usage. The HF307 Tire is the OEM tire for the following models: Ural Solo ST, Gear Up, M70 Retro, Patrol T, Ural T and Yamaha LTD motorcycles. For added off-road traction, the HF308 can be paired with Duro''s HF307 Tire at rear and/or sidecar positions.', 'Classically inspired vintage tire Modern rubber compounds 4 to 6 ply bias construction Front, rear or sidecar fitment Tube type DOT approved Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/duro_hf308_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/duro_hf308_tires.webp"]', '{"Wheel Location": "nan", "Type": "STREET BIKE", "Product Type": "Cruiser Tire / Harley Tire / Vintage Tire / Dot Tire", "Make": "Harley-Davidson", "Model": "Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
