INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (159, '10481084.0', 'Michelin Power Shift Scooter Tires', 'michelin-power-shift-scooter-tires-10481084.0', 'Michelin Tires', 1, 'STREET BIKE', 'Dot Tire / Scooter Tire', 'Honda', 'Honda PCX150 / Ruckus, Yamaha Zuma / XMAX, Vespa Primavera / GTS 300, Suzuki Burgman 400', '2005 - 2025', 'P1132102', 198.57, '291.95', '291.95', 'Save up to Save $38.52 13%', 4.0, 1, 'nan', 'nan', 'Front; Rear', 3, '160/60R15 67H; 120/70R15 56H; 120/70R17 58H', 3, 'Michelin Power Shift Scooter Tires Crafted to enhance the performance of high-capacity scooters, the Power Shift tire draws from the acclaimed Pilot Road 4 series. This tire provides a seamless fusion of reliability and agility, engineered specifically for the demands of modern scooters.', 'Radial tubeless Scooter tire Higher performance on wet surfaces High-tech compound and Water Evergrip Technology sipes Engineered with cutting-edge technology for impressive grip and handling, allowing you to experience adrenaline rush with confidence New high-tech compound allows for 15% longer tire life compared to previous versions Michelin Power Shift increase wet grip performance by +15% in comparison with the Michelin Pilot Road 4 scooter, per Michelin testing Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here!', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_tires_tire_power_shift12070_r1556_hft.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_tires_tire_power_shift12070_r1556_hft.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Scooter Tire", "Make": "Honda", "Model": "Honda PCX150 / Ruckus, Yamaha Zuma / XMAX, Vespa Primavera / GTS 300, Suzuki Burgman 400", "Tire Size": "160/60R15 67H; 120/70R15 56H; 120/70R17 58H"}', 50, 1, 1, NOW(), NOW());
