INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (167, '10456458.0', 'Pirelli Scorpion Trail III Tires', 'pirelli-scorpion-trail-iii-tires-10456458.0', 'Pirelli', 2, 'STREET BIKE', '90 On Road 10 Off Road / Dot Tire / Multi Compound Tire / Touring Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1119085', 156.87, '382.29', '382.29', 'Save up to Save $96.97 25%', 4.0, 5, 'nan', 'nan', 'Front; Rear', 19, '120/70ZR17 58W TL; 120/90-17 64H TL; 130/80R17 65V TL; 140/80R17 69V TL; 150/70R17 69V TL; 160/60ZR17 69W TL; 170/60R17 72V TL; 170/60ZR17 72W TL; 170/60ZR17 72W TL D-Spec; 180/55ZR17 73W TL; 100/90-18 56V TL; 110/80R18 58V TL; 150/70ZR18 70W TL; 100/90-19 57V TL; 110/80R19 59V TL; 120/70R19 60V TL; 120/70ZR19 60W TL; 120/70ZR19 60W TL D-Spec; 90/90V21 54V TL', 19, 'Pirelli Scorpion Trail III Tires The Scorpion Trail III tires are adventure-touring tires designed for sporty performance, delivering confidence on both winding roads and gravel terrain. Compound: New full silica compounds for both front and rear that improve performance in both wet and dry conditions. Rear sizes are bi-compound with a softer stripe on shoulders thanks to different plastifying resins that improve grip while cornering. Front compound is similar to the rear central one, allowing high stability and wear resistance. Structure: The high stiffness structure that supports the profile and guarantees the sporty handling is directly derived from our experience in super sport and sport-touring. Structure cords have a superior linear density and higher stiffness, to increase lateral thrust for better trajectory precision and stability when leaning. Moreover, this guaranties that the original performances are maintained throughout the entire tire life. Tread Design: The tread pattern design is an evolution and upgrade over the Scorpion Trail II that provides greater control and stability. The asymmetric repositioning of the grooves increases its efficiency and contact patch sturdiness for better performance at high speed whilst keeping the off-road spirit on dirty roads. Profiles: Directly derived from Sport-touring with a multi-radius approach that increase the sporty feeling with a progressive and confident behavior thanks the to rounded profile and increased overall width.', 'Asymmetric repositioning of the grooves to increase efficiency and contact patch sturdiness for better performance at high speed while keeping the off-road spirit on dirt roads Structure cords have a superior linear density and higher stiffness, to increase lateral thrust for better trajectory precision and stability when leaning Developed for adventure and cross-over motorcycles, to be used in a wide range of conditions, from twisty to gravel roads Full silica compounds for both front and rear that improve performance in both wet and dry conditions High stiffness structure that supports the profile and guarantees a sporty handling Rounded profile and increased overall width D-Spec tires are an OEM Ducati Spec variant designed to replace the OEM tires on applicable models DOT Approved', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/pirelli_scorpion_trail_iii_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/pirelli_scorpion_trail_iii_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "90 On Road 10 Off Road / Dot Tire / Multi Compound Tire / Touring Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/70ZR17 58W TL; 120/90-17 64H TL; 130/80R17 65V TL; 140/80R17 69V TL; 150/70R17 69V TL; 160/60ZR17 69W TL; 170/60R17 72V TL; 170/60ZR17 72W TL; 170/60ZR17 72W TL D-Spec; 180/55ZR17 73W TL; 100/90-18 56V TL; 110/80R18 58V TL; 150/70ZR18 70W TL; 100/90-19 57V TL; 110/80R19 59V TL; 120/70R19 60V TL; 120/70ZR19 60W TL; 120/70ZR19 60W TL D-Spec; 90/90V21 54V TL"}', 50, 1, 1, NOW(), NOW());
