INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (168, '10328194.0', 'Metzeler Enduro 3 Sahara Tires', 'metzeler-enduro-3-sahara-tires-10328194.0', 'Metzeler', 3, 'DIRT BIKE', 'Dual Road Radial Dot / Dual Road Bias Dot / 50 On Road 50 Off Road / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P274166', 179.61, '348.54', '348.54', 'Save up to Save $84.31 24%', 4.3, 7, 'nan', 'nan', 'Front; Rear', 7, '120/90-17 64S TT; 130/80-17 65S TT; 130/80-17 65T TL; 140/80-17 69H TT; 120/80-18 62S TT; 140/80-18 70S TT; 90/90-21 54H TL', 7, 'Metzeler Enduro 3 Sahara Tires The Enduro 3 Sahara is a great fifty-fifty tire - it''s a perfect tire for those spending the same amount of time on the trail as they are on the road.', '50% on-road / 50% off-road Dedicated tread compound perfectly combines safe on-road cornering grip and good off-road traction Tread pattern geometry designed for fast self-cleaning to yield stable and precise trajectories without skidding on soft or muddy terrain Great handling with easy corner entry, stable cornering and high safety margins when you''re riding at the limit 50/50 dual-sport tires engineered for both pavement and off-road riding Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/metzeler_enduro3_sahara_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/metzeler_enduro3_sahara_tires.webp", "https://americaapi.kaafifoods.com/storage/products/metzeler_enduro3_sahara_front_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Dual Road Radial Dot / Dual Road Bias Dot / 50 On Road 50 Off Road / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/90-17 64S TT; 130/80-17 65S TT; 130/80-17 65T TL; 140/80-17 69H TT; 120/80-18 62S TT; 140/80-18 70S TT; 90/90-21 54H TL"}', 50, 1, 1, NOW(), NOW());
