INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (177, '10321331.0', 'Motoz Tractionator Enduro S/T Tires', 'motoz-tractionator-enduro-s-t-tires-10321331.0', 'Motoz', 3, 'DIRT BIKE', '10 On Road 90 Off Road / Dot Dirt Tires / Dirt Bike Tire / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1055126', 122.99, '147.99', '147.99', 'nan', 5.0, 1, 'nan', 'nan', 'Rear; Front', 6, '110/100-18 (M/C) 64R TT; 120/90-18 (M/C) 65R TT; 130/90-18 (M/C) 69R TT; 110/90-19 (M/C) 62R TT; 90/90-21 (M/C) 54R TT; 90/100-21 (M/C) 57R TT', 6, 'Motoz Tractionator Enduro S/T Tires The Tractionator Enduro ST is a DOT homologated enduro tire that offers supreme traction in soft conditions, while offering great longevity for those longer rides and events. The Tractionator ST also features a reversible rear tread pattern that slightly differs, giving you the choice to mount the tire in a mostly we (mud) direction, or a mostly dry (loam and sand) direction for maximum performance.', 'Intended for use in soft terrain Natural / synthetic hybrid rubber construction Designed for 10% on-road / 90% off-road 20% dry / 80% wet weather 30% hard / 70% soft terrain Reversible rear tread pattern DOT approved Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_tractionator_enduro_st_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_tractionator_enduro_st_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "DIRT BIKE", "Product Type": "10 On Road 90 Off Road / Dot Dirt Tires / Dirt Bike Tire / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/100-18 (M/C) 64R TT; 120/90-18 (M/C) 65R TT; 130/90-18 (M/C) 69R TT; 110/90-19 (M/C) 62R TT; 90/90-21 (M/C) 54R TT; 90/100-21 (M/C) 57R TT"}', 50, 1, 1, NOW(), NOW());
