INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (182, '10584556.0', 'Shinko 017 Peak Tires', 'shinko-017-peak-tires-10584556.0', 'Shinko Tires', 2, 'STREET BIKE', '100 On Road 0 Off Road / Dot Tire / Multi Compound Tire / Touring Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1184412', 127.46, '242.95', '242.95', 'Save up to Save $36.44 15%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 11, '120/60ZR17 55W; 120/70ZR17 58W; 160/60ZR17 69W; 180/55ZR17 73W; 180/60ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W; 120/70ZR18 59W; 160/60ZR18 70W; 200/55R18 79V', 11, 'Shinko R017 Peak Tires Experience reliable performance on every ride with the Shinko 017 Peak Tire. The Peak 017 features a 3-Layer Tread Compound that offers a steadfast center cap for stability during straight-line travel, while the high-grip silica shoulders enhance confidence during leans. The Jointless Steel Belted construction ensures the tire retains its shape even under the rigors of high speeds, dynamic stress, and hard braking. Wet weather riding is improved thanks to a silica-rich compound that improves handling and braking performance in a variety of conditions. For those who seek a blend of durability and spirited riding, the Shinko 017 Peak Tires offer an impressive balance for the adventurous sport rider, as well as a sportier edge for touring enthusiasts desiring more than what traditional touring tires can offer, all with exceptional value.', 'An all-weather tire that pleases sport riders and touring riders looking for a more spirited ride High-Speed Stability: Advanced JLSB (Jointless Steel Belt) construction provides maximum structural integrity and strength for aggressive sport riding Advanced Rear Compound: Three-layer tread design utilizes a silica-enriched shoulder for immediate grip and a specialized cap compound for consistent stability Precision Cornering: Elite shoulder grooves optimize contact patch performance to enhance handling and confidence through every turn All-Weather Performance: Specialized tread patterns and compounds ensure superior wet grip and reliable handling in diverse road conditions Straight-Line Control: Artistic center groove design improves tracking and stability during high-speed highway pulls or upright commutes Technology: Jointless steel belt construction delivers added stability and high-speed strength Design: 3-Layer tread compound with silica-enriched shoulder and stable cap compound Tubeless (TL) construction in all sizes', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/shinko017_peak_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/shinko017_peak_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "100 On Road 0 Off Road / Dot Tire / Multi Compound Tire / Touring Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/60ZR17 55W; 120/70ZR17 58W; 160/60ZR17 69W; 180/55ZR17 73W; 180/60ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W; 120/70ZR18 59W; 160/60ZR18 70W; 200/55R18 79V"}', 50, 1, 1, NOW(), NOW());
