INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (185, '1807150.0', 'Continental ContiStreet Tires', 'continental-contistreet-tires-1807150.0', 'Continental Tire', 2, 'STREET BIKE', 'Sport Touring Bias Dot / Dot Tire / Cruiser Tire', 'Harley-Davidson', 'Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard', '1990 - 2025', 'P1053682', 48.07, '177.45', '177.45', 'Save up to Save $64.88 37%', 5.0, 4, 'nan', 'nan', 'Front; Front/Rear; Rear', 16, '70/90-17 38P TL; 80/90-17 47P TL; 90/80-17 46P TL; 100/90-17 55P TL; 120/70-17 58P TL; 2.50-17 43P TL; 2.75-17 47P TL; 3.00-17 50P TL; 80/90-18 45P TL; 80/100-18 47P TL; 90/90-18 57P TL; 100/80-18 53P TL; 100/90-18 56P TL; 2.50-18 40P TL; 2.75-18 48P TL; 3.00-18 52P TL', 16, 'Continental ContiStreet Tires The Continental ContiStreet Tires are the perfect cruiser tire for slow rides around the city. Superior handling in wet and dry conditions make Continental a no brainer when treads look bare. Deeper tread depth keeps you riding longer.', 'Designed for superior handling in wet or dry conditions Deeper tread depth for better mileage Improved puncture resistance Reliable feedback Tubeless Blackwall Bias construction Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/continental_conti_street_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/continental_conti_street_tires.webp"]', '{"Wheel Location": "Front; Front/Rear; Rear", "Type": "STREET BIKE", "Product Type": "Sport Touring Bias Dot / Dot Tire / Cruiser Tire", "Make": "Harley-Davidson", "Model": "Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard", "Tire Size": "70/90-17 38P TL; 80/90-17 47P TL; 90/80-17 46P TL; 100/90-17 55P TL; 120/70-17 58P TL; 2.50-17 43P TL; 2.75-17 47P TL; 3.00-17 50P TL; 80/90-18 45P TL; 80/100-18 47P TL; 90/90-18 57P TL; 100/80-18 53P TL; 100/90-18 56P TL; 2.50-18 40P TL; 2.75-18 48P TL; 3.00-18 52P TL"}', 50, 1, 1, NOW(), NOW());
