INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (193, '10584776.0', 'Mitas Touring Force SP Tires', 'mitas-touring-force-sp-tires-10584776.0', 'Mitas', 2, 'STREET BIKE', '100 On Road 0 Off Road / Dot Tire / Multi Compound Tire / Touring Tire', 'Honda', 'Touring', '1995 - 2025', 'P1184557', 154.03, '228.99', '228.99', 'Save up to Save $27.86 12%', 4.8, 12, 'nan', 'nan', 'Rear; Front', 6, '120/60ZR17 55W; 120/70ZR17 58W; 160/60ZR17 69W; 180/55ZR17 66W; 190/50ZR17 73W; 190/55ZR17 75W', 6, 'Mitas Touring Force Tires The Mitas Touring Force tire is designed to achieve the near-impossible: produce excellent dry-weather traction, provide long life even on sport-touring machines, and offer superb and confidence-inspiring traction on cold and wet pavement. To reach these goals, Mitas has built the Touring Force tread design using virtual 3D technology, purposely ending the tread sipes before the edge of the tire to improve traction at maximum lean angles. Get your Mitas Touring Force tire today and be ready for the next long ride.', '3D-modeled tread sipes for maximum water ejection High silica content for excellent wet-weather traction OSCT (Optimum Steel Cord Technology) provides balanced & predictable handling 3-D Optimum Groove Technology optimizes tread design, wet performance & longevity ZR rated tire, safe for operation at elevated speeds Rear tires feature hard center compound, softer compound on sides Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_touring_force_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_touring_force_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "STREET BIKE", "Product Type": "100 On Road 0 Off Road / Dot Tire / Multi Compound Tire / Touring Tire", "Make": "Honda", "Model": "Touring", "Tire Size": "120/60ZR17 55W; 120/70ZR17 58W; 160/60ZR17 69W; 180/55ZR17 66W; 190/50ZR17 73W; 190/55ZR17 75W"}', 50, 1, 1, NOW(), NOW());
