INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (204, '10252868.0', 'EFX MotoClaw Radial Tires', 'efx-motoclaw-radial-tires-10252868.0', 'EFX Tires', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1018017', 260.0, '317.0', '317.0', 'nan', 1.0, 1, 'nan', 'nan', 'nan', 0, 'nan', 11, 'EFX Tires MotoClaw Radial Tire The EFX Tires MotoClaw tire is like nothing else on the market. Complete with distinctive sidewall styling, unique non-directional tread pattern, incredibly strong rubber compound and a rugged radial carcass. Utilizing decades of manufacturing experience and trail knowledge EFX created a brand new industry-changing tire that will climb rocks, grab roots, latch onto side ruts and perform in light mud. Get ready for a whole new level of ATV/UTV tire performance.', '8-ply radial construction Distinctive styling to help your rig stand out at the trailhead Strong lugs spaced precisely to provide a smooth ride on intense terrain', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/efx_tires_moto_claw_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/efx_tires_moto_claw_tire.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
