INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (208, '10321069.0', 'Motoz Mountain Hybrid Tires', 'motoz-mountain-hybrid-tires-10321069.0', 'Motoz', 3, 'DIRT BIKE', '30 On Road 70 Off Road / 20 On Road 80 Off Road / Dot Dirt Tires / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1054915', 140.99, '165.99', '165.99', 'nan', 5.0, 1, 'nan', 'nan', 'Rear; Front', 4, '110/100-18 (M/C) 64M TT; 120/100-18 (M/C) 68M TT; 110/90-19 (M/C) 62M TT; 80/100-21 (M/C) 51M TT', 4, 'Motoz Mountain Hybrid Tires Motoz is the originator of the trials / moto hybrid tire, starting with their Mountain Hybrid. Taking the DNA of a motocross tire and injecting a trials-like tread pattern and grip, the Mountain Hybrid is a game changer for enduro riders. This design concept works on a flexible tread concave and lock system, to give increased traction while avoiding punctures at low inflation pressures. The Motoz Mountain Hybrid tire climbs like a trials tire, but handles corners, creek crossings, sand, and rocks like a regular DOT off-road tire. Constructed like a trials tire, but with reinforced sidewalls to allow lower inflation pressure when riding in off-road and mountain conditions.', '25% on-road / 75% off-road use Intermediate terrain tread pattern Hybrid natural / synthetic rubber construction Reinforced sidewalls to allow for lower inflation pressure Flexible tread Concave and Lock system for increased traction Tread blocks with deep sipes for extra trials-like grip Reversible rear tread design DOT approved Tube type Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_mountain_hybrid_gummy_rear_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_mountain_hybrid_gummy_rear_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "DIRT BIKE", "Product Type": "30 On Road 70 Off Road / 20 On Road 80 Off Road / Dot Dirt Tires / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/100-18 (M/C) 64M TT; 120/100-18 (M/C) 68M TT; 110/90-19 (M/C) 62M TT; 80/100-21 (M/C) 51M TT"}', 50, 1, 1, NOW(), NOW());
