INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (210, '10584680.0', 'Mitas Sport Force Plus Evolution Tires', 'mitas-sport-force-plus-evolution-tires-10584680.0', 'Mitas', 1, 'STREET BIKE', 'Sportbike Tire / Dot Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P1184491', 172.43, '263.99', '263.99', 'Save up to Save $37.89 14%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 6, '120/70ZR17 58W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W', 6, 'Mitas Sport Force+ EV Tires Mitas Sport Force+ Evolution Tire serve as a high-performance, street-legal tire engineered for sport, super-naked, and sport-touring platforms capable of handling both public roads and track environments. This specific Mitas Sport Force+ Evolution utilizes Multi Compound Tread Technology to ensure rapid thermal activation and increased stability during aggressive cornering maneuvers for dedicated riders. Positioned as a performance upgrade for hyper-sport applications, the Mitas Sport Force+ EV offers enhanced grip levels over the standard version while maintaining street legality for two-wheeled fans who do not require non-homologated racing slicks.', 'Enhanced Performance Evolution: Upgraded design delivers consistent results for enthusiasts during intense street or track sessions Multi-Compound Technology: MCTT ensures maximum grip at extreme lean angles and sustains performance throughout tire life Precision Handling: Engineered for fast, effortless, and highly accurate steering response for aggressive riders Rapid Warm-Up: Reaches optimal service temperatures quickly to provide immediate traction and rider confidence High-Speed Stability: Maintains superior straight-line tracking even after prolonged and intense high-speed use Versatile Application: Optimized for legal public road use while remaining fully capable for race track conditions Wet Grip Performance: Limited silica content provides necessary traction for damp or wet road surfaces Compatibility: Designed for high-performance supersport and sport naked motorcycles Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_sport_force_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_sport_force_tire.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Sportbike Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/70ZR17 58W; 160/60ZR17 69W; 180/55ZR17 73W; 190/50ZR17 73W; 190/55ZR17 75W; 200/55ZR17 78W"}', 50, 1, 1, NOW(), NOW());
