INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (211, '10542901.0', 'Kenda KR20 Kanine Tires For Can-Am Spyder / Ryker', 'kenda-kr20-kanine-tires-for-can-am-spyder-ryker-10542901.0', 'nan', 2, 'STREET BIKE', 'Dot Tire / Touring Tire / Sportbike Tire', 'Can-Am', 'Spyder / Ryker', '1990 - 2025', 'P1165198', 95.99, '161.95', '161.95', 'nan', 4.8, 12, 'nan', 'nan', 'Front; Rear', 6, '165/55R15 69H TL; 205/55R15 81T TL; 225/50R15 84H TL; 145/60R16 66T TL; 205/45R16 77T TL; 205/65R15 92T TL', 6, 'Kenda KR20 Kanine Tires For Can-Am Spyder / Ryker Experience a seamless transition from factory-installed to aftermarket performance with Kenda''s Kanine KR20 tires, exclusively crafted for your Can-Am Spyder or Ryker. Designed to surpass the original tires in longevity and to outperform typical passenger car tires in handling, the Kanine KR20 ensures a reliable and confident ride in any weather condition.', 'Purpose-Built: The only aftermarket tire designed specifically for three-wheeled auto cycles Superior Performance: Delivers greater mileage than stock tires and better handling than passenger car replacements Confidence in the Wet: Increased siping helps evacuate standing water for excellent wet weather performance Fully Certified: DOT and E-Mark approved', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/kenda_kr20_kanine_tires_for_can_am_spyder_ryker.webp', '["https://americaapi.kaafifoods.com/storage/products/kenda_kr20_kanine_tires_for_can_am_spyder_ryker.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Touring Tire / Sportbike Tire", "Make": "Can-Am", "Model": "Spyder / Ryker", "Tire Size": "165/55R15 69H TL; 205/55R15 81T TL; 225/50R15 84H TL; 145/60R16 66T TL; 205/45R16 77T TL; 205/65R15 92T TL"}', 50, 1, 1, NOW(), NOW());
