INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (218, '1275717.0', 'Metzeler Karoo Street Tires', 'metzeler-karoo-street-tires-1275717.0', 'Metzeler', 2, 'STREET BIKE', 'Dual Road Radial Dot / Dual Road Bias Dot / 80 On Road 20 Off Road / Touring Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P398658', 132.59, '393.77', '393.77', 'Save up to Save $95.21 24%', 4.3, 69, 'nan', 'nan', 'Front; Rear', 14, '120/70R17 58V TL; 130/80R17 65V TL; 140/80R17 69V TL; 150/70R17 69V TL; 170/60R17 72V TL; 180/55R17 73V TL; 150/70R18 70H TL; 150/70R18 70V; 150/70R18 70V TL; 100/90-19 57V TL; 110/80R19 59V TL; 120/70R19 60V TL; 90/90-21 54H TL; 90/90-21 54V TL', 14, 'Metzeler Karoo Street Tires The Karoo Street Tires from Metzeler blend the aggressive, blocky tread pattern of the popular Karoo 3 Tires with a sport touring profile and extra silica, resulting in the perfect road-biased ADV tire.', 'Outstanding on road performance from a knobby tread pattern Sport touring profile High silicompound delivers excellent grip on road, both dry and wet Excellent traction off road Precise cornering and stability throughout tires life Constant contact patch works well with sophisticated electronic systems like ABS and traction control Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/metzeler_karoo_st.webp', '["https://americaapi.kaafifoods.com/storage/products/metzeler_karoo_st.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dual Road Radial Dot / Dual Road Bias Dot / 80 On Road 20 Off Road / Touring Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/70R17 58V TL; 130/80R17 65V TL; 140/80R17 69V TL; 150/70R17 69V TL; 170/60R17 72V TL; 180/55R17 73V TL; 150/70R18 70H TL; 150/70R18 70V; 150/70R18 70V TL; 100/90-19 57V TL; 110/80R19 59V TL; 120/70R19 60V TL; 90/90-21 54H TL; 90/90-21 54V TL"}', 50, 1, 1, NOW(), NOW());
