INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (224, '1807155.0', 'Continental Race Attack 2 Tires', 'continental-race-attack-2-tires-1807155.0', 'Continental Tire', 4, 'STREET BIKE', 'Road Race Dot And Non D / Sportbike Tire / Dot Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P846236', 194.18, '454.45', '454.45', 'Save up to Save $160.73 35%', 5.0, 2, 'nan', 'nan', 'Front; Rear', 5, '120/70ZR17 58W TL; 180/55ZR17 73W TL; 190/50ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL', 5, 'Continental Race Attack 2 Tires Enhance your street or track experience with the Continental Race Attack 2 Tires! Continental has gone the extra mile in designing the Race Attack 2, impressing BMW enough to select these tires as the OEM-supplied rubber for their high-performance M1000XR. Featuring a specialized black chili sport compound, these tires offer unparalleled grip, traction, and predictability in the wet or dry. With no shoulder grooves, they optimize grip during aggressive leans on corners. Whether devouring miles on the street or delivering exceptional grip and feedback on each track lap, Continental''s Race Attack 2 tires are primed for top-notch performance.', 'Black Chili Hypersport-Compound for superior grip on road and track surfaces Carcass construction provides consistent predictability at limits No shoulder grooves for maximum grip at lean angles Medium compound Handmade in Germany Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/continental_tire_tire_ratk2_str12070_zr17.webp', '["https://americaapi.kaafifoods.com/storage/products/continental_tire_tire_ratk2_str12070_zr17.webp", "https://americaapi.kaafifoods.com/storage/products/continental_race_attack2_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Road Race Dot And Non D / Sportbike Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/70ZR17 58W TL; 180/55ZR17 73W TL; 190/50ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL"}', 50, 1, 1, NOW(), NOW());
