INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (225, '10043953.0', 'Sedona Rock-A-Billy Tires', 'sedona-rock-a-billy-tires-10043953.0', 'Sedona', 3, 'UTV/ATV', 'Hard Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P896012', 209.66, '321.95', '321.95', 'Save up to Save $32.15 10%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 6, 'Sedona Rock-A-Billy Tires Queue up some Stray Cats, lace up your two-tone creepers and take to the trails with the Sedona Rock-A-Billy Tires. These rugged-terrain radials excel in dirt and rock. The eight ply design is ultra tough, designed with the high speed running of big power UTVs and ATVs in mind. The Rock-A-Billy has served as the race tire of choice at the UTV Terracross Championships.', 'High speed rugged-terrain tread pattern Engineered for high output UTV and ATV applications 8 ply radial constsruction Aggressive tread design with integrated side lugs to grip in extreme riding conditions Revised compound for higher grip with longer treadwear Integrated rock ejectors Built in rim guard UTV Terracross Championships tire of choice: 2016 Bead-to-bead layer of puncture resistant material For off highway use only Note : Yellow balance dot to be positioned opposite the valve stem.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/sedona_rock_a_billy_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/sedona_rock_a_billy_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Hard Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
