INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (234, '10482252.0', 'Dunlop Dragmax Tire', 'dunlop-dragmax-tire-10482252.0', 'Dunlop', 4, 'STREET BIKE', 'Road Race Dot And Non D / Race Tire / Sportbike Tire / Dot Tire', 'Harley-Davidson', 'Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard', '1990 - 2025', 'P962515', 243.99, '310.95', '310.95', 'Save up to Save $36.96 12%', 4.0, 1, 'nan', 'nan', 'Rear; Front', 2, '110/60ZR17 50W TL; 190/50ZR17 73W', 2, 'Dunlop Dragmax Tire Pro Street Class drag racing has reached new levels of performance in recent years, and Dunlop wants to offer a tire capable of meeting these demands. For maximum stability and feel, this radial tire utilizes Dunlop''s exclusive N-TEC technology, which combines the benefits of their own aramid Jointless Belt and cut-breaker construction. This construction allows the racer to run very low tire pressures, all wrapped in the softest street compound Dunlop has ever made with a new profile that''s wider and flatter than typical hypersports tires. Dunlop''s ready for you to hit the strip on the Dragmax!', 'Dunlop''s softest street compound N-TEC technology features continuously wound aramid Jointless Belt and cut-breaker construction Maximum feel and stability Racers can run very low tire pressures for optimal hookup Wider and flatter profile Minimal centrifugal growth for consistent footprint and reduced risk of de-beading Maximum Grip Technology Made in the USA Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_dragmax_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_dragmax_tire.webp"]', '{"Wheel Location": "Rear; Front", "Type": "STREET BIKE", "Product Type": "Road Race Dot And Non D / Race Tire / Sportbike Tire / Dot Tire", "Make": "Harley-Davidson", "Model": "Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard", "Tire Size": "110/60ZR17 50W TL; 190/50ZR17 73W"}', 50, 1, 1, NOW(), NOW());
