INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (236, '10512903.0', 'Pirelli Scorpion MX32 Mid Soft Tires', 'pirelli-scorpion-mx32-mid-soft-tires-10512903.0', 'Pirelli', 3, 'DIRT BIKE', 'Soft Terrain / Intermediate Terrain / Non Dot Tire / Multi Compound Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1150179', 116.64, '211.51', '211.51', 'Save up to Save $53.69 25%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 4, '110/90-19; 120/80-19; 120/90-19; 80/100-21', 4, 'Pirelli Scorpion MX32 Mid-Soft Tires Engineered for intermediate and soft motocross tracks, the Pirelli Scorpion MX32 Mid Soft tire delivers consistent performance when the dirt is loose. Its tread pattern is designed for excellent traction during acceleration cornering and braking, offering riders confidence lap after lap. A championship-proven choice for your next moto.', 'Designed for soft to intermediate terrain - dirt, mud, sand or loamy surfaces Front uses a new sidewall compound and stiffer structure that provides a better feeling and improved handling Rear features a new tread compound and softer vertical cap designed to improve wear regularity and traction, ensuring consistent performance and durability Improved knob pattern for improved braking stability and lateral grip in corners Factory yellow Pirelli label and high visibility sidewall design Directional design offers maximum performance Enhanced tear resistance Tube Type (TT) Sold individually Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/pirelli_scorpion_mx32_mid_soft_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/pirelli_scorpion_mx32_mid_soft_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Soft Terrain / Intermediate Terrain / Non Dot Tire / Multi Compound Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/90-19; 120/80-19; 120/90-19; 80/100-21"}', 50, 1, 1, NOW(), NOW());
