INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (244, '1023467.0', 'Bridgestone Battlax RS10 Tires', 'bridgestone-battlax-rs10-tires-1023467.0', 'Bridgestone', 4, 'STREET BIKE', 'Hypersport Dot / Race Tire / Sportbike Tire / Dot Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P300955', 198.0, '392.08', '392.08', 'Save up to Save $98.08 25%', 4.4, 8, 'nan', 'nan', 'Front; Rear', 6, '110/70R17 54H; 120/70ZR17 58W; 140/70R17 66H; 150/60R17 66H; 180/55ZR17 73W; 190/50ZR17 73W', 6, 'Bridgestone Battlax RS10 Tires The Bridgestone Battlax RS10 Tires feature high-performance grip, handling, and control.', 'High-performance sport radials optimized for high-grip and handling performance on dry surfaces Bridgestone’s MotoGP development analysis was used to determine the placement of 3-D tread grooves to improve stability, grip and handling by optimizing block stiffness Specially formulated rubber compounds front and rear offer sure grip as well as increased durability Rear profile enables a larger contact patch for improved grip in mid to high lean angles Cap and base on rear tire adds tread stiffness for stability when braking and accelerating Rear tire has softer sidewall construction incorporated for better damping to improve handling Front tire uses a Mono-Spiral Belt constructed with stiffer steel to enhance rigidity of the tread area for upgraded response and stability 120/70ZR17 E OE tire for the Suzuki GSX-R1000R 120/70ZR17 G OE tire for the Yamaha R1M and for the Yamaha R1 / R1S 2015-2017 120/70ZR17 G OE tire for the Yamaha R1 / R1S 2018+ 120/70ZR17 L OE tire for the Kawasaki ZX-10R 120/70ZR17 M OE tire for the Honda RC213 120/70ZR17 N OE tire for the Honda CBR1000RR SP 120/70ZR17 J OE tire for the Kawasaki H2 190/50ZR17 N OE tire for the Honda CBR1000RR SP 190/55ZR17 E OE tire for the Suzuki GSX-R1000R 190/55ZR17 G OE tire for the Yamaha R1 / R1S 2015-2017 190/55ZR17 G2 OE tire for the Yamaha R1 / R1S 2018+ 190/55ZR17 L OE tire for the Kawasaki ZX-10R 190/55ZR17 M OE tire for the Honda RC213 200/55ZR17 G OE tire for the Yamaha R1M 200/55ZR17 J OE tire for the Kawasaki H2 Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mc_enterprises_canyon_cage1400_concours1013.webp', '["https://americaapi.kaafifoods.com/storage/products/mc_enterprises_canyon_cage1400_concours1013.webp", "https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_rs10_r_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Hypersport Dot / Race Tire / Sportbike Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "110/70R17 54H; 120/70ZR17 58W; 140/70R17 66H; 150/60R17 66H; 180/55ZR17 73W; 190/50ZR17 73W"}', 50, 1, 1, NOW(), NOW());
