INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (247, '10506447.0', 'Plews Tyres MX2 Matterly GP Medium / All Terrain Tires', 'plews-tyres-mx2-matterly-gp-medium-all-terrain-tires-10506447.0', 'Plews Tyres', 3, 'DIRT BIKE', 'Intermediate Terrain / Non Dot Tire / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1147489', 57.55, '146.99', '146.99', 'Save up to Save $7.11 5%', 5.0, 1, 'nan', 'nan', 'Rear; Front', 14, '90/100-12; 80/100-10 (3.00/10); 60/100-12; 80/100-12; 60/100-14; 90/90-14; 90/100-14; 90/100-16; 70/100-17; 70/100-19; 100/90-19; 110/90-19; 120/80-19; 80/100-21', 14, 'Plews Tyres MX2 Matterly GP Medium / All Terrain Tires Experience the MX2 Matterly GP, a motocross tire engineered to conquer intermediate terrains with exceptional precision, grip, and longevity. It incorporates a globally optimized compound, striking a fine balance between enduring performance and competitive edge traction. The directional front pattern affords riders assured handling, as the aggressive rear tread design digs deeply into diverse surfaces. MX2 Matterly GP is crafted for supreme comfort, ensuring rider control is not sacrificed, presenting top-tier performance that comes at a value accessible to racers.', 'Engineered for intermediate motocross terrain Advanced compound developed by world-leading chemists Directional front tire delivers responsive handling and front-end feel Aggressive rear tread provides exceptional traction and drive Carcass construction designed for enhanced comfort and control Built for race performance and long-term durability Priced to support competitive riders at all levels Inspired by the iconic Matterly Basin GP track', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/plews_tyres_mx2_matterly_gp_front_medium_front.webp', '["https://americaapi.kaafifoods.com/storage/products/plews_tyres_mx2_matterly_gp_front_medium_front.webp"]', '{"Wheel Location": "Rear; Front", "Type": "DIRT BIKE", "Product Type": "Intermediate Terrain / Non Dot Tire / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "90/100-12; 80/100-10 (3.00/10); 60/100-12; 80/100-12; 60/100-14; 90/90-14; 90/100-14; 90/100-16; 70/100-17; 70/100-19; 100/90-19; 110/90-19; 120/80-19; 80/100-21"}', 50, 1, 1, NOW(), NOW());
