INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (250, '949965.0', 'Dunlop Geomax MX3SF Front Tire', 'dunlop-geomax-mx3sf-front-tire-949965.0', 'Dunlop', 3, 'DIRT BIKE', 'Off Highway Non Dot Inc / Dirt Bike Tire / Intermediate Terrain / Soft Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P266846', 103.99, NULL, NULL, 'Save $41.96 29%', 5.0, 4, 'nan', 'nan', 'Front', 1, '80/100-21 51M', 1, 'Dunlop MX3SF Front Tire', 'Directional Tread Pattern: Offers great traction and steering feel for a wide range of riders who have differing riding styles Enhanced Carcass Tension Control System (CTCS): Tuned carcass flexibility offers enhanced feel and steering accuracy Staggered Middle Blocks: Alternating mid-shoulder knobs in the MX32 have been angled differently and are sized differently to add side grip and promote light, responsive steering while being less prone to grabbing in ruts Elimination of tie-bar design: The tie bars have been eliminated to reduce the resistance toward bending within blocks This enhances steering feel and promotes stability in muddy conditions Chiseled Shoulder Block: Derived from the MX31, this chiseled block shape penetrates the surface to enhance side grip Knob Placement: Improved knob placement and angling reduces knob stress Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_geomax_mx3_s_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_geomax_mx3_s_tires.webp"]', '{"Wheel Location": "Front", "Type": "DIRT BIKE", "Product Type": "Off Highway Non Dot Inc / Dirt Bike Tire / Intermediate Terrain / Soft Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "80/100-21 51M"}', 50, 1, 1, NOW(), NOW());
