INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (257, '10043836.0', 'Sedona Coyote Tires', 'sedona-coyote-tires-10043836.0', 'Sedona', 3, 'UTV/ATV', 'Intermediate Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P895991', 122.36, '230.95', '230.95', 'Save up to Save $23.05 10%', 4.8, 4, 'nan', 'nan', 'nan', 0, 'nan', 5, 'Sedona Coyote Tires Sedona''s Coyote Tires are ready to handle the wiliest of trails. Packing the latest tech in ATV and UTV tire construction, the Coyote Tires balance reduced with with puncture resistance and smooth ride characteristics. Depending on size, the Coyote Tires use either six ply bias or eight ply radial tire construction. The all-terrain tread design uses wider lug spacing to increase bite over rocks, roots and ruts. A built-in rim guard and siping on the tread lugs boost durability and performance.', 'Ultra-durable, puncture-resistant "New-Tech" construction "Smooth-Ride" Technology and aggressive tread design for excellent traction and a smooth ride in all terrain Integrated side lugs for added traction in deep ruts and rocks Siped tread lugs for added traction and durability Built-in rim guard for added wheel protection Available in 6 ply bias or 8 ply radial construction For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/sedona_coyote_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/sedona_coyote_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Intermediate Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
