INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (262, '10566857.0', 'Mitas Enduro Trail ADV 2 Tires', 'mitas-enduro-trail-adv-2-tires-10566857.0', 'Mitas', 3, 'DIRT BIKE', 'Dual Sport Tire / 70 On Road 30 Off Road / Dot Tire / Touring Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1174728', 148.27, '277.99', '277.99', 'Save up to Save $26.75 10%', 2.5, 2, 'nan', 'nan', 'Front; Rear', 6, '150/70R17 69V; 170/60ZR17 72W; 150/70R18 70V; 110/80R19 59V; 120/70ZR19 60W; 90/90-21 54V', 6, 'Mitas Enduro Trail ADV 2 Tires The Mitas Enduro Trail ADV 2 tire is crafted for the modern explorer who demands strong performance on the tarmac and the ability to handle uncharted paths with ease. With a 70% on-road and 30% off-road tread pattern, drawn from the acclaimed Mitas ENDURO TRAIL+ design, it provides exceptional self-cleaning properties on light to medium terrains. This tire is a go-to choice for riders seeking versatility across various landscapes. Equipped with high silica content, the Enduro Trail ADV 2 tire delivers outstanding wet grip, empowering riders with the confidence to navigate rainy conditions safely. Its advanced carcass design ensures remarkable stability and comfort even at higher speeds, offering a seamless experience on highways or curvy backroads alike. Whether undertaking long hauls or short excursions, the Enduro Trail ADV 2 tire maintains consistent performance for a balance of adventure and reliability.', 'Classified for 70% on-road use, offering exceptional performance and confidence on both paved and off-road terrains Multi-compound tread technology with a chevron pattern guarantees superior grip and durability in all conditions Recommended for Dual-Purpose Adventure Touring motorcycles Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_adv2_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_adv2_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Dual Sport Tire / 70 On Road 30 Off Road / Dot Tire / Touring Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "150/70R17 69V; 170/60ZR17 72W; 150/70R18 70V; 110/80R19 59V; 120/70ZR19 60W; 90/90-21 54V"}', 50, 1, 1, NOW(), NOW());
