INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (264, '10043858.0', 'Sedona Cyclone Rear Tires', 'sedona-cyclone-rear-tires-10043858.0', 'Sedona', 3, 'UTV/ATV', 'Sand Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P895994', 119.65, '140.95', '140.95', 'Save up to Save $14.05 10%', 5.0, 1, 'nan', 'nan', 'nan', 0, 'nan', 6, 'Sedona Cyclone Rear Tires The Cyclone Tire from Sedona is a no-compromises sand tire for rear wheel ATV applications. Eight stonking paddles and a reinforced four ply construction are ready to create propulsion in all forms of sand - wet, dry and volcanic. Support ridges on the backside of the paddles add support and stability when side hilling. The lightweight design reduces rotating mass and aids acceleration. Left- and right-side specific designs ensure the utmost traction.', 'Bias ply sand tire for traction, flotation, predictable turning and side hilling Excels in dry light sand, wet heavy sand and volcanic sand Proven dune tire with R&D from the major sand parks in the USA Premium rubber compound is strong yet flexible and light Long lasting treadwear Lightweight overall design 8 large paddles 4 ply construction Back support ridges for controlled slides on ridge-back dunes For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/sedona_cyclone_rear_bias4_pr_cyclone_rear.webp', '["https://americaapi.kaafifoods.com/storage/products/sedona_cyclone_rear_bias4_pr_cyclone_rear.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Sand Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
