INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (265, '1812615.0', 'Dunlop AT81 Enduro Cross Tires', 'dunlop-at81-enduro-cross-tires-1812615.0', 'Dunlop', 3, 'DIRT BIKE', 'Off Highway Non Dot Inc / Dirt Bike Tire / Hard Terrain / Intermediate Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P849376', 147.99, NULL, NULL, 'Save $30.96 17%', 5.0, 1, 'nan', 'nan', 'Rear', 1, '110/100-18', 1, 'Dunlop AT81 Enduro Cross Tires Dunlop’s vast championship experience and development expertise has been infused into the next generation of off-road tires: the Dunlop AT81 Enduro Cross.', 'AT81 rear tread block shape and distribution plus DIRTuitive Grip Design (DGD) knobs help the tire penetrate down through the surface dirt for extra traction across a broad range of off-road applications Newly formulated high-wear-resistant rear tire compound offers enhanced chipping, tearing and wear appearance AT81 EX rear tire carcass features two nylon plies Lateral grooves on the shoulder knobs provide additional biting edges and also allow the knobs to be more flexible Rear center blocks are arranged in-line to provide a larger contact patch for maximum traction Dunlop’s “plush pad” recess design between tread blocks enhances compliance for bump absorption and ride comfort Front tire construction includes two plies of nylon wrapped with a third ply of polyester for a strong base Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_at81_ex_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_at81_ex_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "Off Highway Non Dot Inc / Dirt Bike Tire / Hard Terrain / Intermediate Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/100-18"}', 50, 1, 1, NOW(), NOW());
