INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (266, '1818508.0', 'Avon Roadrider Mk II Tires', 'avon-roadrider-mk-ii-tires-1818508.0', 'Avon Tire', 2, 'STREET BIKE', 'Cruiser Tire / Sportbike Tire / Touring Tire / Dot Tire', 'Harley-Davidson', 'Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard', '1990 - 2025', 'P853446', 152.24, '458.85', '458.85', 'Save up to Save $110.93 24%', 4.9, 14, 'nan', 'nan', 'Front; Front/Rear; Rear', 30, '110/80V17 57V; 110/80V18 58V; 140/70V18 67V; 160/80-15 74V; 160/80V15 74V; 120/80V16 60V; 130/90-16 73V; 100/80-17 52H; 110/70-17 54H; 110/70-17 54V; 110/80B17 57V; 120/70-17 58V; 120/80-17 61V; 120/90-17 64V; 130/70-17 62H; 130/80-17 65H; 130/80-17 65V; 130/90-17 68V; 140/70-17 66H; 140/70-17 66V; 140/80-17 69V; 150/70-17 69V; 90/90-18 51V; 100/90-18 56H; 120/80-18 62V; 120/90-18 65V; 130/70V18 63V; 130/80-18 66V; 150/70-18 70V; 90/90-21 54V', 31, 'Avon Roadrider Mk II Tires The Avon Roadrider MK II Tires are revised with features and performance that outshine its well-regarded Roadrider Mk I predecessor. Maintaining classic British restraint, the tread pattern is slightly more chiseled than before, but front and rear tread designs continue to mirror one another for a cohesive overall appearance. Once past the Roadrider Mk II''s aesthetics, sport, sport-touring and cruiser riders will benefit from a silica-rich compound and aggressive shoulder contour for excellent stiction in wet and dry conditions.', 'High silica compound for excellent wet and dry performance Symmetrical front and rear tread designs Interrupted center groove to prevents tramlining Enhanced sidewall offers better resistance to ozone degradation Embossed Union Jack sidewall treatment Tubeless (TL) Bias ply construction Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/avon_roadrider_mk_ii_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/avon_roadrider_mk_ii_tires.webp"]', '{"Wheel Location": "Front; Front/Rear; Rear", "Type": "STREET BIKE", "Product Type": "Cruiser Tire / Sportbike Tire / Touring Tire / Dot Tire", "Make": "Harley-Davidson", "Model": "Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard", "Tire Size": "110/80V17 57V; 110/80V18 58V; 140/70V18 67V; 160/80-15 74V; 160/80V15 74V; 120/80V16 60V; 130/90-16 73V; 100/80-17 52H; 110/70-17 54H; 110/70-17 54V; 110/80B17 57V; 120/70-17 58V; 120/80-17 61V; 120/90-17 64V; 130/70-17 62H; 130/80-17 65H; 130/80-17 65V; 130/90-17 68V; 140/70-17 66H; 140/70-17 66V; 140/80-17 69V; 150/70-17 69V; 90/90-18 51V; 100/90-18 56H; 120/80-18 62V; 120/90-18 65V; 130/70V18 63V; 130/80-18 66V; 150/70-18 70V; 90/90-21 54V"}', 50, 1, 1, NOW(), NOW());
