INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (270, '10579736.0', 'Dunlop Geomax MX34 Factory Spec Tires', 'dunlop-geomax-mx34-factory-spec-tires-10579736.0', 'Dunlop', 3, 'DIRT BIKE', 'Soft Terrain / Intermediate Terrain / Non Dot Tire / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1181575', 140.99, '213.95', '213.95', 'Save up to Save $42.96 20%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 3, '110/90-19; 120/90-19; 80/100-21', 3, 'Dunlop Geomax MX34 Factory Spec Tires Experience professional-grade performance with the Dunlop MX34 Factory Spec Tires, crafted with the same carcass and single-radius profile utilized by the elites in the sport. This Spec version delivers unrivaled stability and precise feedback, excelling even under the most demanding track conditions. Designed for those who seek the utmost in traction and control, the MX34 Factory Spec is engineered to shave vital seconds off your lap times, ensuring you stay ahead of the competition.', 'Proprietary Ultra-High Molecular Mass compound increases knob strength to penetrate deep into soft soil Single-radius profile provides a rounder shape for more consistent feel and predictable slide control Advanced Apex design features a taller profile for improved responsiveness and harsh landing support Stiffer carcass construction enhances stability and maintains performance during high-speed sections Advanced mud evacuation technology keeps the tread clear for maximum hook up in sloppy conditions Next-generation Progressive Cornering Block Technology (PCBT) improves cornering grip and feel', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_geomax_mx34_factory_spec_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_geomax_mx34_factory_spec_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Soft Terrain / Intermediate Terrain / Non Dot Tire / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/90-19; 120/90-19; 80/100-21"}', 50, 1, 1, NOW(), NOW());
