INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (272, '10584794.0', 'Mitas Touring Force SC Scooter Tires', 'mitas-touring-force-sc-scooter-tires-10584794.0', 'Mitas', 2, 'STREET BIKE', 'Dot Tire / Scooter Tire', 'Harley-Davidson', 'Touring', '2000 - 2025', 'P1184559', 52.84, '120.99', '120.99', 'Save up to Save $26.52 22%', 4.8, 12, 'nan', 'nan', 'Front/Rear; Front; Rear', 18, '90/90-10 50M; 100/80-10 53L; 120/70-10 54L; 120/90-10 66L; 3.50-10 51P; 110/90-12 64P; 140/70-12 65P Reinforced; 110/90-13 56P; 130/70-13 63P Reinforced; 150/70-13 64S; 90/90-14 46P; 100/90-14 57P Reinforced; 110/80-14 59S Reinforced; 120/70-14 55S; 120/80-14 58S; 120/70-15 56S; 100/80-16 50P; 120/80-16 60P', 18, 'Mitas Touring Force SC Scooter Tires They might be small, but the Mitas Touring Force SC Tires are truly mighty. Touring Force SC''s utilizes a unique tread compound to ensure reliable grip across various weather conditions while the structural design is aimed at efficient water displacement. The Mitas Touring Force SC features a robust carcass construction that maintains stability and precision during straight-line travel, in aggressive cornering, under heavy loads, and over potholes, train tracks, and urban detritus. Larger 15" and 16" diameter options allows the Mitas Touring Force SC to support modern maxi scooters and high-performance three-wheeled machines. This tire is o riginal equipment for the Piaggio Beverly 400. Available in standard and reinforced sidewall versions to suit ever rider''s needs.', '​ Urban Commuting Performance: Specialized tread compound engineered for predictable handling and safety on all paved city roads All-Weather Grip: Unique rubber formulation ensures reliable traction and effective water displacement in diverse weather conditions Stability And Precision: Strong carcass design provides high stability and steering accuracy during straight-line riding and cornering Maximum Comfort: Developed for sports and classic scooter riders seeking a smooth and comfortable urban riding experience Extended Service Life: High-performance compound offers excellent durability and long-lasting wear for daily commuters Compatibility: Designed for all types of sports and classic scooters, including modern maxi scooters and powerful three-wheelers Includes: Available in 15-inch sizes featuring the advanced TOURING FORCE pattern Compatibility: Selected as the OEM fitment for the Piaggio Beverly 400 Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_touring_force_sc_scooter_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_touring_force_sc_scooter_tires.webp"]', '{"Wheel Location": "Front/Rear; Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Scooter Tire", "Make": "Harley-Davidson", "Model": "Touring", "Tire Size": "90/90-10 50M; 100/80-10 53L; 120/70-10 54L; 120/90-10 66L; 3.50-10 51P; 110/90-12 64P; 140/70-12 65P Reinforced; 110/90-13 56P; 130/70-13 63P Reinforced; 150/70-13 64S; 90/90-14 46P; 100/90-14 57P Reinforced; 110/80-14 59S Reinforced; 120/70-14 55S; 120/80-14 58S; 120/70-15 56S; 100/80-16 50P; 120/80-16 60P"}', 50, 1, 1, NOW(), NOW());
