INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (273, '10566836.0', 'Metzeler Sportec 01 RS Tires', 'metzeler-sportec-01-rs-tires-10566836.0', 'Metzeler', 2, 'STREET BIKE', 'Dot Tire / Multi Compound Tire / Sportbike Tire', 'Harley-Davidson', 'Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard', '1990 - 2025', 'P1174721', 207.72, '466.77', '466.77', 'Save up to Save $122.91 26%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 5, '120/70ZR17 58W TL; 180/55ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL; 200/60ZR17 80W TL', 5, 'Metzeler Sportec 01 RS Tires The Sportec 01 RS tire brings unparalleled performance to the pavement, serving street riders and track enthusiasts alike with an enhanced grip over its counterpart, the standard Sportec 01. This tire elevates the supersport tire category, offering a blend of cutting-edge performance with unwavering wet weather functionality. Equipped with Dynatread™ technology, it boasts an adaptive tread design that responds dynamically to varying speeds and load conditions. The intelligently designed sipes flex at high speeds, effectively transforming the tire to increase the rubber contact patch on the road for better traction. When navigating through city streets, in rain, or at lower speeds, the tread''s grooves adeptly channel water away, maintaining exceptional wet grip. The Sportec 01 RS is an ideal choice for spirited street riders who demand that extra bit of grip when venturing onto the track.', 'The sharpest evolution of SPORTEC™ 01 for riders demanding highest level of grip on the road Enriched road racing expertise delivering Metzeler high performance on road and track High-contrast sidewall design that elevates the tires character Features Dynatread™, the adaptive tread design technology Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/metzeler_sportec01_rs_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/metzeler_sportec01_rs_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Multi Compound Tire / Sportbike Tire", "Make": "Harley-Davidson", "Model": "Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard", "Tire Size": "120/70ZR17 58W TL; 180/55ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL; 200/60ZR17 80W TL"}', 50, 1, 1, NOW(), NOW());
