INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (277, '10584781.0', 'Mitas Touring Force SC 2 Scooter Tires', 'mitas-touring-force-sc-2-scooter-tires-10584781.0', 'Mitas', 2, 'STREET BIKE', 'Dot Tire / Scooter Tire', 'Harley-Davidson', 'Touring', '2000 - 2025', 'P1184560', 53.32, '150.99', '150.99', 'Save up to Save $33.04 22%', 4.8, 12, 'nan', 'nan', 'Front/Rear; Rear', 8, '100/90-10 61M Reinforced; 110/70-11 45P; 110/70-12 47S; 120/70-12 58S Reinforced; 130/70-12 64S Reinforced; 140/70-14 68S Reinforced; 150/70-14 66S; 110/70-16 52S', 8, 'Mitas Touring Force SC 2 Scooter Tires The Mitas Touring Force SC 2 is the improved successor to the original Mitas Touring Force scooter tire. Upping the level of performance, the Touring Force SC 2 Tire features an improved pattern design to facilitate an improved ride, boosted grip, and improved overall service life. Specialized tread geometry facilitates efficient water displacement to maintain traction in diverse weather conditions for sports and classic scooter applications. The high-strength carcass construction of the Mitas Touring Force SC 2 ensures structural stability and handling precision. The Mitas Touring Force SC 2 incorporates a unique tread compound that reduces acoustic noise and improves rolling resistance for riders seeking comfort and efficiency.', '​ Urban Commuting Performance: Optimized for all paved surfaces and diverse city weather conditions Precision Handling: High-stability carcass ensures steering accuracy on straightaways and through corners Advanced Compound: Specialized material reduces road noise and improves rolling resistance All-Weather Traction: Unique tread pattern provides rapid water displacement for wet-road safety Enhanced Durability: Refined design extends tire life while maintaining consistent grip levels Smooth Performance: Engineered for predictability and comfort in demanding urban environments Compatibility: Fits a wide range of sports and classic scooters Compatibility: Engineered as the high-performance successor to the original Mitas TOURING FORCE-SC Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_touring_force_sc2_scooter_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_touring_force_sc2_scooter_tires.webp"]', '{"Wheel Location": "Front/Rear; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Scooter Tire", "Make": "Harley-Davidson", "Model": "Touring", "Tire Size": "100/90-10 61M Reinforced; 110/70-11 45P; 110/70-12 47S; 120/70-12 58S Reinforced; 130/70-12 64S Reinforced; 140/70-14 68S Reinforced; 150/70-14 66S; 110/70-16 52S"}', 50, 1, 1, NOW(), NOW());
