INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (312, '1067162.0', 'Michelin StarCross 5 Medium Terrain Tires', 'michelin-starcross-5-medium-terrain-tires-1067162.0', 'Michelin Tires', 3, 'DIRT BIKE', 'Off Highway Non Dot Inc / Intermediate Terrain / Dirt Bike Tire / Non Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P315700', 64.99, '157.95', '157.95', 'Save up to Save $25.54 16%', 4.5, 8, 'nan', 'nan', 'Front; Rear', 13, '90/100-14; 90/100-16; 70/100-17; 100/100-18; 110/100-18; 120/90-18; 70/100-19; 100/90-19; 100/90-19 TT; 110/90-19; 120/80-19; 80/100-21; 90/100-21', 13, 'Michelin StarCross 5 Medium Terrain Tires The Michelin StarCross 5 tires were designed using feedback from riders of all levels, from amateurs to world champions, often riding in extreme conditions, who shared their experiences in the field with Michelin Motorsports and Michelin’s world-class research and development team.The Michelin StarCross 5 range breaks new ground for Michelin in the world of Off-Road/Motocross tires. Compared to its predecessors (Michelin StarCross 3/4), the Michelin StarCross 5 line is based on a new casing design that delivers several significant performance improvements. The new casing design incorporates stronger, higher density materials that reduce weight up to 15 percent without compromising strength or durability. The casing construction also features Michelin’s all-new Comfort Casing Technology (CCT), which provides exceptional shock absorption that reduces rider fatigue.', 'Experienced motocross rider or occasional rider riding motocross for fun, StarCross 5 is the high-performance motocross tire designed to allow you to face any terrain Tested and approved by riders from pros to occasional motocross rider Designed to give the ultimate performance Adapted to each type of terrain, bike and use Larger size range for a wider scope of usage including new sizes designed for cross-country Blackwall Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_star_cross_mini_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_star_cross_mini_tires.webp", "https://americaapi.kaafifoods.com/storage/products/michelin_star_cross5_medium_terrain_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Off Highway Non Dot Inc / Intermediate Terrain / Dirt Bike Tire / Non Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "90/100-14; 90/100-16; 70/100-17; 100/100-18; 110/100-18; 120/90-18; 70/100-19; 100/90-19; 100/90-19 TT; 110/90-19; 120/80-19; 80/100-21; 90/100-21"}', 50, 1, 1, NOW(), NOW());
