INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (313, '10566837.0', 'Metzeler Sportec 01 Tires', 'metzeler-sportec-01-tires-10566837.0', 'Metzeler', 1, 'STREET BIKE', 'Dot Tire / Multi Compound Tire / Sportbike Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P1174720', 164.35, '377.43', '377.43', 'Save up to Save $94.87 25%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 8, '110/70ZR17 54W TL; 120/70ZR17 58W TL; 150/60ZR17 66W TL; 160/60ZR17 69W TL; 180/55ZR17 73W TL; 190/50ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL', 8, 'Metzeler Sportec 01 Tires Building upon its predecessor, the M9 tire, the Metzeler Sportec 01 stands as the apex of Metzeler''s supersport tires designed for spirited street riding regardless of weather conditions. Equipped with Dynatread™ technology, the Sportec 01''s adaptive tread design enables its sipes to adjust and conform. During high speed riding, the sipes contract to maximize rubber contact with the pavement. Conversely, under lighter loads or at slower speeds, such as in wet conditions or urban traffic, the grooves effectively disperse water to maintain traction. Hence, the Sportec 01 excels in both dry and rainy climates, offering you a dependable tire for daily commutes or exhilarating weekend jaunts.', 'Precise and responsive steering for accurate line holding and a strong front-end feel Developed to perform on wet roads with supersport-level feeling High-contrast sidewall design that elevates the tires character Features Dynatread™, the adaptive tread design technology Patented distinctive supersport tread design Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/metzeler_sportec01_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/metzeler_sportec01_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "STREET BIKE", "Product Type": "Dot Tire / Multi Compound Tire / Sportbike Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "110/70ZR17 54W TL; 120/70ZR17 58W TL; 150/60ZR17 66W TL; 160/60ZR17 69W TL; 180/55ZR17 73W TL; 190/50ZR17 73W TL; 190/55ZR17 75W TL; 200/55ZR17 78W TL"}', 50, 1, 1, NOW(), NOW());
