INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (317, '1790997.0', 'Michelin Enduro Xtrem Rear Tires', 'michelin-enduro-xtrem-rear-tires-1790997.0', 'Michelin Tires', 3, 'DIRT BIKE', 'Dirt Bike Tire / Hard Terrain / Non Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P836178', 215.96, NULL, NULL, 'Save $34.03 14%', 4.8, 12, 'nan', 'nan', 'Rear', 1, '140/80-18 70M TT', 1, 'Michelin Enduro Xtrem Rear Tires Outstanding performance on a wide range of challenging surfaces. Extremely pliable tread rubber compound that is derived from the legendary MICHELIN Trials tires. Features Winner of 2019 Red Bull Erzberg Rodeo, top five sweep at Hixpania Hard Enduro, and American Hard Enduro Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_tires_enduro_xtrem14080_mc70_mrtt.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_tires_enduro_xtrem14080_mc70_mrtt.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "Dirt Bike Tire / Hard Terrain / Non Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "140/80-18 70M TT"}', 50, 1, 1, NOW(), NOW());
