INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (318, '10321036.0', 'Motoz Xtreme Hybrid Tires', 'motoz-xtreme-hybrid-tires-10321036.0', 'Motoz', 3, 'DIRT BIKE', '20 On Road 80 Off Road / 10 On Road 90 Off Road / Dot Dirt Tires / Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1054907', 140.99, '170.99', '170.99', 'nan', 4.8, 12, 'nan', 'nan', 'Rear; Front', 4, '110/100-18 (M/C) 64M TT; 120/100-18 (M/C) 68M TT; 110/90-19 (M/C) 62M TT; 80/100-21 (M/C) 51M TT', 4, 'Motoz Xtreme Hybrid Tires For a technical single-track tire that can handle soft and slick conditions, look no further. The Xtreme Hybrid features the Motoz Hybrid design, giving you a mix of moto and trials performance in a DOT approved package.', '15% on-road / 85% off-road Intermediate / soft terrain tread pattern Hybrid natural / synthetic rubber compound Reinforced sidewalls to allow for lower inflation pressure Flexible tread Concave and Lock system for increased traction Tread blocks with deep sipes for extra trials-like grip Reversible rear tread design DOT approved Tube type Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_xtreme_hybrid_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_xtreme_hybrid_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "DIRT BIKE", "Product Type": "20 On Road 80 Off Road / 10 On Road 90 Off Road / Dot Dirt Tires / Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/100-18 (M/C) 64M TT; 120/100-18 (M/C) 68M TT; 110/90-19 (M/C) 62M TT; 80/100-21 (M/C) 51M TT"}', 50, 1, 1, NOW(), NOW());
