INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (324, '1325957.0', 'Shinko Reactor II Drag Slick', 'shinko-reactor-ii-drag-slick-1325957.0', 'Shinko Tires', 4, 'STREET BIKE', 'Non Dot Tire / Race Tire', 'Harley-Davidson', 'Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard', '1990 - 2025', 'P422004', 216.71, NULL, NULL, 'Save $38.24 15%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 1, 'Shinko Reactor 2 Drag Slick Experience the rush of acceleration with the Shinko Reactor 2, a wrinkle wall drag slick that''s meticulously crafted for the drag strip. Shinko Reactor 2 provides an exceptional traction advantage, thanks to its sticky tread compound that''s laser-focused on maximum hook-up to shave precious tenths off your elapsed time. Designed to accommodate the majority of sport bike rear wheels, Shinko Reactor 2 delivers a sizable contact patch to ensure you''re at the forefront when it''s time to launch.', 'Wrinkle wall construction for massive off-the-line traction Specialized tread compound designed for maximum grip 26” x 7” x 17” size fits most common sport bike rear wheels Approximate equivalent size: 180/65-17 Recommended rim width 5-1/2” to 7-1/2” NHS (Not for Highway Service) Track use only Note: Non-DOT tire designed for closed-course drag racing only.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/shinko_reactor_ii_drag_slick.webp', '["https://americaapi.kaafifoods.com/storage/products/shinko_reactor_ii_drag_slick.webp"]', '{"Wheel Location": "nan", "Type": "STREET BIKE", "Product Type": "Non Dot Tire / Race Tire", "Make": "Harley-Davidson", "Model": "Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
