INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (325, '10032679.0', 'Maxxis Bighorn 2.0 Tires', 'maxxis-bighorn-2-0-tires-10032679.0', 'Maxxis Tires', 3, 'UTV/ATV', 'Utv Atv Tire / Hard Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P891846', 201.4, '363.99', '363.99', 'Save up to Save $18.20 5%', 4.8, 12, 'nan', 'nan', 'Front; Front/Rear; Rear', 0, 'nan', 21, 'Maxxis Bighorn 2.0 Tires The Bighorn 2.0 tires from Maxxis pack all the style and traction. The Bighorn 2.0 Tires keep the tread pattern of the original Bighorn while slimmer lugs reduce mass. Radial construction provides better shock absorption, allowing for a smoother ride. The non-directional pattern provides predictable cornering and claws over roots and rocks for optimum climbing confidence. The Bighorn 2.0 boasts a 6-ply rating (unless noted), offering the durability that UTV fans have grown to respect from the Bighorn Tires.', 'Durable 6 ply construction (unless noted) Radial design offers a significantly smoother ride over rough trails Designed for hard-pack, intermediate, soft terrain and sandy applications Excels in mud and sand Select sizes available in 4 ply For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/maxxis_bighorn20_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/maxxis_bighorn20_tires.webp"]', '{"Wheel Location": "Front; Front/Rear; Rear", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Hard Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
