INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (334, '10506507.0', 'Plews Tyres MX1 Hawkstone GP Rear Soft Tires', 'plews-tyres-mx1-hawkstone-gp-rear-soft-tires-10506507.0', 'Plews Tyres', 3, 'DIRT BIKE', 'Soft Terrain / Non Dot Tire / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1147524', 61.1, '159.99', '159.99', 'Save up to Save $36.71 23%', 5.0, 1, 'nan', 'nan', 'Rear', 7, '90/100-12; 80/100-12; 90/100-14; 90/100-16; 100/90-19; 110/90-19; 120/80-19', 7, 'Plews Tyres MX1 Hawkstone GP Rear Soft Tires The MX1 Hawkstone GP tire is engineered to excel in the most challenging sand and mud environments. Its lightweight construction ensures unmatched agility while the aggressive tread pattern delivers powerful traction in soft terrain. Developed with input from leading chemists, its advanced rubber compound strikes an optimal balance between durability and grip. This tire features enhanced shoulder support and a specialized polyester carcass to offer remarkable lateral stability during challenging off-cambers, deep ruts, and on jump faces. Ideal for competitive racers seeking an edge in loose conditions, the MX1 Hawkstone GP is built for victory and competitively priced to support the racing community.', 'Optimized for sand and mud terrain performance Lightweight construction enhances agility and speed Sharp, aggressive tread for superior grip in deep conditions Increased block height for maximum traction off the line Reinforced shoulders improve lateral stability on off-cambers and jumps Polyester carcass with custom ply layout for control and comfort Globally developed compound for durability and race-day grip Built tough to endure the rigors of off-road racing Race-focused performance at rider-friendly pricing', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/plews_tyres_mx1_hawkstone_gp_rear_soft_tires_1800x1800.webp', '["https://americaapi.kaafifoods.com/storage/products/plews_tyres_mx1_hawkstone_gp_rear_soft_tires_1800x1800.webp", "https://americaapi.kaafifoods.com/storage/products/plews_tyres_mx1_hawkstone_gp_rear_soft_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "Soft Terrain / Non Dot Tire / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "90/100-12; 80/100-12; 90/100-14; 90/100-16; 100/90-19; 110/90-19; 120/80-19"}', 50, 1, 1, NOW(), NOW());
