INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (346, '1645439.0', 'Michelin Scorcher 21 Tires', 'michelin-scorcher-21-tires-1645439.0', 'Michelin Tires', 2, 'STREET BIKE', 'Cruiser Tire / Harley Tire / Dot Tire', 'Harley-Davidson', 'Harley Sportster / Harley Fxfxr / Harley Street / Harley Touring / Harley V Rod / Harley Softail / Harley Dyna / Harley Dyna Fat Bo / Harley Dyna Street / Harley Dyna Super / Harley Dyna Switch / Harley Softail Del / Harley Softail Deu / Harley Softail Fat / Harley Softail Her / Harley Softail Nig / Harley Sportster 1 / Harley Sportster 8 / Harley Sportster I / Harley Touring Ele / Harley Touring Roa / Harley Touring Str', '1990 - 2025', 'P919612', 166.99, '319.99', '319.99', 'Save up to Save $100.00 31%', 4.9, 207, 'nan', 'nan', 'Front; Rear', 2, '120/70R17; 160/60R17', 2, 'Michelin Scorcher 21 Tires The Michelin Scorcher 21 Tires are designed from the ground up as original equipment tires used exclusively on Harley-Davidson Street Rod motorcycles. The tires feature a style and tread pattern used on generations of HD with advanced compounds, wet weather technology and radial design that significantly boosts the performance factor for modern performance and modern expectations.', 'Original equipment tires on Harley-Davidson Street Rod motorcycles Radial construction for sporty feel and urban agility Michelin Carbon Black compound formulation Traditional cruiser tread pattern with upgraded compound and engineering Modeled after Michelin Hypersport road tires F