INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (351, '10321039.0', 'Motoz Mountain Hybrid Gummy Rear Tires', 'motoz-mountain-hybrid-gummy-rear-tires-10321039.0', 'Motoz', 3, 'DIRT BIKE', '30 On Road 70 Off Road / 20 On Road 80 Off Road / Dot Dirt Tires / Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1054910', 171.99, '178.99', '178.99', 'nan', 4.8, 12, 'nan', 'nan', 'Rear', 3, '110/100-18 (M/C) 64M TT; 120/100-18 (M/C) 68M TT; 110/90-19 (M/C) 62M TT', 3, 'Motoz Mountain Hybrid Gummy Rear Tires The Mountain Hybrid Gummy is an ultra-soft version of the original hybrid tire, the Mountain Hybrid. Offering the same motocross / trials DNA as the original, the Gummy BFM compound adds even more traction to the rear of your machine. This design concept works on a flexible tread concave and lock system, to give increased traction while avoiding punctures at low inflation pressures. The Motoz Mountain Hybrid tire climbs like a trials tire, but handles corners, creek crossings, sand, and rocks like a regular DOT off-road tire. Constructed like a trials tire, but with reinforced sidewalls to allow lower inflation pressure when riding in off-road and mountain conditions.', '25% on-road / 75% off-road use Intermediate terrain tread pattern Ultra-soft BFM Gummy compound Hybrid natural / synthetic rubber construction Reinforced sidewalls to allow for lower inflation pressure Flexible tread Concave and Lock system for increased traction Tread blocks with deep sipes for extra trials-like grip Reversible rear tread design DOT approved Tube type Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_mountain_hybrid_gummy_rear_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_mountain_hybrid_gummy_rear_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "30 On Road 70 Off Road / 20 On Road 80 Off Road / Dot Dirt Tires / Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/100-18 (M/C) 64M TT; 120/100-18 (M/C) 68M TT; 110/90-19 (M/C) 62M TT"}', 50, 1, 1, NOW(), NOW());
