INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (357, '1088537.0', 'Bridgestone Battlax Hypersport S21 Tires', 'bridgestone-battlax-hypersport-s21-tires-1088537.0', 'Bridgestone', 4, 'STREET BIKE', 'Hypersport Dot / Race Tire / Sportbike Tire / Dot Tire', 'Honda', 'Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale', '1998 - 2025', 'P326568', 219.8, NULL, NULL, 'Save $10.38 5%', 4.7, 49, 'nan', 'nan', 'Front', 1, '120/60ZR17 55W', 1, 'Bridgestone Battlax Hypersport S21 Tires The Bridgestone Battlax S21 Tires are ultra high-performance radials designed and developed to get the best out of the latest sport bikes.', 'Dry grip and wear life significantly improved without sacrificing wet performance 3D cross grooves designed to optimize rigidity and improve contact with the road Dual compound front tire (3LC) with revised profile generates higher grip at lower lean angles Triple compound rear tire (5LC) with revised profile provides improved stability and durability New enhanced Micro-contact-patch compound (EMC) technology used for both front and rear shoulder compounds EMC increases grip potential and improves thermal stability to make sure the tire performance remains consistent as temps go up Tubeless (TL) Blackwall (W) - rated for speeds up to 168+ MPH 120/70ZR17 E OE fitment for Honda CBR1000RR 2017 120/70ZR17 G OE fitment for Suzuki GSX-S750 2017 120/70ZR17 J OE fitment for Yamaha R6 2017 180/55ZR17 G OE fitment for Suzuki GSX-S750 2017 180/55ZR17 J OE fitment for Yamaha R6 2017 190/50ZR17 E OE fitment for Honda CBR1000RR 2017 Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_hypersport_s21_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_hypersport_s21_tires.webp", "https://americaapi.kaafifoods.com/storage/products/bridgestone_battlax_hypersport_front21_tires.webp"]', '{"Wheel Location": "Front", "Type": "STREET BIKE", "Product Type": "Hypersport Dot / Race Tire / Sportbike Tire / Dot Tire", "Make": "Honda", "Model": "Honda CBR600RR / CBR1000RR, Yamaha YZF-R6 / YZF-R1 / MT-07 / MT-09, Kawasaki Ninja 650 / ZX-6R / ZX-10R, Suzuki GSX-R600 / GSX-R1000, BMW S1000RR, Ducati Monster / Panigale", "Tire Size": "120/60ZR17 55W"}', 50, 1, 1, NOW(), NOW());
