INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (361, '157913.0', 'Bridgestone TW41 / TW42 Trail Wing Tires', 'bridgestone-tw41-tw42-trail-wing-tires-157913.0', 'Bridgestone', 1, 'STREET BIKE', 'Dual Road Bias Dot / 70 On Road 30 Off Road / Intermediate Terrain / Hard Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P290809', 120.73, '249.6', '249.6', 'Save up to Save $51.10 20%', 3.2, 6, 'nan', 'nan', 'Front; Rear', 5, '120/90-17; 130/80-17; 120/90-18; 80/100-21; 90/90-21', 5, 'Bridgestone TW41 / TW42 Trail Wing Tires', 'A 4-ply front/rear combination designed primarily for dual sport use Special dimpled tread pattern means many edges, which helps maximize traction Unique front/rear combination provides balanced highway and offroad performance 4-ply construction for long-wearing durability Self-cleaning tread blocks still give a traction edge for muddy and loose terrains DOT approved Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/bridgestone_tw41_tw42_trail_wing_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/bridgestone_tw41_tw42_trail_wing_tires.webp", "https://americaapi.kaafifoods.com/storage/products/bridgestone_tw42_trail_wing_r