INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (362, '10045531.0', 'AMS Pactrax Tires', 'ams-pactrax-tires-10045531.0', 'AMS', 3, 'UTV/ATV', 'Intermediate Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P896801', 64.95, '153.95', '153.95', 'nan', 1.0, 1, 'nan', 'nan', 'Rear; Front', 0, 'nan', 7, 'AMS Pactrax Tires The Pactrax Tires from AMS are an MX quad tire that is designed for use on sport ATVs with racing in mind. The tough six ply bias casing maintains a profile that provides excellent traction while keeping rotating mass low. Steering and cornering control are excellent. A special natural rubber compound is formulated with racing in mind and balances superb traction with extended tread life - making the tire a tenable recreational tire option, as well. The signature Pactrax "X" tread design provides improved forward traction at the rear and braking response at the front.', 'High performance MX sport ATV tire Excellent on groomed surfaces Race formulated compound For recreational or race applications alike X-shaped lug design for excellent response, acceleration and braking Puncture resistant 6 ply bias assembly Lightweight design For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/ams_pactrax_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/ams_pactrax_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "UTV/ATV", "Product Type": "Intermediate Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
