INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (365, '10175116.0', 'Michelin StarCross 6 Sand Tires', 'michelin-starcross-6-sand-tires-10175116.0', 'Michelin Tires', 3, 'DIRT BIKE', 'Dirt Bike Tire / Non Dot Tire / Sand Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P973216', 106.99, '156.95', '156.95', 'Save up to Save $30.96 20%', 4.6, 12, 'nan', 'nan', 'Front; Rear', 3, '100/90-19; 110/90-19; 80/100-21', 3, 'Michelin StarCross 6 Sand Tires The Michelin StarCross 6 Tires use technologies developed in Michelin’s R&D centers and fine tuned on tracks around the world to offer more traction and better durability. These improvements mean that riders can push their bikes to higher performance levels, while at the same time benefitting from longer lasting tire performance. Compared to its predecessor, the StarCross 5, the new StarCross 6 uses technologies developed in Michelin’s R&D centers and fine-tuned on racetracks around the world to offer up to 16 percent more traction and up to 19 percent better durability. These improvements mean that riders can push their bikes to higher performance levels, while at the same time benefitting from longer-lasting tire performance.', 'The Sand tread design is engineered for extremely soft and sandy motocross tracks, like Southwick. Silica technology increases durability up to 20% and maintains tread block integrity over the life of the tire The adaptive design provides up to 15% more traction Tread blocks resist irregular wear for better traction Double ply carcass (2 layers crossed at 90 degrees) Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_star_cross6_sand_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_star_cross6_sand_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Dirt Bike Tire / Non Dot Tire / Sand Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "100/90-19; 110/90-19; 80/100-21"}', 50, 1, 1, NOW(), NOW());
