INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (370, '10203836.0', 'Dunlop K950 Trials Tires', 'dunlop-k950-trials-tires-10203836.0', 'Dunlop', 3, 'DIRT BIKE', 'Dual Onoff Dot / 30 On Road 70 Off Road / Dot Dirt Tires / Hard Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P987220', 97.99, NULL, NULL, 'Save $19.96 17%', 3.5, 2, 'nan', 'nan', 'Rear', 0, 'nan', 1, 'Dunlop K950 Trials Tires The Dunlop K950 Trials Tires are not just for Trials, but can be perfect for your street going enduro as well.', 'Perfect for off-road riders who also enjoy a dose of pavement on their rides and for that the street-legal K950 is ideal Performance that trials riders and off-road enthusiasts are looking for, with additional durability and on-road capability Featuring bias-ply construction, compounds and a tread pattern designed to tackle tough single-track terrain despite challenging conditions In both wet and dry, the K950 excels when the course or trail turns hard-packed, rocky, or littered with tree roots For dual-sport riding, the K950 provides a smoother ride and longer wear than a traditional knobby tire on the street, while still providing a high level of grip and bump-absorbing compliance in the dirt Exceptionally light at only 11.6lbs Tube type DOT approved Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_k950_trials_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_k950_trials_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "Dual Onoff Dot / 30 On Road 70 Off Road / Dot Dirt Tires / Hard Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
