INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (387, '10506516.0', 'Plews Tyres Enduro EN1 Grand Prix Tires', 'plews-tyres-enduro-en1-grand-prix-tires-10506516.0', 'Plews Tyres', 3, 'DIRT BIKE', 'Non Dot Tire / Intermediate Terrain / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1147527', 100.7, '179.99', '179.99', 'Save up to Save $43.14 24%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 2, '140/80-18; 90/100-21', 2, 'Plews Tyres Enduro EN1 Grand Prix Tires Optimized for the rigors of Enduro GP, Sprint Enduros, and Time Card events, the EN1 Grand Prix tire stands out as a top contender on challenging terrain. This tire, crafted with meticulous British engineering and advanced by leading chemists, adheres to FIM standards and exemplifies a harmonious blend of longevity, adherence, and adaptability, vital for competitive off-road racing. Its tread pattern excels in delivering superior traction and surface feedback, incorporating intricate lateral blocks for a reliable grip on intricate paths. With a high silica composition, the EN1 Grand Prix enhances performance on wet surfaces and in cold conditions, as well as on a variety of terrains, solidifying its position as the preferred option for enduro racers in pursuit of excellence.', 'Designed for Enduro GP, Sprint Enduro, Time Card, Hare & Hound, and more FIM-compliant for race legality and peace of mind UK-developed compound blends durability with high grip High silica content for enhanced wet traction and cold-weather performance Detailed lateral block shaping improves bite and control in technical sections Versatile tread pattern optimized for intermediate to hard terrain Comparable to Michelin Medium and Metzeler Enduro Intermediate/Hard tires Built to endure demanding race conditions with precision and reliability', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/plews_tyres_enduro_en1_grand_prix_tires_1800x1800.webp', '["https://americaapi.kaafifoods.com/storage/products/plews_tyres_enduro_en1_grand_prix_tires_1800x1800.webp", "https://americaapi.kaafifoods.com/storage/products/plews_tyres_enduro_en1_grand_prix_tires.webp", "https://americaapi.kaafifoods.com/storage/products/plews_tyres_enduro_en1_grand_prix_enduro_front.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Non Dot Tire / Intermediate Terrain / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "140/80-18; 90/100-21"}', 50, 1, 1, NOW(), NOW());
