INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (392, '10354913.0', 'Maxxis Maxxcross MX-IH Tires', 'maxxis-maxxcross-mx-ih-tires-10354913.0', 'Maxxis Tires', 3, 'DIRT BIKE', 'Off Highway Non Dot Inc / Dirt Bike Tire / Non Dot Tire / Intermediate Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1072922', 57.0, '130.11', '130.11', 'nan', 4.8, 12, 'nan', 'nan', 'Front; Rear', 8, '90/100-16; 110/100-18; 120/90-18; 70/100-19; 110/90-19; 120/80-19; 120/90-19; 80/100-21', 8, 'Maxxis Maxxcross MX-IH Tires The Maxxcross MX-IH, a result of collaboration with 7X Supercross champion Jeremy McGrath, signifies the pinnacle of Maxxis tire innovation. With a fresh tread pattern, advanced compound, and precise engineering tailored for Pro Motocross and Supercross racing on demanding intermediate-to-hard terrains, the MX-IH delivers stability, predictability, and superior traction. Whether you''re a weekend warrior or a pro racer, this purpose-built tire excels on challenging terrain, ensuring consistent performance in cornering, acceleration, and braking, instilling racers with unwavering confidence. Its meticulously tuned tread compound and pattern provide extreme predictability in straight-line zones, establishing the MX-IH as the ultimate choice for off-road racing excellence.', 'Intermediate-hard terrain tread compound and pattern Predictable performance in straight line acceleration and braking zones Directional front tread pattern Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/maxxis_tires_tire_maxxcross_mx_ih66_m_bias_tt_1800x1800.webp', '["https://americaapi.kaafifoods.com/storage/products/maxxis_tires_tire_maxxcross_mx_ih66_m_bias_tt_1800x1800.webp", "https://americaapi.kaafifoods.com/storage/products/maxxis_tires_tire_maxxcross_mx_ih66_m_bias_tt.webp", "https://americaapi.kaafifoods.com/storage/products/maxxis_maxxcross_mxih_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Off Highway Non Dot Inc / Dirt Bike Tire / Non Dot Tire / Intermediate Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "90/100-16; 110/100-18; 120/90-18; 70/100-19; 110/90-19; 120/80-19; 120/90-19; 80/100-21"}', 50, 1, 1, NOW(), NOW());
