INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (411, '1791002.0', 'Michelin StarCross 5 Soft Terrain Tires', 'michelin-starcross-5-soft-terrain-tires-1791002.0', 'Michelin Tires', 3, 'DIRT BIKE', 'Off Highway Non Dot Inc / Soft Terrain / Dirt Bike Tire / Non Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P315707', 64.99, '159.98', '159.98', 'Save up to Save $18.59 12%', 3.9, 9, 'nan', 'nan', 'Front; Rear', 8, '90/100-14; 90/100-16; 70/100-17; 100/100-18; 70/100-19; 100/90-19; 110/90-19; 120/80-19', 8, 'Michelin StarCross 5 Soft Terrain Tires The Michelin StarCross 5 tires were designed based on feedback from riders of all levels, from amateurs to world champions, often riding in extreme conditions. Compared to its predecessors the Michelin StarCross 5 delivers several significant performance improvements and breaks new ground for Michelin in the world of Off-Road/Motocross tires. The new design incorporates stronger, higher density materials that reduce weight by up to 15% over previous versions - without compromising strength or durability. Unique construction techniques provide exceptional shock absorption that reduces rider fatigue. Michelin''s "M ud-phobic Bars" maximize cleaning capability to prevent mud and dirt from building up between tread blocks. Staggered intermediate knobbies along the side of the carcass create communicating handling and traction at all degrees of lean angle.', 'Experienced motocross rider or occasional rider riding motocross for fun, StarCross 5 is the high-performance motocross tire designed to allow you to face any terrain Tested and approved by riders from pros to occasional motocross rider Designed to give the ultimate performance Adapted to each type of terrain, bike and use Larger size range for a wider scope of usage including new sizes designed for cross-country Blackwall Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_star_cross5_soft_terrain_tires_front.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_star_cross5_soft_terrain_tires_front.webp", "https://americaapi.kaafifoods.com/storage/products/michelin_star_cross5_soft_terrain_tires_rear.webp", "https://americaapi.kaafifoods.com/storage/products/michelin_star_cross_mini_tires.webp", "https://americaapi.kaafifoods.com/storage/products/michelin_starcross_soft_terrain_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Off Highway Non Dot Inc / Soft Terrain / Dirt Bike Tire / Non Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "90/100-14; 90/100-16; 70/100-17; 100/100-18; 70/100-19; 100/90-19; 110/90-19; 120/80-19"}', 50, 1, 1, NOW(), NOW());
