INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (424, '10386932.0', 'Mitas Enduro Trail XT Dakar Tires', 'mitas-enduro-trail-xt-dakar-tires-10386932.0', 'Mitas', 3, 'DIRT BIKE', '30 On Road 70 Off Road / Dot Dirt Tires / Dirt Bike Tire / Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1087820', 182.25, '257.99', '257.99', 'Save up to Save $47.40 18%', 3.9, 7, 'nan', 'nan', 'Rear', 5, '140/80B17 69H; 150/70B17 69H; 170/60B17 72H; 140/80B18 70H; 150/70B18 70H', 5, 'Mitas Enduro Trail XT Dakar Tires The Mitas Enduro Trail XT Dakar Tires address the needs of riders seeking authentic off-road performance with the flexibility to navigate the tarmac on their journey home. Derived from the original E-10 ADV product line, the XT Rear tire boasts a block-style tread pattern paired with a wide footprint profile, ensuring on-road stability during all adventures.', 'The XT is designed for 30% on-road / 70% off-road use on Adventure and Dual Sport motorcycles All XT tires approved for TL (Tubeless) and TT (Tube Type) applications Rear fitment options from full sized ADV bikes down to single cylinder Dual Sport machines Ideal fitment when combined with the XT+ or Rally front tires ADV specific tire profile with block style knob pattern for off-road performance DOT approved Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_xt_dakar_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_xt_dakar_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "30 On Road 70 Off Road / Dot Dirt Tires / Dirt Bike Tire / Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "140/80B17 69H; 150/70B17 69H; 170/60B17 72H; 140/80B18 70H; 150/70B18 70H"}', 50, 1, 1, NOW(), NOW());
