INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (437, '10049408.0', 'BF Goodrich Mud-Terrain T/A KM3 Tires', 'bf-goodrich-mud-terrain-t-a-km3-tires-10049408.0', 'BF Goodrich', 3, 'UTV/ATV', 'Mud Tire / Utv Atv Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P898940', 265.16, '503.95', '503.95', 'nan', 5.0, 1, 'nan', 'nan', 'nan', 0, 'nan', 12, 'BF Goodrich Mud-Terrain T/A KM3 Tires The BF Goodrich Mud-Terrain KM3s are designed for grip in mud and loose soil. The "Terrain-Attack" tread design uses massive tread lugs that are positioned to achieve traction at any angle of approach. Along with the reinforced lugs are mud phobic bars that help the tire release compacted mud for enhanced traction. BFG formulates the softer "Built to Climb" or Krawl-TEK rubber compound specifically for UTV applications - enhancing grip over rock and slick surfaces. Designed to conquer the toughest terrain, these tires are constructed with extreme sidewall protection, shock resistance and chip-and-tear resistance on gravel. The CoreGuard Max race proven technology helps prevent splitting or puncturing with increased thickness that protects critical sidewall failure.', 'Mud-terrain tire with light truck-inspired design UTV-specific tread compound 8 ply radial construction BF Goodrich "Traction Advantage" Notched shoulder design for grip in mud and soft soil Mud phobic bars release packed mud Advanced deflection design protects sidewall Designed for excellent low PSI flex Not DOT approved For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/bf_goodrich_mud_terrain_takm3_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/bf_goodrich_mud_terrain_takm3_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Mud Tire / Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
