INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (441, '10049766.0', 'System 3 Off-Road XT400 Tires', 'system-3-off-road-xt400-tires-10049766.0', 'System 3 Off-Road', 3, 'UTV/ATV', 'Utv Atv Tire / Mud Tire / Soft Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P899134', 264.6, '589.24', '589.24', 'Save up to Save $59.14 10%', 4.0, 1, 'nan', 'nan', 'nan', 0, 'nan', 11, 'System 3 Off-Road XT400 Tires The System 3 Off-Road XT400 Tire is specifically designed for riders who demand exceptional performance in muddy and trail conditions. This tire is a hybrid, incorporating the outstanding qualities of the XTR370 and XM310 series. The design features a wide, square footprint with deep, dual-stage lugs that excel in providing traction over both loose surfaces and rocky terrain. The advanced tread pattern derives its versatility from a ten-ply radial carcass, prized for its durability and flexibility. Additionally, the tire includes a substantial, reinforced rim guard that aids in protecting against flats while traversing challenging trails.', 'Mud-trail hybrid for extreme trail traction Advanced 10 ply radial construction Multi-stage center lugs Super aggressive shoulder lugs Deep rim guard Tires up to 33": 1.25" to 1.5" tread depth Tires 35" and larger: 1.5" to 2" tread depth For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/system3_off_road_xt400_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/system3_off_road_xt400_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Mud Tire / Soft Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
