INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (449, '10036282.0', 'Duro DI-K167A Front Tires', 'duro-di-k167a-front-tires-10036282.0', 'nan', 3, 'UTV/ATV', 'Non Dot Tire / Intermediate Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P893602', 129.52, NULL, NULL, 'Save $28.43 18%', 5.0, 1, 'nan', 'nan', 'Front', 0, 'nan', 1, 'Duro DI-K167A Front Tires The DIK167A Tires from Duro are a knobby MX-style front tire with four ply bias construction. The directional tread pattern offers good grip over a variety of terrain.', 'All-terrain MX tread pattern Directional design 4 ply bias construction Extended tread life over many OE tires Matching tread design with Duro DI-K567A rear tires For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/duro_dik167_a_front_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/duro_dik167_a_front_tires.webp"]', '{"Wheel Location": "Front", "Type": "UTV/ATV", "Product Type": "Non Dot Tire / Intermediate Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
