INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (450, '10049448.0', 'GMZ Sand Stripper HP Rear Tires', 'gmz-sand-stripper-hp-rear-tires-10049448.0', 'GMZ Race Products', 3, 'UTV/ATV', 'Sand Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P898985', 248.0, '366.0', '366.0', 'nan', 5.0, 1, 'nan', 'nan', 'Rear', 0, 'nan', 3, 'GMZ Sand Stripper HP Rear Tires For the sand and dune enthusiasts of the world, GMZ Race Products presents the Sand Stripper line of performance tires. Front or rear, Sand Stripper Tires feature an extra wide footprint that provides maximum flotation and smooth dune transitions. Thick rim guards protect the wheel lip and seal the bead from sand intrusion. Bias-ply construction in two, four, and six-ply variants delivers good durability while keeping weight savings at the forefront. Sand Stripper Staggered HP Rear Tires are designed for machines with high RPM power delivery / reduced low RPM torque. The staggered paddle design allows for some calculated tire slippage in the sand - helping your rig get into its powerband before hooking up completely. Speed builds as the tire regains traction. The staggered cut design is excellent for peaky two-strokes and smaller displacement rigs with lower overall power output. Paddles are positioned in a staggered pattern, running partially across the tire''s width. The fourteen paddles design uses a six-ply bias construction to maintain their form and contact patch when harnessing high RPM power.', 'Full-service sand and dune tire 32" tires are rated to handle up to 240 horsepower Designed for rear wheel applications 28.5mm paddle depth on 28" tire 25.4mm paddle depth on 30" tire 22.2mm paddle depth on 32" tire 14 or 16 paddle variations Excellent floatation and smooth transitions Thick rim guard keeps sand out of bead and protects rim 6 ply bias construction on 28" and 30" versions 4 ply bias construction on 32" version For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/gmz_sand_stripper_hp_rear_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/gmz_sand_stripper_hp_rear_tires.webp"]', '{"Wheel Location": "Rear", "Type": "UTV/ATV", "Product Type": "Sand Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
