INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (451, '10033506.0', 'Kenda K3203 Mastodon AT Tires', 'kenda-k3203-mastodon-at-tires-10033506.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Soft Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P892494', 132.26, '298.95', '298.95', 'Save up to Save $29.85 10%', 5.0, 1, 'nan', 'nan', 'Front; Front/Rear; Rear', 0, 'nan', 11, 'Kenda K3203 Mastodon AT Tires The Kenda K3203 Mastodon AT Tires are your new favorite UTV all-terrain tires. Engineered to deliver as a true "do-it-all" option, the Mastodon AT Tires sport a very aggressive open tread design for good clean-out performance in muddy conditions. The large contact patch and HD radial design offer superior traction and durability on harder packed surfaces. DOT certification extends the list of territories where theses Mastodons can roam.', 'All-terrain (AT) is the ultimate “do-it-all” tire 8-ply rated, heavy-duty radial construction Aggressive, open lug design for good clean-out in mud Large contact patch on harder ground conditions for superior traction and durability', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/kenda_k3203_mastodon_at_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/kenda_k3203_mastodon_at_tires.webp"]', '{"Wheel Location": "Front; Front/Rear; Rear", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Soft Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
