INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (453, '10032776.0', 'Maxxis Razr Plus MX Tires', 'maxxis-razr-plus-mx-tires-10032776.0', 'Maxxis Tires', 3, 'UTV/ATV', 'Hard Terrain / Utv Atv Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P891862', 142.49, '169.99', '169.99', 'Save up to Save $8.50 5%', 5.0, 1, 'nan', 'nan', 'Front; Rear', 0, 'nan', 2, 'Maxxis Razr Plus MX Tires The RAZR Plus MX Tires from Maxxis are built to win championships at the highest levels of ATV MX racing. Tested and developed with ATV Motocross champions Joel Hetrick and Chad Wienen, the RAZR Plus MX Tires have passed the ultimate test: helping each rider take championship titles between 2018 and 2020. Achieve your own championship goals with the performance and confidence of the RAZR Plus MX Tires. With an all-terrain tread pattern and 4-ply radial construction, these tires deliver a smooth ride over rough trails. They''re perfect for off-highway use, providing reliable performance in tough conditions.', 'Designed for cross country, hard pack and intermediate terrain Excels on highway and motocross surfaces Aggressive tread design featuring angled shoulder knobs for improved steering and braking Carcass construction and tread pattern provide unmatched straight-line acceleration Lightweight 4 ply rated carcass built for performance on any track Shoulder knobs offer even more predictable sliding capabilities For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/maxxis_razr_plus_mx_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/maxxis_razr_plus_mx_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "UTV/ATV", "Product Type": "Hard Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
