INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (465, '10354921.0', 'Maxxis Maxxcross MX-SI Tires', 'maxxis-maxxcross-mx-si-tires-10354921.0', 'Maxxis Tires', 3, 'DIRT BIKE', 'Off Highway Non Dot Inc / Non Dot Tire / Dirt Bike Tire / Intermediate Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1072924', 52.0, '121.0', '121.0', 'nan', 5.0, 1, 'nan', 'nan', 'Rear; Front', 6, '90/100-14; 70/100-17; 110/100-18; 110/90-19; 120/80-19; 80/100-21', 6, 'Maxxis Maxxcross MX-SI Tires The Maxxcross MX-SI, a recent addition to Maxxis''s MX lineup, enhances soft-to-intermediate motocross performance. Developed with 7X Supercross champion Jeremy McGrath, this tire ensures superior traction in rough conditions, boosting rider confidence on varying terrains. Its redesigned tread pattern and compound optimize corner exit traction, efficiently transferring power on softer terrain. Additionally, the front tire features a new tread pattern and carcass design, enhancing lean angle grip, predictability, and stability, marking a significant advancement in motocross tire technology.', 'Intermediate-soft terrain compound and tread pattern Tread design provides confidence and stability in a variety of terrains Perfect for intermediate and loamy tracks or trails Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/maxxis_tires_tire_maxxcross_mx_si63_m_bias_tt_1800x1800.webp', '["https://americaapi.kaafifoods.com/storage/products/maxxis_tires_tire_maxxcross_mx_si63_m_bias_tt_1800x1800.webp", "https://americaapi.kaafifoods.com/storage/products/maxxis_tires_tire_maxxcross_mx_si63_m_bias_tt.webp", "https://americaapi.kaafifoods.com/storage/products/maxxis_maxxcross_mxsi_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "DIRT BIKE", "Product Type": "Off Highway Non Dot Inc / Non Dot Tire / Dirt Bike Tire / Intermediate Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "90/100-14; 70/100-17; 110/100-18; 110/90-19; 120/80-19; 80/100-21"}', 50, 1, 1, NOW(), NOW());
