INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (468, '10042495.0', 'Kenda K7102 Washougal III Tire', 'kenda-k7102-washougal-iii-tire-10042495.0', 'nan', 3, 'DIRT BIKE', 'Non Dot Tire / Soft Terrain / Hard Terrain / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P895577', 37.55, '97.99', '97.99', 'Save up to Save $9.11 9%', 3.0, 1, 'nan', 'nan', 'Front', 7, '60/100-10 33J; 60/100-12 33J; 60/100-14 30M; 70/100-17 40M; 70/100-19 42M; 80/100-21 51M; 90/100-21 57M', 7, 'Kenda K7102 Washougal III Tire The K7102 Washougal III tire is the first to feature Kenda''s Advanced Apex technology for increased lateral response and optimal carcass stiffness. It features an all-new tread design that allows for faster forward roll, increased side bite and controlled flex without washing out. Unique sipe / groove orientation provide linear cornering characteristics as well as superb braking control.', 'Deepest front tread in the Kenda off-road lineup Medium compound density Specifically developed carcass for lighter, more responsive feel Scooped side knobs for the most advanced side biting tire on the market Intermediate tread pattern, for a wide variety of terrain Circumferential sipes in shoulder knobs for better cornering control and feedback Kenda’s most advanced casing construction for better lateral response Chaffered intermediate knob edges for better rolling leading edge and better braking trailing edge Radial groove in center block plus scooped trailing edges give better braking control, feedback and stability Larger footprint than previous generation for better grip in all conditions Tread pattern allows for maximum efficiency in a wide variety of terrains and conditions Triangular shaped knobs to reduce knob flex on hard base areas Designed to meet the demands of intermediate terrains Casing structure includes reinforced sidewalls FIM-approved Tube Type 4 ply, bias construction (all sizes) Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/kenda_k7102_washougal_iii_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/kenda_k7102_washougal_iii_tire.webp"]', '{"Wheel Location": "Front", "Type": "DIRT BIKE", "Product Type": "Non Dot Tire / Soft Terrain / Hard Terrain / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "60/100-10 33J; 60/100-12 33J; 60/100-14 30M; 70/100-17 40M; 70/100-19 42M; 80/100-21 51M; 90/100-21 57M"}', 50, 1, 1, NOW(), NOW());
