INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (479, '10253112.0', 'EFX MotoSlayer Tires', 'efx-motoslayer-tires-10253112.0', 'EFX Tires', 3, 'UTV/ATV', 'Utv Atv Tire / Mud Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1018213', 210.0, '435.0', '435.0', 'nan', 3.0, 2, 'nan', 'nan', 'nan', 0, 'nan', 10, 'EFX Tires MotoSlayer Tire Make the elements dread the tread with the all-new EFX MotoSlayer. Owning up to its namesake, the MotoSlayer shows no mercy while brutalizing the mud pits and its competition along the way. Neurotically engineered to be the most capable mud tire in the industry, the MotoSlayer boasts an updated checkmark tread design built for ample tracking in forward and reverse. Rest assured all your off-road antics will remain unimpaired with EFX’s puncture resistant sidewalls and alternating 1.5”-2” lugs resulting in a capable and comfortable ride. Unleash the MotoSlayer!', '6-ply construction Alternating 1.5" and 2" lugs resulting in a capable and comfortable ride Puncture-resistant sidewalls Updated checkmark tread design for traction in forward and reverse', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/efx_tires_moto_slayer_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/efx_tires_moto_slayer_tire.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Mud Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
