INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (480, '10313104.0', 'Tensor Desert Series Race Tires', 'tensor-desert-series-race-tires-10313104.0', 'nan', 4, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain / Soft Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1026424', 419.0, '620.0', '620.0', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 7, 'Tensor Tire Desert Series Race Tire Looking for the best competition-legal UTV race tire? Look no further than the Desert Race Series (DSR) Tire from Tensor. Specifically designed for motorsports UTVs, the Tensor Desert Series Tire is the lightest high-performance tire available, with countless race wins to back it up. Weighing in as low as 39.2 pounds, the DSR offers maximum weight savings with race proven technology that''s built for those who demand the best.', 'Patented, American-Made race tire developed specifically for competition Superior steering response and decreased braking distance from flatter tread contact patch Unique weight-optimized ribbed protection for puncture prone upper sidewalls Proprietary nylon bias ply with fiberglass belted construction saves weight over steel Increased number of biting edges for quick acceleration 1600 lb. load rating', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/tensor_tire_desert_series_race.webp', '["https://americaapi.kaafifoods.com/storage/products/tensor_tire_desert_series_race.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain / Soft Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
