INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (485, '10041264.0', 'ITP Versa Cross V3 Tires', 'itp-versa-cross-v3-tires-10041264.0', 'nan', 3, 'UTV/ATV', 'Intermediate Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P895121', 280.36, '568.99', '568.99', 'Save up to Save $228.06 40%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 6, 'ITP Versa Cross V3 DOT Tires The ITP Versa Cross V3 Tire offers performance on hard pack and intermediate terrain. With an enhanced tread pattern and eight ply rated radial construction, the Versa Cross V3 is designed for high performance UTV applications. On low profile sizes, shoulder lugs enhanced with unique contouring and channel cuts promote easier, lower resistance steering. This DOT rated tire has been approved for on highway use. Additional sizes of the Versa Cross V3 are available without the DOT rating (NHS).', 'Designed for hard pack and intermediate surfaces 8 ply construction Light truck-inspired extreme-terrain tread pattern Shoulder lugs enhanced with contour changes and channel cuts to promote ease of steering on low profile sizes Increases traction in slick and rutted conditions Additional channel cuts to improve traction on slick rock and on wet, muddy surfaces Deep rim guard designed to protect the rim lip on aftermarket wheels Reinforced belts provide increased traction and improved puncture resistance "Tough Tread” rubber compound protects against cuts, chips and tread wear 3/4" lug depth Made in USA', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/itp_versa_cross_v3_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/itp_versa_cross_v3_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Intermediate Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
