INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (486, '10253014.0', 'EFX Sandslinger Tires', 'efx-sandslinger-tires-10253014.0', 'EFX Tires', 3, 'UTV/ATV', 'Utv Atv Tire / Sand Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1018122', 301.0, NULL, NULL, 'nan', 4.8, 12, 'nan', 'nan', 'Front; Rear', 0, 'nan', 2, 'EFX Tires Sandslinger Tire After investing a couple hundred bucks into high quality sunscreen, snagging a couple of high-powered test machines and a band of misfit test riders, EFX took to the dunes to hand craft the best performing UTV sand tire. Because their test offices are located in Colorado, they have their pick of some amazing terrain right at home or awesome dunes just over the Utah border. After numerous edits, upgrades, and modifications they nailed the tire all UTV riders have been waiting for.', '4-ply construction 14 lug rear paddle design Optimized for float, balanced grip and superior power from a complete stop', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/efx_tires_sandslinger_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/efx_tires_sandslinger_tire.webp"]', '{"Wheel Location": "Front; Rear", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Sand Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
