INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (488, '10048674.0', 'CST Lobo RC Tires', 'cst-lobo-rc-tires-10048674.0', 'nan', 3, 'UTV/ATV', 'Hard Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P898333', 257.4, '338.0', '338.0', 'Save up to Save $54.05 16%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 3, 'CST Lobo RC Tires "RC" stands for "Rock Crawling" with CST''s Lobo RC Tires. The Lobo RC keeps the fast rolling center tread and high speed stability of the standard CST Lobo Tire but dials-up the off-road ability with bigger tread lugs at the shoulder. Designed with traction over rocks and hard edges in mind, this RC version sports a softer, grippier rubber compound than the standard Lobo. The radial construction comes in a variety of plies to balance durability and lightweight. The Lobo RC tire is engineered with full size, big output desert rigs in mind. For a tire with further reduced weight that is designed for high speed stability without the emphasis on rock crawling, consider the standard CST Lobo.', 'Easy-rolling all-terrain tire designed for high speed stability Softer rubber compound for traction over rock Excels on hard and intermediate surfaces Aggressive, square shoulder lugs designed for grip over rocks and roots 6 ply, 8 ply and 9 ply radial construction Crisp, responsive steering For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/cst_lobo_rc_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/cst_lobo_rc_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Hard Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
