INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (492, '10032730.0', 'Maxxis MU9C Coronado Tires', 'maxxis-mu9c-coronado-tires-10032730.0', 'Maxxis Tires', 3, 'UTV/ATV', 'Soft Terrain / Utv Atv Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P891851', 233.7, '384.95', '384.95', 'Save up to Save $19.25 5%', 4.8, 12, 'nan', 'nan', 'Front; Front/Rear; Rear', 0, 'nan', 10, 'Maxxis MU9C Coronado Tires Designed for high speeds and high temperatures, the MU9C Coronado Tires from Maxxis are the ultimate desert tire for your ATV or side-by-side. An eight ply carcass and aggressive tread pattern allow the Coronado Tires to serve double-duty against brutal rocks and thorns or function equally well against chores and ho-hum utility miles. Whether you are running backcountry trails or national races, the MU9C Coronado Tires deliver a smooth ride stemming from true radial construction and a center tread configuration with a high land-to-sea ratio of lugs. Tread compounds offer supreme performance and longevity. The stepped side lugs and a long-wearing rubber formulation optimize grip on loose-over-hard desert terrains.', 'Designed for desert and rocky terrain Excels on hard pack and intermediate surfaces 8 ply radial construction resists punctures High weight capacity for utility needs Performance-matched front and rear setup provides steering control and confidence at high speeds Aggressive tread pattern extends well over the shoulder area for increased sidewall protection Stepped lugs to provide multiple biting edges Rounded front tire edges boost steering feel and traction For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/maxxis_mu9_c_coronado_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/maxxis_mu9_c_coronado_tires.webp"]', '{"Wheel Location": "Front; Front/Rear; Rear", "Type": "UTV/ATV", "Product Type": "Soft Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
