INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (493, '10041374.0', 'ITP Cryptid Tires', 'itp-cryptid-tires-10041374.0', 'nan', 3, 'UTV/ATV', 'Mud Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P895165', 261.41, '444.99', '444.99', 'Save up to Save $82.83 19%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 10, 'ITP Cryptid Tires The Cryptid Tires from ITP are an extreme mud tire with a paddle-like chevron tread configuration for maximum side bite. The Cryptid Tire specializes in conquering the gnarliest muck. They''re real swamp monsters that feature mud-churning performance, unmatched tread size and trail versatility. The chevron pattern allows the Cryptid Tires to climb in and out of the mud without compromising ride comfort on trails and hard pack. They also excel in snow.', 'Extreme mud tire with chevron-shaped paddles Ultra deep lug depth Good performance in snow Maximum side bite for climbing in and out of the mud without compromising ride comfort on trails and hard pack Grooved center lugs to channel away mud and debris and a super durable rubber compound to protect against abrasions, chips and cuts Unparalleled forward traction Graduated lug height: 1.5" at center growing to 2" at the shoulder 6 ply rated bias construction Made in the USA For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/itp_cryptid_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/itp_cryptid_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Mud Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
