INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (500, '10476859.0', 'EFX MotoCrusher Tires', 'efx-motocrusher-tires-10476859.0', 'EFX Tires', 3, 'UTV/ATV', 'Soft Terrain / Intermediate Terrain / Hard Terrain / Utv Atv Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1130574', 314.0, '445.0', '445.0', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 7, 'EFX Tires MotoCrusher Tire The EFX MotoCrusher tire is engineered to dominate any terrain with ease. Built with an 8-ply radial construction and a proprietary competition-grade compound, it offers exceptional softness, grip, and adaptability for off-road adventures. Featuring a flexible reinforced sidewall for low-pressure applications and advanced siping for enhanced traction, the MotoCrusher lives up to its name. Its alternating side lugs deliver outstanding control in deep ruts, while the balanced tread depth ensures optimal self-cleaning for peak performance.', '8-ply radial construction 22" Tread depth Speed Rating: M Made from a proprietary competition-grade compound Flexible reinforced sidewall for low-pressure applications Advanced siping for increased traction Alternating side lugs Specifications: 32x10R14 - 48.24 lbs / 760 Load Rating 32x10R15 - 49.12 lbs / 760 Load Rating 33x10R15 - 52.65 lbs / 760 Load Rating 35x10R15 - 56.77 lbs / 785 Load Rating 37x10R15 - 63.92 lbs / 935 Load Rating 37x10R18 - 60.63 lbs / 880 Load Rating 40x10R18 - 70.28 lbs / 1020 Load Rating', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/efx_tires_motocrusher32_x1000_r148_ply321014.webp', '["https://americaapi.kaafifoods.com/storage/products/efx_tires_motocrusher32_x1000_r148_ply321014.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Soft Terrain / Intermediate Terrain / Hard Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
