INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (501, '10303573.0', 'Tensor Sand Series Tires', 'tensor-sand-series-tires-10303573.0', 'nan', 3, 'UTV/ATV', 'Sand Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1046790', 329.0, '384.0', '384.0', 'nan', 4.8, 12, 'nan', 'nan', 'Rear; Front', 0, 'nan', 2, 'Tensor Sand Series Tires The Sand Series Tires from Tensor Tire are race-built tires aimed squarely at UTV sand racing. Available in both bias and radial construction, all versions of the Sand Tire use two ply construction with reinforced sidewalls for excellent puncture resistance. These rigid tires are designed with high horsepower, full size UTVs and have the load capacity to match. The Sand Series Tires keep steering response sharp, braking distances short and accelerative grip strong. Bias ply models use a proprietary fiberglass belted construction.', 'Developed specifically for modern high-performance machines Lightweight 2 ply bias construction reduces rotating mass for maximum power delivery 33" tall tire provides added ground clearance for increased vehicle capability Patent-pending Velocity Grid design provides added biting edges for superior handling and acceleration Less drag and rolling resistance with decreased weight from incorporated Velocity GridT pattern Front tire features dual apex turning ribs to provide exceptional steering response Rear tire features 14 paddles optimized with a 1" height for maximum performance.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/tensor_sand_series_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/tensor_sand_series_tires.webp", "https://americaapi.kaafifoods.com/storage/products/tensor_sand_series_tires_front.webp"]', '{"Wheel Location": "Rear; Front", "Type": "UTV/ATV", "Product Type": "Sand Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
