INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (504, '10620477.0', 'System 3 Off-Road XT400W Tires', 'system-3-off-road-xt400w-tires-10620477.0', 'System 3 Off-Road', 3, 'UTV/ATV', 'Mud Tire / Non Dot Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1198433', 347.79, NULL, NULL, 'Save $38.64 10%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 1, 'System 3 Off-Road XT400W Tires The System 3 Off-Road XT400W Tire is designed for riders seeking reliable traction across mud, rocks, and challenging trails. Its full-width tread showcases deep dual-stage lugs and aggressive shoulder blocks that enhance grip significantly. Constructed with a 10-ply radial design, it ensures both strength and comfort during rides. The deep rim guard serves as an added layer of protection against impacts and punctures, equipping the XT400W for rigorous off-road experiences.', '"W" features a full 12" tread Deeper 1.625" - 2.50" deep 2-stage lugs Mud-trail hybrid for extreme trail traction Advanced 10 ply radial construction Multi-stage center lugs Super aggressive shoulder lugs Deep rim guard For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/system3_off_road_xt400_w_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/system3_off_road_xt400_w_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Mud Tire / Non Dot Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
