', '["https://americaapi.kaafifoods.com/storage/products/maxxis_bighorn_radial_tires.webp"]', '{"Wheel Location": "Front; Front/Rear; Rear", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
