INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (509, '10426450.0', 'System 3 Off-Road RC500S "Sticky" Tires', 'system-3-off-road-rc500s-sticky-tires-10426450.0', 'System 3 Off-Road', 3, 'UTV/ATV', 'Hard Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1104845', 309.77, '467.12', '467.12', 'Save up to Save $46.82 10%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 4, 'System 3 Off-Road RC500S "Sticky" Tire The product presents a tire featuring deep interlocking tread blocks that range from 0.65 to 1.0 inches in depth, paired with optimal voids for trail superiority. Its design ensures enhanced grip due to wider spaced, staggered tread blocks adept for traversing loose surfaces. Engineered with a "Sticky Compound," the blend of a proprietary soft tread on a flexible 8-ply rated carcass positions it as a leading choice for rock crawling endeavors. The inventive combination of soft compound and carcass crafts a new benchmark in slick surface traction. Furthermore, the innovative carcass construction enhances ride quality and offers exceptional stability across a variety of terrains, both loose and compacted. The tire also boasts a super deep rim guard to shield wheel lips and aid in the prevention of pinch flats at reduced air pressures.', 'Deep .65” - 1.0” inter-locking tread blocks and optimal void excels on the trails while the wider spaced, staggered tread blocks grip in the loose terrain “S” or “sticky compound” features a combination of our proprietary soft tread compound and flexible 8-ply rated carcass which results in one of the best rock crawling tires on the market The soft compound and carcass flotation set a new standard in slick surface traction The new carcass maximizes ride quality and the trackability is unmatched on loose or hard pack terrains Super deep rim guard protects wheel lips and helps avoid pinch flats at lower psi', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/system3_off_road_rc500_s_sticky_tire_1800x1800.webp', '["https://americaapi.kaafifoods.com/storage/products/system3_off_road_rc500_s_sticky_tire_1800x1800.webp", "https://americaapi.kaafifoods.com/storage/products/system3_off_road_rc500_s_sticky_tire.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Hard Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
