INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (511, '10046942.0', 'Michelin Desert Race Baja Tires', 'michelin-desert-race-baja-tires-10046942.0', 'Michelin Tires', 4, 'DIRT BIKE', 'Dirt Bike Tire / Intermediate Terrain / Soft Terrain / Sand Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P897485', 306.99, NULL, NULL, 'Save $54.96 15%', 4.8, 12, 'nan', 'nan', 'Rear', 1, '140/80-18', 1, 'Michelin Desert Race Baja Tires Racing born and desert bred, the Desert Race Baja tires from Michelin were developed alongside KTM and Husqvarna rally teams. Michelin combined the same proven Desert Race compound from the original Desert Race tires with a new tread pattern (with more void ratio) and a new softer architecture to provide better grip and stronger support when riding in deep, soft ground conditions.', 'Improved tread pattern with more void ratio New softer architecture Highly proven Michelin Desert Race compound More grip and better support in deep, soft ground V-shaped central knobs on front tires provide maximum traction in deep sand 500g lighter than original Desert Race tires Michelin Desert Bib Mousse (M02) optimized', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/michelin_desert_race_baja_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/michelin_desert_race_baja_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "Dirt Bike Tire / Intermediate Terrain / Soft Terrain / Sand Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "140/80-18"}', 50, 1, 1, NOW(), NOW());
