INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (514, '10475264.0', 'ITP Tenacity XSR Tires', 'itp-tenacity-xsr-tires-10475264.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P895542', 305.43, '361.38', '361.38', 'Save up to Save $52.45 15%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 4, 'ITP Tenacity XSR Tires The Tenacity XSR Tire by ITP stands as a testament to advanced engineering for peak performance across desert, gravel, and sand. Designed with an emphasis on high-speed stability, this tire features a 10-ply radial construction inspired by light truck designs, catering specifically to the demands of extreme riders and competitors. The addition of steel-belted radial technology marks ITP''s inaugural venture into this robust category. The tire''s rigid body ply structure enhances steering precision and feedback, ensuring a confident and responsive ride in challenging terrains.', 'All-terrain light truck design for desert, hard pack, intermediate and loose surfaces Specifically designed for desert, gravel, rock and sandy terrain High-performance 10 ply radial construction Computer-aided, non-directional tread pattern Revised chain type tread pattern increases traction in loose terrain Staggered shoulder blocks ensure consistent traction New rubber compound effectively balances traction and tread life ITP’s first steel-belted radial design tailored for the extreme rider/competitor Reinforced steel belts offer improved puncture resistance and confidence-inspiring high-speed stability A more rigid body ply construction method provides crisp steering response', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/itp_tenacity_xsr_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/itp_tenacity_xsr_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
