INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (517, '10589654.0', 'ITP Tires Savage XT Tire', 'itp-tires-savage-xt-tire-10589654.0', 'nan', 3, 'UTV/ATV', 'Hard Terrain / Non Dot Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1186762', 321.92, '475.23', '475.23', 'Save up to Save $50.38 11%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 9, 'ITP Tires Savage XT Tire The ITP Savage XT Tire confidently supports the increased weight and power of modern high-performance UTVs. Designed with an assertive all-terrain tread, it ensures reliable traction through mud, rocks, and compacted terrains, offering the rider command in diverse conditions. Featuring an 8-ply radial structure, it not only delivers a comfortable ride but also resists punctures effectively. Stout sidewalls bolstered with a protective rim guard shield against harsh impacts and trail hazards. It arrives in RG2 and Hyper Adhesion compounds to meet the expectations of riders seeking persistent grip and high resilience through their adventures.', 'Engineered to support the heavier demands of today''s larger, more powerful UTVs Aggressive All Terrain pattern designed to excel in a wide variety of terrain, including mud, rocks and hard pack 8-ply Durable 8PR radial construction Reinforced sidewall and aggressive shoulder design Protective rim guard Available in two compounds - RG2 (soft) and all new super sticky (Hyper-Adhesion Rubber Compound Tread Depth: 24 Weight: 45.5 lb. - 63 lb. Hand crafted in the USA Sold each', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/itp_tires_savage_xt_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/itp_tires_savage_xt_tire.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Hard Terrain / Non Dot Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
