INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (518, '10431076.0', 'Sedona Trail Saw 2.0 Tires', 'sedona-trail-saw-2-0-tires-10431076.0', 'Sedona', 3, 'UTV/ATV', 'Soft Terrain / Intermediate Terrain / Utv Atv Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1087962', 263.66, '402.95', '402.95', 'Save up to Save $40.25 10%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 6, 'Sedona Trail Saw 2.0 Tires Crafted for today''s high-performance UTVs, the Sedona Trail Saw 2.0 radial tire is your all-encompassing solution, conquering deserts to east coast woods. With aggressive tread and 18mm depth, it excels in various terrains, while sidewall coverage enhances protection and traction in rutted landscapes. The performance-driven Crown Radius tread ensures precise steering through hardpack, ruts, and rocky terrain.', '8 ply rated puncture resistant Radial Extremely durable sidewall with inset bead for added protection Aggressive tread design with integrated side lugs to grip in extreme riding conditions Integrated rock ejectors in tread design Designed to match the high-horsepower, high-speed requirements of today’s side-by-sides Note: Yellow balance dot needs to be positioned opposite the valve stem', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/sedona_trail_saw20_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/sedona_trail_saw20_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Soft Terrain / Intermediate Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
