INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (519, '10046120.0', 'Moose Racing Rigid Tires', 'moose-racing-rigid-tires-10046120.0', 'Moose Racing', 3, 'UTV/ATV', 'Hard Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P897050', 238.95, '330.95', '330.95', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 7, 'Moose Racing Rigid Tires Big, square tread blocks? Radial construction? Six ply and eight ply versions. Yes, yes and yes! The Moose Racing Rigid Tires check all the necessary boxes for rigidity. The rugged-terrain design provides a good balance of surface area with lug spacing and a 19/32" tread depth. The design is smooth and composed over hard pack and pavement and easily handles the weight of full size UTVs and side-by-sides. The square-shouldered footprint delivers a wide, sure-footed contact patch that is bolstered with large side lugs for bite over rocks and roots. Improved road manners, longer tread life and better stability at higher speeds are other benefits of the unique tread design. Another highlight of the Rigid Tire is the shoulder lugs which creep all the way up the sidewall for an aggressive look even when parked. Features Light truck-inspired all-terrain tire High land ratio at the tread center enhances steering and performance on hard pack Flatter profile offers wide ground contact and enhances cornering traction Radial construction provides a better ride with more stability 19/32" tread depth 6 ply and 8 ply versions', 'nan', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/moose_racing_rigid_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/moose_racing_rigid_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Hard Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
