INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (520, '10045534.0', 'AMS Mud Evil Tires', 'ams-mud-evil-tires-10045534.0', 'AMS', 3, 'UTV/ATV', 'Mud Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P896805', 254.95, '344.95', '344.95', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 3, 'AMS Mud Evil Tires The Mud Evil Tires are both mud-ready and very evil. Your local pits, bogs and mires tremble with the mere mention of the name "Mud Evil". AMS uses a towering two inch tread depth for excellent traction in deep, rutty mud. A semi-continuous center tread improves steering response and keeps the Mud Evil Tires flowing more steadily over dryer, harder, less intense surfaces. Shoulder knobs wrap themselves up the sidewall for increased protection and side bite. The natural rubber compound and six ply nylon bias construction increase durability and puncture resistance.', 'Extreme mud directional paddle Designed for deep mud and ruts 2" lug depth Tractor-inspired tread pattern Aggressive shoulder knobs for increased side bite and sidewall protection Semi-continuous center tread for sure-footed control in smoother, less intense conditions 6 ply rated nylon casing Natural rubber compound increases puncture resistance For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/ams_mud_evil_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/ams_mud_evil_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Mud Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
