INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (521, '10499324.0', 'Moose Racing Insurgent Tires', 'moose-racing-insurgent-tires-10499324.0', 'Moose Racing', 3, 'UTV/ATV', 'Soft Terrain / Intermediate Terrain / Utv Atv Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1143359', 222.95, '334.95', '334.95', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 11, 'Moose Racing Insurgent Tires Moose Racing introduces the Insurgent UTV Tires, designed for exceptional performance across diverse off-road conditions. These tires feature an all-terrain tread pattern, ensuring reliable traction wherever the trail may lead. At the tread''s center, a densely arranged lug pattern enhances the Insurgent''s comportment on hard-packed surfaces. Available in both six-ply and eight-ply versions, their radial construction delivers a comfortable ride, while providing the strength to support full-size UTVs and side-by-sides, even when carrying heavy loads or additional passengers. Features Light truck-inspired all-terrain tire 6 and 8 ply versions High land ratio at the tread center enhances steering and performance on hard pack Flatter profile offers wide ground contact and enhances cornering traction Radial construction provides a better ride with more stability', 'nan', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/moose_racing_insurgent_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/moose_racing_insurgent_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Soft Terrain / Intermediate Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
