INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (522, '10307823.0', 'High Lifter Outlaw Max Tires', 'high-lifter-outlaw-max-tires-10307823.0', 'High Lifter Products Inc', 3, 'UTV/ATV', 'Utv Atv Tire / Mud Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1048477', 259.95, '456.65', '456.65', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 12, 'High Lifter Outlaw Max Tire Overengineered to dominate the mud the Outlaw Max Tire by High Lifters super deep 2.0”-2.5” pre-grooved, "dual stage” tread lugs and beefy square shoulder combined with aggressively siped and stepped center lug that will shed mud and stay clean. The 10" tread width provides a 2" wider footprint than narrow ag style treads for superior traction and flotation. The super deep, notched shoulder lugs will bite through the ruts and the overlapping tread at the center gives a smooth transitional trail use.', 'Continued evolution of the iconic Outlaw tire line Super deep 2.0”-2.5” pre-grooved, “dual stage” tread lugs Square shoulder Aggressively siped and stepped center lug that will shed mud and stay clean 10” tread width 2” wider footprint than narrow Ag style treads for superior traction and flotation at a competitive weight Super deep, notched shoulder lugs bite in the ruts Overlapping tread at center Flexible 8-ply carcass Smooth transitional trail use Sold each', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/high_lifter_outlaw_max_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/high_lifter_outlaw_max_tire.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Mud Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
