INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (523, '10426442.0', 'System 3 Off-Road RC500 Tires', 'system-3-off-road-rc500-tires-10426442.0', 'System 3 Off-Road', 3, 'UTV/ATV', 'Hard Terrain / Soft Terrain / Utv Atv Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1104844', 252.21, '453.79', '453.79', 'Save up to Save $45.19 10%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 8, 'System 3 Off-Road RC500 Tire The product boasts an aggressive tread design with interlocking blocks measuring from 0.65 inches to a full inch, delivering superb trail handling and superior traction on loose surfaces thanks to its wide, staggered pattern. With a durable 10-ply carcass that includes a fortified lower sidewall and robust ply cord, this tire is built for resilience. The innovative carcass architecture enhances ride comfort and ensures steady tracking across various terrains. Moreover, the exceptionally deep rim guard shields the wheel edges and assists in reducing the risk of pinch flats when operating at lower pressures.', 'Deep .65” - 1.0” inter-locking tread blocks and optimal void excels on the trails while the wider spaced, staggered tread blocks grip in the loose terrain 10-ply carcass which utilizes a reinforced lower sidewall and heavier ply cord resulting in extreme durability The new carcass maximizes ride quality and the trackability is unmatched on loose or hard pack terrains Super deep rim guard protects wheel lips and helps avoid pinch flats at lower psi', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/system3_off_road_rc500_tire_1800x1800.webp', '["https://americaapi.kaafifoods.com/storage/products/system3_off_road_rc500_tire_1800x1800.webp", "https://americaapi.kaafifoods.com/storage/products/system3_off_road_rc500_tire.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Hard Terrain / Soft Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
