INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (524, '10046508.0', 'Vision W396 Duo Trax Tires', 'vision-w396-duo-trax-tires-10046508.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P897241', 201.95, '241.95', '241.95', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 4, 'Vision W396 Duo Trax Tires The Duo Trax Tires from Vision Wheel pack an asymmetrical, all-terrain tread design with different inner and outer tread patterns. The highlight of this dynamic tread pattern is excellent performance in mud, hard pack and snow. The tread design delivers a smooth ride with great stability when cornering. The radial, six-ply construction holds up against trail damage and punctures while handling the load needs of full size SxS''s and hardworking UTVs.', 'Unique asymmetrical tread design for superb performance in mud, hard pack and snow All-terrain performance Radial 6 ply design Dimpled tire surfaces helps eject packed mud and snow Smooth ride and increased handling stability at high speeds and on hard cornering Designed for full size UTVs and side-by-sides Load rating of 760lb at 15psi Non-directional and reversible, fitting both left-side and right-side applications', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/vision_duo_trax_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/vision_duo_trax_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
