INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (525, '10579729.0', 'Maxxis Razr XTZ Tires', 'maxxis-razr-xtz-tires-10579729.0', 'Maxxis Tires', 3, 'UTV/ATV', 'Hard Terrain / Non Dot Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1184318', 292.6, NULL, NULL, 'Save $15.40 5%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 1, 'Maxxis Razr XTZ Tires The RAZR XTZ leverages cutting-edge materials to trim excess weight, enhancing both acceleration and agility without compromising the renowned durability associated with Maxxis. Its carefully engineered contact patch delivers exceptional traction, making it suitable for challenging conditions. In addition, the RAZR XTZ''s updated tread design not only boosts its resistance to abrasion and punctures but also amplifies ride comfort for the user.', 'Next-Generation Tread Pattern: Enhances traction and steering performance for superior handling. Sipe Design: Reduces tread stiffness, delivering a smoother and more comfortable ride. Optimized Shoulder Lug Design: Features integrated rock ejectors to improve debris cleanout and prevent clogging. Enhanced Tread Pattern and Lower Void Ratio: Boosts abrasion and puncture resistance for increased durability. 8-ply-rated', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/maxxis_razr_xtz_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/maxxis_razr_xtz_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Hard Terrain / Non Dot Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
