INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (526, '10049435.0', 'Tensor Desert Series Tires', 'tensor-desert-series-tires-10049435.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Hard Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P898956', 254.66, '488.66', '488.66', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 9, 'Tensor Desert Series Tires The Desert Series Tires from Tensor Tire are race-built tires aimed squarely at UTV desert racing. Available in both bias and radial construction, all versions of the Desert Tire use tough, eight ply construction with reinforced sidewalls for excellent puncture resistance. These rigid tires are designed with high horsepower, full size UTVs and have the load capacity to match. The Desert Series Tires keep steering response sharp, braking distances short and accelerative grip strong. Bias ply models use a proprietary fiberglass belted construction. Select sizes of the Desert Series are approved for Score and BITD racing. Tensor Tire rates the 35" model among the lightest race tire on the market. All models of the Desert Series feature tread blocks designed to allow custom grooving.', 'High performance desert-running tire Engineered for UTV race applications Bias or radial 8 ply designs Ribbed sidewall for enhanced puncture resistance Large, flat contact patch Superior steering response and decreased braking distance Designed for high horsepower, full size UTV applications 1,200-1,600lb load capacity, depending on model 33" approved for Score and BITD (2020) UTV Racing 35" among the lightest Class 10 specific race tires on the market Made in USA For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/tensor_desert_series_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/tensor_desert_series_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Hard Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
