INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (528, '10051958.0', 'GBC Terra Master Tires', 'gbc-terra-master-tires-10051958.0', 'nan', 3, 'UTV/ATV', 'Hard Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P899566', 228.56, '437.95', '437.95', 'Save up to Save $43.43 10%', 4.8, 12, 'nan', 'nan', 'Front; Front/Rear; Rear', 0, 'nan', 16, 'GBC Terra Master Tires The Terra Master Tires from GBC hold a unique tread design that gives riders the benefits of two tires in one. You customize the orientation of the Terra Masters to best match your vehicle and driving style. With lateral lugs facing outward, the Terra Masters are oriented for better forward traction in mud and loose surfaces with better obstacle climbing ability. Flip them around (with staggered A/T pattern facing out) for quicker steering response and better high speed road manners. Either way, the ten ply radial construction is well up the the task of battling flats and trail damage, and the Terra Master is also DOT approved.', 'The industry''s first asymmetrical, non-directional all-terrain tire Can be oriented facing either direction 10 ply rated radial design Puncture resistant Lightweight construction Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/gbc_tire_terra_master_front27_x9_r14_radial_lr760_lbs_terra_master_front27_x9_r14.webp', '["https://americaapi.kaafifoods.com/storage/products/gbc_tire_terra_master_front27_x9_r14_radial_lr760_lbs_terra_master_front27_x9_r14.webp", "https://americaapi.kaafifoods.com/storage/products/gbc_terra_master_tires.webp"]', '{"Wheel Location": "Front; Front/Rear; Rear", "Type": "UTV/ATV", "Product Type": "Hard Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
