INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (529, '10045092.0', 'Carlisle Versa Trail XTR Tires', 'carlisle-versa-trail-xtr-tires-10045092.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha Ténéré 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650', '2000 - 2025', 'P896476', 241.16, '286.95', '286.95', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 2, 'Carlisle Versa Trail XTR Tires Carlisle Versa Trail XTR Tires, an all-terrain option with six ply radial construction. Carlisle''s tough tread rubber compound ensures excellent grip over the life of the tire along with resistance to cuts, chips and punctures. The XTR version of the Versa Trail Tire features enlarged lug channels for improved off-road bite and mud ejection. The Versa Trail XTR Tires also sport a reinforced construction with added puncture resistance via heavier, reinforced plies.', 'Extreme rugged-trail design for hard pack and intermediate conditions Increased lug spacing Non-directional tread pattern Extreme performance and handling on multiple surfaces Reinforcement belts for added puncture resistance Reinforced radial 6 ply construction For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/carlisle_versa_trail_xtr_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/carlisle_versa_trail_xtr_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "BMW R1200GS / R1250GS / F850GS, KTM 1290 Super Adventure / 890 Adventure, Honda Africa Twin / CRF300L, Yamaha T\\u00e9n\\u00e9r\\u00e9 700, Triumph Tiger 900 / 1200, Suzuki V-Strom 650, Kawasaki KLR650", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
