INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (530, '159093.0', 'ITP Mud Lite XTR Tires', 'itp-mud-lite-xtr-tires-159093.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Mud Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P43390', 231.3, '350.99', '350.99', 'Save up to Save $49.49 14%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 0, 'nan', 8, 'ITP Mud Lite XTR Tires Radial construction means the Mud Lite XTR Tire delivers extreme traction over mud and rock. The radial design creates a smoother ride while handling higher payload and delivering sharper handling. The super-aggressive tread design features 1 1/8 inch deep angled, grooved lugs to achieve exceptional grip. Long-wearing tread compound and six ply construction resist punctures mile after mile.', 'Extreme terrain radial tire Super aggressive tread design features deep, angled, grooved lugs to achieve an exceptional level of traction 1 1/8 inch tread depth Among the smoothest-riding mud tires on the market today Super-aggressive tread design features deep, angled, grooved lugs to achieve an exceptional level of traction Radial construction means the Mud Lite XTR rides smoothly and finds more traction than a bias-ply tire because of a larger contact patch - a radial tires footprint actually grows under load Lightweight, 6 ply design Puncture resistant construction Made in USA For off highway use only Note: Sold individually.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/ITP_Mud_Lite_XTR_ATV_Tires.webp', '["https://americaapi.kaafifoods.com/storage/products/ITP_Mud_Lite_XTR_ATV_Tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Mud Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
