INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (531, '10046500.0', 'Vision W1805 Trail Finder Tires', 'vision-w1805-trail-finder-tires-10046500.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Soft Terrain / Mud Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P897237', 213.95, '243.95', '243.95', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 2, 'Vision W1805 Trail Finder Tires The Trailfinder Tire by Vision Wheel is designed for UTVs and ATVs. Featuring a non-directional tread pattern for both front and rear use, this tire is perfect for multi-terrain adventures. The 26x10R14 tire size and 6-ply radial construction ensure durability and reliability in diverse conditions. The tire is designed with a flatter tread area to provide more contact area with the ground, improving traction and handling. The reduction in sidewall height enhances handling at higher speeds and in hard cornering, while meeting or exceeding OEM requirements for tread wear and shock deflection. Lightweight yet sturdy, the Trailfinder Tire is a great choice for anyone looking for reliable performance on different types of terrain.', 'All-terrain mud tire tread pattern Flatter tread area to give more contact area with ground Reduced sidewall height for improved handling at higher speeds and in hard cornering Large shoulder lugs with wide tread spacing Lightweight 6 ply radial construction Note : Not certified for use on public roads. Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/vision_w1805_trail_finder_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/vision_w1805_trail_finder_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Soft Terrain / Mud Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
