INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (533, '10613753.0', 'System 3 Off-Road XTR370W Tires', 'system-3-off-road-xtr370w-tires-10613753.0', 'System 3 Off-Road', 3, 'UTV/ATV', 'Intermediate Terrain / Hard Terrain / Non Dot Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1196105', 325.67, '462.95', '462.95', 'Save up to Save $44.62 10%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 6, 'System 3 Off-Road XTR370W Tires The XTR370W Wide Xtreme Terrain Radial is designed for those who tackle the toughest trails with confidence. Its impressive 12-inch tread width allows for easier navigation over ruts, preventing riders from becoming stuck. Featuring deep 1.125-inch tread blocks with integrated siping, it ensures remarkable traction on loose, rocky, and slick surfaces. Extended sidewall lugs enhance grip during aggressive cornering and steep climbs. Offered in both a durable 10-ply standard compound and a softer 8-ply carcass option, the XTR370W strikes the perfect balance between traction, flotation and durability for extreme all-terrain capabilities.', '"W" features a full 12-inch tread width 1.125 inch tread depth 10 ply radial construction for Standard Compound 8 ply radial construction for Sticky Compound Extreme all-terrain performance Multi-angle tread blocks with integrated siping Extended sidewall tread offers increased side bite and lateral grip Wide lug spacing ejects mud Flexible, pliant advanced sidewall construction Deep rim guard Max load: 1,210 lbs. - 1,860 lbs. Tire weight: 58.2 lbs. - 69.4 lbs. For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/system3_off_road_xtr370_w_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/system3_off_road_xtr370_w_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Intermediate Terrain / Hard Terrain / Non Dot Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
