INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (535, '10585010.0', 'Sedona Ridge Ripr Tire', 'sedona-ridge-ripr-tire-10585010.0', 'Sedona', 3, 'UTV/ATV', 'Soft Terrain / Intermediate Terrain / Hard Terrain / Non Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1184658', 228.56, '339.95', '339.95', 'Save up to Save $38.45 11%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 7, 'Sedona Ridge Ripr Tire The Sedona Ridge Ripr offers unwavering traction and control over a diverse range of terrains, from jagged mountain paths to expansive desert sands. Its pronounced tread design ensures a solid grip and stable handling for side by side riders, allowing them to confidently navigate mixed landscapes. The tire''s 8 ply radial build, fortified by robust sidewalls, enhances puncture resistance and extends its longevity under rough conditions. It is crafted to keep pace with the rigors of high-speed desert runs and the technical demands of narrow forest trails, providing riders with a tire that''s not only reliable but also complements the dynamic styling of modern high-performance vehicles.', '8-ply rated puncture-resistant radial construction for extreme durability Reinforced sidewall with inset bead for added protection against trail hazards Aggressive tread pattern with integrated side lugs for superior grip in rutted terrain Self-cleaning tread design with rock e