INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (537, '10519177.0', 'EFX MotoRavage XL Tires', 'efx-motoravage-xl-tires-10519177.0', 'EFX Tires', 3, 'UTV/ATV', 'Intermediate Terrain / Hard Terrain / Non Dot Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1152777', 249.0, '415.0', '415.0', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 7, 'EFX MotoRavage XL Tires The EFX MotoRavage XL, a highly regarded radial tire, features an all-terrain tread design that ensures reliable performance across various surfaces. Enhanced with both an aggressive sidewall pattern and deep main lugs, it delivers exceptional traction whether navigating through thick mud or scaling rough, rocky terrain. Constructed with an eight-ply rating, this tire excels in maintaining internal pressure. The "XL" iteration builds upon the original with an increased lug depth of 1.5 inches and a more pronounced sidewall pattern, enhancing its capabilities and durability even further.', 'Designed to conquer everything XL version features deeper main lugs and sidewall lugs 1.5"+ main lug depth Rugged 8-ply radial construction Soft compound formulation All-terrain tread pattern Performs in mud, sand, rock and everything else Smooth, controlled ride on hard surfaces / trails Deep main lugs and lugged sidewalls Pebbled sidewall pattern', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/efx_tires_moto_ravage_tire.webp',