INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (539, '10042400.0', 'ITP Terra Claw Tires', 'itp-terra-claw-tires-10042400.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P895534', 221.36, '440.99', '440.99', 'Save up to Save $189.93 43%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 3, 'ITP Terra Claw Tires The Terra Claw Tires from ITP are an all-terrain style tire with wider lug spacing for more aggressive off-road ability. This widely spaced tread design ejects packed mud easier and creates a large biting edge for rocks and ruts. Siping throughout the tread pattern creates better wet weather grip and tread flex for rock crawling. The rounded shoulder, V-shaped center lugs and tough eight ply radial construction add to the tire''s long lasting, easy handling nature.', 'All-terrain pattern designed for hard pack, intermediate, soft and loose surfaces Excels over rocks and ruts and for utility duties Unique alternating angled tread pattern to provide ultimate traction in multiple terrains Additional siping yields increased traction in wet conditions and allows tread ﬂex over rocky terrain Reinforced belts provide increased traction and puncture resistance Stepped tread blocks give additional biting edges to aid traction in rutted conditions Round shoulder design provides excellent steering response and lateral stability V-shaped lug design provides increased traction and self-cleaning Center lug design provides both traction and a comfortable ride 8 ply radial construction Made in the USA For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/itp_terra_claw_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/itp_terra_claw_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
