INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (553, '10042433.0', 'ITP Coyote Tires', 'itp-coyote-tires-10042433.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P895555', 248.08, '457.99', '457.99', 'Save up to Save $104.08 23%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 8, 'ITP Coyote Tires ITP has created one of the best all-terrain UTV tires to have ever hit the market. The ITP Coyote is designed for high performance, high horsepower units that command traction and excel at high speeds. Built using ITP’s legendary technology these racing tires perform well above the standard in dirt, gravel, sand and even hard pack. Their 8-ply construction makes them strong enough to handle heavy power and also resist punctures.', 'All-terrain design engineered for racing, desert, hard pack, intermediate, soft and loose surfaces Dominates rough, hard-pack, gravel and sandy terrain Specifically designed for high horsepower UTV and SxS vehicles Wide tread voids and multiple biting edges on the tread blocks offer excellent traction in a variety of environments 0.75" inch lug depth for maximum handling, braking and traction control Center lug channels improve traction by allowing the tread to flex and wrap around rocks and other objects when riding on rough trails 8 ply rated radial performance tire Superior traction and side bite Predictable lateral stability "Surgical" steering response Staggered width shoulder lugs Optimal footprint for even pressure distribution', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/itp_coyote_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/itp_coyote_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
