INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (560, '10042418.0', 'ITP Terra Hook Tires', 'itp-terra-hook-tires-10042418.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P895548', 211.75, '426.92', '426.92', 'Save up to Save $59.62 14%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 11, 'ITP Terra Hook Tires The Terra Hook Tires pack an aggressive all-terrain tread pattern with alternating lug pitches and shoulder elements with DOT compliance. The eight ply radial construction features a three-quarter inch tread depth and a balanced tread-to-void ratio for a smooth ride over hard surfaces.', 'All-terrain design for hard pack, intermediate, rocks and ruts, loose and soft surfaces Tread block channels allow the tread to flex giving consistent traction over roots, rocks and other trail conditions Unique tread blocks with alternating pitches provide true multi-surface, multi-condition traction Alternating shoulder elements assist grip from any angle of approach or direction and enhance forward or reverse motion in rutted conditions Multi-angled channeled lugs Supreme traction on lush trails and soft terrain Unique non-directional tread design delivers traction and performance over roots, rocks and other trail conditions 8 ply radial construction Balanced tread-to-void ratio ensures a smooth ride on harder surfaces 0.75" lug depth for maximum handling and control', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/itp_tires_terra_hook_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/itp_tires_terra_hook_tires.webp", "https://americaapi.kaafifoods.com/storage/products/itp_terra_hook_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
