INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (566, '10388088.0', 'System 3 Off-Road ATX470 Tires', 'system-3-off-road-atx470-tires-10388088.0', 'System 3 Off-Road', 3, 'UTV/ATV', 'Intermediate Terrain / Hard Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1088737', 221.16, '354.57', '354.57', 'Save up to Save $35.07 10%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 7, 'System 3 Off-Road ATX470 Tire The ATX 470 tire enhances all-terrain capabilities with a medium compound material and supple tread blocks, combined with an expansive contact patch for exceptional traction on slippery surfaces. Angled at .80 inches, the tread blocks deliver effective grip across varied terrain types, from loose soil to compacted trails. Split, staggered shoulder blocks on either side improve the tire''s grip during lateral movements, making it simple to maneuver through challenging ruts. The 10-ply rating of this tire indicates a commitment to longevity, accompanied by a pliable carcass that adeptly absorbs bumps for a smoother ride. A deep rim guard reinforces the tire, shielding the wheel edge from damage due to impacts.', '10 Ply Medium compound all-terrain Split, dual stagger shoulder blocks Deep rim guard Tread Depth: .80-1.50 Weight: 28x10R14: 34.8 lbs. 30x10R14: 37.7 lbs. 32x10R14: 41.2 lbs. 31x10R15: 40.6 lbs. 33x10R15: 44.1 lbs. 35x10R15: 50.3 lbs. 35x10R18: 49.6 lbs. Max Load: 28x10R14: 1160 lbs. 30x10R14: 1210 lbs. 32x10R14: 1410 lbs. 31x10R15: 1370 lbs. 33x10R15: 1515 lbs. 35x10R15: 1710 lbs. 35x10R18: 1530 lbs. For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/system3_off_road_atx470_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/system3_off_road_atx470_tire.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Intermediate Terrain / Hard Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
