INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (567, '10044254.0', 'Quad Boss QBT671 Mud Tires', 'quad-boss-qbt671-mud-tires-10044254.0', 'Quad Boss', 3, 'UTV/ATV', 'Mud Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P896152', 125.25, '187.03', '187.03', 'nan', 4.8, 12, 'nan', 'nan', 'Front; Front/Rear', 0, 'nan', 4, 'QuadBoss QBT671 Mud Tires The Quad Boss 671 Mud Tires uses a split "V" tread design for excellent grip in mud. Deep, widely spaced lugs bite well over rock, roots and ruts with equal aplomb. The 671 Mud Tires use a six ply bias construction with superior puncture resistance and sport a built-in rim guard. The tread valley uses a uniquely "scaled" surface to provide extra traction and cleanout - all while looking like pterodactyl skin.', 'Heavy duty split lug "V" mud tread Excels over mud, rocks, roots and ruts Reinforced 6 ply bias construction 24" and 25" tires feature 3/4" tread depth 26" and 27" tires feature 7/8" tread depth Unique scale design in tread valley provides extra traction and superior cleanout Slotted lugs add traction and provide weight savings for better steering control Wrap around shoulder lugs give extra sidewall protection and excellent bite for cornering Built-in rim guard for wheel protection For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/quad_boss_qbt671_mud_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/quad_boss_qbt671_mud_tires.webp"]', '{"Wheel Location": "Front; Front/Rear", "Type": "UTV/ATV", "Product Type": "Mud Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
