INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (570, '10042700.0', 'ITP Dura City Radial Tires', 'itp-dura-city-radial-tires-10042700.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P895657', 167.35, '205.95', '205.95', 'Save up to Save $20.61 10%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 0, 'nan', 2, 'ITP Dura City Radial Tires The Duracity Radial Tires are a versatile extreme-terrain radial with improved on-road manners. The multi-pitch design and directional tread pattern keep steering, ride and road noise in check. Stepped shoulder blocks and wide lug spacing not only create solid bite off-road and over rocks but also expel packed in mud - all without the penalties typically associated with hardcore all-terrain rubber.', 'All-terrain design engineered for hard pack, intermediate, soft surfaces, rocks and ruts Multi-pitch design with siping promotes a quieter ride on harder surfaces Directional, self-cleaning tread pattern with shoulder steps ensures traction in multiple dry, loose and wet conditions True multi-surface design and with features to match the demands of terrains ranging from hard, engineered surfaces to various off-road environments Radial construction provides a compliant, comfortable ride and enhances traction Reinforced belts increase puncture resistance in the vulnerable tread areas Multiple pitch design with siping to promote a quiet ride Continuous center contact patch and directional tread pattern make this tire ideal for off-roading in various conditions Shoulder steps allow for better self-cleaning and improved handling and stability Flatter center profile for enhanced traction and stability Rounded shoulder design improves steering response 6 ply radial construction Made in the USA For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/itp_duracity_radial_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/itp_duracity_radial_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
