INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (577, '10033615.0', 'Kenda K3204R Klever X/T Tires', 'kenda-k3204r-klever-x-t-tires-10033615.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P892217', 182.74, '344.99', '344.99', 'Save up to Save $32.25 9%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 9, 'Kenda K3204R Klever X/T Tires The Kenda Klever X/T Tires present a formidable option for all-terrain radial needs, designed with durability and DOT approval in mind. Their eight-ply construction ensures wear resistance and longevity, coupled with the benefit of lower rolling resistance. As a lighter choice among steel-belted radial options for UTVs, the Klever X/T Tires excel in versatility, with the capability to be outfitted with studs to enhance traction in ice and snowy conditions.', 'Smooth ride quality with low rolling resistance 8 ply steel-belted radial design Medium durometer compound Exceptional traction on all surfaces Reduced weight Robust bead protector to shield wheel from rocks Studdable design for snow and ice riding', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/kenda_k3204_klever_xt_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/kenda_k3204_klever_xt_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
