INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (578, '10043928.0', 'Sedona Mud Rebel R/T Tires', 'sedona-mud-rebel-r-t-tires-10043928.0', 'Sedona', 3, 'UTV/ATV', 'Mud Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P896007', 158.4, '247.95', '247.95', 'Save up to Save $24.75 10%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 9, 'Sedona Mud Rebel R/T Tires The Sedona Mud Rebel R/T Tire mirrors the tread design of the standard Mud Rebel Tire but turns up the wick with radial, eight ply construction and deeper 1-1/8 inch V-shaped tread lugs. The more aggressive design relies on the addition of radial construction to maintain good steering response and ride over hard pack that is on par with the more mild, standard Mud Rebel. Wide lug spacing ejects packed mud and claws tenaciously over rocks, ruts and roots.', 'Designed for aggressive mud and utility applications V-shaped lug pattern excels over trails, rocks and ruts 8 ply radial construction 1-1/8" tread depth High-quality rubber compounds and construction methods Increased sidewall strength for puncture resistance and impact absorption Designed for high load capacities Responsive steering Increased puncture resistance For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/sedona_mud_rebel_rt_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/sedona_mud_rebel_rt_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Mud Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
