INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (579, '10431081.0', 'Sedona Ridge Saw 2.0 Tires', 'sedona-ridge-saw-2-0-tires-10431081.0', 'Sedona', 3, 'UTV/ATV', 'Intermediate Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1106125', 171.86, '376.95', '376.95', 'Save up to Save $38.55 10%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 10, 'Sedona Ridge Saw 2.0 Tire The Sedona Ridge Saw 2.0 tires are crafted using advanced technology to deliver remarkable durability and precise control. These tires come with a new-tech carcass that''s 8-ply rated and puncture-resistant, ensuring they stand up to challenging terrains. A crown radius tread profile on the tire offers meticulous steering and effective handling. Sizes 30 inches and above feature an 8-ply radial construction to elevate performance on the latest UTV models. For increased defense and traction in deep ruts, the tires are equipped with integrated side lugs. Additionally, the durable sidewall design includes an inset bead for enhanced protection against the elements.', 'Ultra durable, puncture resistant 8 ply rated new tech carcass Performance driven crown radius tread profile for precise steering and control Tire sizes 30” and above are upgraded to an 8pr RADIAL CARCASS for improved performance on todays performance UTV’s Integrated side lugs for added protection and traction in deep ruts Extremely durable sidewall with inset bead for added protection Note : Yellow balance dot needs to be positioned opposite the valve stem', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/sedona_ridge_saw20_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/sedona_ridge_saw20_tire.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Intermediate Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
