INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (580, '10051938.0', 'GBC Dirt Commander Tires', 'gbc-dirt-commander-tires-10051938.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P899564', 168.26, '330.95', '330.95', 'Save up to Save $33.09 10%', 4.8, 12, 'nan', 'nan', 'Front; Front/Rear; Rear', 0, 'nan', 18, 'GBC Dirt Commander Tires The Dirt Commanders from GBC Tire are an aggressive all-terrain design that borrows cues from the world of light truck tires. Available in both radial and bias versions, all options of the Dirt Commanders use super tough, puncture-resistant eight ply construction. Deep, wide traction bars are positioned on a bias across the tire''s surface. Shoulder lugs are positioned laterally for grip up and over rocks and obstacles. Void spacing is wide to eject packed mud, and a rounded tire profile keeps steering effort light and breakaway handling characteristics predictable. For a more aggressive Dirt Commander option, consider the Dirt Commander 2.0 Radial Tires.', 'Aggressive all-terrain design Excels on rock, mud, dirt, creek beds, grass, hills and rock ledges Rounder tread profile with tapering shoulder lugs Balanced void ratio for added bite Improved mud clean out Excellent braking and acceleration 8 ply radial or 8 ply bias construction For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/gbc_tire_dirt_commander8_ply_front_bias_lr480_lbs_dirt_commander8_ply_front_1800x1800.webp', '["https://americaapi.kaafifoods.com/storage/products/gbc_tire_dirt_commander8_ply_front_bias_lr480_lbs_dirt_commander8_ply_front_1800x1800.webp", "https://americaapi.kaafifoods.com/storage/products/gbc_tire_dirt_commander8_ply_front_bias_lr480_lbs_dirt_commander8_ply_front.webp"]', '{"Wheel Location": "Front; Front/Rear; Rear", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
