INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (582, '10043820.0', 'Sedona Buck Snort Tires', 'sedona-buck-snort-tires-10043820.0', 'Sedona', 3, 'UTV/ATV', 'Mud Tire / Soft Terrain / Utv Atv Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P895988', 158.35, '235.95', '235.95', 'Save up to Save $23.55 10%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 4, 'Sedona Buck Snort Tires The Buck Snort Tires are an extreme-terrain UTV tire with a center lug pattern that mimics a deer hoof. Wide lug spacing provides a more aggressive bite off-road than typical all-terrain options. Heavy-duty six ply construction uses Sedona''s New-Tech assembly methods - keeping the tire durable and puncture-resistant. Siped tread lugs, a built-in rim guard and smooth ride characteristics provide ample "go" to match the novelty tread pattern "show".', 'Extreme all-terrain with wide lug spacing for ruts and rocks Functional deer hoof center tread design leaves tracks down the trail Ultra-durable, puncture-resistant 6 ply bias construction Sedona New-Tech carcass construction Aggressive tread with integrated side lugs grip in extreme conditions Tread lugs are siped for added traction and durability Built-in rim guard for added wheel protection Class leading ride quality and performance For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/sedona_buck_snort_bias6_pr_buck_snort.webp', '["https://americaapi.kaafifoods.com/storage/products/sedona_buck_snort_bias6_pr_buck_snort.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Mud Tire / Soft Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
