INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (583, '10049449.0', 'GMZ Sand Stripper Rear Tires', 'gmz-sand-stripper-rear-tires-10049449.0', 'GMZ Race Products', 3, 'UTV/ATV', 'Sand Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P899006', 247.48, '336.0', '336.0', 'Save up to Save $67.36 20%', 4.8, 12, 'nan', 'nan', 'Rear', 0, 'nan', 2, 'GMZ Sand Stripper Rear Tires For the sand and dune enthusiasts of the world, GMZ Race Products present the Sand Stripper line of performance tires. Front or rear, Sand Stripper Tires feature an extra wide footprint that provides maximum flotation and smooth dune transitions. Thick rim guards protect the wheel lip and seal the bead from sand intrusion. Bias ply construction in two, four and six ply variants deliver good durability while keeping weight savings at the forefront. Sand Stripper Rear Tires feature a 22.2mm paddle depth with paddles running the width of the contact patch. In both ten or fourteen paddle versions, the tires use a six ply bias construction to maintain their form and contact patch when putting down big power. For a more aggressive sand option, consider the "HP" version of the GMZ Sand Stripper Rear Tires with a 28.5mm paddle depth.', 'Full-service sand and dune tire Designed for rear wheel applications 22.2mm paddle depth 10 or 14 paddle variations Excellent floatation and smooth transitions Thick rim guard keeps sand out of bead and protects rim Rear tires use deep cut lateral paddles 6 ply bias construction For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/gmz_sand_stripper_rear_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/gmz_sand_stripper_rear_tires.webp"]', '{"Wheel Location": "Rear", "Type": "UTV/ATV", "Product Type": "Sand Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
