INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (584, '10386966.0', 'Mitas Enduro Trail Rally MH Super Light Tires', 'mitas-enduro-trail-rally-mh-super-light-tires-10386966.0', 'Mitas', 3, 'DIRT BIKE', '20 On Road 80 Off Road / 10 On Road 90 Off Road / Dot Dirt Tires / Hard Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1087831', 149.06, NULL, NULL, 'Save $21.93 13%', 4.8, 12, 'nan', 'nan', 'Front', 1, '90/90-21 54R TT', 1, 'Mitas Enduro Trail Rally MH Super Light Tires The Mitas Enduro Trail Rally Tires meet the needs of riders craving the utmost in aggressive off-road performance for high-speed Rally Raid ADV use. Part of the Rally product line, these tires are the result of rigorous testing and development with world-class riders in the Dakar Rally. Engineered with a flexible reinforced carcass and a soft compound, the Enduro Trail Rally tires maximize off-road potential. Offering unparalleled traction, these tires provide the ultimate off-road experience without the need to switch to Enduro model tires.', 'The Rally tires are designed for Rally and competition use on adventure, dual sport and off road motorcycles Mitas Rally tires are approved for Tube Type use only DOT Road Legal Enduro influenced tire profile and knob pattern balancing maximum off-highway traction stability in medium to hard terrain Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_rally_mh_super_light_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_rally_mh_super_light_tires.webp"]', '{"Wheel Location": "Front", "Type": "DIRT BIKE", "Product Type": "20 On Road 80 Off Road / 10 On Road 90 Off Road / Dot Dirt Tires / Hard Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "90/90-21 54R TT"}', 50, 1, 1, NOW(), NOW());
