INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (585, '10049452.0', 'GMZ Sand Stripper TT Front Tires', 'gmz-sand-stripper-tt-front-tires-10049452.0', 'GMZ Race Products', 3, 'UTV/ATV', 'Sand Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P898959', 263.12, '301.0', '301.0', 'Save up to Save $24.08 8%', 4.8, 12, 'nan', 'nan', 'Front', 0, 'nan', 3, 'GMZ Sand Stripper TT Front Tires For the sand and dune enthusiasts of the world, GMZ Race Products present the Sand Stripper line of performance tires. Front or rear, Sand Stripper Tires feature an extra wide footprint that provides maximum flotation and smooth dune transitions. Thick rim guards protect the wheel lip and seal the bead from sand intrusion. Bias ply construction in two, four and six ply variants deliver good durability while keeping weight savings at the forefront. Sand Stripper TT Front Tires are intended for four-wheel-drive applications. Sand Stripper TT Tires use a hybrid tread design that pairs concave tread ribs with lateral traction blocks. These lateral traction blocks take power from front driven wheels and deliver it straight to the sand - maximizing grip to climb steep hills faster while keeping transitions nimble. Sand Stripper TT Front Tires can be paired with any of the rear tire applications in the Sand Stripper lineup. For rear-wheel-drive applications, consider the "standard" Sand Stripper Front Tires without lateral traction blocks for reduced drag.', 'Full-service sand and dune tire Designed for 4x4 front wheel applications Lateral traction blocks for front wheel power delivery Excellent floatation and smooth transitions Thick rim guard keeps sand out of bead and protects rim 4 ply bias construction For off-highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/gmz_sand_stripper_tt_front_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/gmz_sand_stripper_tt_front_tires.webp"]', '{"Wheel Location": "Front", "Type": "UTV/ATV", "Product Type": "Sand Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
