INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (586, '10395448.0', 'Atturo Trail Blade Boss SXS Tires', 'atturo-trail-blade-boss-sxs-tires-10395448.0', 'Atturo Tires', 3, 'UTV/ATV', 'Soft Terrain / Intermediate Terrain / Hard Terrain / Utv Atv Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1093319', 189.05, '289.0', '289.0', 'Save up to Save $56.24 19%', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 11, 'Atturo Tires Trail Blade Boss SXS Tire The product, known for its race-proven tread pattern, swiftly adapts to various terrains, providing exceptional versatility. Its design features sizeable split tread blocks to effectively channel water and debris away, without compromising the tire''s strength and durability. A significant void ratio ensures an extensive biting edge, facilitating the clearance of mud and rocks. Equipped with an integrated rim protector, the tire not only reduces the incidence of rock rash on wheels but also maintains a neat appearance.', 'Race inspired tire built off proven LT design Split tread blocks High void ratio Alternating shoulder blocks Integrated rim protector 8PR steel belted construction Max PSI: 38 Tread depth 1/32: 23 Sold each', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/atturo_tires_trail_blade_boss_sxs_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/atturo_tires_trail_blade_boss_sxs_tire.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Soft Terrain / Intermediate Terrain / Hard Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
