INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (587, '10045504.0', 'AMS Slingshot X/T Tires', 'ams-slingshot-x-t-tires-10045504.0', 'AMS', 3, 'UTV/ATV', 'Mud Tire / Utv Atv Tire', 'Honda', 'Gs', '2008 - 2025', 'P896796', 148.95, '194.95', '194.95', 'nan', 4.8, 12, 'nan', 'nan', 'Front/Rear; Rear', 0, 'nan', 6, 'AMS Slingshot X/T Tires The AMS Slingshot X/T Tire are built to tackle extreme terrain with ease. Their aggressive design is focused on excelling over rocks, ruts, roots and through mud. These tires also perform well in snow, thanks to their 1" tread depth. With 6-ply bias construction, they offer durability and reliability on any trail. The reinforced centerline lugs keep the tire smooth over hard surfaces and pavement, while the dimpled tread elements on the surface of each lug provide better traction and expel mud. The large shoulder lugs wrap the sidewall for deeper mud and snow grip, making these tires a must-have for any off-road adventure.', 'Aggressive extreme-terrain design focused on mud and rock Excels over rocks, ruts and roots Performs well in snow 1" tread depth 6 ply bias construction Reinforced centerline lugs keep the tire smooth over hard surfaces and pavement Dimpled tread elements on surface of each lug offers better traction and expel mud Large shoulder lugs wrap the sidewall for deeper mud and snow grip Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/ams_slingshot_xt_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/ams_slingshot_xt_tires.webp"]', '{"Wheel Location": "Front/Rear; Rear", "Type": "UTV/ATV", "Product Type": "Mud Tire / Utv Atv Tire", "Make": "Honda", "Model": "Gs", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
