INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (590, '10045459.0', 'AMS Swamp Fox Plus Tires', 'ams-swamp-fox-plus-tires-10045459.0', 'AMS', 3, 'UTV/ATV', 'Mud Tire / Soft Terrain / Utv Atv Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P896788', 143.95, '259.95', '259.95', 'nan', 4.8, 12, 'nan', 'nan', 'Front/Rear; Rear', 0, 'nan', 9, 'AMS Swamp Fox Plus Tires The Swamp Fox Plus Tires pack a punch with staggered, V-oriented main lugs that are a whopping 1.2" deep. Adding further grip are oversized shoulder knobs for good bite up and over ruts. The dimpled tread design with wide spacing ejects packed mud and snow for continued traction bog after bog. Tough, six ply bias construction and natural rubber compounds deliver long life and good puncture resistance.', 'Extreme all-terrain design excels in mud Deep 1.2" center tread depth for maximum grip Excellent snow traction Dimpled, reinforced lugs give more biting edges Aggressive shoulder knobs add side bite in deep ruts and protect against punctures Rugged 6 ply construction Computer-enhanced tread pattern for stability and traction at any speed Natural rubber compound for superior puncture resistance and durability Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/ams_swamp_fox_plus_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/ams_swamp_fox_plus_tires.webp"]', '{"Wheel Location": "Front/Rear; Rear", "Type": "UTV/ATV", "Product Type": "Mud Tire / Soft Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
