INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (592, '10386868.0', 'Mitas Terra Force EX XT Super Light Tires', 'mitas-terra-force-ex-xt-super-light-tires-10386868.0', 'Mitas', 3, 'DIRT BIKE', '20 On Road 80 Off Road / Dot Dirt Tires / Dot Tire / Intermediate Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1087873', 136.57, NULL, NULL, 'Save $19.42 12%', 4.8, 12, 'nan', 'nan', 'Rear', 1, '120/90-18 65R TT', 1, 'Mitas Terra Force EX XT Super Light Tires Experience superior traction and legendary durability with the Mitas Terra Force EX XT Tires. These tires are equipped with multiple rubber compound and carcass options, complemented by tread designs tailored for specific terrains. The rear tire, with full-height knobs, is race-ready and DOT certified, ensuring a high-performance and reliable option for your off-road adventures. Note: This tire is shown with the green stripe in the photo.', 'Rear tire tread designed for optimum performance in extreme soft to medium terrain, deep roots and rocks Competition tire, DOT legal for use on Enduro and Dual Sport Motorcycles 20% on-road / 80% off-road Legendary Chunking Resistance Extra tall knob pattern for maximum bite in the deepest mud, ruts or rocks Tube Type Application Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_terra_force_exxt_super_light_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_terra_force_exxt_super_light_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "20 On Road 80 Off Road / Dot Dirt Tires / Dot Tire / Intermediate Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/90-18 65R TT"}', 50, 1, 1, NOW(), NOW());
