INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (594, '158978.0', 'ITP Holeshot XCR Tires', 'itp-holeshot-xcr-tires-158978.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Non Dot Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P43332', 148.64, '226.62', '226.62', 'Save up to Save $43.92 19%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 0, 'nan', 2, 'ITP Holeshot XCR Tires The ITP Holeshot XCR Tires sport specially angled shoulder knobs designed for increased side bite for faster, more controllable cornering. The MX tread pattern excels in hard pack, intermediate terrain, mud, rocks and ruts - creating a good all around all-terrain option. The six ply design is tough while being lighter in weight than most of the competition.', 'Classic MX all-terrain tread pattern designed for hard pack, intermediate, rocks, ruts and mud 6 ply toughness yet light in weight Weight savings of 2 lbs when compared to similarly sized ITP Holeshot XC and Razr models Specially angled shoulder knob design provides increased side bite for faster, more controllable cornering Bright hot patch logo on sidewall Made in the USA For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/ITP_Holeshot_XCR_Tires.webp', '["https://americaapi.kaafifoods.com/storage/products/ITP_Holeshot_XCR_Tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Non Dot Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
