INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (595, '10340880.0', 'Dunlop Geomax EN91 EX Gummy Rear Tire', 'dunlop-geomax-en91-ex-gummy-rear-tire-10340880.0', 'Dunlop', 3, 'DIRT BIKE', 'Off Highway Non Dot Inc / Dual Onoff Dot / Non Dot Tire / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1065602', 177.99, NULL, NULL, 'Save $37.96 18%', 4.8, 12, 'nan', 'nan', 'Rear', 1, '140/80-18', 1, 'Dunlop Geomax EN91 EX Gummy Rear Tire The Dunlop Geomax EN91 EX Tires excel in delivering superior traction across a diverse array of landscapes, particularly on rocky and hardpack terrains, courtesy of their Block-In-A-Block tread design. Additionally, a fresh rubber compound enhances both longevity and grip performance.', 'Progressive Cornering Block Technology (PCBT) on the shoulder knobs increases surface area of the interior block, while additional tread angles enhance grip, stability, and slide control Construction has an additional ply to improve the linearity of the sidewall stiffness and enhance damping and absorption performance A super soft rubber compound provides tremendous traction in the gnarliest of conditions Improves grip while cornering with enhanced feel and absorption Provides grip and handling for off-road performance A hard enduro tire based off the popular EN91 Works in hard packed conditions Neither DOT nor FIM approved Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_geomax_en91_ex_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_geomax_en91_ex_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "Off Highway Non Dot Inc / Dual Onoff Dot / Non Dot Tire / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "140/80-18"}', 50, 1, 1, NOW(), NOW());
