INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (596, '10321030.0', 'Motoz Xtreme Hybrid Gummy Rear Tires', 'motoz-xtreme-hybrid-gummy-rear-tires-10321030.0', 'Motoz', 3, 'DIRT BIKE', '20 On Road 80 Off Road / 10 On Road 90 Off Road / Dot Dirt Tires / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1054906', 177.99, '181.99', '181.99', 'nan', 4.8, 12, 'nan', 'nan', 'Rear', 3, '110/100-18 (M/C) 64M TT; 120/100-18 (M/C) 68M TT; 110/90-19 (M/C) 62M TT', 3, 'Motoz Xtreme Hybrid Gummy Rear Tires The Xtreme Hybrid Gummy takes the aggressive hybrid (moto/trials) tread pattern of the Xtreme Hybrid and increases traction in slick conditions using the Motoz Gummy BFM compound.', '15% on-road / 85% off-road Intermediate / soft terrain tread pattern Ultra-soft Gummy BFM compound Hybrid natural / synthetic rubber construction Reinforced sidewalls to allow for lower inflation pressure Flexible tread Concave and Lock system for increased traction Tread blocks with deep sipes for extra trials-like grip Reversible rear tread design DOT approved Tube type Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_xtreme_hybrid_gummy_rear_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_xtreme_hybrid_gummy_rear_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "20 On Road 80 Off Road / 10 On Road 90 Off Road / Dot Dirt Tires / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/100-18 (M/C) 64M TT; 120/100-18 (M/C) 68M TT; 110/90-19 (M/C) 62M TT"}', 50, 1, 1, NOW(), NOW());
