INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (597, '10555678.0', 'Mitas Enduro Trail-SP Tires', 'mitas-enduro-trail-sp-tires-10555678.0', 'Mitas', 3, 'DIRT BIKE', '90 On Road 10 Off Road / Dot Tire / Multi Compound Tire / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1170599', 136.46, '186.99', '186.99', 'Save up to Save $22.68 12%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 2, '130/80B17 65H; 100/90-19 57H', 2, 'Mitas Enduro Trail-SP Tires For riders who demand top-tier performance on the open road, regardless of the weather or the allure of gravel trails, the ENDURO TRAIL-SP stands as the ideal selection. Boasting Multi Compound Tread Technology, it delivers outstanding mileage and tenacious cornering grip, excelling even in cooler conditions. Infused with a high silica content, the tires ensure exceptional grip on wet roads. The innovative construction technology, paired with a skillfully designed tread pattern, offers unparalleled straight-line stability and fluid handling that riders of both lightweight and hefty trail motorcycles will appreciate.', 'Unique construction technology and highly functional pattern design provides superb straight-line stability and smooth handling for both light and heavy trail motorcycles Multi Compound Technology (MCTT) combined with a functional tread pattern, offers excellent traction on wet and dry surfaces 90% on-road use for all around performance and confidence on both paved and gravel roads Delivers excellent mileage and cornering grip High silica content ensures superior wet road grip Recommended for dual-purpose adventure touring motorcycles Not recommended of course on ice and/or snow Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_sp_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_sp_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "90 On Road 10 Off Road / Dot Tire / Multi Compound Tire / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "130/80B17 65H; 100/90-19 57H"}', 50, 1, 1, NOW(), NOW());
