INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (612, '10048589.0', 'CST Ambush Tires', 'cst-ambush-tires-10048589.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P898204', 93.6, '164.99', '164.99', 'Save up to Save $17.39 11%', 1.0, 2, 'nan', 'nan', 'Front; Rear', 0, 'nan', 10, 'CST Ambush Tires CST provides a lightweight puncture resistant 4-ply tire that is at home on the track as it is on the trail. The CST Ambush tire has a front tire that is directional to deliver predictable corning and stability in the straight-line. On the rears are knobs extending across the full section width for superior traction and stability.', 'Classic MX-style knobby tread pattern Built for cross country and prepared surfaces Directional front tread design offers predictable cornering with straight-line stability Non-directional rear knobs provide maximum acceleration Rear knobs extend across section width for maximum traction and control Durable 4 ply rating construction provides puncture resistance and reduces tire roll For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/cst_ambush_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/cst_ambush_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
