INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (615, '10526949.0', 'Motoz Tractionator Outback Race Tires', 'motoz-tractionator-outback-race-tires-10526949.0', 'Motoz', 4, 'DIRT BIKE', '10 On Road 90 Off Road / Intermediate Terrain / Hard Terrain / Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1156624', 191.99, NULL, NULL, 'nan', 4.8, 12, 'nan', 'nan', 'Rear', 1, '140/80-18 (M/C) 70R TT', 1, 'Motoz Tractionator Outback Race Tires Experience peak performance on treacherous terrains with the Motoz Tractionator Outback Race Tire, meticulously crafted for the extreme rally raid environment. Subjected to years of rigorous testing over thousands of kilometers, this tire stands as Motoz''s toughest creation, adept at handling high speeds off-road. It guarantees exceptional stability and dissipates heat effectively to maintain consistent performance. A proven companion in the intense Dakar Rally, it caters to riders who demand the pinnacle of endurance and power.', '10% on-road / 90% off-road Motoz’s most heavy duty tire built for the worlds toughest conditions Unique tread compound and carcass construction enhance stability and longevity in extreme terrain Developed and tested in the most extreme world rally raid events ECER75 Approved DOT approved Tube type', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_tractionator_outback_race_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_tractionator_outback_race_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "10 On Road 90 Off Road / Intermediate Terrain / Hard Terrain / Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "140/80-18 (M/C) 70R TT"}', 50, 1, 1, NOW(), NOW());
