INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (618, '269431.0', 'ITP Mud Lite Tires', 'itp-mud-lite-tires-269431.0', 'nan', 3, 'UTV/ATV', 'Mud Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P71955', 109.15, '287.99', '287.99', 'Save up to Save $67.97 24%', 4.8, 12, 'nan', 'nan', 'Front; Front/Rear; Rear', 0, 'nan', 27, 'ITP Mud Lite Tires The Mud Lite Tires from ITP are equally at home on the trails or in the slop. These mud-oriented all-terrain tires sport a V-shaped center tread pattern designed for intermediate, mud, rocks, snow and soft surfaces. The six ply bias construction is designed for full size UTV and SxS machines with stabilizing cords to reduce flex.', 'Bias ply construction Unique center tread contact area provides a smooth, radial-like ride Pure trail tire handling combined with pure mud tire performance Angled shoulder lugs provide unmatched mud traction 1/2" tread depth 6 ply rating for unmatched durability For off-highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/itp_mud_lite_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/itp_mud_lite_tires.webp"]', '{"Wheel Location": "Front; Front/Rear; Rear", "Type": "UTV/ATV", "Product Type": "Mud Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(),