INSERT INTO product_fitments (product_id, year, make, model, position, tire_size, sku_number, item_number, vendor_part_number, created_at, updated_at) VALUES (618, '2008 - 2025', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', 'Front, Rear', 'nan', '269431.0', 'P71955', '269431.0', NOW(), NOW());
INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (619, '10049455.0', 'GMZ Sand Stripper Staggered Cut Rear Tires', 'gmz-sand-stripper-staggered-cut-rear-tires-10049455.0', 'GMZ Race Products', 3, 'UTV/ATV', 'Sand Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P898982', 187.93, NULL, NULL, 'Save $15.28 8%', 4.8, 12, 'nan', 'nan', 'Rear', 0, 'nan', 1, 'GMZ Sand Stripper Staggered Cut Rear Tires For the sand and dune enthusiasts of the world, GMZ Race Products presents the Sand Stripper line of performance tires. Front or rear, Sand Stripper Tires feature an extra wide footprint that provides maximum flotation and smooth dune transitions. Thick rim guards protect the wheel lip and seal the bead from sand intrusion. Bias-ply construction in two, four, and six-ply variants delivers good durability while keeping weight savings at the forefront. Sand Stripper Staggered Cut Rear Tires are designed for machines with high RPM power delivery / reduced low RPM torque. The staggered paddle design allows for some calculated tire slippage in the sand - helping your rig get into its powerband before hooking up completely. Speed builds as the tire regains traction. The staggered cut design is excellent for peaky two-strokes and smaller displacement rigs with lower overall power output. The Sand Stripper Staggered Cut Rear Tires feature a 22.2mm paddle depth. Paddles are positioned in a staggered pattern, running partially across the tire''s width. The fourteen paddles design uses a six-ply bias construction to maintain their form and contact patch when harnessing high RPM power.', 'Full-service sand and dune tire Staggered paddle design Engineered for peaky powerbands 14 paddles Designed for rear wheel applications 22.2mm paddle depth Excellent floatation and smooth transitions Thick rim guard keeps sand out of bead and protects rim 6 ply bias construction For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/gmz_sand_stripper_staggered_cut_rear_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/gmz_sand_stripper_staggered_cut_rear_tires.webp"]', '{"Wheel Location": "Rear", "Type": "UTV/ATV", "Product Type": "Sand Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
