INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (620, '10046094.0', 'Moose Racing Switchback Tires', 'moose-racing-switchback-tires-10046094.0', 'Moose Racing', 3, 'UTV/ATV', 'Intermediate Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P897047', 110.95, '323.95', '323.95', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 26, 'Moose Racing Switchback Tires Moose Racing has created a tire that can tackle multiple terrains while being available in popular sizing with the Switchback Tires. Built using radial or bias construction the angled tread pattern features large, unbroken lugs that cover the width of the tire surface.', 'All-terrain tire for ATV, side-by-side and utility applications Wide, angled tread lugs 4 ply, 6 ply and 8 ply versions Bias and radial construction', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/moose_racing_tire_swtchbk_dst28_x1014.webp', '["https://americaapi.kaafifoods.com/storage/products/moose_racing_tire_swtchbk_dst28_x1014.webp", "https://americaapi.kaafifoods.com/storage/products/moose_racing_switchback_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Intermediate Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
