INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (621, '10049451.0', 'GMZ Sand Stripper Front Tires', 'gmz-sand-stripper-front-tires-10049451.0', 'GMZ Race Products', 3, 'UTV/ATV', 'Sand Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P898999', 180.32, '229.0', '229.0', 'nan', 4.8, 12, 'nan', 'nan', 'Front', 0, 'nan', 2, 'GMZ Sand Stripper Front Tires For the sand and dune enthusiasts of the world, GMZ Race Products present the Sand Stripper line of performance tires. Front or rear, Sand Stripper Tires feature an extra wide footprint that provides maximum flotation and smooth dune transitions. Thick rim guards protect the wheel lip and seal the bead from sand intrusion. Bias ply construction in two, four and six ply variants deliver good durability while keeping weight savings at the forefront. These "standard" Sand Stripper Front Tires feature the trademark Sand Stripper design with concave tread ribs for responsive steering and low drag. These models are designed for rear-wheel-drive applications. Sand Stripper Front Tires can be paired with any of the rear tire applications in the Sand Stripper lineup. For four-wheel-drive applications, GMZ Race Products also sells the Sand Stripper "TT" Front Tires with lateral traction blocks - delivering power from front driven wheels to the ground.', 'Front sand and dune tire Intended for rear-wheel-drive applications Excellent floatation and transition Thick rim guard keeps sand out of bead and protects rim Concave tread ribs for stability, handling and low drag 6 ply bias construction For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/gmz_sand_stripper_front_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/gmz_sand_stripper_front_tires.webp"]', '{"Wheel Location": "Front", "Type": "UTV/ATV", "Product Type": "Sand Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
