INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (628, '10252233.0', 'Kenda K671 Cruiser Motorcycle Tires', 'kenda-k671-cruiser-motorcycle-tires-10252233.0', 'nan', 2, 'STREET BIKE', 'Cruiser Tire / Dot Tire', 'Harley-Davidson', 'Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard', '1990 - 2025', 'P1017631', 91.99, NULL, NULL, 'nan', 4.8, 12, 'nan', 'nan', 'Front', 1, '110/70B16 52H', 1, 'Kenda K671 Cruiser Motorcycle Tires', 'The aggressive tread design of the Kenda K671 Cruiser provides excellent traction and performance Matched front and rear patterns offer superior stability and maximum handling Deep, offset tread sipes deliver outstanding water dispersion and wet-weather traction The K671 is a tubeless construction for touring and cruiser bikes H-rated for speeds up to 130 mph with a strong 6-ply rating carcass Blackwall only Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/kenda_k671_cruiser_motorcycle_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/kenda_k671_cruiser_motorcycle_tires.webp"]', '{"Wheel Location": "Front", "Type": "STREET BIKE", "Product Type": "Cruiser Tire / Dot Tire", "Make": "Harley-Davidson", "Model": "Harley (Sportster, Softail, Dyna, Street Glide, Road King, Fat Boy), Honda Shadow / VTX, Yamaha V-Star / Bolt, Indian Scout / Chief, Kawasaki Vulcan, Suzuki Boulevard", "Tire Size": "110/70B16 52H"}', 50, 1, 1, NOW(), NOW());
