INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (629, '10035859.0', 'Duro HF246 Tires', 'duro-hf246-tires-10035859.0', 'nan', 3, 'UTV/ATV', 'Intermediate Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P893295', 85.81, '104.95', '104.95', 'Save up to Save $16.59 16%', 4.8, 12, 'nan', 'nan', 'Front', 0, 'nan', 2, 'Duro HF246 Tires The HF246 Tire is a rugged all-terrain tire and great OEM replacement option. Lightweight two ply construction uses stiff sidewalls for added stability. Center knobs with V-shaped indents greatly enhance performance in loose terrain and hardpack.', 'Ideal for hardpack and loose terrain Good all-terrain performance Longer tire life than many OEM options Good all-terrain performance Rugged yet lightweight 2 ply construction For off highway use only', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/duro_hf246_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/duro_hf246_tires.webp"]', '{"Wheel Location": "Front", "Type": "UTV/ATV", "Product Type": "Intermediate Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
