INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (636, '10555654.0', 'Mitas Terra Force MX Sand 2 Tires', 'mitas-terra-force-mx-sand-2-tires-10555654.0', 'Mitas', 3, 'DIRT BIKE', 'Sand Tire / Non Dot Tire / Dual Sport Tire / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1170579', 109.79, NULL, NULL, 'Save $16.20 13%', 4.8, 12, 'nan', 'nan', 'Rear', 1, '100/90-19 57M', 1, 'Mitas Terra Force MX Sand 2 Tires Enjoy unparalleled control and traction on sandy terrains with the TERRA FORCE-MX SAND 2 rear tire. Its deep (19.7 mm) paddle tread design, coupled with expansive voids, delivers exceptional grip during acceleration, cornering, and braking. For peak performance, it''s recommended to pair it with the TERRA FORCE-MX SAND or TERRA FORCE-MX SM front tires, ensuring an optimized riding experience.', 'Designed for Motocross racing in deep soft sandy terrain offering outstanding traction as well as cornering and braking stability High performance hard rubber compound and specially designed carcass with increased lateral support gives it incredible traction and control Tire structure and compound were developed in collaboration with Valentin Teillet and Alvin Oslund Identified by its characteristic 2 red stripes and is classified as NHS (Not for Highway Service) Recommended for Motocross motorcycles and available only for the rear Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_terra_force_mx_sand2_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_terra_force_mx_sand2_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "Sand Tire / Non Dot Tire / Dual Sport Tire / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "100/90-19 57M"}', 50, 1, 1, NOW(), NOW());
