INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (647, '10584815.0', 'Mitas MC-32 Win Scoot Winter Scooter Tires', 'mitas-mc-32-win-scoot-winter-scooter-tires-10584815.0', 'Mitas', 1, 'STREET BIKE', 'Dot Tire / Scooter Tire', 'Honda', 'Honda PCX150 / Ruckus, Yamaha Zuma / XMAX, Vespa Primavera / GTS 300, Suzuki Burgman 400', '2005 - 2025', 'P1184571', 71.99, '82.99', '82.99', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 5, '100/80-10 53P; 3.50-10 - 51P; 120/70-12; 130/70-12; 110/80-14', 5, 'Mitas MC-32 Winter Scooter Tires Designed for scooterists braving extreme winter landscapes and varying terrains, the Mitas MC 32 Win Scoot steps up to the challenge with cutting-edge technical prowess. It boasts an aggressive tread pattern, optimized for mud and snow, and is composed of special winter compounds that retain tire elasticity even in sub-zero temperatures. For added grip on slippery surfaces, the tire features pattern sipes that enhance traction on snow and slush, and its durable carcass construction supports the use of metal studs for icy conditions. Riders will appreciate the safety benefits of reflective sidewall arrows, which improve visibility in low lighting, ensuring safer commutes. With its dependable grip and precise handling, the Mitas MC 32 Win Scoot excels across diverse on-road and off-road environments, delivering steadfast performance where it counts.', 'Extreme Winter Traction: High-performance M+S compound maintains flexibility in sub-zero temperatures for snow and slush grip All-Terrain Versatility: Aggressive tread handles both on-road and off-road challenges in extreme weather High Visibility Safety: Reflective sidewall arrows improve presence during low-light winter commutes Cold Weather Precision: Specialized rubber stays elastic below 0°C ensuring consistent handling Advanced Sipe Technology: Integrated biting edges provide superior stability on slippery seasonal surfaces Compatibility: Suitable for winter stud installation Compatibility: Designed for all ground conditions Compatibility: Designed for all types of scooters Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_mc32_win_scoot_winter_scooter_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_mc32_win_scoot_winter_scooter_tires.webp"]', '{"Wheel Location": "nan", "Type": "STREET BIKE", "Product Type": "Dot Tire / Scooter Tire", "Make": "Honda", "Model": "Honda PCX150 / Ruckus, Yamaha Zuma / XMAX, Vespa Primavera / GTS 300, Suzuki Burgman 400", "Tire Size": "100/80-10 53P; 3.50-10 - 51P; 120/70-12; 130/70-12; 110/80-14"}', 50, 1, 1, NOW(), NOW());
