INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (650, '10506435.0', 'Plews Tyres MX3 Foxhills GP Hard Pack Tires', 'plews-tyres-mx3-foxhills-gp-hard-pack-tires-10506435.0', 'Plews Tyres', 3, 'DIRT BIKE', 'Non Dot Tire / Hard Terrain / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1147477', 56.63, '155.99', '155.99', 'Save up to Save $24.66 16%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 12, '60/100-12; 80/100-12; 60/100-14; 90/100-14; 90/100-16; 70/100-17; 120/90-18; 70/100-19; 100/90-19; 110/90-19; 120/90-19; 80/100-21', 12, 'Plews Tyres MX3 Foxhills GP Hard Pack Tires Experience the competitive edge with the MX3 Foxhills GP, a tire designed for high performance on hard-pack motocross tracks. Named after the famed Foxhills GP circuit, it boasts a lightweight construction with a unique, staggered tread pattern to provide superior grip, precise handling, and enhanced stability on demanding surfaces. The tire''s prominent tread block surfaces promise improved rider comfort and lessen fatigue even under intense riding conditions. Reinforced bridges on the rear tire ensure longevity and defend against wear and tear. Ideal for riders aiming for faster lap times or securing a strong start, the MX3 Foxhills GP is crafted for leaders of the race.', 'Designed specifically for hard-pack motocross tracks Lightweight construction for agile, high-speed performance Staggered tread layout enhances handling and control Asymmetrical front and rear tread design for optimized contact and grip Enlarged tread blocks improve feel and reduce rider fatigue Rear tire bridges increase durability and resist chunking Precision-cut blocks offer superior bite and traction Named after the iconic Foxhills GP track – where legends raced', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/plews_tyres_mx3_foxhills_gp_front_hard_front_1800x1800.webp', '["https://americaapi.kaafifoods.com/storage/products/plews_tyres_mx3_foxhills_gp_front_hard_front_1800x1800.webp", "https://americaapi.kaafifoods.com/storage/products/plews_tyres_mx3_foxhills_gp_front_hard_front.webp", "https://americaapi.kaafifoods.com/storage/products/plews_tyres_mx3_foxhills_gp_rear_hard_rear8010012.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Non Dot Tire / Hard Terrain / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "60/100-12; 80/100-12; 60/100-14; 90/100-14; 90/100-16; 70/100-17; 120/90-18; 70/100-19; 100/90-19; 110/90-19; 120/90-19; 80/100-21"}', 50, 1, 1, NOW(), NOW());
