INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (651, '10482662.0', 'Motoz Terrapactor MXS Tires', 'motoz-terrapactor-mxs-tires-10482662.0', 'Motoz', 3, 'DIRT BIKE', 'Soft Terrain / Sand Tire / Mud Tire / Non Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1133190', 94.99, '143.99', '143.99', 'nan', 4.8, 12, 'nan', 'nan', 'Front; Rear', 8, '110/100-18 64M; 120/90-18 65M; 100/90-19 57M; 110/90-19 62M; 120/80-19 63M; 120/90-19 66M; 80/100-21 51M; 90/100-21 57M', 8, 'Motoz Terrapactor MXS Tires The Terrapactor MXS competition tire emerges as an ideal choice for soft terrain, purpose-built for navigating soft soil and mixed conditions on mud/dry MX tracks. Engineered by Motoz, the tire''s lightweight design ensures top-tier performance where soft terrain prevails. With a focus on preventing tread clog, the MXS flaunts an aggressive open tread pattern that maintains cleanliness and grip, even amidst sticky mud. The tire incorporates innovative tread flex zones within both the carcass and knobs, amplifying its flexibility and grip to adapt to challenging surfaces. Riders seeking to conquer soft terrains can rely on the Terrapactor MXS for superior precision and confidence.', 'Lightweight carcass construction Chunky, open tread pattern prevents build-up, keeps the tread clean and ensures a firm grip Optimized MX compound for improved longevity and durability Flex zones incorporated into carcass for improved cornering grip and drive stability Flex zones incorporated into all tread rows to improve the feel and grip of cornering and accelerating Front tire sizes 80/100-21 has a traditional feel on the track 90/100-21 has a taller profile for increased contact patch and better feel and feedback through hard edged ruts Track Conditions – Soft Terrain (Soft soil, mixed mud/dry) NHS - not highway safe Tube type Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_terrapactor_mxs_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_terrapactor_mxs_tires.webp", "https://americaapi.kaafifoods.com/storage/products/motoz_terrapactor_mxs_tires_rear.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Soft Terrain / Sand Tire / Mud Tire / Non Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/100-18 64M; 120/90-18 65M; 100/90-19 57M; 110/90-19 62M; 120/80-19 63M; 120/90-19 66M; 80/100-21 51M; 90/100-21 57M"}', 50, 1, 1, NOW(), NOW());
