INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (653, '157861.0', 'Bridgestone M40 Tires', 'bridgestone-m40-tires-157861.0', 'Bridgestone', 3, 'DIRT BIKE', 'Off Highway Non Dot Inc / Dirt Bike Tire / Sand Tire / Non Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P42827', 52.54, NULL, NULL, 'Save $20.78 28%', 4.8, 12, 'nan', 'nan', 'Rear', 0, 'nan', 1, 'Bridgestone M40 Soft Terrain Tires', 'Great for loose dirt, soft sand and muddy conditions Extra wide spacing between tread blocks, together with rounded shape, means a self-cleaning tire even in wet, sticky mud Wraparound knob pattern provides climbing action out of ruts 4-ply construction for durability Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/bridgestone_m40_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/bridgestone_m40_tires.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "Off Highway Non Dot Inc / Dirt Bike Tire / Sand Tire / Non Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
