INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (654, '10052041.0', 'GBC Mini Master Tires', 'gbc-mini-master-tires-10052041.0', 'nan', 3, 'UTV/ATV', 'Hard Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P899576', 71.06, '115.95', '115.95', 'Save up to Save $11.59 10%', 4.8, 12, 'nan', 'nan', 'Front; Rear', 0, 'nan', 4, 'GBC Mini Master Tires The Mini Master Tire was specifically engineered for mini ATV and youth side-by-side applications. Following the same X-type lug design as the bigger XC Master Tires, the Mini Master’s tread pattern digs into loose terrain and gives superior acceleration and braking power. The MX knobby design gives excellent performance over a wide range of surfaces: mud, hard pack, blue groove and sand. Made from a soft, yet durable rubber compound, the Mini Masters remain flexible to conform to surface irregularities. Rear tires have a flat profile to achieve a full footprint with the ground - leaving no knob unused.', 'Youth-sized MX knobby Excels on mud, hard pack, blue groove and sand X-type lug pattern for excellent traction and braking power Front tires remain flexible to absorb surface irregularities Rear tires maintain a square contact patch for added traction For off highway use only Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/gbc_tire_mini_master_rear18_x8_x8_bias_lr182_lbs_mini_master_rear18_x8_x8.webp', '["https://americaapi.kaafifoods.com/storage/products/gbc_tire_mini_master_rear18_x8_x8_bias_lr182_lbs_mini_master_rear18_x8_x8.webp"]', '{"Wheel Location": "Front; Rear", "Type": "UTV/ATV", "Product Type": "Hard Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
