INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (658, '10506524.0', 'Plews Tyres Extreme EN1 The Tough One GP Hard Enduro Gummy Rear Tire', 'plews-tyres-extreme-en1-the-tough-one-gp-hard-enduro-gummy-rear-tire-10506524.0', 'Plews Tyres', 3, 'DIRT BIKE', 'Intermediate Terrain / Non Dot Tire / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1147534', 148.09, NULL, NULL, 'Save $40.90 22%', 4.8, 12, 'nan', 'nan', 'Rear', 1, '140/80-18', 1, 'Plews Tyres Extreme EN1 The Tough One GP Hard Enduro Gummy Rear Tire The Tough One GP is engineered to withstand the relentless challenges of Extreme Enduro. It''s a top-tier choice for riders facing treacherous rivers, craggy rocks, steep ascents, and punishing terrains. Specially designed to meet the standards of WEC and BEC-style racing, this tire features a super-soft, ultra-tacky compound, developed in the UK by leading chemists. Its lightweight polyester carcass provides exceptional flexibility, imperative for navigating technical sections with precision. The thoughtfully rounded profile of the Tough One GP enhances traction and prevents inward deflection on varied surfaces like grass, hills, and loose soil. In compliance with FIM regulations and primed for competition, it delivers the necessary grip, control, and confidence for riders to excel in one-day extreme enduro events.', 'Engineered for Extreme Enduro, WEC, and BEC-style races Super-soft, ultra-tacky rear compound for maximum grip on wet, rocky, and steep terrain Lightweight polyester carcass enhances flexibility and feel in technical riding Ideal round profile improves traction on varied surfaces like grass, hills, and rocks Designed to prevent inward deflection and maintain consistent ground contact Developed in the UK using cutting-edge materials and compound technology FIM-compliant 14mm tread depth and construction for race legality Tailored for elite-level performance in the toughest one-day events', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/plews_tyres_extreme_en1_the_tough_one_hard_enduro_gummy_gummy_rear1408018_1800x1800.webp', '["https://americaapi.kaafifoods.com/storage/products/plews_tyres_extreme_en1_the_tough_one_hard_enduro_gummy_gummy_rear1408018_1800x1800.webp", "https://americaapi.kaafifoods.com/storage/products/plews_tyres_extreme_en1_the_tough_one_hard_enduro_gummy_rear_tire.webp", "https://americaapi.kaafifoods.com/storage/products/plews_tyres_extreme_en1_the_tough_one_hard_enduro_gummy_gummy_rear1408018.webp"]', '{"Wheel Location": "Rear", "Type": "DIRT BIKE", "Product Type": "Intermediate Terrain / Non Dot Tire / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "140/80-18"}', 50, 1, 1, NOW(), NOW());
