INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (660, '10482642.0', 'Motoz Terrapactor MXI Tires', 'motoz-terrapactor-mxi-tires-10482642.0', 'Motoz', 3, 'DIRT BIKE', 'Intermediate Terrain / Hard Terrain / Non Dot Tire / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1133189', 42.99, '139.99', '139.99', 'nan', 4.8, 12, 'nan', 'nan', 'Front; Rear', 14, '80/100-12 50L; 60/100-14 26L; 90/100-14 49L; 90/100-16 51L; 70/100-17 40L; 110/100-18 64M; 120/90-18 65M; 70/100-19 42M; 100/90-19 57M; 110/90-19 62M; 120/80-19 63M; 120/90-19 66M; 80/100-21 51M; 90/100-21 57M', 14, 'Motoz Terrapactor MXI Tires The Terrapactor MXI (MX Intermediate) competition tire is a testament to cutting-edge engineering, optimized for intermediate to hard terrain, including a blend of loose, packed soil, and deep, heavy ruts. Standing as the benchmark for motocross tire performance on diverse surfaces, the MXI distinguishes itself with a unique tread pattern, meticulously designed for peak performance. Its innovative structure allows for strategic flex points within the tire''s carcass and knobs, ensuring both predictability and superior corner grip. This design allows the tire to adapt and flex with the terrain, offering riders increased control and confidence. For those seeking exceptional performance and versatility as they traverse challenging terrains, the Terrapactor MXI competition tire is a formidable choice.', 'Lightweight carcass construction Unique flex zones built into carcass and knobs for improved feel and compliance Flex zones incorporated into all tread rows to improve corning feel and drive Optimized inner sidewall construction for improved compliance in corners and in a straight line Front tire sizes 80/100-21 for most aggressive on track performance 90/100-21 with a taller profile for increased contact patch and better feel and feedback under race conditions Track Conditions – Intermediate to hard terrain (mix of loose and packed soil, hard packed soil and deep heavy ruts) NHS - not highway safe Tube type Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_terrapactor_mxi_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_terrapactor_mxi_tires.webp", "https://americaapi.kaafifoods.com/storage/products/motoz_terrapactor_mxi_tires_front.webp", "https://americaapi.kaafifoods.com/storage/products/motoz_terrapactor_mxi_tires_rear.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Intermediate Terrain / Hard Terrain / Non Dot Tire / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "80/100-12 50L; 60/100-14 26L; 90/100-14 49L; 90/100-16 51L; 70/100-17 40L; 110/100-18 64M; 120/90-18 65M; 70/100-19 42M; 100/90-19 57M; 110/90-19 62M; 120/80-19 63M; 120/90-19 66M; 80/100-21 51M; 90/100-21 57M"}', 50, 1, 1, NOW(), NOW());
