INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (664, '10482488.0', 'Motoz Terrapactor MXX Tires', 'motoz-terrapactor-mxx-tires-10482488.0', 'Motoz', 3, 'DIRT BIKE', 'Soft Terrain / Sand Tire / Mud Tire / Non Dot Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1133066', 107.99, '140.99', '140.99', 'nan', 4.8, 12, 'nan', 'nan', 'Front; Rear', 4, '110/90-19 62M; 120/80-19 63M; 120/90-19 66M; 90/100-21 57M', 4, 'Motoz Terrapactor MXX Tires The Terrapactor MXX tires redefine off-road performance, excelling on sand, soft soil, mud, and loose MX tracks where premium traction is crucial. Designed with a remarkably lightweight structure, the tires boast an open tread pattern, complemented by cutting-edge shoulder knobs that improve cornering grip on challenging surfaces. The inventive open scoop design and strategic tread flex zones within the tire ensure that debris is expelled efficiently, preserving optimal traction in sandy environments. With the Terrapactor MXX tires, you''ve got the edge needed to dominate in sandy and exceedingly soft terrain conditions.', 'Innovative scoop pattern for improved grip and cornering Super lightweight carcass construction Reinforced tread blocks on A, B and C blocks provide compliant drive and cornering in the loosest conditions Reinforced tread blocks provide a stable braking platform in all competition conditions Track Conditions – Sandy/Super Soft Terrain (Sand, soft soil, loose loam, mud) NHS - not highway safe Tube type Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/motoz_terrapactor_mxx_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/motoz_terrapactor_mxx_tires.webp", "https://americaapi.kaafifoods.com/storage/products/motoz_terrapactor_mxx_tires_rear.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Soft Terrain / Sand Tire / Mud Tire / Non Dot Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "110/90-19 62M; 120/80-19 63M; 120/90-19 66M; 90/100-21 57M"}', 50, 1, 1, NOW(), NOW());
