INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (671, '10386899.0', 'Mitas Enduro Trail Dakar Tires', 'mitas-enduro-trail-dakar-tires-10386899.0', 'Mitas', 3, 'DIRT BIKE', '50 On Road 50 Off Road / Dot Tire / Hard Terrain / Intermediate Terrain', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1087813', 149.06, '241.99', '241.99', 'Save up to Save $29.43 12%', 5.0, 1, 'nan', 'nan', 'Rear; Front', 5, '150/70B17 69H; 140/80B18 70H; 150/70B18 70H; 110/80B19 59H; 90/90B21 54H', 5, 'Mitas Enduro Trail Dakar Tires The Mitas Enduro Trail Dakar Tires employ a reinforced carcass and sidewall, featuring a durable rubber compound designed for extended wear. Bearing the "Dakar" designation, these Mitas tires enhance load-handling capacity, minimize the risk of pinch flats, and optimize road mileage, making them an ideal choice for overland adventures.', 'Designed for 50% on-road / 50% off-road use on Adventure and Dual Sport motorcycles TL (Tubeless) and TT (Tube Type) applications E-07+ Sidewall marking confirms the highly popular original design Can be used in combination with other E-07/E-07+ or ENDURO TRAIL 60/40 and 50/50 tires (Dakar and Standard) for customized performance Features large chevron style block pattern and independent shoulder knobs for ideal handling and wear on tarmac combined with stable, predictable off-highway performance Notes : It is recommended to change your valve stem, tube and/or rim strip when installing a new tire. Shop Here! Need your tire mounted? We’ve got you covered! Tire Mount Discount', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_dakar_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/mitas_enduro_trail_dakar_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "DIRT BIKE", "Product Type": "50 On Road 50 Off Road / Dot Tire / Hard Terrain / Intermediate Terrain", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "150/70B17 69H; 140/80B18 70H; 150/70B18 70H; 110/80B19 59H; 90/90B21 54H"}', 50, 1, 1, NOW(), NOW());
