INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (674, '10251681.0', 'EFX Gripper UTV R/T-K Tires', 'efx-gripper-utv-r-t-k-tires-10251681.0', 'EFX Tires', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1017274', 226.0, '317.0', '317.0', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 4, 'EFX Gripper UTV R/T-K Tires By maintaining the lightweight casing and adding a proprietary Aramid fiber-reinforced sidewall, EFX has taken the Gripper UTV to the next level. Add unparalleled strength and puncture resistance over the regular Gripper UTV tire without a weight penalty.', 'Strong enough to blast through open desert and also features channeled tread design to cut deep into mud and loam Siped tread blocks reduce heat generation Shoulder block design improves lateral grip and impact resistance Large block pattern design extends to the sidewall, greatly improving the sidewall impact resistance Large deep groove pattern greatly improves grip while providing higher wear resistance Rim Protector design protects your rim from shock damage Strong, lightweight Aramid fiber-reinforced sidewalls for puncture resistance Specifications: 28" Load Range: 855 lbs. max 32" Load Range: 1070 lbs. max 35" Load Range: 1050 lbs. max Designed for 6.5-8.5 inch wheels', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/efx_tires_gripper_utv_kevlar.webp', '["https://americaapi.kaafifoods.com/storage/products/efx_tires_gripper_utv_kevlar.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
