INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (676, '10046504.0', 'Vision W3057 Journey A/T Tires', 'vision-w3057-journey-a-t-tires-10046504.0', 'nan', 3, 'UTV/ATV', 'Utv Atv Tire / Intermediate Terrain', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P897239', 288.95, '302.95', '302.95', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 2, 'Vision W3057 Journey A/T Tires The Journey A/T Tires from Vision Wheel are an all-terrain tire inspired by light-truck designs. The tightly spaced center lugs offer good road manners over hard pack and help extend overall tread life. Wider spacing at the side lugs improves grip over obstacles and cornering traction. The robust radial design uses eight plies for increased load handling and puncture resistance.', 'All-terrain design Wider shoulder lug spacing for improve traction over rocks, ruts and roots High land ratio at the tread center effectively enhances steering and performance on straightaways Flatter profile offers wide ground contact and enhances cornering traction Non-directional tread pattern Tough 8 ply radial construction offers better ride and stability', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/vision_w3057_journey_at_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/vision_w3057_journey_at_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Utv Atv Tire / Intermediate Terrain", "Make": "Honda"