INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (677, '10045537.0', 'AMS M4 Evil Tires', 'ams-m4-evil-tires-10045537.0', 'AMS', 3, 'UTV/ATV', 'Intermediate Terrain / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P896806', 227.95, '413.95', '413.95', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 4, 'AMS M4 Evil Tires AMS''s M4 Evil Tires are a great all-around utility and rugged-terrain tire. These tough, long lasting radials use an eight ply design to increase puncture resistance, load carrying ability and handling response. Wide, angled lug spacing helps eject packed mud. The three-quarter inch tread depth gives the M4 Evil Tires better road-manners over hard pack, pavement and utility runs. Shoulder lugs with a slightly rounder profile keep the M4 Evil Tire''s ride smooth and quiet. For a more aggressive alternative, consider the M1 Evil Tires from AMS. The M1 Evil Tires feature a deeper 1" tread depth and more aggressive, squared-off shoulder lugs for added bite.', 'Rugged-terrain design for sand, dirt and rocks Light truck-inspired tread pattern with non-directional dual center lug design Smooth, quiet ride and superior handling over hard surfaces 3/4" tread depth Special long-lasting compound for ultra wear protection Reinforced sidewall for greater loading handling ability Excellent puncture resistance 8 ply radial design Note : Tire only. Wheel not included.', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/amsm4_evil_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/amsm4_evil_tires.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Intermediate Terrain / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
