INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (680, '10596640.0', 'Valor Offroad Tango UTV Tire', 'valor-offroad-tango-utv-tire-10596640.0', 'Valor Offroad', 3, 'UTV/ATV', 'Intermediate Terrain / Hard Terrain / Non Dot Tire / Utv Atv Tire', 'Honda', 'Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly', '2008 - 2025', 'P1189878', 289.0, '339.0', '339.0', 'nan', 4.8, 12, 'nan', 'nan', 'nan', 0, 'nan', 3, 'Valor Offroad Tango UTV Tire The Valor Offroad Tango UTV Tire meets the demands of drivers navigating fast, hard-packed terrain while seeking reliable grip over long distances. Crafted with care, the Tango showcases optimized tread spacing and shoulder angles that provide essential traction, stability, and control at high speeds. Its 8-ply rated steel belted radial construction, combined with a sturdy casing, enhances ride quality without compromising durability in tough conditions. Staggered shoulder lugs and a square crown profile are designed to improve cornering bite and straight-line performance, positioning the Tango as a dependable option for aggressive trail riders.', '8-ply rated steel-belted radial construction standard 65A compound 15mm tread depth Rigid casing provides superior ride quality and grip Staggered shoulder lugs Square crown profile Weight: 45-51 lbs Sold each Specifications: Overall Diameter UT32x9.50R15 - 32.10" @ 15psi UT33x9.50R15 - 33.10" @ 15psi UT35x10.00R15 - 35.10" @ 15psi Overall Width UT32x9.50R15 - 9.50" @ 15psi UT33x9.50R15 - 9.50" @ 15psi UT35x10.00R15 - 9.80" @ 15psi', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/valor_offroad_tango_utv_tire.webp', '["https://americaapi.kaafifoods.com/storage/products/valor_offroad_tango_utv_tire.webp"]', '{"Wheel Location": "nan", "Type": "UTV/ATV", "Product Type": "Intermediate Terrain / Hard Terrain / Non Dot Tire / Utv Atv Tire", "Make": "Honda", "Model": "Can-Am Spyder / Ryker / Maverick, Polaris RZR / Ranger, Honda Pioneer / Foreman, Yamaha Grizzly", "Tire Size": "nan"}', 50, 1, 1, NOW(), NOW());
