INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (685, '10596649.0', 'Dunlop Tire Geomax EN92 Soft Tires', 'dunlop-tire-geomax-en92-soft-tires-10596649.0', 'Dunlop', 3, 'DIRT BIKE', 'Intermediate Terrain / Non Dot Tire / Dirt Bike Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1189884', 158.95, '185.95', '185.95', 'nan', 4.8, 12, 'nan', 'nan', 'Front; Rear', 2, '140/80-18; 90/90-21', 2, 'Dunlop Geomax EN92 Soft Tires The Dunlop EN92 Soft is designed for challenging hard enduro terrains. This ultra-gummy tire excels in wet conditions filled with roots and rocks. It features a podium-proven tread pattern from the standard model, enhanced with a high-grip compound that adapts to obstacles. The result is improved traction that transforms difficult ledge hops into confident climbs.', 'Dedicated soft compound for maximum mechanical grip on wet and rocky terrain V-Block Technology (V-BT) optimizes rear traction and slide control Reinforced Scoop Technology (RST) helps the rear dig deep into soft soil Progressive Cornering Block Technology (PCBT) improves lean angle grip Rounded sidewall profile increases rider comfort and bump compliance Staggered front tread pattern with reduced land ratio for better rocky surface bite Increased block cavities improve shock absorption over jagged obstacles FIM legal knob height/size', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_tire_geomax_en92_soft_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_tire_geomax_en92_soft_tires.webp"]', '{"Wheel Location": "Front; Rear", "Type": "DIRT BIKE", "Product Type": "Intermediate Terrain / Non Dot Tire / Dirt Bike Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "140/80-18; 90/90-21"}', 50, 1, 1, NOW(), NOW());
