INSERT INTO products (id, sku, name, slug, brand, category_id, vehicle_type, product_type, compatible_makes, compatible_models, fitment_year_range, item_number, price, was_price, compare_at_price, savings, rating, review_count, front_tire_fitment, rear_tire_fitment, wheel_locations, available_sizes_count, available_sizes, total_part_numbers, description, specs_and_features, fitment_vehicle, fitment_disclaimer, primary_image, gallery_images, custom_attributes, stock_quantity, is_active, is_featured, created_at, updated_at) VALUES (690, '10596646.0', 'Dunlop Tire Geomax EN92 Tires', 'dunlop-tire-geomax-en92-tires-10596646.0', 'Dunlop', 3, 'DIRT BIKE', '10 On Road 90 Off Road / Intermediate Terrain / Dot Tire / Dual Sport Tire', 'Honda', 'Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450', '1995 - 2025', 'P1189882', 142.95, '168.95', '168.95', 'nan', 4.8, 12, 'nan', 'nan', 'Rear; Front', 3, '120/90-18; 140/80-18; 90/90-21', 3, 'Dunlop Geomax EN92 Tires The Dunlop EN92 is engineered for challenging terrains where precision is crucial. Designed specifically for hard enduro and technical trails, it features a gummy-spec rubber compound that excels in grip and traction. This tire efficiently sheds mud and maintains control over rocky paths and slippery roots, allowing riders to navigate with confidence. With the Dunlop EN92, conquering difficult conditions becomes a seamless experience.', 'V-Block Technology (V-BT) optimizes rear traction and slide control Reinforced Scoop Technology (RST) helps the rear dig deep into soft soil Progressive Cornering Block Technology (PCBT) improves lean angle grip Rounded sidewall profile increases rider comfort and bump compliance Staggered front tread pattern with reduced land ratio for better rocky surface bite Increased block cavities improve shock absorption over jagged obstacles DOT approved to get you to the trailhead legally FIM legal knob height/size', 'nan', 'nan', 'https://americaapi.kaafifoods.com/storage/products/dunlop_tire_geomax_en92_tires.webp', '["https://americaapi.kaafifoods.com/storage/products/dunlop_tire_geomax_en92_tires.webp"]', '{"Wheel Location": "Rear; Front", "Type": "DIRT BIKE", "Product Type": "10 On Road 90 Off Road / Intermediate Terrain / Dot Tire / Dual Sport Tire", "Make": "Honda", "Model": "Honda CRF250R / CRF450R, Yamaha YZ250F / YZ450F, KTM 250 SX-F / 450 SX-F, Kawasaki KX250 / KX450, Suzuki RM-Z250 / RM-Z450, Husqvarna FC 250 / FC 450", "Tire Size": "120/90-18; 140/80-18; 90/90-21"}', 50, 1, 1, NOW(), NOW());
